sys_ui_page.client_script:
//Start
// Storage wrapper to isolate iframe data from standalone data
var isInIframe = (function() {
    try { return window.self !== window.top; } catch (e) { return true; }
})();
var STORAGE_PREFIX = isInIframe ? 'iframe_' : '';
var appStorage = {
    getItem: function(key) { return window.localStorage.getItem(STORAGE_PREFIX + key); },
    setItem: function(key, value) { window.localStorage.setItem(STORAGE_PREFIX + key, value); },
    removeItem: function(key) { window.localStorage.removeItem(STORAGE_PREFIX + key); }
};

// Show cached credits immediately on DOM ready
(function() {
    var cachedCredits = appStorage.getItem('cachedCredits');
    if (cachedCredits) {
        document.addEventListener('DOMContentLoaded', function() {
            var el = document.getElementById('credits-display');
            if (el) el.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>$' + cachedCredits;
        });
    }
})();

// Get ServiceNow session token for API calls
window.sessionToken = "$[gs.getSessionToken()]";
// Default API providers (used on first load, then stored in IndexedDB)
var DEFAULT_API_PROVIDERS = [
    {
        name: 'Kimi K2.5',
        apiKey: '{{OPENROUTER_API_KEY}}',
        model: 'moonshotai/kimi-k2.5',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        context_length: 262000,
        maxTokens: 64000,
        thinkingBudget: 40000,
        provider: 'moonshotai'
    },
    {
        name: 'opus-4.6',
        apiKey: '{{OPENROUTER_API_KEY}}',
        model: 'anthropic/claude-opus-4.6',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        context_length: 200000,
        maxTokens: 64000,
        thinkingBudget: 40000
    },
    {
        name: 'sonnet-4.5',
        apiKey: '{{OPENROUTER_API_KEY}}',
        model: 'anthropic/claude-sonnet-4.5',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        context_length: 200000,
        maxTokens: 64000,
        thinkingBudget: 40000
    },
    {
        name: 'haiku-4.5',
        apiKey: '{{OPENROUTER_API_KEY}}',
        model: 'anthropic/claude-haiku-4.5',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        context_length: 200000,
        maxTokens: 64000,
        thinkingBudget: 40000
    },
    {
        name: 'gpt-5.2',
        apiKey: '{{OPENROUTER_API_KEY}}',
        model: 'openai/gpt-5.2',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        context_length: 400000,
        maxTokens: 128000,
        effort: 'low'
    },
    {
        name: 'Gemini 3 Flash Preview',
        apiKey: '{{OPENROUTER_API_KEY}}',
        model: 'google/gemini-3-flash-preview',
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        context_length: 1000000,
        maxTokens: 64000,
        thinkingBudget: 50000
    },
    {
        name: 'Proxy',
        model: 'anthropic/claude-opus-4.6',
        endpoint: 'http://localhost:8000/api/v1/chat/completions',
        apiKey: '----',
        maxTokens: 100000,
        context_length: 200000,
        thinkingBudget: 64000
    }
];

// API providers (loaded from IndexedDB, initialized with defaults on first load)
var apiProviders = [];

// Default API provider template for adding new providers (based on haiku45)
var DEFAULT_API_PROVIDER = {
    name: '',
    apiKey: '{{OPENROUTER_API_KEY}}',
    model: '',
    endpoint: 'https://openrouter.ai/api/v1/chat/completions',
    context_length: 200000,
    maxTokens: 64000,
    thinkingBudget: 40000,
    provider: ''
};

var currentProvider = 'opus-4.6'; // Default provider name (must match a provider in DEFAULT_API_PROVIDERS)
var currentChatId = null;
var chats = {};
var paused = false;
var isRunning = false;
var pendingInjection = null; // User message to inject into the next tool result batch
var currentStreamingMsgIndex = -1;
var activeStreamingChatId = null; // Track which chat has active streaming
var sidebarCollapsed = false;
var historyExpanded = true; // History section expanded by default
var showApiStats = true;
var iframeLogs = [];
var networkRequests = [];
var lastRequestMetrics = null; // Track token usage and performance
var currentIframeUrl = '/'; // Track current iframe URL for AI context
var iframeFullscreen = false; // Track fullscreen state
var iframePanelWidgetId = null; // Track if iframe panel is showing a widget (null = browser mode)
var chatOverlayMinimized = false; // Track chat overlay minimized state
var settingsPanelOpen = false; // Track settings panel state
var toolPermissions = {}; // Tool security settings: 'auto', 'ask', 'disabled'
var cacheTokenLimit = 4000; // Cache limit in tokens (default ~4k tokens = ~16KB)
var sessionPermissions = {}; // Session-only permissions (cleared on page reload)
var pendingToolApprovals = {}; // Track pending tool approval requests by chatId:approvalIndex
var currentScope = 'global'; // Current app scope (used for API calls)
var platformScope = 'global'; // Last known platform scope
var localScopeOverride = null; // User's local scope override (null = use platform scope)
var cachedUserSysId = null; // Cache user sys_id to avoid repeated API calls
var impersonateOriginalUserSysId = null; // Store original user sys_id before impersonation
var scopeFetched = false; // Track if scope has been fetched (lazy load for POST)
var versionHistory = []; // Track all record changes with before/after versions
var chatSearchQuery = ''; // Track chat search query
var activeSkills = {}; // Track active skills with their XML backups: { skillId: { xmlBackups: { table_sysId: versionSysId } } }
var skillAssetsStoreName = 'skillAssets'; // IndexedDB store for skill assets
var chatWidgets = {}; // Track widgets per chat: { chatId: [{ id, title, html, height, width, createdAt, msgIndex }] }
var isFollowingScroll = true; // Track if user is following scroll (turned off when user scrolls away from bottom)
var streamingDisplayLen = {}; // Buffered display length per message index for consistent streaming speed
var STREAM_CHARS_PER_TICK = 40; // Base chars revealed per 50ms tick (~800 chars/sec readable pace)
var lastLargeResponse = null; // Store the last large API response for Agent manipulation via js_eval
var lastUserScrollTime = 0; // Track when user last scrolled (for debounce)
var SCROLL_DEBOUNCE_MS = 1000; // 1 second debounce before auto-scroll can take over
var compactToolCalls = true; // Display option: collapse all tool calls in one area
var screenshotMethod = 'html-to-image'; // Screenshot method: 'html-to-image' or 'display-media'
var compactAreaExpandedState = {}; // Track expanded state of compact tool areas during streaming: { msgIndex: true/false }
var thinkingExpandedState = {}; // Track expanded state of thinking sections during streaming: { 'msgIdx-tlIdx': true/false }
var lastApiError = null; // Track last API error for retry functionality
var pendingImageAttachments = []; // Track images to attach to the next message: [{ base64, name, width, height }]
var _screenshotIdCounter = 0; // Auto-increment counter for screenshot IDs
var chatPendingImages = {}; // Per-chat/view pending images: { chatId|'home': [{ base64, name, width, height }] }
var chatPendingTexts = {}; // Per-chat/view pending input text: { chatId|'home': 'text' }
var isHandlingPopState = false; // Track if we're handling a popstate event (to avoid pushing duplicate state)
var isInitialLoad = true; // Track if we're in initial page load (use replaceState instead of pushState)

// Hooks system
var hooksEnabled = {
    autoTitle: true, // Hook to auto-generate chat title after agent completes
    showHookMessages: false // Show hook messages in chat UI
};
var _silentHookRunning = false; // Suppress UI updates during silent hook runs

// Browser History Management
function getHistoryTitle(view, chatId, skillId) {
    var baseTitle = 'AppAgent';
    if (view === 'chat' && chatId && chats[chatId]) {
        var chat = chats[chatId];
        return (chat.title && chat.title !== 'New Chat') ? chat.title + ' - ' + baseTitle : 'New Chat - ' + baseTitle;
    } else if (view === 'skill-editor' && skillId && skills[skillId]) {
        return skills[skillId].name + ' - Skills - ' + baseTitle;
    } else if (view === 'skills') {
        return 'Skills - ' + baseTitle;
    } else if (view === 'dashboard') {
        return 'Dashboard - ' + baseTitle;
    } else if (view === 'home') {
        return baseTitle;
    } else if (view === 'tools') {
        return 'Tools - ' + baseTitle;
    } else if (view === 'settings-page') {
        return 'Settings - ' + baseTitle;
    } else if (view === 'docs') {
        return 'Documentation - ' + baseTitle;
    } else if (view === 'history') {
        return 'Chat History - ' + baseTitle;
    }
    return baseTitle;
}

function pushHistoryState(view, chatId, skillId) {
    if (isHandlingPopState) return; // Don't push state when handling back/forward
    var state = { view: view, chatId: chatId || null, skillId: skillId || null };
    var url = window.location.pathname + window.location.search; // Keep current URL
    var title = getHistoryTitle(view, chatId, skillId);
    document.title = title;
    if (isInitialLoad) {
        // Use replaceState for initial load to set up base state without creating extra history entry
        // Note: isInitialLoad is set to false at the end of init(), not here, to ensure
        // all pushHistoryState calls during initialization use replaceState
        history.replaceState(state, '', url);
    } else {
        history.pushState(state, '', url);
    }
}

function replaceHistoryState(view, chatId, skillId) {
    var state = { view: view, chatId: chatId || null, skillId: skillId || null };
    var url = window.location.pathname + window.location.search;
    var title = getHistoryTitle(view, chatId, skillId);
    document.title = title;
    history.replaceState(state, '', url);
}

function handlePopState(event) {
    var state = event.state;
    if (!state) return;

    isHandlingPopState = true;

    try {
        var targetView = state.view || 'chat';
        var targetChatId = state.chatId;

        // Navigate to the appropriate view
        if (targetView === 'chat' && targetChatId && chats[targetChatId]) {
            // Close any open view first
            hideAllPanels();
            showChatView();
            currentView = 'chat';
            appStorage.setItem('currentView', 'chat');

            // Select the chat
            currentChatId = targetChatId;
            appStorage.setItem('lastChatId', targetChatId);
            clearUpdateSet();
            loadVersionHistory();
            renderChatList();
            renderMessages();
            updateInputPosition();
            updateChatTitleHeader();
            updateAllButtonStates();
            document.title = getHistoryTitle('chat', targetChatId, null);

            // Restore streaming UI state if returning to an actively streaming chat
            if (activeStreamingChatId === targetChatId) {
                isRunning = true;
                showPauseButton();
            }
        } else if (targetView === 'dashboard') {
            currentView = 'dashboard';
            appStorage.setItem('currentView', 'dashboard');
            currentEditingWidget = null;
            hideAllPanels();
            var dashboardPanel = document.getElementById('dashboard-panel');
            if (dashboardPanel) { dashboardPanel.style.display = 'flex'; renderDashboard(); }
            var headersBtn = document.getElementById('dashboard-toggle-headers-btn');
            if (headersBtn) headersBtn.classList.toggle('active', showDashboardHeaders);
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('dashboard', null, null);
        } else if (targetView === 'skill-editor' && state.skillId && skills[state.skillId]) {
            // Open specific skill editor
            currentView = 'skills';
            appStorage.setItem('currentView', 'skills');
            hideAllPanels();
            var skillsPanel = document.getElementById('skills-panel');
            if (skillsPanel) skillsPanel.style.display = 'flex';
            // Open the skill editor directly
            openSkillEditor(state.skillId);
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('skill-editor', null, state.skillId);
        } else if (targetView === 'skills') {
            currentView = 'skills';
            appStorage.setItem('currentView', 'skills');
            currentEditingSkill = null;
            hideAllPanels();
            var skillsPanel = document.getElementById('skills-panel');
            var listPanel = document.getElementById('skills-list-panel');
            var editorPanel = document.getElementById('skill-editor-panel');
            if (listPanel) listPanel.style.display = 'flex';
            if (editorPanel) editorPanel.style.display = 'none';
            if (skillsPanel) { skillsPanel.style.display = 'flex'; renderSkillsList(); }
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('skills', null, null);
        } else if (targetView === 'home') {
            currentView = 'home';
            appStorage.setItem('currentView', 'home');
            hideAllPanels();
            var homePanel = document.getElementById('home-panel');
            if (homePanel) { homePanel.style.display = 'flex'; renderHome(); }
            updateAllButtonStates();
            renderChatList();
            restorePendingImagesForContext('home');
            document.title = getHistoryTitle('home', null, null);
        } else if (targetView === 'tools') {
            currentView = 'tools';
            appStorage.setItem('currentView', 'tools');
            hideAllPanels();
            var toolsPanel = document.getElementById('tools-panel');
            if (toolsPanel) { toolsPanel.style.display = 'flex'; renderToolsList(); }
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('tools', null, null);
        } else if (targetView === 'settings-page') {
            currentView = 'settings-page';
            appStorage.setItem('currentView', 'settings-page');
            hideAllPanels();
            var settingsPanel = document.getElementById('settings-page-panel');
            if (settingsPanel) { settingsPanel.style.display = 'flex'; renderSettingsPage(); }
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('settings-page', null, null);
        } else if (targetView === 'docs') {
            currentView = 'docs';
            appStorage.setItem('currentView', 'docs');
            hideAllPanels();
            var docsPanel = document.getElementById('docs-panel');
            if (docsPanel) { docsPanel.style.display = 'flex'; renderDocsPage(); }
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('docs', null, null);
        } else if (targetView === 'history') {
            currentView = 'history';
            appStorage.setItem('currentView', 'history');
            hideAllPanels();
            var historyPanel = document.getElementById('history-panel');
            if (historyPanel) { historyPanel.style.display = 'flex'; renderHistoryPage(); }
            updateAllButtonStates();
            renderChatList();
            document.title = getHistoryTitle('history', null, null);
        } else {
            // Default: go to home or current chat
            hideAllPanels();
            showChatView();
            currentView = 'chat';
            appStorage.setItem('currentView', 'chat');
            updateAllButtonStates();
            renderChatList();
            renderMessages();
        }
    } finally {
        isHandlingPopState = false;
    }
}

// Initialize popstate listener
window.addEventListener('popstate', handlePopState);

// Centralized scroll helpers
function isNearBottom(container) {
    container = container || document.getElementById('messages');
    if (!container) return false;
    var distanceFromBottom = container.scrollHeight - container.scrollTop - container.clientHeight;
    return distanceFromBottom < 150;
}

// Get buffered content for consistent streaming speed
function getDisplayContent(msg, index) {
    if (!msg.isStreaming || !msg.content) {
        delete streamingDisplayLen[index];
        return msg.content || '';
    }
    var prevLen = streamingDisplayLen[index] || 0;
    var remaining = msg.content.length - prevLen;
    // Adaptive rate: faster when buffer is large to avoid falling too far behind
    var rate = remaining > 500 ? 120 : remaining > 200 ? 80 : STREAM_CHARS_PER_TICK;
    var newLen = Math.min(prevLen + rate, msg.content.length);
    // Snap to word boundary to avoid cutting mid-word
    if (newLen < msg.content.length && newLen > prevLen) {
        var space = msg.content.indexOf(' ', newLen);
        if (space !== -1 && space - newLen < 30) newLen = space + 1;
    }
    streamingDisplayLen[index] = newLen;
    return msg.content.substring(0, newLen);
}

// Track whether user has scrolled up inside the streaming text container
var isFollowingStreamingScroll = true;
// Create and configure the #streaming-text container element
function createStreamingTextEl() {
    var el = document.createElement('div');
    el.id = 'streaming-text';
    el.className = 'streaming-answer';
    isFollowingStreamingScroll = true;
    el.addEventListener('scroll', function() {
        var distFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
        // Hysteresis: only disengage when user deliberately scrolls far up,
        // re-engage when near bottom. Prevents layout-induced scroll jitter from disabling auto-scroll.
        if (distFromBottom < 30) {
            isFollowingStreamingScroll = true;
        } else if (distFromBottom > 150) {
            isFollowingStreamingScroll = false;
        }
        el.classList.toggle('has-top-shadow', el.scrollTop > 10);
    });
    return el;
}

// Update the streaming text container (#streaming-text) at the bottom of messages
// Each assistant message gets its own div - only the streaming message is updated per tick
function updateStreamingText(msg, index) {
    var el = document.getElementById('streaming-text');
    if (!el) {
        var container = document.getElementById('messages');
        if (!container) return;
        el = createStreamingTextEl();
        container.appendChild(el);
    }
    var chat = chats[currentChatId];
    if (!chat) return;
    // Find last user message to scope to current response
    var lastUserIdx = -1;
    for (var i = chat.messages.length - 1; i >= 0; i--) {
        if (chat.messages[i].role === 'user') { lastUserIdx = i; break; }
    }
    // For each assistant message, find or create its div - only update the streaming one
    var prevMsgDiv = null;
    for (var j = lastUserIdx + 1; j < chat.messages.length; j++) {
        var m = chat.messages[j];
        if (m.role === 'assistant' && m.content) {
            var msgDiv = el.querySelector('[data-msg-idx="' + j + '"]');
            if (!msgDiv) {
                // Add separator before new message (if not the first)
                if (prevMsgDiv || el.children.length > 0) {
                    var hr = document.createElement('hr');
                    hr.style.cssText = 'border:none;border-top:1px solid var(--border);margin:12px 0;';
                    el.appendChild(hr);
                }
                msgDiv = document.createElement('div');
                msgDiv.setAttribute('data-msg-idx', j);
                el.appendChild(msgDiv);
            }
            if (j === index) {
                // Only update the streaming message's content
                msgDiv.innerHTML = formatContent(getDisplayContent(m, j));
            } else if (!msgDiv.dataset.finalized) {
                // Update completed messages once, then mark as finalized
                msgDiv.innerHTML = formatContent(m.content);
                msgDiv.dataset.finalized = '1';
            }
            prevMsgDiv = msgDiv;
        }
    }
    updateStreamingContainerHeight();
    if (isFollowingStreamingScroll) {
        el.scrollTop = el.scrollHeight;
    }
}

// Calculate and set the streaming container height to fill remaining viewport space
function updateStreamingContainerHeight() {
    var streamingEl = document.querySelector('.streaming-answer');
    if (!streamingEl) return;
    var savedScroll = streamingEl.scrollTop;
    var rect = streamingEl.getBoundingClientRect();
    var viewportHeight = window.innerHeight;
    var availableHeight = viewportHeight - rect.top - 16;
    streamingEl.style.maxHeight = Math.max(availableHeight, 100) + 'px';
    // After maxHeight change: if following, go to the new bottom; otherwise restore position
    if (isFollowingStreamingScroll) {
        streamingEl.scrollTop = streamingEl.scrollHeight;
    } else {
        streamingEl.scrollTop = savedScroll;
    }
}

function scrollToBottomIfAllowed(container) {
    container = container || document.getElementById('messages');
    if (!container) return;

    // During streaming, scroll the inner container independently of outer scroll state
    var streamingEl = container.querySelector('.streaming-answer');
    if (streamingEl) {
        updateStreamingContainerHeight();
        if (isFollowingStreamingScroll) {
            streamingEl.scrollTop = streamingEl.scrollHeight;
        }
        return;
    }

    // For non-streaming: only scroll if user is following and hasn't scrolled recently
    if (!isFollowingScroll) return;
    if (Date.now() - lastUserScrollTime < SCROLL_DEBOUNCE_MS) return;
    container.scrollTo({ top: container.scrollHeight, behavior: 'smooth' });
}

