// IndexedDB for all app data (much larger capacity than localStorage)
// Use prefix for iframe isolation (separate database for iframe vs standalone)
var dbName = STORAGE_PREFIX + 'AppAgentDB';
var dbVersion = 7;
var chatStoreName = 'chats';
var settingsStoreName = 'settings';
var skillsStoreName = 'skills';
var dashboardWidgetsStoreName = 'dashboardWidgets';
var apiProvidersStoreName = 'apiProviders';
var db = null;
var skills = {};
var currentView = 'chat';
var currentEditingSkill = null;

// Dashboard state
var dashboardWidgets = {}; // { widgetId: { id, title, prompt, html, conversation, width, height, order, createdAt, updatedAt, error, isLoading, isStreaming } }
var currentEditingWidget = null;
var dashboardRefreshing = false;
var activeWidgetStreamingId = null; // Track which widget has active streaming
var showDashboardHeaders = false; // Toggle for showing widget headers
var pendingWidgetRegeneration = null; // Track which dashboard widget is being regenerated
var widgetDragState = null; // { widgetId, startX, startY, dragType: 'move'|'resize', startWidth, startHeight }
var expandedWidgetId = null; // Track expanded widget

// Grid-based positioning state
var gridState = {
    columns: 12,
    rowHeight: 50,
    gap: 16,
    occupancy: {},           // Sparse grid: "row,col" -> widgetId (for new widget placement)
    draggedWidgetId: null,
    dragOffset: null,        // { x, y } offset within widget where drag started
    maxZIndex: 1             // Track highest z-index for bringing widgets to front
};

function openDatabase() {
    return new Promise(function(resolve, reject) {
        if (db) { resolve(db); return; }
        var request = indexedDB.open(dbName, dbVersion);
        request.onerror = function() { reject(request.error); };
        request.onsuccess = function() { db = request.result; resolve(db); };
        request.onupgradeneeded = function(e) {
            var database = e.target.result;
            if (!database.objectStoreNames.contains(chatStoreName)) {
                database.createObjectStore(chatStoreName, { keyPath: 'id' });
            }
            if (!database.objectStoreNames.contains(settingsStoreName)) {
                database.createObjectStore(settingsStoreName, { keyPath: 'key' });
            }
            if (!database.objectStoreNames.contains(skillsStoreName)) {
                database.createObjectStore(skillsStoreName, { keyPath: 'id' });
            }
            if (!database.objectStoreNames.contains(skillAssetsStoreName)) {
                database.createObjectStore(skillAssetsStoreName, { keyPath: 'id' });
            }
            if (!database.objectStoreNames.contains(dashboardWidgetsStoreName)) {
                database.createObjectStore(dashboardWidgetsStoreName, { keyPath: 'id' });
            }
            if (!database.objectStoreNames.contains(apiProvidersStoreName)) {
                database.createObjectStore(apiProvidersStoreName, { keyPath: 'name' });
            }
        };
    });
}

// Generic settings get/set for IndexedDB
async function getSetting(key, defaultValue) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([settingsStoreName], 'readonly');
        var store = transaction.objectStore(settingsStoreName);
        var request = store.get(key);
        return new Promise(function(resolve) {
            request.onsuccess = function() {
                resolve(request.result ? request.result.value : defaultValue);
            };
            request.onerror = function() { resolve(defaultValue); };
        });
    } catch (e) {
        return defaultValue;
    }
}

async function setSetting(key, value) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([settingsStoreName], 'readwrite');
        var store = transaction.objectStore(settingsStoreName);
        store.put({ key: key, value: value });
    } catch (e) {
        console.error('Failed to save setting:', key, e);
    }
}

// Helper function to get provider by name
function getProviderByName(providerName) {
    return apiProviders.find(function(p) { return p.name === providerName; }) || null;
}

// Alias for backward compatibility
var getProviderById = getProviderByName;

// Get all providers
function getAllProviders() {
    return apiProviders;
}

// API Providers Management
async function loadApiProviders() {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([apiProvidersStoreName], 'readonly');
        var store = transaction.objectStore(apiProvidersStoreName);
        var request = store.getAll();
        return new Promise(function(resolve) {
            request.onsuccess = function() {
                var loaded = request.result || [];
                if (loaded.length === 0) {
                    // First load - initialize with defaults
                    apiProviders = DEFAULT_API_PROVIDERS.slice();
                    // Save defaults to IndexedDB
                    saveAllApiProviders();
                } else {
                    apiProviders = loaded;
                    // Merge any new default providers not yet in IndexedDB
                    var added = false;
                    DEFAULT_API_PROVIDERS.forEach(function(def) {
                        var exists = apiProviders.some(function(p) { return p.name === def.name; });
                        if (!exists) {
                            apiProviders.push(Object.assign({}, def));
                            added = true;
                        }
                    });
                    if (added) saveAllApiProviders();
                }
                resolve();
            };
            request.onerror = function() {
                console.error('Failed to load API providers:', request.error);
                apiProviders = DEFAULT_API_PROVIDERS.slice();
                resolve();
            };
        });
    } catch (e) {
        console.error('IndexedDB error loading API providers:', e);
        apiProviders = DEFAULT_API_PROVIDERS.slice();
        return Promise.resolve();
    }
}

async function saveAllApiProviders() {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([apiProvidersStoreName], 'readwrite');
        var store = transaction.objectStore(apiProvidersStoreName);
        // Clear and re-add all
        store.clear();
        apiProviders.forEach(function(p) { store.put(p); });
    } catch (e) {
        console.error('Failed to save all API providers:', e);
    }
}

async function saveApiProvider(provider) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([apiProvidersStoreName], 'readwrite');
        var store = transaction.objectStore(apiProvidersStoreName);
        store.put(provider);
        // Update in-memory array
        var existingIndex = apiProviders.findIndex(function(p) { return p.name === provider.name; });
        if (existingIndex >= 0) {
            apiProviders[existingIndex] = provider;
        } else {
            apiProviders.push(provider);
        }
    } catch (e) {
        console.error('Failed to save API provider:', e);
    }
}

async function deleteApiProvider(providerName) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([apiProvidersStoreName], 'readwrite');
        var store = transaction.objectStore(apiProvidersStoreName);
        store.delete(providerName);
        // Remove from in-memory array
        apiProviders = apiProviders.filter(function(p) { return p.name !== providerName; });
    } catch (e) {
        console.error('Failed to delete API provider:', e);
    }
}

function generateSkillId(title) {
    return title.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'skill_' + Date.now();
}

async function loadSkillsFromStorage() {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([skillsStoreName], 'readonly');
        var store = transaction.objectStore(skillsStoreName);
        var request = store.getAll();
        return new Promise(function(resolve) {
            request.onsuccess = function() {
                var results = request.result || [];
                skills = {};
                results.forEach(function(skill) {
                    skills[skill.id] = skill;
                });
                resolve();
            };
            request.onerror = function() {
                console.error('Failed to load skills:', request.error);
                resolve();
            };
        });
    } catch (e) {
        console.error('IndexedDB error loading skills:', e);
        return Promise.resolve();
    }
}

async function saveSkill(skill) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([skillsStoreName], 'readwrite');
        var store = transaction.objectStore(skillsStoreName);
        store.put(skill);
        skills[skill.id] = skill;
    } catch (e) {
        console.error('Failed to save skill:', e);
    }
}

async function deleteSkill(skillId) {
    try {
        // Deactivate first to revert XML files
        if (activeSkills[skillId]) {
            await deactivateSkill(skillId);
        }
        // Delete all assets for this skill
        await deleteSkillAssets(skillId);
        // Delete skill from IndexedDB
        var database = await openDatabase();
        var transaction = database.transaction([skillsStoreName], 'readwrite');
        var store = transaction.objectStore(skillsStoreName);
        store.delete(skillId);
        delete skills[skillId];
    } catch (e) {
        console.error('Failed to delete skill:', e);
    }
}

// Skill Assets Management (XML/MD files stored in IndexedDB)
// Asset format: { id: 'skillId_filename', skillId: string, filename: string, type: 'xml'|'md', content: string }

async function saveSkillAsset(skillId, filename, type, content) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([skillAssetsStoreName], 'readwrite');
        var store = transaction.objectStore(skillAssetsStoreName);
        var asset = { id: skillId + '_' + filename, skillId: skillId, filename: filename, type: type, content: content };
        store.put(asset);
    } catch (e) {
        console.error('Failed to save skill asset:', e);
    }
}

async function getSkillAssets(skillId) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([skillAssetsStoreName], 'readonly');
        var store = transaction.objectStore(skillAssetsStoreName);
        var request = store.getAll();
        return new Promise(function(resolve) {
            request.onsuccess = function() {
                var results = (request.result || []).filter(function(a) { return a.skillId === skillId; });
                resolve(results);
            };
            request.onerror = function() { resolve([]); };
        });
    } catch (e) {
        console.error('Failed to get skill assets:', e);
        return [];
    }
}

async function getSkillAsset(skillId, filename) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([skillAssetsStoreName], 'readonly');
        var store = transaction.objectStore(skillAssetsStoreName);
        var request = store.get(skillId + '_' + filename);
        return new Promise(function(resolve) {
            request.onsuccess = function() { resolve(request.result || null); };
            request.onerror = function() { resolve(null); };
        });
    } catch (e) {
        return null;
    }
}

async function deleteSkillAsset(skillId, filename) {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([skillAssetsStoreName], 'readwrite');
        var store = transaction.objectStore(skillAssetsStoreName);
        store.delete(skillId + '_' + filename);
    } catch (e) {
        console.error('Failed to delete skill asset:', e);
    }
}

async function deleteSkillAssets(skillId) {
    try {
        var assets = await getSkillAssets(skillId);
        var database = await openDatabase();
        var transaction = database.transaction([skillAssetsStoreName], 'readwrite');
        var store = transaction.objectStore(skillAssetsStoreName);
        assets.forEach(function(a) { store.delete(a.id); });
    } catch (e) {
        console.error('Failed to delete skill assets:', e);
    }
}

// Skill Tools - JS tools loaded from skill assets (run in isolated sandbox)
// JS Tool File Format (valid JS):
// ```
// var TOOL_DEFINITION = {
//     type: 'function',
//     function: {
//         name: 'tool_name',
//         description: 'Tool description',
//         parameters: { type: 'object', properties: {...}, required: [...] }
//     }
// };
//
// async function tool_name(args) {
//     // Runs in isolated sandbox - only executeTool() is available
//     // Call other tools via: await executeTool('servicenow_api', {...})
//     return { success: true, result: ... };
// }
// ```

var skillTools = {}; // { skillId: { toolName: { definition: {...}, code: string, name: string } } }

function parseSkillToolFile(content) {
    // Try multiple formats:
    // 1. var TOOL_DEFINITION = {...};
    // 2. // TOOL_DEFINITION\n{...}\n// END_TOOL_DEFINITION
    // 3. const TOOL_DEFINITION = {...};
    var defMatch = content.match(/(?:var|const|let)\s+TOOL_DEFINITION\s*=\s*(\{[\s\S]*?\n\});?/);
    if (!defMatch) {
        // Try comment format
        defMatch = content.match(/\/\/\s*TOOL_DEFINITION\s*\n([\s\S]*?)\n\s*\/\/\s*END_TOOL_DEFINITION/);
    }
    if (!defMatch) {
        console.warn('Skill tool file: No TOOL_DEFINITION found');
        return null;
    }

    try {
        var defStr = defMatch[1].trim();
        // Remove trailing semicolon if present
        if (defStr.endsWith(';')) defStr = defStr.slice(0, -1);
        var definition = eval('(' + defStr + ')');
        var toolName = definition.function && definition.function.name;
        if (!toolName) {
            console.warn('Skill tool file: No function name in definition');
            return null;
        }

        // Verify the function exists in the content
        var fnMatch = content.match(new RegExp('async\\s+function\\s+' + toolName + '\\s*\\('));
        if (!fnMatch) {
            fnMatch = content.match(new RegExp('function\\s+' + toolName + '\\s*\\('));
        }
        if (!fnMatch) {
            // Try arrow function: const toolName = async (args) => {...}
            fnMatch = content.match(new RegExp('(?:var|const|let)\\s+' + toolName + '\\s*='));
        }
        if (!fnMatch) {
            console.warn('Skill tool file: Function "' + toolName + '" not found in content');
            return null;
        }

        // Store raw code for sandboxed execution (don't eval here)
        return { definition: definition, code: content, name: toolName };
    } catch (e) {
        console.error('Failed to parse skill tool:', e);
        return null;
    }
}

async function loadSkillTools(skillId) {
    var assets = await getSkillAssets(skillId);
    var jsAssets = assets.filter(function(a) { return a.type === 'js'; });

    skillTools[skillId] = {};
    var errors = [];

    for (var i = 0; i < jsAssets.length; i++) {
        var parsed = parseSkillToolFile(jsAssets[i].content);
        if (parsed) {
            skillTools[skillId][parsed.name] = parsed;
        } else {
            var errMsg = jsAssets[i].filename + ': Failed to parse tool definition';
            console.warn(errMsg);
            errors.push(errMsg);
        }
    }
    return { loaded: Object.keys(skillTools[skillId]).length, errors: errors };
}

function unloadSkillTools(skillId) {
    delete skillTools[skillId];
}

function getActiveSkillTools() {
    var tools = [];
    for (var skillId in activeSkills) {
        if (skillTools[skillId]) {
            for (var toolName in skillTools[skillId]) {
                tools.push(skillTools[skillId][toolName].definition);
            }
        }
    }
    return tools;
}

var LARGE_RESPONSE_LINE_LIMIT = 50; // Max lines to show for large responses

// Execute skill tool in isolated sandbox (same security model as js_eval)
async function executeSkillTool(toolName, args, options) {
    var toolInfo = null;
    for (var skillId in skillTools) {
        if (skillTools[skillId][toolName]) {
            toolInfo = skillTools[skillId][toolName];
            break;
        }
    }

    if (!toolInfo) {
        return { success: false, error: 'Skill tool not found: ' + toolName };
    }

    var sandbox = null;
    try {
        var chatId = (options && options.chatId) || activeStreamingChatId || currentChatId;

        // Create isolated sandbox iframe with srcdoc (same as js_eval)
        sandbox = document.createElement('iframe');
        sandbox.style.display = 'none';
        sandbox.sandbox = 'allow-scripts';

        // Escape code and args for embedding in HTML
        // Note: backticks don't need escaping since we use single-quoted strings for concatenation
        var escapedCode = toolInfo.code
            .replace(/\\/g, '\\\\')
            .replace(/<\/script>/gi, '<\\/script>');

        var escapedArgs = JSON.stringify(args)
            .replace(/\\/g, '\\\\')
            .replace(/<\/script>/gi, '<\\/script>');

        // Build the HTML content with embedded script
        var htmlContent = '<!DOCTYPE html><html><head></head><body><script>' +
            'window._pendingCalls = {};' +
            'window._callId = 0;' +
            'window.executeTool = function(name, args) {' +
                'return new Promise(function(resolve, reject) {' +
                    'var id = ++window._callId;' +
                    'window._pendingCalls[id] = { resolve: resolve, reject: reject };' +
                    'window.parent.postMessage({ type: "skillToolCall", id: id, name: name, args: args }, "*");' +
                '});' +
            '};' +
            'window.addEventListener("message", function(e) {' +
                'if (e.data && e.data.type === "skillToolResult" && window._pendingCalls[e.data.id]) {' +
                    'var cb = window._pendingCalls[e.data.id];' +
                    'delete window._pendingCalls[e.data.id];' +
                    'if (e.data.error) cb.reject(new Error(e.data.error));' +
                    'else cb.resolve(e.data.result);' +
                '}' +
            '});' +
            '(async () => {' +
                'try {' +
                    // Execute the skill tool code (defines the function)
                    escapedCode + ';' +
                    // Call the function with args
                    'var result = await ' + toolName + '(' + escapedArgs + ');' +
                    'window.parent.postMessage({ type: "skillToolDone", result: result }, "*");' +
                '} catch (e) {' +
                    'window.parent.postMessage({ type: "skillToolDone", error: e.message }, "*");' +
                '}' +
            '})();' +
        '<\/script></body></html>';

        // Store listener reference outside Promise for cleanup on error
        var sandboxMessageHandler = null;

        // Promise to wait for result
        var resultPromise = new Promise(function(resolveMain, rejectMain) {
            // Handle tool calls from sandbox
            function handleSandboxMessage(e) {
                if (e.source !== sandbox.contentWindow) return;
                if (e.data && e.data.type === 'skillToolCall') {
                    var toolPromise = executeTool(e.data.name, e.data.args, null, { chatId: chatId });
                    toolPromise
                        .then(function(result) {
                            // Persist screenshot to chat.screenshots map so screenshot_by_id can find it
                            if (result && result._screenshotMessage) {
                                var ssMsg = result._screenshotMessage;
                                if (ssMsg.screenshot_id) {
                                    var ssChat = chats[chatId];
                                    if (ssChat) {
                                        if (!ssChat.screenshots) ssChat.screenshots = {};
                                        ssChat.screenshots[ssMsg.screenshot_id] = { base64: ssMsg.base64, name: ssMsg.name, width: ssMsg.width, height: ssMsg.height, timestamp: ssMsg.timestamp, description: ssMsg.description };
                                        saveChatsToStorage();
                                    }
                                }
                                result.base64 = ssMsg.base64;
                                result.width = ssMsg.width;
                                result.height = ssMsg.height;
                                result.screenshot_id = ssMsg.screenshot_id || result.screenshot_id;
                                delete result._screenshotMessage;
                            }
                            sandbox.contentWindow.postMessage({ type: 'skillToolResult', id: e.data.id, result: result }, '*');
                        })
                        .catch(function(err) {
                            sandbox.contentWindow.postMessage({ type: 'skillToolResult', id: e.data.id, error: err.message }, '*');
                        });
                } else if (e.data && e.data.type === 'skillToolDone') {
                    window.removeEventListener('message', handleSandboxMessage);
                    sandboxMessageHandler = null; // Clear reference
                    if (e.data.error) rejectMain(new Error(e.data.error));
                    else resolveMain(e.data.result);
                }
            }
            sandboxMessageHandler = handleSandboxMessage;
            window.addEventListener('message', handleSandboxMessage);

            // Set srcdoc to load the iframe with the script
            sandbox.srcdoc = htmlContent;
            document.body.appendChild(sandbox);
        });

        var result = await resultPromise;
        document.body.removeChild(sandbox);

        // Check if response is too large
        var resultStr = JSON.stringify(result, null, 2);
        var lines = resultStr.split('\n');

        if (lines.length > LARGE_RESPONSE_LINE_LIMIT) {
            // Store full response in global variable for Agent manipulation
            lastLargeResponse = result;

            // Create truncated preview (first 50 lines)
            var preview = lines.slice(0, LARGE_RESPONSE_LINE_LIMIT).join('\n');
            var totalLines = lines.length;

            // Return truncated result with metadata
            return {
                success: result.success !== undefined ? result.success : true,
                status: result.status,
                _response_truncated: true,
                _total_lines: totalLines,
                _preview_lines: LARGE_RESPONSE_LINE_LIMIT,
                _notice: 'Response too large (' + totalLines + ' lines). Showing first ' + LARGE_RESPONSE_LINE_LIMIT + ' lines. Full data stored in `lastLargeResponse` variable - use js_eval to process it (e.g., filter, map, count items, extract specific fields).',
                preview: preview
            };
        }

        return result;
    } catch (e) {
        // Clean up listener on error to prevent memory leak
        if (sandboxMessageHandler) {
            window.removeEventListener('message', sandboxMessageHandler);
        }
        if (sandbox && sandbox.parentNode) sandbox.parentNode.removeChild(sandbox);
        return { success: false, error: e.message };
    }
}

function isSkillTool(toolName) {
    for (var skillId in skillTools) {
        if (skillTools[skillId][toolName]) return true;
    }
    return false;
}

// Skill Activation/Deactivation with XML loading and version tracking
async function activateSkill(skillId) {
    var skill = skills[skillId];
    if (!skill || activeSkills[skillId]) return { success: false, error: 'Skill not found or already active' };

    var assets = await getSkillAssets(skillId);
    var xmlAssets = assets.filter(function(a) { return a.type === 'xml'; });
    var jsAssets = assets.filter(function(a) { return a.type === 'js'; });

    // Load JS tools first - fail if any tool fails to parse
    var toolResult = await loadSkillTools(skillId);
    if (toolResult.errors.length > 0) {
        unloadSkillTools(skillId);
        return { success: false, error: 'Failed to load tools: ' + toolResult.errors.join('; ') };
    }
    var toolCount = toolResult.loaded;

    if (xmlAssets.length === 0) {
        activeSkills[skillId] = { xmlBackups: {}, activatedAt: Date.now() };
        await saveActiveSkills();
        renderSkillsList();
        var msg = 'Skill activated with ' + toolCount + ' tool(s)';
        return { success: true, message: msg };
    }

    var backups = {};
    var errors = [];

    for (var i = 0; i < xmlAssets.length; i++) {
        var asset = xmlAssets[i];
        try {
            // Parse XML to get table and sys_id (case-insensitive, flexible format)
            var tableMatch = asset.content.match(/<([a-zA-Z_][a-zA-Z0-9_]*)\s+action=/i);
            var sysIdMatch = asset.content.match(/sys_id>([a-f0-9]{32})</i);

            if (tableMatch && sysIdMatch) {
                var table = tableMatch[1].toLowerCase();
                var sysId = sysIdMatch[1].toLowerCase();
                var key = table + '_' + sysId;

                // Get current version before uploading
                var currentVersion = await getCurrentRecordVersion(table, sysId);
                if (currentVersion) {
                    backups[key] = currentVersion;
                }

                // Upload the XML
                var result = await uploadXml(asset.content, table, sysId);
                if (!result.success) {
                    errors.push(asset.filename + ': ' + (result.error || 'Upload failed'));
                }
            } else {
                errors.push(asset.filename + ': Could not parse table/sys_id from XML');
            }
        } catch (e) {
            errors.push(asset.filename + ': ' + e.message);
        }
    }

    // If any XML failed to upload, fail the activation
    if (errors.length > 0) {
        unloadSkillTools(skillId);
        return { success: false, error: 'Failed to load XML: ' + errors.join('; ') };
    }

    activeSkills[skillId] = { xmlBackups: backups, activatedAt: Date.now() };
    await saveActiveSkills();
    renderSkillsList();

    var msg = 'Skill activated';
    if (toolCount > 0) msg += ' with ' + toolCount + ' tool(s)';
    if (xmlAssets.length > 0) msg += ' and ' + xmlAssets.length + ' XML file(s)';
    return { success: true, message: msg };
}

async function deactivateSkill(skillId) {
    var activeSkill = activeSkills[skillId];
    if (!activeSkill) return { success: false, error: 'Skill not active' };

    // Unload JS tools
    unloadSkillTools(skillId);

    var errors = [];
    var backups = activeSkill.xmlBackups || {};

    for (var key in backups) {
        var versionSysId = backups[key];
        // Key format is table_sysId where sysId is always 32 hex chars
        // Extract sysId (last 32 chars) and table (everything before the last underscore + 32 chars)
        var sysId = key.slice(-32);
        var table = key.slice(0, -33); // Remove underscore + 32 char sysId

        try {
            var xml = await getVersionXml(versionSysId);
            if (xml) {
                var result = await uploadXml(xml, table, sysId);
                if (!result.success) {
                    errors.push(key + ': revert failed');
                }
            }
        } catch (e) {
            errors.push(key + ': ' + e.message);
        }
    }

    delete activeSkills[skillId];
    await saveActiveSkills();
    renderSkillsList();

    if (errors.length > 0) {
        return { success: true, message: 'Skill deactivated with errors: ' + errors.join(', ') };
    }
    return { success: true, message: 'Skill deactivated and reverted' };
}

async function getCurrentRecordVersion(table, sysId) {
    try {
        var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
        var url = '/api/now/table/sys_update_version?sysparm_query=name=' + table + '_' + sysId + '^ORDERBYDESCsys_created_on&sysparm_limit=1&sysparm_fields=sys_id';
        var res = await fetch(url, { headers: headers });
        var data = await res.json();
        if (data.result && data.result.length > 0) {
            return data.result[0].sys_id;
        }
    } catch (e) {
        console.error('Failed to get current version:', e);
    }
    return null;
}

async function saveActiveSkills() {
    await setSetting('activeSkills', activeSkills);
}

async function loadActiveSkills() {
    activeSkills = await getSetting('activeSkills', {});
    // Load JS tools for all active skills
    for (var skillId in activeSkills) {
        await loadSkillTools(skillId);
    }
}

// =============================================
// DASHBOARD WIDGET MANAGEMENT
// =============================================

async function loadDashboardWidgets() {
    try {
        // Load header visibility state from localStorage
        var savedHeaderState = appStorage.getItem('showDashboardHeaders');
        if (savedHeaderState !== null) {
            showDashboardHeaders = savedHeaderState === 'true';
        }

        var database = await openDatabase();
        var transaction = database.transaction([dashboardWidgetsStoreName], 'readonly');
        var store = transaction.objectStore(dashboardWidgetsStoreName);
        var request = store.getAll();
        return new Promise(function(resolve) {
            request.onsuccess = function() {
                var results = request.result || [];
                dashboardWidgets = {};
                results.forEach(function(widget) {
                    dashboardWidgets[widget.id] = widget;
                });
                resolve();
            };
            request.onerror = function() {
                console.error('Failed to load dashboard widgets:', request.error);
                resolve();
            };
        });
    } catch (e) {
        console.error('IndexedDB error loading dashboard widgets:', e);
        return Promise.resolve();
    }
}

async function saveDashboardWidget(widget, skipHistory) {
    try {
        widget.updatedAt = Date.now();

        // Track HTML history (max 10 versions)
        if (!skipHistory && widget.html) {
            var oldWidget = dashboardWidgets[widget.id];
            if (oldWidget && oldWidget.html && oldWidget.html !== widget.html) {
                if (!widget.history) widget.history = [];
                widget.history.push({
                    html: oldWidget.html,
                    timestamp: Date.now(),
                    prompt: oldWidget.lastPrompt || ''
                });
                // Keep only last 10 versions
                if (widget.history.length > 10) {
                    widget.history = widget.history.slice(-10);
                }
            }
        }
        widget.lastPrompt = widget.prompt;

        dashboardWidgets[widget.id] = widget;

        // Create a copy without transient state for storage
        var widgetToSave = Object.assign({}, widget);
        delete widgetToSave.isLoading;
        delete widgetToSave.isStreaming;

        var database = await openDatabase();
        var transaction = database.transaction([dashboardWidgetsStoreName], 'readwrite');
        var store = transaction.objectStore(dashboardWidgetsStoreName);

        // Wait for the write to complete
        return new Promise(function(resolve, reject) {
            var request = store.put(widgetToSave);
            request.onsuccess = function() {
                resolve();
            };
            request.onerror = function() {
                console.error('Failed to save widget:', request.error);
                reject(request.error);
            };
        });
    } catch (e) {
        console.error('Failed to save dashboard widget:', e);
    }
}

async function deleteDashboardWidget(widgetId) {
    try {
        delete dashboardWidgets[widgetId];
        var database = await openDatabase();
        var transaction = database.transaction([dashboardWidgetsStoreName], 'readwrite');
        var store = transaction.objectStore(dashboardWidgetsStoreName);
        store.delete(widgetId);
    } catch (e) {
        console.error('Failed to delete dashboard widget:', e);
    }
}

function generateWidgetId() {
    return 'widget_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
}

// Dashboard View Management
function toggleDashboardView() {
