function renderToolsList() {
    var container = document.getElementById('tools-list');
    if (!container) return;

    // Define actions for tools that have sub-actions with permissions
    var toolActions = {
        'servicenow_api': ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
        'iframe_tool': ['navigate', 'get_visible_text', 'get_dom', 'click', 'fill', 'get_console_logs', 'get_network_requests', 'close', 'open_widget', 'edit_html', 'dispatch_event', 'select_option', 'scroll', 'resize', 'get_properties', 'set_style', 'impersonate']
    };

    var html = '';
    TOOLS.forEach(function(tool) {
        var toolName = tool.function.name;
        var displayName = TOOL_DISPLAY_NAMES[toolName] || toolName;
        var desc = tool.function.description || '';
        var icon = getToolIcon(toolName);
        var permission = toolPermissions[toolName] || 'ask';
        var hasActions = toolActions[toolName] && toolActions[toolName].length > 0;

        // Build parameters HTML
        var paramsHtml = '';
        var props = tool.function.parameters && tool.function.parameters.properties;
        var required = tool.function.parameters && tool.function.parameters.required || [];
        if (props) {
            paramsHtml = '<div class="tool-item-params"><strong style="font-size:11px;color:var(--text-muted);margin-bottom:8px;display:block;">Parameters:</strong>';
            Object.keys(props).forEach(function(paramName) {
                var param = props[paramName];
                var isRequired = required.indexOf(paramName) >= 0;
                var paramType = param.type || 'any';
                // Don't show enum values inline for action param if we have actions section
                if (paramName === 'action' && hasActions) {
                    paramType = 'string';
                } else if (param.enum) {
                    paramType = param.enum.join(' | ');
                }
                paramsHtml += '<div class="tool-param">' +
                    '<span class="tool-param-name">' + escapeHtml(paramName) + (isRequired ? ' *' : '') + '</span>' +
                    '<span class="tool-param-type">' + escapeHtml(paramType) + '</span>' +
                    '<span class="tool-param-desc">' + escapeHtml(param.description || '') + '</span>' +
                '</div>';
            });
            paramsHtml += '</div>';
        }

        // Build actions HTML with permissions for tools that have sub-actions
        var actionsHtml = '';
        if (hasActions) {
            actionsHtml = '<div class="tool-item-actions"><strong style="font-size:11px;color:var(--text-muted);margin-bottom:8px;display:block;">Actions:</strong>';
            toolActions[toolName].forEach(function(action) {
                var actionKey = toolName + ':' + action;
                var actionPerm = toolPermissions[actionKey] || 'ask';
                var actionDisplayName = TOOL_DISPLAY_NAMES[actionKey] || action;
                var containerId = 'tool-action-perm-' + toolName.replace(/[^a-zA-Z0-9]/g, '-') + '-' + action.replace(/[^a-zA-Z0-9]/g, '-');
                actionsHtml += '<div class="tool-action-item">' +
                    '<span class="tool-action-name">' + escapeHtml(actionDisplayName) + '</span>' +
                    '<div class="tool-action-permission" id="' + containerId + '" data-key="' + escapeHtml(actionKey) + '"></div>' +
                '</div>';
            });
            actionsHtml += '</div>';
        }

        // For tools with actions, don't show top-level permission select
        var permissionHtml = hasActions ? '' : 
            '<div class="tool-item-permission">' +
                '<select onchange="updateToolPermission(\'' + escapeHtml(toolName) + '\', this.value)">' +
                    '<option value="auto"' + (permission === 'auto' ? ' selected' : '') + '>Auto</option>' +
                    '<option value="ask"' + (permission === 'ask' ? ' selected' : '') + '>Ask First</option>' +
                    '<option value="disabled"' + (permission === 'disabled' ? ' selected' : '') + '>Disabled</option>' +
                '</select>' +
            '</div>';

        // Build code display HTML with both schema and function source
        var functionSource = getToolFunctionSource(toolName);
        var codeHtml = '<div class="tool-item-code" id="tool-code-' + escapeHtml(toolName) + '" style="display:none;">' +
            '<div class="tool-code-section">' +
                '<div class="tool-code-header">' +
                    '<strong style="font-size:11px;color:var(--text-muted);">Tool Definition (JSON Schema)</strong>' +
                    '<button class="tool-code-copy-btn" onclick="event.stopPropagation();copyToolCode(\'' + escapeHtml(toolName) + '\', \'schema\')" title="Copy Schema">' + UI_ICONS.copy + '</button>' +
                '</div>' +
                '<pre class="tool-code-content">' + escapeHtml(JSON.stringify(tool.function, null, 2)) + '</pre>' +
            '</div>' +
            (functionSource ? '<div class="tool-code-section" style="margin-top:12px;">' +
                '<div class="tool-code-header">' +
                    '<strong style="font-size:11px;color:var(--text-muted);">Implementation Source</strong>' +
                    '<button class="tool-code-copy-btn" onclick="event.stopPropagation();copyToolCode(\'' + escapeHtml(toolName) + '\', \'source\')" title="Copy Source">' + UI_ICONS.copy + '</button>' +
                '</div>' +
                '<pre class="tool-code-content" style="max-height:400px;">' + escapeHtml(functionSource) + '</pre>' +
            '</div>' : '') +
        '</div>';

        html += '<div class="tool-item" data-tool="' + escapeHtml(toolName) + '">' +
            '<div class="tool-item-header" onclick="toggleToolCode(\'' + escapeHtml(toolName) + '\')" style="cursor:pointer;">' +
                '<div class="tool-item-icon">' + icon + '</div>' +
                '<div class="tool-item-info">' +
                    '<div class="tool-item-name">' + escapeHtml(displayName) + ' <span class="tool-expand-hint">' + UI_ICONS.chevronDown + '</span></div>' +
                    '<div class="tool-item-desc">' + escapeHtml(desc.substring(0, 150)) + (desc.length > 150 ? '...' : '') + '</div>' +
                '</div>' +
                permissionHtml +
            '</div>' +
            actionsHtml +
            paramsHtml +
            codeHtml +
        '</div>';
    });

    container.innerHTML = html;

    // Render permission radio groups for actions
    Object.keys(toolActions).forEach(function(toolName) {
        toolActions[toolName].forEach(function(action) {
            var actionKey = toolName + ':' + action;
            var containerId = 'tool-action-perm-' + toolName.replace(/[^a-zA-Z0-9]/g, '-') + '-' + action.replace(/[^a-zA-Z0-9]/g, '-');
            var actionPerm = toolPermissions[actionKey] || 'ask';
            renderToolActionPermission(containerId, actionPerm, actionKey);
        });
    });
}

function renderToolActionPermission(containerId, selectedValue, permKey) {
    var container = document.getElementById(containerId);
    if (!container) return;

    var options = [
        { value: 'auto', label: 'Auto' },
        { value: 'ask', label: 'Ask' },
        { value: 'disabled', label: 'Off' }
    ];

    var html = '<div class="radio-group radio-group-small">';
    options.forEach(function(opt) {
        var isSelected = opt.value === selectedValue;
        html += '<div class="radio-option' + (isSelected ? ' selected' : '') + '" ' +
            'data-value="' + opt.value + '" ' +
            'onclick="event.stopPropagation(); setToolActionPermission(\'' + permKey + '\', \'' + opt.value + '\', this)">' +
            opt.label + '</div>';
    });
    html += '</div>';
    container.innerHTML = html;
}

function setToolActionPermission(permKey, value, element) {
    var parent = element.parentElement;
    parent.querySelectorAll('.radio-option').forEach(function(o) {
        o.classList.remove('selected');
    });
    element.classList.add('selected');
    toolPermissions[permKey] = value;
    saveToolPermissions();
}

function toggleToolCode(toolName) {
    var codeEl = document.getElementById('tool-code-' + toolName);
    var toolItem = codeEl ? codeEl.closest('.tool-item') : null;
    if (!codeEl) return;

    var isVisible = codeEl.style.display !== 'none';
    codeEl.style.display = isVisible ? 'none' : 'block';

    // Update expand hint icon
    if (toolItem) {
        var hint = toolItem.querySelector('.tool-expand-hint');
        if (hint) {
            hint.innerHTML = isVisible ? UI_ICONS.chevronDown : '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg>';
        }
    }
}

function getToolFunctionSource(toolName) {
    // Map tool names to their implementation functions
    var toolFunctions = {
        'js_eval': 'executeTool (js_eval branch)',
        'servicenow_api': 'executeTool (servicenow_api branch)',
        'servicenow_diff_edit': executeDiffEdit,
        'iframe_tool': executeIframeTool,
        'set_chat_title': executeSetChatTitle,
        'get_skill': executeGetSkill,
        'manage_skill': executeManageSkill,
        'html_widget': executeHtmlWidget
    };

    var fn = toolFunctions[toolName];
    if (typeof fn === 'function') {
        return fn.toString();
    } else if (typeof fn === 'string') {
        // For inline implementations, show the executeTool function
        return 'Implementation is inline in executeTool function.\nSee: ' + fn;
    }
    return null;
}

function copyToolCode(toolName, type) {
    var tool = TOOLS.find(function(t) { return t.function.name === toolName; });
    if (!tool) return;

    var code;
    if (type === 'source') {
        code = getToolFunctionSource(toolName) || 'No source available';
    } else {
        code = JSON.stringify(tool.function, null, 2);
    }

    navigator.clipboard.writeText(code).then(function() {
        showSnackbar((type === 'source' ? 'Source' : 'Schema') + ' copied!', 'success');
    }).catch(function() {
        showSnackbar('Failed to copy', 'error');
    });
}

function updateToolPermission(toolName, permission) {
    toolPermissions[toolName] = permission;
    saveToolPermissions();
}

