    renderSystemPromptEditor();

    // Render API providers list
    renderApiProvidersList();
}

// API Providers UI Functions
function isProviderCustomized(provider) {
    var defaultProvider = DEFAULT_API_PROVIDERS.find(function(d) { return d.name === provider.name; });
    if (!defaultProvider) return false; // It's a new custom provider, not customized
    return JSON.stringify(defaultProvider) !== JSON.stringify(provider);
}

function getEndpointDomain(endpoint) {
    try {
        var url = new URL(endpoint);
        return url.hostname.replace('www.', '');
    } catch (e) {
        return '';
    }
}

function renderApiProvidersList() {
    var container = document.getElementById('custom-api-providers-list');
    if (!container) return;

    if (apiProviders.length === 0) {
        container.innerHTML = '<div style="color:var(--text-muted);font-size:13px;padding:8px 0;">No providers configured.</div>';
        return;
    }

    var html = '';
    apiProviders.forEach(function(provider) {
        var isCustomized = isProviderCustomized(provider);
        var isNew = !DEFAULT_API_PROVIDERS.find(function(d) { return d.name === provider.name; });
        var isActive = provider.name === currentProvider;
        var statusBadge = isNew ? '<span class="provider-badge new">custom</span>' : (isCustomized ? '<span class="provider-badge">modified</span>' : '');
        var activeTag = isActive ? '<span class="provider-tag active">Active</span>' : '';
        var domain = getEndpointDomain(provider.endpoint);
        var domainTag = domain ? '<span class="provider-tag">' + escapeHtml(domain) + '</span>' : '';
        var providerTag = provider.provider ? '<span class="provider-tag">' + escapeHtml(provider.provider) + '</span>' : '';

        html += '<div class="api-provider-row' + (isActive ? ' active' : '') + '">' +
            '<span class="api-provider-name">' + escapeHtml(provider.name) + '</span>' +
            statusBadge +
            '<div class="api-provider-tags">' + activeTag + domainTag + providerTag + '</div>' +
            '<div class="api-provider-actions">' +
                '<button class="api-provider-btn' + (isActive ? ' selected' : '') + '" onclick="selectApiProvider(\'' + escapeHtml(provider.name).replace(/'/g, "\\'") + '\')" title="' + (isActive ? 'Active' : 'Use this model') + '">' + UI_ICONS.check + '</button>' +
                '<button class="api-provider-btn" onclick="editApiProvider(\'' + escapeHtml(provider.name).replace(/'/g, "\\'") + '\')" title="Edit">' + UI_ICONS.edit + '</button>' +
                '<button class="api-provider-btn danger" onclick="confirmDeleteApiProvider(\'' + escapeHtml(provider.name).replace(/'/g, "\\'") + '\')" title="Delete">' + UI_ICONS.trash + '</button>' +
            '</div>' +
        '</div>';
    });
    container.innerHTML = html;
}

function selectApiProvider(providerName) {
    changeProvider(providerName);
    renderApiProvidersList();
}

function getDefaultApiKey() {
    // Get API key from first default provider or existing providers
    if (apiProviders.length > 0 && apiProviders[0].apiKey) return apiProviders[0].apiKey;
    if (DEFAULT_API_PROVIDERS.length > 0) return DEFAULT_API_PROVIDERS[0].apiKey;
    return '';
}

function showAddApiProviderModal(editingProvider) {
    // Remove any existing modal first
    var existingModal = document.getElementById('api-provider-modal');
    if (existingModal) existingModal.remove();

    var isEditing = !!editingProvider;
    var originalName = isEditing ? editingProvider.name : '';
    var defaultApiKey = getDefaultApiKey();
    var provider = editingProvider || { 
        name: '', 
        model: '', 
        endpoint: 'https://openrouter.ai/api/v1/chat/completions', 
        apiKey: defaultApiKey, 
        maxTokens: 64000, 
        context_length: 200000,
        provider: ''
    };

    var overlay = document.createElement('div');
    overlay.id = 'api-provider-modal';
    overlay.className = 'modal-overlay show';
    overlay.onclick = function(e) { if (e.target === overlay) closeApiProviderModal(); };

    overlay.innerHTML = 
        '<div class="modal-dialog" style="max-width:480px;">' +
            '<div class="modal-header">' + (isEditing ? 'Edit' : 'Add') + ' API Provider</div>' +
            '<div class="modal-body" style="display:flex;flex-direction:column;gap:16px;">' +
                '<div class="form-field">' +
                    '<label class="form-label">Display Name <span class="required">*</span></label>' +
                    '<input type="text" id="provider-name" class="form-input" value="' + escapeHtml(provider.name) + '" placeholder="e.g. Claude 4 Sonnet">' +
                '</div>' +
                '<div class="form-field">' +
                    '<label class="form-label">Model ID <span class="required">*</span></label>' +
                    '<input type="text" id="provider-model" class="form-input" value="' + escapeHtml(provider.model) + '" placeholder="e.g. anthropic/claude-sonnet-4">' +
                '</div>' +
                '<div class="form-field">' +
                    '<label class="form-label">Provider (Optional)</label>' +
                    '<input type="text" id="provider-provider" class="form-input" value="' + escapeHtml(provider.provider || '') + '" placeholder="e.g. anthropic or novita/bf16">' +
                '</div>' +
                '<div class="form-field">' +
                    '<label class="form-label">API Endpoint</label>' +
                    '<input type="text" id="provider-endpoint" class="form-input" value="' + escapeHtml(provider.endpoint) + '" placeholder="https://openrouter.ai/api/v1/chat/completions">' +
                '</div>' +
                '<div class="form-field">' +
                    '<label class="form-label">API Key <span class="required">*</span></label>' +
                    '<input type="password" id="provider-apikey" class="form-input" value="' + escapeHtml(provider.apiKey) + '" placeholder="sk-or-...">' +
                '</div>' +
                '<div style="display:flex;gap:12px;">' +
                    '<div class="form-field" style="flex:1;">' +
                        '<label class="form-label">Max Tokens</label>' +
                        '<input type="number" id="provider-maxtokens" class="form-input" value="' + (provider.maxTokens || 16000) + '">' +
                    '</div>' +
                    '<div class="form-field" style="flex:1;">' +
                        '<label class="form-label">Context Length</label>' +
                        '<input type="number" id="provider-context" class="form-input" value="' + (provider.context_length || 200000) + '">' +
                    '</div>' +
                '</div>' +
            '</div>' +
            '<div class="modal-actions">' +
                '<button class="modal-btn secondary" onclick="closeApiProviderModal()">Cancel</button>' +
                '<button class="modal-btn primary" onclick="saveApiProviderFromModal(\'' + escapeHtml(originalName).replace(/'/g, "\\'") + '\')">' + (isEditing ? 'Save' : 'Add') + '</button>' +
            '</div>' +
        '</div>';

    document.body.appendChild(overlay);
}

function closeApiProviderModal() {
    var modal = document.getElementById('api-provider-modal');
    if (modal) modal.remove();
}

async function saveApiProviderFromModal(originalName) {
    var name = document.getElementById('provider-name').value.trim();
    var model = document.getElementById('provider-model').value.trim();
    var providerField = document.getElementById('provider-provider').value.trim();
    var endpoint = document.getElementById('provider-endpoint').value.trim() || 'https://openrouter.ai/api/v1/chat/completions';
    var apiKey = document.getElementById('provider-apikey').value.trim();
    var maxTokens = parseInt(document.getElementById('provider-maxtokens').value) || 16000;
    var contextLength = parseInt(document.getElementById('provider-context').value) || 200000;

    if (!name || !model || !apiKey) {
        showSnackbar('Please fill in all required fields (Name, Model ID, API Key)', 'error');
        return;
    }

    // If renaming, handle in-place update to preserve list order
    var originalIndex = -1;
    if (originalName && originalName !== name) {
        originalIndex = apiProviders.findIndex(function(p) { return p.name === originalName; });
        // Delete old entry from IndexedDB (but don't remove from array yet)
        try {
            var database = await openDatabase();
            var transaction = database.transaction([apiProvidersStoreName], 'readwrite');
            var store = transaction.objectStore(apiProvidersStoreName);
            store.delete(originalName);
        } catch (e) {
            console.error('Failed to delete old provider entry:', e);
        }
        // Update currentProvider if it was the renamed one
        if (currentProvider === originalName) {
            currentProvider = name;
            saveProviderToStorage();
        }
    }

    var provider = {
        name: name,
        model: model,
        endpoint: endpoint,
        apiKey: apiKey,
        maxTokens: maxTokens,
        context_length: contextLength,
        thinkingBudget: 40000
    };
    if (providerField) provider.provider = providerField;

    // If renaming, update in-place to preserve list order
    if (originalIndex >= 0) {
        apiProviders[originalIndex] = provider;
        // Save to IndexedDB
        try {
            var database = await openDatabase();
            var transaction = database.transaction([apiProvidersStoreName], 'readwrite');
            var store = transaction.objectStore(apiProvidersStoreName);
            store.put(provider);
        } catch (e) {
            console.error('Failed to save renamed provider:', e);
        }
    } else {
        await saveApiProvider(provider);
    }
    closeApiProviderModal();
    renderApiProvidersList();
    populateProviderDropdown();
    showSnackbar(originalName ? 'Provider updated' : 'Provider added', 'success');
}

function editApiProvider(providerName) {
    var provider = apiProviders.find(function(p) { return p.name === providerName; });
    if (provider) {
        showAddApiProviderModal(provider);
    }
}

async function confirmDeleteApiProvider(providerName) {
    var provider = apiProviders.find(function(p) { return p.name === providerName; });
    if (!provider) return;

    if (await showConfirmModal('Delete Provider', 'Delete provider "' + provider.name + '"? This cannot be undone.')) {
        deleteApiProviderAndRefresh(providerName);
    }
}

async function deleteApiProviderAndRefresh(providerName) {
    // Check if this provider is currently selected
    if (currentProvider === providerName) {
        // Switch to first available provider
        currentProvider = apiProviders.length > 1 ? apiProviders.find(function(p) { return p.name !== providerName; }).name : 'opus-4.6';
        saveProviderToStorage();
    }

    await deleteApiProvider(providerName);
    renderApiProvidersList();
    populateProviderDropdown();
    updateModelDisplay();
    showSnackbar('Provider deleted', 'success');
}

// System Prompt Editor Functions
function renderSystemPromptEditor() {
    var container = document.getElementById('system-prompt-editor-container');
    if (!container) return;

    var isEditing = systemPromptEditMode;
    var isCustom = hasCustomSystemPrompt();
    var template = getSystemPromptTemplate();
    var expandedPrompt = expandSystemPromptPlaceholders(template);
    var tokenCount = estimateTokens(expandedPrompt);

    // Calculate tools token count too
    var tools = getEnabledTools();
    var toolsJson = JSON.stringify(tools);
    var toolsTokenCount = estimateTokens(toolsJson);
    var totalTokenCount = tokenCount + toolsTokenCount;

    var content = isEditing ? escapeHtml(template) : escapeHtml(expandedPrompt);

    var html = '<div class="system-prompt-editor">' +
        '<div class="system-prompt-toolbar">' +
            '<div class="system-prompt-toolbar-left">' +
                (isEditing ? 
                    '<span class="system-prompt-mode-badge editing">Editing Template</span>' :
                    '<span class="system-prompt-mode-badge preview">Preview Mode</span>') +
                (isCustom ? '<span class="system-prompt-custom-badge">Custom</span>' : '') +
            '</div>' +
            '<div class="system-prompt-toolbar-right">' +
                (isEditing ?
                    '<button class="skills-action-btn" onclick="cancelSystemPromptEdit()">' + UI_ICONS.close + ' Cancel</button>' +
                    '<button class="skills-action-btn primary" onclick="saveSystemPromptEdit()">' + UI_ICONS.save + ' Save</button>' :
                    (isCustom ? '<button class="skills-action-btn" onclick="revertSystemPromptToDefault()">' + UI_ICONS.refresh + ' Revert to Default</button>' : '') +
                    '<button class="skills-action-btn primary" onclick="startSystemPromptEdit()">' + UI_ICONS.edit + ' Edit</button>') +
            '</div>' +
        '</div>' +
        '<div class="system-prompt-content-wrapper">' +
            (isEditing ?
                '<textarea id="system-prompt-textarea" class="system-prompt-textarea" oninput="updateSystemPromptTokenCount()">' + escapeHtml(template) + '</textarea>' :
                '<pre class="system-prompt-preview">' + content + '</pre>') +
            '<div class="system-prompt-token-count">' +
                '<span id="system-prompt-token-display">' + totalTokenCount.toLocaleString() + ' tokens</span>' +
                '<span class="system-prompt-token-detail">(prompt: ' + tokenCount.toLocaleString() + ' + tools: ' + toolsTokenCount.toLocaleString() + ')</span>' +
            '</div>' +
        '</div>' +
        '<div class="system-prompt-placeholders-help">' +
            '<strong>Available Placeholders:</strong> ' +
            '<code>{{SCOPE_CONTEXT}}</code> - Current app scope info, ' +
            '<code>{{DISABLED_TOOLS}}</code> - List of disabled tools, ' +
            '<code>{{SKILLS_SUMMARY}}</code> - Available skills list' +
        '</div>' +
    '</div>';

    container.innerHTML = html;
}

function startSystemPromptEdit() {
    systemPromptEditMode = true;
    renderSystemPromptEditor();
    // Focus the textarea
    var textarea = document.getElementById('system-prompt-textarea');
    if (textarea) textarea.focus();
}

function cancelSystemPromptEdit() {
    systemPromptEditMode = false;
    renderSystemPromptEditor();
}

async function saveSystemPromptEdit() {
    var textarea = document.getElementById('system-prompt-textarea');
    if (!textarea) return;

    var newTemplate = textarea.value;

    // Validate that the template is not empty
    if (!newTemplate.trim()) {
        showSnackbar('System prompt cannot be empty', 'error');
        return;
    }

    // Save the custom prompt
    await saveCustomSystemPrompt(newTemplate);
    systemPromptEditMode = false;
    renderSystemPromptEditor();
    showSnackbar('System prompt saved', 'success');
}

async function revertSystemPromptToDefault() {
    var confirmed = await showConfirmModal('Revert to Default', 'Are you sure you want to revert to the default system prompt? Your custom prompt will be deleted.');
    if (!confirmed) return;

    await clearCustomSystemPrompt();
    systemPromptEditMode = false;
    renderSystemPromptEditor();
    showSnackbar('Reverted to default system prompt', 'success');
}

function updateSystemPromptTokenCount() {
    var textarea = document.getElementById('system-prompt-textarea');
    var tokenDisplay = document.getElementById('system-prompt-token-display');
    var detailDisplay = document.querySelector('.system-prompt-token-detail');
    if (!textarea || !tokenDisplay) return;

    var template = textarea.value;
    var expandedPrompt = expandSystemPromptPlaceholders(template);
    var tokenCount = estimateTokens(expandedPrompt);

    var tools = getEnabledTools();
    var toolsJson = JSON.stringify(tools);
    var toolsTokenCount = estimateTokens(toolsJson);
    var totalTokenCount = tokenCount + toolsTokenCount;

    tokenDisplay.textContent = totalTokenCount.toLocaleString() + ' tokens';
    if (detailDisplay) {
        detailDisplay.textContent = '(prompt: ' + tokenCount.toLocaleString() + ' + tools: ' + toolsTokenCount.toLocaleString() + ')';
    }
}

async function fetchAndPopulateSettingsPageScopeDropdown() {
    var container = document.getElementById('settings-page-scope-container');
    if (!container) return;

    // Show current scope from local storage immediately (no loading message)
    // Include enough options to render as dropdown, not radio buttons
    var currentSelectedScope = localScopeOverride !== null ? localScopeOverride : platformScope;
    var currentLabel = currentSelectedScope === 'global' ? 'Global' : (window.currentScopeName || currentSelectedScope);
    var initialOptions = [{ value: 'global', label: 'Global' }];
    if (currentSelectedScope !== 'global') {
        initialOptions.push({ value: currentSelectedScope, label: currentLabel });
    }
    // Add placeholder options to ensure dropdown rendering (>3 options)
    initialOptions.push({ value: '_placeholder1', label: 'Loading scopes...' });
    initialOptions.push({ value: '_placeholder2', label: '' });
    initialOptions.push({ value: '_placeholder3', label: '' });
    renderCustomSelect('settings-page-scope-container', initialOptions, currentSelectedScope, changeLocalScope, 'Select scope...');

    try {
        var response = await fetch('/api/now/table/sys_scope?sysparm_query=sys_class_name=sys_app^ORsys_class_name=sys_store_app&sysparm_fields=scope,name,sys_id&sysparm_limit=500', {
            headers: { 'Accept': 'application/json', 'X-UserToken': window.sessionToken }
        });
        var data = await response.json();

        var options = [{ value: 'global', label: 'Global' }];
        if (data.result && data.result.length > 0) {
            data.result.forEach(function(scope) {
                if (scope.scope && scope.scope !== 'global') {
                    options.push({ value: scope.scope, label: scope.name || scope.scope });
                }
            });
        }

        var selectedScope = localScopeOverride !== null ? localScopeOverride : platformScope;
        renderCustomSelect('settings-page-scope-container', options, selectedScope, changeLocalScope, 'Select scope...');
    } catch (e) {
        console.error('Failed to fetch scopes:', e);
        renderCustomSelect('settings-page-scope-container', [{ value: 'global', label: 'Global' }], 'global', changeLocalScope, 'Select scope...');
    }
}

function renderSettingsToolPermissions() {
    var container = document.getElementById('settings-tool-permissions');
    if (!container) return;

    var html = '';
    var snMethods = ['servicenow_api:GET', 'servicenow_api:POST', 'servicenow_api:PUT', 'servicenow_api:PATCH', 'servicenow_api:DELETE'];
    var iframeActions = ['iframe_tool:navigate', 'iframe_tool:get_visible_text', 'iframe_tool:get_dom', 'iframe_tool:click', 'iframe_tool:fill', 'iframe_tool:get_console_logs', 'iframe_tool:get_network_requests', 'iframe_tool:close', 'iframe_tool:open_widget', 'iframe_tool:edit_html', 'iframe_tool:dispatch_event', 'iframe_tool:select_option', 'iframe_tool:scroll', 'iframe_tool:resize', 'iframe_tool:get_properties', 'iframe_tool:set_style'];
    var manageSkillActions = ['manage_skill:create', 'manage_skill:update', 'manage_skill:add_file', 'manage_skill:update_file', 'manage_skill:delete_file', 'manage_skill:activate', 'manage_skill:deactivate'];
    var otherTools = PERMISSION_KEYS.filter(function(k) { return snMethods.indexOf(k) === -1 && iframeActions.indexOf(k) === -1 && manageSkillActions.indexOf(k) === -1; });

    // Render other tools first
    otherTools.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'settings-perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });

    // Render ServiceNow API group
    html += '<div class="tool-permission-group">';
    html += '<div class="tool-permission-group-title">ServiceNow API</div>';
    snMethods.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'settings-perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item tool-permission-subitem">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });
    html += '</div>';

    // Render Manage Skill group
    html += '<div class="tool-permission-group">';
    html += '<div class="tool-permission-group-title">Manage Agent Skill</div>';
    manageSkillActions.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'settings-perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item tool-permission-subitem">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });
    html += '</div>';

    // Render Browser Control group
    html += '<div class="tool-permission-group">';
    html += '<div class="tool-permission-group-title">Browser Control</div>';
    iframeActions.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'settings-perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item tool-permission-subitem">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });
    html += '</div>';

    // Render active skill tools
    var skillToolKeys = [];
    var activeSkillIds = Object.keys(activeSkills);
    activeSkillIds.forEach(function(skillId) {
        var skill = skills[skillId];
        var skillToolsForSkill = skillTools[skillId] || {};
        var toolNames = Object.keys(skillToolsForSkill);
        if (toolNames.length > 0) {
            var skillName = skill ? (skill.name || skill.id) : skillId;
            html += '<div class="tool-permission-group">';
            html += '<div class="tool-permission-group-title">Skill: ' + escapeHtml(skillName) + '</div>';
            toolNames.forEach(function(toolName) {
                var permKey = 'skill:' + toolName;
                var containerId = 'settings-perm-' + permKey.replace(/[^a-zA-Z0-9]/g, '-');
                skillToolKeys.push(permKey);
                html += '<div class="tool-permission-item tool-permission-subitem">' +
                    '<span class="tool-permission-name">' + escapeHtml(toolName) + '</span>' +
                    '<div class="tool-permission-control" id="' + containerId + '"></div>' +
                '</div>';
            });
            html += '</div>';
        }
    });

    container.innerHTML = html;

    // Render radio groups for each permission
    var allKeys = otherTools.concat(snMethods).concat(manageSkillActions).concat(iframeActions).concat(skillToolKeys);
    allKeys.forEach(function(key) {
        var perm = toolPermissions[key] || 'ask';
        var containerId = 'settings-perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        renderPermissionRadioGroup(containerId, perm, key);
    });
}

// Helper to hide all panels
function hideAllPanels() {
    var panels = ['main-area', 'skills-panel', 'dashboard-panel', 'home-panel', 'tools-panel', 'settings-page-panel', 'docs-panel', 'history-panel'];
    panels.forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.display = 'none';
    });
    // Hide browser controls when leaving chat view
    var browserControls = document.getElementById('browser-controls');
    if (browserControls) browserControls.style.display = 'none';
}

// Show chat view with browser controls
function showChatView() {
    var mainArea = document.getElementById('main-area');
    if (mainArea) mainArea.style.display = 'flex';
    var browserControls = document.getElementById('browser-controls');
    if (browserControls) browserControls.style.display = '';
}

// Update all sidebar button states
function updateAllButtonStates() {
    var buttons = {
        'new-chat-nav-btn': currentView === 'home',
        'skills-btn': currentView === 'skills',
        'tools-btn': currentView === 'tools',
        'dashboard-btn': currentView === 'dashboard' || currentView === 'widget-editor',
        'settings-page-btn': currentView === 'settings-page',
        'docs-btn': currentView === 'docs'
    };
    Object.keys(buttons).forEach(function(id) {
        var btn = document.getElementById(id);
        if (btn) btn.classList.toggle('active', buttons[id]);
    });
    // Update history button active state
    var historyRow = document.getElementById('history-toggle-btn');
    if (historyRow) historyRow.classList.toggle('active', currentView === 'history');
}

// History View Management
function toggleHistoryView() {
    if (currentView === 'history') return;
    openHistoryView();
}

function openHistoryView() {
    currentView = 'history';
    appStorage.setItem('currentView', 'history');
    hideAllPanels();
    var historyPanel = document.getElementById('history-panel');
    if (historyPanel) { historyPanel.style.display = 'flex'; renderHistoryPage(); }
    updateAllButtonStates();
    renderChatList();
    pushHistoryState('history', null);
}

function renderHistoryPage() {
    var historyList = document.getElementById('history-list');
    var historyStats = document.getElementById('history-stats');
    var historySearchIcon = document.getElementById('history-search-icon');
    var historyDownloadIcon = document.getElementById('history-download-icon');

    // Initialize icons (burger icon is in HTML)
    if (historySearchIcon) historySearchIcon.innerHTML = UI_ICONS.search;
    if (historyDownloadIcon) historyDownloadIcon.innerHTML = UI_ICONS.download;

    if (!historyList) return;

    var q = historySearchQuery ? historySearchQuery.toLowerCase().trim() : '';
    var isSearching = q && q.length >= 2;

    // Get filtered chat IDs
    var chatIds = filterHistoryChats(historySearchQuery);
    var totalChats = Object.keys(chats).length;
    var filteredCount = chatIds.length;
    var pinnedCount = Object.keys(chats).filter(function(id) { return chats[id].pinned; }).length;
    var totalCost = Object.keys(chats).reduce(function(sum, id) {
        var chat = chats[id];
        if (!chat || !chat.messages) return sum;
        return sum + chat.messages.reduce(function(chatSum, msg) {
            return chatSum + ((msg.metrics && msg.metrics.cost) || 0);
        }, 0);
    }, 0);

    // Update stats
    if (historyStats) {
        if (isSearching) {
            historyStats.innerHTML = '<strong>' + filteredCount + '</strong> result' + (filteredCount !== 1 ? 's' : '') + ' for "' + escapeHtml(q) + '"';
        } else {
            var statsHtml = '<strong>' + totalChats + '</strong> conversation' + (totalChats !== 1 ? 's' : '');
            if (pinnedCount > 0) statsHtml += ' · <strong>' + pinnedCount + '</strong> pinned';
            if (totalCost > 0) statsHtml += ' · Total cost: <strong>$' + totalCost.toFixed(2) + '</strong>';
            historyStats.innerHTML = statsHtml;
        }
    }

    if (totalChats === 0 && !q) {
        historyList.innerHTML = '<div class="history-empty">' +
            '<div class="history-empty-icon">' + UI_ICONS.chat + '</div>' +
            '<div class="history-empty-title">No conversations yet</div>' +
            '<div class="history-empty-text">Start a new chat to begin</div>' +
            '</div>';
        return;
    }

    if (filteredCount === 0 && isSearching) {
        historyList.innerHTML = '<div class="history-empty">' +
            '<div class="history-empty-icon">' + UI_ICONS.search + '</div>' +
            '<div class="history-empty-title">No matching chats</div>' +
            '<div class="history-empty-text">Try a different search term</div>' +
            '</div>';
        return;
    }

    // Sort: pinned first, then by date (newest first) - same as sidebar
    var sortedChats = chatIds.map(function(id) { return chats[id]; }).sort(function(a, b) {
        if (a.pinned && !b.pinned) return -1;
        if (!a.pinned && b.pinned) return 1;
        return b.createdAt - a.createdAt;
    });

    // When searching, use sidebar's exact search result display (renderChatItem)
    if (isSearching) {
        // Temporarily set chatSearchQuery to use renderChatItem properly
        var oldQuery = chatSearchQuery;
        chatSearchQuery = historySearchQuery;
        historyList.innerHTML = sortedChats.map(function(c) {
            return renderChatItem(c);
        }).join('');
        chatSearchQuery = oldQuery;
    } else {
        // Normal view: use history chat cards
        historyList.innerHTML = sortedChats.map(function(c) {
            return renderHistoryChatCard(c.id);
        }).join('');
    }
}

function getChatStats(chatId) {
    var chat = chats[chatId];
    var stats = { toolCalls: 0, fileChanges: [], fileTables: [], widgetNames: [], hasDashboardWidget: false, model: '', cost: 0 };
    if (!chat || !chat.messages) return stats;

    // Get widgets from chat.widgets (persisted) or getWidgetsForChat
    var widgetList = getWidgetsForChat(chatId);
    stats.widgetNames = widgetList.map(function(w) { return w.title || w.name || 'Widget'; });

    // Check if any widget from this chat is on dashboard
    Object.keys(dashboardWidgets || {}).forEach(function(dwId) {
        var dw = dashboardWidgets[dwId];
        if (dw.chatId === chatId) {
            stats.hasDashboardWidget = true;
        }
    });

    // Get files from chat.versionHistory (persisted per chat)
    var chatVersionHistory = chat.versionHistory || [];
    var filesMap = {};
    chatVersionHistory.forEach(function(v) {
        if (v.action !== 'REVERT' && v.action !== 'USER_DELETE' && !v.invalidated) {
            var key = v.table + '_' + v.sysId;
            if (!filesMap[key]) {
                filesMap[key] = { name: v.displayName, table: v.table };
            }
        }
    });
    var filesArr = Object.values(filesMap);
    stats.fileChanges = filesArr.map(function(f) { return f.name; });
    stats.fileTables = filesArr.map(function(f) { return f.table; });

    // Loop through messages for tool calls, model and cost from metrics
    chat.messages.forEach(function(msg) {
        if (msg.role === 'assistant') {
            if (msg.tool_calls) {
                stats.toolCalls += msg.tool_calls.length;
            }
            // Get model and cost from metrics
            if (msg.metrics) {
                if (msg.metrics.actualModel && !stats.model) {
                    stats.model = msg.metrics.actualModel;
                }
                if (msg.metrics.cost) {
                    stats.cost += msg.metrics.cost;
                }
            }
        }
    });

    return stats;
}

function renderHistoryChatCard(chatId) {
    var chat = chats[chatId];
    if (!chat) return '';

    var title = chat.title || 'Untitled Chat';
    var preview = getHistoryChatPreview(chat);
    var messageCount = chat.messages ? chat.messages.length : 0;
    var dateStr = formatHistoryDate(chat.updatedAt || chat.createdAt);
    var isActive = chatId === currentChatId;
    var stats = getChatStats(chatId);
    var contextLength = getContextLength(chat);

    // Badges
    var badgesHtml = '';
    if (chat.pinned) badgesHtml += '<span class="history-chat-badge pinned">' + UI_ICONS.pinFilled + 'Pinned</span>';
    if (stats.hasDashboardWidget) badgesHtml += '<span class="history-chat-badge dashboard">' + UI_ICONS.widget + 'Dashboard</span>';

    // Action buttons - pin button is bold when pinned
    var pinBtnClass = chat.pinned ? 'history-chat-action-btn pinned' : 'history-chat-action-btn';
    var actionsHtml = '<div class="history-chat-actions">' +
        '<button class="history-chat-action-btn" onclick="event.stopPropagation(); openRenameModal(\'' + chatId + '\')" title="Rename">' + UI_ICONS.edit + '</button>' +
        '<button class="' + pinBtnClass + '" onclick="event.stopPropagation(); togglePinChat(\'' + chatId + '\'); renderHistoryPage();" title="' + (chat.pinned ? 'Unpin' : 'Pin') + '">' + (chat.pinned ? UI_ICONS.pinFilled : UI_ICONS.pin) + '</button>' +
        '<button class="history-chat-action-btn" onclick="event.stopPropagation(); exportChatFromHistory(\'' + chatId + '\')" title="Export">' + UI_ICONS.download + '</button>' +
        '<button class="history-chat-action-btn danger" onclick="event.stopPropagation(); deleteChat(\'' + chatId + '\', event)" title="Delete">' + UI_ICONS.trash + '</button>' +
        '</div>';

    // Stats row with message count and tools
    var statsHtml = '<div class="history-chat-stats">';
    statsHtml += '<span class="history-chat-stat">' + UI_ICONS.chat + messageCount + ' msg</span>';
    if (stats.toolCalls > 0) statsHtml += '<span class="history-chat-stat">' + UI_ICONS.tool + stats.toolCalls + ' tools</span>';
    // Widget tags inline
    stats.widgetNames.slice(0, 3).forEach(function(name) {
        statsHtml += '<span class="history-chat-stat widgets">' + UI_ICONS.widget + escapeHtml(name) + '</span>';
    });
    if (stats.widgetNames.length > 3) statsHtml += '<span class="history-chat-stat widgets">+' + (stats.widgetNames.length - 3) + '</span>';
    // File tags inline with proper icons from table
    stats.fileChanges.slice(0, 3).forEach(function(name, idx) {
        var table = stats.fileTables[idx] || '';
        statsHtml += '<span class="history-chat-stat files">' + getTableIcon(table) + escapeHtml(name) + '</span>';
    });
    if (stats.fileChanges.length > 3) statsHtml += '<span class="history-chat-stat files">+' + (stats.fileChanges.length - 3) + '</span>';
    statsHtml += '</div>';

    // Preview with user message and Agent answer
    var previewHtml = '<div class="history-chat-preview-area" onclick="openChatFromHistory(\'' + chatId + '\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \')openChatFromHistory(\'' + chatId + '\')" role="button" tabindex="0" aria-label="Open chat: ' + escapeHtml(title) + '">';
    if (preview.user) {
        previewHtml += '<div class="history-preview-msg user"><span class="history-preview-label">' + UI_ICONS.user + 'You:</span><span class="history-preview-text">' + escapeHtml(preview.user) + '</span></div>';
    }
    if (preview.assistant) {
        previewHtml += '<div class="history-preview-msg assistant"><span class="history-preview-label">' + UI_ICONS.bot + 'Agent:</span><span class="history-preview-text">' + escapeHtml(preview.assistant) + '</span></div>';
    }
    previewHtml += '</div>';

    // Meta row with date, context, cost, then model (inside card at bottom)
    var metaHtml = '<div class="history-chat-meta">';
    metaHtml += '<span>' + UI_ICONS.clock + dateStr + '</span>';
    if (contextLength > 0) metaHtml += '<span>' + formatContextLength(contextLength) + '</span>';
    if (stats.cost > 0) {
        var costStr = stats.cost < 0.01 ? stats.cost.toFixed(4) : stats.cost.toFixed(2);
        metaHtml += '<span class="history-meta-cost">' + UI_ICONS.money + '$' + costStr + '</span>';
    }
    if (stats.model) metaHtml += '<span class="history-meta-model">' + UI_ICONS.model + stats.model + '</span>';
    metaHtml += '</div>';

    return '<div class="history-chat-card' + (isActive ? ' active' : '') + '">' +
        '<div class="history-chat-header">' +
        '<div class="history-chat-title-row" onclick="openChatFromHistory(\'' + chatId + '\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \')openChatFromHistory(\'' + chatId + '\')" role="button" tabindex="0">' +
        '<span class="history-chat-title">' + escapeHtml(title) + '</span>' +
        '<div class="history-chat-badges">' + badgesHtml + '</div>' +
        '</div>' + actionsHtml + '</div>' +
        previewHtml +
        statsHtml +
        metaHtml +
        '</div>';
}

function getHistoryChatPreview(chat) {
    if (!chat.messages || chat.messages.length === 0) return { user: '', assistant: '' };

    var userMsg = '';
    var assistantMsg = '';

    // Find first user message
    for (var i = 0; i < chat.messages.length; i++) {
        var msg = chat.messages[i];
        if (msg.role === 'user' && typeof msg.content === 'string' && msg.content.trim()) {
            userMsg = msg.content;
            break;
        }
    }

    // Find first assistant message after user message
    for (var j = 0; j < chat.messages.length; j++) {
        var msg = chat.messages[j];
        if (msg.role === 'assistant' && typeof msg.content === 'string' && msg.content.trim()) {
            assistantMsg = msg.content;
            break;
        }
    }

    return { user: userMsg, assistant: assistantMsg };
}

function getContextLength(chat) {
    if (!chat.messages) return 0;
    var total = 0;
    chat.messages.forEach(function(msg) {
        if (typeof msg.content === 'string') total += estimateTokens(msg.content);
        if (msg.tool_calls) {
            msg.tool_calls.forEach(function(tc) {
                if (tc.function && tc.function.arguments) total += estimateTokens(tc.function.arguments);
            });
        }
    });
    return total;
}

function formatContextLength(tokens) {
    if (tokens < 1000) return tokens + ' tokens';
    if (tokens < 1000000) return (tokens / 1000).toFixed(1) + 'K tokens';
    return (tokens / 1000000).toFixed(2) + 'M tokens';
}

function formatHistoryDate(timestamp) {
    if (!timestamp) return 'Unknown';
    var date = new Date(timestamp);
    var now = new Date();
    var diffMs = now - date;
    var diffMins = Math.floor(diffMs / 60000);
    var diffHours = Math.floor(diffMs / 3600000);
    var diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return diffMins + 'm ago';
    if (diffHours < 24) return diffHours + 'h ago';
    if (diffDays < 7) return diffDays + 'd ago';
    return date.toLocaleDateString();
}

function openChatFromHistory(chatId) {
    if (!chats[chatId]) return;
    currentChatId = chatId;
    appStorage.setItem('currentChatId', chatId);
    appStorage.setItem('lastChatId', chatId);
    currentView = 'chat';
    appStorage.setItem('currentView', 'chat');
    hideAllPanels();
    showChatView();
    clearUpdateSet();
    loadVersionHistory();
    renderMessages();
    updateInputPosition();
    updateChatTitleHeader();
    updateAllButtonStates();
    renderChatList();
    pushHistoryState('chat', chatId);
}

var historySearchQuery = '';
var historySearchDebounceTimer = null;

function handleHistorySearch(e) {
    var value = e.target.value;

    // Debounce the search
    if (historySearchDebounceTimer) {
        clearTimeout(historySearchDebounceTimer);
    }

    historySearchDebounceTimer = setTimeout(function() {
        historySearchQuery = value;
        renderHistoryPage();
    }, 250);
}

function filterHistoryChats(query) {
    var q = (query || '').toLowerCase().trim();
    if (!q || q.length < 2) return Object.keys(chats);

    return Object.keys(chats).filter(function(id) {
        var chat = chats[id];
        return chatMatchesSearch(chat, q);
    });
}

function clearHistorySearch() {
    historySearchQuery = '';
    var input = document.getElementById('history-search-input');
    if (input) {
        input.value = '';
    }
    renderHistoryPage();
}

function exportChatFromHistory(chatId) {
    var chat = chats[chatId];
    if (!chat) return;
    var exportData = {
        title: chat.title || 'Untitled Chat',
        messages: chat.messages || [],
        createdAt: chat.createdAt,
        updatedAt: chat.updatedAt,
        model: chat.model,
        totalCost: chat.totalCost
    };
    var blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = (chat.title || 'chat').replace(/[^a-z0-9]/gi, '_') + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showSnackbar('Chat exported', 'success');
}

function downloadChatHistory() {
    var exportData = {
        exportedAt: new Date().toISOString(),
        totalChats: Object.keys(chats).length,
        chats: {}
    };
    Object.keys(chats).forEach(function(chatId) {
        var chat = chats[chatId];
        exportData.chats[chatId] = {
            title: chat.title || 'Untitled Chat',
            messages: chat.messages || [],
            createdAt: chat.createdAt,
            updatedAt: chat.updatedAt,
            model: chat.model,
            totalCost: chat.totalCost,
            pinned: chat.pinned
        };
    });
    var blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'appagent_chat_history_' + new Date().toISOString().split('T')[0] + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showSnackbar('Chat history exported (' + Object.keys(chats).length + ' chats)', 'success');
}

// Documentation View Management
function toggleDocsView() {
    if (currentView === 'docs') return;
    openDocsView();
}

function openDocsView() {
    currentView = 'docs';
    appStorage.setItem('currentView', 'docs');
    hideAllPanels();
    var docsPanel = document.getElementById('docs-panel');
    if (docsPanel) { docsPanel.style.display = 'flex'; renderDocsPage(); }
    updateAllButtonStates();
    renderChatList();
    // Push browser history state
    pushHistoryState('docs', null);
}

function downloadDocsAsMarkdown() {
    var docsContent = document.getElementById('docs-content');
    if (!docsContent) return;

    // Convert HTML to Markdown
    var markdown = '# AppAgent Documentation\n\n';
    var sections = docsContent.querySelectorAll('.docs-section');

    sections.forEach(function(section) {
        var h1 = section.querySelector('h1');
        var h2 = section.querySelector('h2');

        if (h1) {
            markdown += '## ' + h1.textContent.trim() + '\n\n';
        } else if (h2) {
            markdown += '### ' + h2.textContent.trim() + '\n\n';
        }

        var paragraphs = section.querySelectorAll('p');
        paragraphs.forEach(function(p) {
            markdown += p.textContent.trim() + '\n\n';
        });

        var lists = section.querySelectorAll('ul, ol');
        lists.forEach(function(list) {
            var items = list.querySelectorAll('li');
            var isOrdered = list.tagName === 'OL';
            items.forEach(function(item, idx) {
                var prefix = isOrdered ? (idx + 1) + '. ' : '- ';
                markdown += prefix + item.textContent.trim() + '\n';
            });
            markdown += '\n';
        });

        var tables = section.querySelectorAll('table');
        tables.forEach(function(table) {
            var rows = table.querySelectorAll('tr');
            rows.forEach(function(row, rowIdx) {
                var cells = row.querySelectorAll('th, td');
                var rowContent = '| ';
                cells.forEach(function(cell) {
                    rowContent += cell.textContent.trim() + ' | ';
                });
                markdown += rowContent + '\n';
                if (rowIdx === 0) {
                    markdown += '|' + ' --- |'.repeat(cells.length) + '\n';
                }
            });
            markdown += '\n';
        });

        var codeBlocks = section.querySelectorAll('pre.docs-code');
        codeBlocks.forEach(function(code) {
            markdown += '```\n' + code.textContent.trim() + '\n```\n\n';
        });

        var tips = section.querySelectorAll('.docs-tip');
        tips.forEach(function(tip) {
            markdown += '> **Tip:** ' + tip.textContent.trim() + '\n\n';
        });
    });

    var blob = new Blob([markdown], { type: 'text/markdown' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'appagent-documentation.md';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showSnackbar('Documentation downloaded', 'success');
}

