function scrollToDocSection(id) {
    var el = document.getElementById(id);
    if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    return false;
}

function openDashboardView() {
    currentView = 'dashboard';
    appStorage.setItem('currentView', 'dashboard');
    currentEditingWidget = null;
    hideAllPanels();
    var dashboardPanel = document.getElementById('dashboard-panel');
    if (dashboardPanel) { dashboardPanel.style.display = 'flex'; renderDashboard(); }
    // Update headers toggle button state based on loaded preference
    var headersBtn = document.getElementById('dashboard-toggle-headers-btn');
    if (headersBtn) headersBtn.classList.toggle('active', showDashboardHeaders);
    updateAllButtonStates();
    renderChatList(); // Update sidebar to deselect chat
    // Push browser history state
    pushHistoryState('dashboard', null);
    // Setup responsive actions
    setupDashboardResponsive();
}

function closeDashboardView() {
    currentView = 'chat';
    appStorage.setItem('currentView', 'chat');
    currentEditingWidget = null;
    activeWidgetStreamingId = null;
    var dashboardPanel = document.getElementById('dashboard-panel');
    showChatView();
    if (dashboardPanel) dashboardPanel.style.display = 'none';
    updateDashboardButtonState();
    if (activeStreamingChatId && currentChatId === activeStreamingChatId) {
        renderMessages();
    }
}

function updateDashboardButtonState() {
    var dashboardPanel = document.getElementById('dashboard-panel');
    var btn = document.getElementById('dashboard-btn');
    var isOpen = dashboardPanel && dashboardPanel.style.display === 'flex';
    if (btn) btn.classList.toggle('active', isOpen);
}

var dashboardRenderGeneration = 0; // Track render generation to cancel stale callbacks

function renderDashboard() {
    var container = document.getElementById('dashboard-grid');
    if (!container) return;

    // Increment generation to invalidate any pending render callbacks
    dashboardRenderGeneration++;
    var currentGeneration = dashboardRenderGeneration;

    var widgetList = Object.values(dashboardWidgets);
    if (widgetList.length === 0) {
        container.innerHTML = '<div class="dashboard-empty"><span class="dashboard-empty-icon">' + UI_ICONS.widget + '</span><p>No widgets yet</p><p class="dashboard-empty-hint">Add widgets to your dashboard using prompts.</p></div>';
        return;
    }

    // Migrate widgets from order-based to grid-based positioning if needed
    migrateWidgetPositions();

    var html = '';
    widgetList.forEach(function(widget) {
        html += buildWidgetHtml(widget);
    });

    container.innerHTML = html;

    // Apply show-headers class if enabled
    if (showDashboardHeaders) {
        container.classList.add('show-headers');
    } else {
        container.classList.remove('show-headers');
    }

    // Render widget content synchronously using requestAnimationFrame for proper timing
    requestAnimationFrame(function() {
        // Check if this render is still current
        if (currentGeneration !== dashboardRenderGeneration) return;

        widgetList.forEach(function(widget) {
            if (!widget.isLoading) {
                renderWidgetContent(widget);
            }
        });
    });
}

// Toggle dashboard headers visibility
function toggleDashboardHeaders() {
    showDashboardHeaders = !showDashboardHeaders;
    appStorage.setItem('showDashboardHeaders', showDashboardHeaders);
    var grid = document.getElementById('dashboard-grid');
    var btn = document.getElementById('dashboard-toggle-headers-btn');
    if (grid) {
        grid.classList.toggle('show-headers', showDashboardHeaders);
    }
    if (btn) {
        btn.classList.toggle('active', showDashboardHeaders);
    }
}

// Dashboard responsive More menu
function toggleDashboardMoreMenu(e) {
    e.stopPropagation();
    var dropdown = document.getElementById('dashboard-more-dropdown');
    if (dropdown) {
        dropdown.classList.toggle('show');
        if (dropdown.classList.contains('show')) {
            // Close on click outside
            setTimeout(function() {
                document.addEventListener('click', closeDashboardMoreMenu, { once: true });
            }, 0);
        }
    }
}

function closeDashboardMoreMenu() {
    var dropdown = document.getElementById('dashboard-more-dropdown');
    if (dropdown) dropdown.classList.remove('show');
}

// Check if dashboard actions should collapse
function checkDashboardActionsOverflow() {
    var container = document.getElementById('dashboard-actions');
    if (!container) return;

    // Temporarily uncollapse to measure
    container.classList.remove('collapsed');

    // Check if content overflows (with some buffer)
    var header = container.closest('.dashboard-header');
    if (header) {
        var availableWidth = header.clientWidth - 200; // Reserve space for sidebar btn + title
        var actionsWidth = container.scrollWidth;

        if (actionsWidth > availableWidth - 20) {
            container.classList.add('collapsed');
        }
    }
}

// Setup dashboard responsive observer
var dashboardResizeObserver = null;
function setupDashboardResponsive() {
    var header = document.querySelector('.dashboard-header');
    if (!header || dashboardResizeObserver) return;

    dashboardResizeObserver = new ResizeObserver(function() {
        checkDashboardActionsOverflow();
    });
    dashboardResizeObserver.observe(header);
    checkDashboardActionsOverflow();
}

// Expand widget to fullscreen
function expandDashboardWidget(widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget) return;

    expandedWidgetId = widgetId;

    var overlay = document.createElement('div');
    overlay.className = 'widget-fullscreen-overlay';
    overlay.id = 'widget-fullscreen-overlay';
    overlay.onclick = function(e) { if (e.target === overlay) closeExpandedWidget(); };

    var modal = document.createElement('div');
    modal.className = 'widget-fullscreen-modal';

    var header = document.createElement('div');
    header.className = 'widget-fullscreen-header';
    header.innerHTML = '<span class="widget-icon">' + UI_ICONS.widget + '</span>' +
        '<span class="widget-title">' + escapeHtml(widget.title || 'Untitled') + '</span>' +
        '<div class="widget-modal-controls">' +
        '<button class="widget-modal-btn" onclick="closeExpandedWidget();regenerateDashboardWidget(\'' + widgetId + '\')" title="Regenerate">' + UI_ICONS.refresh + '</button>' +
        '<button class="widget-modal-btn" onclick="closeExpandedWidget();editDashboardWidget(\'' + widgetId + '\')" title="Edit">' + UI_ICONS.edit + '</button>' +
        '<button class="widget-modal-btn danger" onclick="closeExpandedWidget();confirmDeleteDashboardWidget(\'' + widgetId + '\')" title="Delete">' + UI_ICONS.trash + '</button>' +
        '<button class="widget-close-btn" onclick="closeExpandedWidget()" title="Close">' + UI_ICONS.close + '</button>' +
        '</div>';

    var content = document.createElement('div');
    content.className = 'widget-fullscreen-content';
    content.id = 'widget-fullscreen-content';

    modal.appendChild(header);
    modal.appendChild(content);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    // Render widget in fullscreen
    if (widget.html) {
        var iframe = document.createElement('iframe');
        iframe.style.cssText = 'width:100%;height:100%;border:none;background:#fff;';
        iframe.sandbox = 'allow-scripts allow-same-origin allow-forms';
        content.appendChild(iframe);

        var doc = iframe.contentDocument || iframe.contentWindow.document;
        doc.open();
        doc.write(injectWidgetBridge(widget.html, widget.title));
        doc.close();
    }
}

function closeExpandedWidget() {
    expandedWidgetId = null;
    var overlay = document.getElementById('widget-fullscreen-overlay');
    if (overlay) overlay.remove();
}

// Grid occupancy and collision detection functions
function initGridOccupancy() {
    gridState.occupancy = {};
    Object.values(dashboardWidgets).forEach(function(widget) {
        if (widget.gridX !== undefined && widget.gridY !== undefined) {
            markOccupied(widget.id, widget.gridX, widget.gridY, widget.width || 4, widget.height || 4);
        }
    });
}

function markOccupied(widgetId, x, y, w, h) {
    for (var row = y; row < y + h; row++) {
        for (var col = x; col < x + w; col++) {
            var key = row + ',' + col;
            gridState.occupancy[key] = widgetId;
        }
    }
}

function checkCollision(x, y, w, h, excludeWidgetId) {
    var collisions = [];
    for (var row = y; row < y + h; row++) {
        for (var col = x; col < x + w; col++) {
            if (col < 0 || col >= 12) continue; // Out of grid bounds
            var key = row + ',' + col;
            var occupant = gridState.occupancy[key];
            if (occupant && occupant !== excludeWidgetId && collisions.indexOf(occupant) === -1) {
                collisions.push(occupant);
            }
        }
    }
    return collisions;
}

function updateWidgetPosition(widgetId) {
    var widget = dashboardWidgets[widgetId];
    var el = document.querySelector('.dashboard-widget[data-widget-id="' + widgetId + '"]');
    if (!widget || !el) return;

    var width = widget.width || 4;
    var height = widget.height || 4;
    var zIndex = widget.zIndex || 1;

    el.style.gridColumn = (widget.gridX + 1) + ' / span ' + width;
    el.style.gridRow = (widget.gridY + 1) + ' / span ' + height;
    el.style.zIndex = zIndex;
}

function findNextAvailablePosition(w, h) {
    // Scan grid row by row to find first available position
    for (var y = 0; y < 1000; y++) {
        for (var x = 0; x <= 12 - w; x++) {
            var collisions = checkCollision(x, y, w, h, null);
            if (collisions.length === 0) {
                return { gridX: x, gridY: y };
            }
        }
    }
    return { gridX: 0, gridY: 0 }; // Fallback
}

function migrateWidgetPositions() {
    var widgets = Object.values(dashboardWidgets)
        .filter(function(w) { return w.gridX === undefined || w.gridY === undefined; })
        .sort(function(a, b) { return (a.order || 0) - (b.order || 0); });

    if (widgets.length === 0) return;

    // Initialize occupancy for already migrated widgets
    initGridOccupancy();

    widgets.forEach(function(widget) {
        var w = widget.width || 4;
        var h = widget.height || 4;
        var pos = findNextAvailablePosition(w, h);
        widget.gridX = pos.gridX;
        widget.gridY = pos.gridY;
        markOccupied(widget.id, pos.gridX, pos.gridY, w, h);
        saveDashboardWidget(widget);
    });
}

// Drag and drop with grid-based positioning
var currentDragWidgetId = null;

function handleWidgetDragStart(event, widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget) return;

    currentDragWidgetId = widgetId;
    gridState.draggedWidgetId = widgetId;

    // Disable pointer events on all widget content to prevent iframe capturing mouse
    var allWidgetContents = document.querySelectorAll('.dashboard-widget-content');
    allWidgetContents.forEach(function(el) {
        el.style.pointerEvents = 'none';
    });

    // Store where user grabbed the widget (offset from widget's top-left)
    var widgetEl = event.target.closest('.dashboard-widget');
    if (widgetEl) {
        var rect = widgetEl.getBoundingClientRect();
        gridState.dragOffset = {
            x: event.clientX - rect.left,
            y: event.clientY - rect.top
        };
        widgetEl.classList.add('dragging');
    }

    event.dataTransfer.setData('text/plain', widgetId);
    event.dataTransfer.effectAllowed = 'move';
}

function handleWidgetDragOver(event) {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
}

function handleWidgetDrop(event) {
    event.preventDefault();

    if (!gridState.draggedWidgetId) return;

    var widget = dashboardWidgets[gridState.draggedWidgetId];
    if (!widget) return;

    // Calculate drop position accounting for grab offset
    var grid = document.getElementById('dashboard-grid');
    if (!grid) return;

    var gridRect = grid.getBoundingClientRect();
    var scrollTop = grid.scrollTop;

    // Adjust mouse position by grab offset to get widget's top-left position
    var offsetX = gridState.dragOffset ? gridState.dragOffset.x : 0;
    var offsetY = gridState.dragOffset ? gridState.dragOffset.y : 0;

    var widgetLeft = event.clientX - offsetX - gridRect.left;
    var widgetTop = event.clientY - offsetY - gridRect.top + scrollTop;

    // Calculate grid cell dimensions
    var cellWidth = (gridRect.width - 32 - (11 * gridState.gap)) / 12;
    var cellHeight = gridState.rowHeight + gridState.gap;

    // Snap to grid
    var gridX = Math.round((widgetLeft - 16) / (cellWidth + gridState.gap));
    var gridY = Math.round((widgetTop - 16) / cellHeight);

    // Clamp to bounds
    var w = widget.width || 4;
    gridX = Math.max(0, Math.min(12 - w, gridX));
    gridY = Math.max(0, gridY);

    // Update position and bring to front
    widget.gridX = gridX;
    widget.gridY = gridY;
    gridState.maxZIndex++;
    widget.zIndex = gridState.maxZIndex;

    // Update visual and save
    updateWidgetPosition(widget.id);
    saveDashboardWidget(widget);

    // Clean up
    gridState.draggedWidgetId = null;
    gridState.dragOffset = null;
    currentDragWidgetId = null;
}

function handleWidgetDragEnd(event) {
    var widgetEl = event.target.closest('.dashboard-widget');
    if (widgetEl) widgetEl.classList.remove('dragging');

    // Restore pointer events on all widget content
    var allWidgetContents = document.querySelectorAll('.dashboard-widget-content');
    allWidgetContents.forEach(function(el) {
        el.style.pointerEvents = '';
    });

    // Clean up
    gridState.draggedWidgetId = null;
    gridState.dragOffset = null;
    currentDragWidgetId = null;
}

function buildWidgetHtml(widget) {
    // Grid-based positioning
    var width = Math.max(3, widget.width || 4);
    var height = Math.max(2, widget.height || 4);
    var gridX = widget.gridX !== undefined ? widget.gridX : 0;
    var gridY = widget.gridY !== undefined ? widget.gridY : 0;
    var zIndex = widget.zIndex || 1;

    // Track max z-index for new widgets
    if (zIndex > gridState.maxZIndex) {
        gridState.maxZIndex = zIndex;
    }

    // Build grid position style
    var gridColStyle = (gridX + 1) + ' / span ' + width;
    var gridRowStyle = (gridY + 1) + ' / span ' + height;

    var errorClass = widget.error ? ' widget-error' : '';
    var loadingClass = widget.isLoading ? ' widget-loading' : '';
    var errorBadge = widget.error ? '<span class="widget-error-badge" title="' + escapeHtml(widget.error) + '">Error</span>' : '';
    var loadingOverlay = widget.isLoading ? '<div class="widget-loading-overlay"><div class="widget-spinner"></div><span>Generating...</span></div>' : '';

    var html = '<div class="dashboard-widget' + errorClass + loadingClass + '" data-widget-id="' + widget.id + '" draggable="true" ';
    html += 'ondragstart="handleWidgetDragStart(event, \'' + widget.id + '\')" ';
    html += 'ondragover="handleWidgetDragOver(event)" ';
    html += 'ondrop="handleWidgetDrop(event)" ';
    html += 'ondragend="handleWidgetDragEnd(event)" ';
    html += 'style="grid-column: ' + gridColStyle + '; grid-row: ' + gridRowStyle + '; z-index: ' + zIndex + ';">';
    html += '<div class="dashboard-widget-header">';
    html += '<span class="dashboard-widget-icon drag-handle">' + UI_ICONS.widget + '</span>';
    html += '<span class="dashboard-widget-title">' + escapeHtml(widget.title || 'Untitled') + '</span>';
    html += errorBadge;
    html += '<div class="dashboard-widget-controls">';
    html += '<button class="dashboard-widget-btn widget-stop-btn" data-widget-id="' + widget.id + '" onclick="toggleWidgetRunning(\'' + widget.id + '\', event)" title="' + (widget.deactivated ? 'Activate Widget' : 'Deactivate Widget') + '">' + (widget.deactivated ? UI_ICONS.play : UI_ICONS.stop) + '</button>';
    html += '<button class="dashboard-widget-btn" onclick="event.stopPropagation();regenerateDashboardWidget(\'' + widget.id + '\')" title="Regenerate">' + UI_ICONS.refresh + '</button>';
    if (widget.history && widget.history.length > 0) {
        html += '<button class="dashboard-widget-btn" onclick="event.stopPropagation();showWidgetHistory(\'' + widget.id + '\')" title="History (' + widget.history.length + ')">' + UI_ICONS.history + '</button>';
    }
    html += '<button class="dashboard-widget-btn" onclick="event.stopPropagation();expandDashboardWidget(\'' + widget.id + '\')" title="Fullscreen">' + UI_ICONS.maximize + '</button>';
    html += '<button class="dashboard-widget-btn" onclick="event.stopPropagation();editDashboardWidget(\'' + widget.id + '\')" title="Edit">' + UI_ICONS.edit + '</button>';
    html += '<button class="dashboard-widget-btn danger" onclick="event.stopPropagation();confirmDeleteDashboardWidget(\'' + widget.id + '\')" title="Delete">' + UI_ICONS.trash + '</button>';
    html += '</div>';
    html += '</div>';
    html += '<div class="dashboard-widget-content" id="dashboard-widget-content-' + widget.id + '">' + loadingOverlay + '</div>';
    html += '<div class="dashboard-widget-resize-handle" onmousedown="startWidgetResize(event, \'' + widget.id + '\')"></div>';
    html += '</div>';
    return html;
}

// Corner resize handling with grid snapping
function startWidgetResize(event, widgetId) {
    event.preventDefault();
    event.stopPropagation();

    var widget = dashboardWidgets[widgetId];
    if (!widget) return;

    var widgetEl = document.querySelector('.dashboard-widget[data-widget-id="' + widgetId + '"]');
    if (!widgetEl) return;

    // Disable pointer events on all widget content to prevent iframe capturing mouse
    var allWidgetContents = document.querySelectorAll('.dashboard-widget-content');
    allWidgetContents.forEach(function(el) {
        el.style.pointerEvents = 'none';
    });

    widgetDragState = {
        widgetId: widgetId,
        startX: event.clientX,
        startY: event.clientY,
        startWidth: widget.width || 4,
        startHeight: widget.height || 4,
        gridX: widget.gridX,
        gridY: widget.gridY
    };

    document.addEventListener('mousemove', handleWidgetResizeMove);
    document.addEventListener('mouseup', handleWidgetResizeEnd);
    document.body.style.cursor = 'nwse-resize';
    document.body.style.userSelect = 'none';
}

function handleWidgetResizeMove(event) {
    if (!widgetDragState) return;

    var widgetEl = document.querySelector('.dashboard-widget[data-widget-id="' + widgetDragState.widgetId + '"]');
    if (!widgetEl) return;

    // Get the dashboard grid for calculating units
    var grid = document.getElementById('dashboard-grid');
    if (!grid) return;

    var gridRect = grid.getBoundingClientRect();
    var cellWidth = (gridRect.width - 32 - (11 * gridState.gap)) / 12;
    var cellHeight = gridState.rowHeight;

    // Calculate new size based on mouse position
    var dx = event.clientX - widgetDragState.startX;
    var dy = event.clientY - widgetDragState.startY;

    // Calculate new dimensions in grid units
    var startPixelWidth = widgetDragState.startWidth * cellWidth + (widgetDragState.startWidth - 1) * gridState.gap;
    var startPixelHeight = widgetDragState.startHeight * cellHeight + (widgetDragState.startHeight - 1) * gridState.gap;

    var newPixelWidth = startPixelWidth + dx;
    var newPixelHeight = startPixelHeight + dy;

    // Snap to grid units
    var newWidthUnits = Math.max(3, Math.round(newPixelWidth / (cellWidth + gridState.gap)));
    var newHeightUnits = Math.max(2, Math.round(newPixelHeight / (cellHeight + gridState.gap)));

    // Clamp width so widget doesn't go off right edge
    var maxWidth = 12 - widgetDragState.gridX;
    newWidthUnits = Math.min(newWidthUnits, maxWidth);

    // Apply size using grid span
    widgetEl.style.gridColumn = (widgetDragState.gridX + 1) + ' / span ' + newWidthUnits;
    widgetEl.style.gridRow = (widgetDragState.gridY + 1) + ' / span ' + newHeightUnits;

    // Store the new units for saving
    widgetDragState.newWidth = newWidthUnits;
    widgetDragState.newHeight = newHeightUnits;
}

function handleWidgetResizeEnd(event) {
    // Re-enable pointer events on all widget content
    var allWidgetContents = document.querySelectorAll('.dashboard-widget-content');
    allWidgetContents.forEach(function(el) {
        el.style.pointerEvents = '';
    });

    if (widgetDragState) {
        var widget = dashboardWidgets[widgetDragState.widgetId];

        if (widget && widgetDragState.newWidth !== undefined && widgetDragState.newHeight !== undefined) {
            widget.width = widgetDragState.newWidth;
            widget.height = widgetDragState.newHeight;
            saveDashboardWidget(widget);

            // Update position in DOM
            updateWidgetPosition(widget.id);
        }
    }

    widgetDragState = null;
    document.removeEventListener('mousemove', handleWidgetResizeMove);
    document.removeEventListener('mouseup', handleWidgetResizeEnd);
    document.body.style.cursor = '';
    document.body.style.userSelect = '';
}

// Inject executeTool bridge into widget HTML before </head> tag
function injectWidgetBridge(html, widgetTitle) {
    var safeTitle = (widgetTitle || 'Widget').replace(/'/g, "\\'").replace(/"/g, '\\"');
    var bridgeScript = '<script>' +
        'window._widgetTitle="' + safeTitle + '";' +
        // executeTool bridge - allows widgets to call agent tools via postMessage
        'window._toolCallbacks={};' +
        'window._toolCallId=0;' +
        'window.executeTool=function(name,args){' +
            'return new Promise(function(resolve,reject){' +
                'var id="tc_"+(++window._toolCallId)+"_"+Date.now();' +
                'window._toolCallbacks[id]={resolve:resolve,reject:reject};' +
                'window.parent.postMessage({type:"widgetToolCall",id:id,name:name,args:args,widgetName:window._widgetTitle},"*");' +
            '});' +
        '};' +
        'window.addEventListener("message",function(e){' +
            'if(e.data&&e.data.type==="widgetToolResult"&&window._toolCallbacks[e.data.id]){' +
                'var cb=window._toolCallbacks[e.data.id];' +
                'delete window._toolCallbacks[e.data.id];' +
                'if(e.data.error)cb.reject(new Error(e.data.error));' +
                'else cb.resolve(e.data.result);' +
            '}' +
        '});' +
    '<\/script>';
    var result = html.replace(/<\/head>/i, bridgeScript + '</head>');
    if (result === html) {
        result = bridgeScript + html;
    }
    return result;
}

// Listen for tool calls from widgets via postMessage (embedded widgets)
window.addEventListener('message', async function(event) {
    if (event.data && event.data.type === 'widgetToolCall') {
        var id = event.data.id;
        var name = event.data.name;
        var args = event.data.args || {};
        var widgetName = event.data.widgetName || 'Widget';

        try {
            // executeTool checks permissions via requestProgrammaticToolApproval
            // For programmatic calls, approval uses notifications (not renderMessages) to preserve widget iframe
            var result = await executeTool(name, args, null, { chatId: currentChatId, widgetName: widgetName });

            // Persist screenshot to chat.screenshots map so screenshot_by_id can find it after reload
            // (NOT chat.messages — inserting there breaks tool_use/tool_result ordering for the API)
            if (result && result._screenshotMessage) {
                var ssMsg = result._screenshotMessage;
                if (ssMsg.screenshot_id) {
                    var ssChat = chats[currentChatId];
                    if (ssChat) {
                        if (!ssChat.screenshots) ssChat.screenshots = {};
                        ssChat.screenshots[ssMsg.screenshot_id] = { base64: ssMsg.base64, name: ssMsg.name, width: ssMsg.width, height: ssMsg.height, timestamp: ssMsg.timestamp, description: ssMsg.description };
                        saveChatsToStorage();
                    }
                }
                result.base64 = ssMsg.base64;
                result.width = ssMsg.width;
                result.height = ssMsg.height;
                result.screenshot_id = ssMsg.screenshot_id || result.screenshot_id;
                delete result._screenshotMessage;
            }

            if (result && result.success === false && result.error) {
                event.source.postMessage({ type: 'widgetToolResult', id: id, error: result.error }, '*');
            } else {
                event.source.postMessage({ type: 'widgetToolResult', id: id, result: result }, '*');
            }
        } catch (e) {
            event.source.postMessage({ type: 'widgetToolResult', id: id, error: e.message }, '*');
        }
    }
});

function renderWidgetContent(widget) {
    // Use dashboard-specific ID to avoid conflict with chat widget containers
    var container = document.getElementById('dashboard-widget-content-' + widget.id);
    if (!container) {
        console.warn('Dashboard widget container not found:', 'dashboard-widget-content-' + widget.id);
        return;
    }
    if (!widget.html) {
        console.warn('Widget has no HTML:', widget);
        container.innerHTML = '<div style="padding:20px;color:#888;text-align:center;">No content available. Try regenerating.</div>';
        return;
    }

    // Create shadow DOM for isolation
    var shadowHost = document.createElement('div');
    shadowHost.className = 'widget-shadow-host';
    container.innerHTML = '';
    container.appendChild(shadowHost);

    var shadow = shadowHost.attachShadow({ mode: 'open' });
    var iframe = document.createElement('iframe');
    iframe.style.cssText = 'width:100%;height:100%;border:none;background:#fff;';
    iframe.sandbox = 'allow-scripts allow-same-origin allow-forms';

    // Use srcdoc for more reliable content injection (avoids doc.write timing issues)
    iframe.srcdoc = injectWidgetBridge(widget.html, widget.title);
    shadow.appendChild(iframe);
}

// Add a chat widget to the dashboard
async function addWidgetToDashboard(widgetId, event) {
    if (event) event.stopPropagation();

    // Get widget from chat widgets - try multiple sources
    var chatWidget = null;
    var chatWidgetsList = getWidgetsForChat(currentChatId);
    chatWidget = chatWidgetsList.find(function(w) { return w.id === widgetId; });

    // Also try getWidgetById as fallback
    if (!chatWidget) {
        chatWidget = getWidgetById(widgetId);
    }

    if (!chatWidget) {
        showSnackbar('Widget not found', 'error');
        return;
    }

    if (!chatWidget.html) {
        showSnackbar('Widget has no content', 'error');
        return;
    }

    // Find the prompt from the source chat
    // IMPORTANT: Always use chatWidget.chatId if it exists - this preserves the original chat reference
    var chatId = chatWidget.chatId || currentChatId;
    var msgIndex = chatWidget.msgIndex;
    if (chatId && chats[chatId] && msgIndex !== undefined) {
        var chat = chats[chatId];
        // Find the last user message before the widget
        for (var i = msgIndex - 1; i >= 0; i--) {
            if (chat.messages[i] && chat.messages[i].role === 'user') {
                prompt = chat.messages[i].content;
                break;
            }
        }
    }

    // Find available grid position for new widget
    initGridOccupancy();
    var pos = findNextAvailablePosition(4, 4);

    // Create dashboard widget from chat widget
    var dashWidget = {
        id: widgetId,
        title: chatWidget.title || 'Widget',
        prompt: prompt,
        conversation: [],
        html: chatWidget.html,
        width: 4,
        height: 4,
        gridX: pos.gridX,
        gridY: pos.gridY,
        createdAt: chatWidget.createdAt || Date.now(),
        chatId: chatId,
        msgIndex: msgIndex,
        error: null,
        isLoading: false
    };

    dashboardWidgets[widgetId] = dashWidget;
    await saveDashboardWidget(dashWidget);

    // Update button state
    var btn = document.querySelector('.widget-dashboard-btn[onclick*="' + widgetId + '"]');
    if (btn) {
        btn.classList.add('on-dashboard');
        btn.setAttribute('onclick', "removeWidgetFromDashboard('" + widgetId + "', event)");
        btn.setAttribute('title', 'Remove from Dashboard');
    }

    // Re-render dashboard if it's currently visible to show the new widget
    var dashboardPanel = document.getElementById('dashboard-panel');
    if (dashboardPanel && dashboardPanel.style.display === 'flex') {
        renderDashboard();
    }

    // Update sidebar to reflect dashboard state
    renderVersionSidebar();

    showSnackbar('Widget added to dashboard', 'success');
}

// Remove a widget from the dashboard
async function removeWidgetFromDashboard(widgetId, event) {
    if (event) event.stopPropagation();

    if (dashboardWidgets[widgetId]) {
        await deleteDashboardWidget(widgetId);
    }

    // Remove the widget element from dashboard DOM if present (without re-rendering other widgets)
    var dashboardWidgetEl = document.querySelector('.dashboard-widget[data-widget-id="' + widgetId + '"]');
    if (dashboardWidgetEl) {
        // Clean up widget iframe event listeners to prevent memory leaks
        var iframe = dashboardWidgetEl.querySelector('iframe');
        if (iframe && iframe.__widgetCleanup) iframe.__widgetCleanup();
        dashboardWidgetEl.remove();

        // Show empty state if no widgets left
        var container = document.getElementById('dashboard-grid');
        if (container && Object.keys(dashboardWidgets).length === 0) {
            container.innerHTML = '<div class="dashboard-empty"><span class="dashboard-empty-icon">' + UI_ICONS.widget + '</span><p>No widgets yet</p><p class="dashboard-empty-hint">Add widgets to your dashboard using prompts.</p></div>';
        }
    }

    // Update button state in chat view
    var btn = document.querySelector('.widget-dashboard-btn[onclick*="' + widgetId + '"]');
    if (btn) {
        btn.classList.remove('on-dashboard');
        btn.setAttribute('onclick', "addWidgetToDashboard('" + widgetId + "', event)");
        btn.setAttribute('title', 'Add to Dashboard');
    }
    // Update sidebar
    renderVersionSidebar();
}

// Toggle widget on/off dashboard from sidebar
async function toggleWidgetOnDashboard(widgetId) {
    if (dashboardWidgets && dashboardWidgets[widgetId]) {
        await removeWidgetFromDashboard(widgetId);
    } else {
        await addWidgetToDashboard(widgetId);
    }
}

// Show widget in the browser/iframe panel
function showWidgetInPanel(widgetId) {
    var widget = getWidgetById(widgetId);
    if (!widget) { showSnackbar('Widget not found', 'error'); return; }
    openWidgetInIframePanel(widgetId);
}

function openAddWidgetModal() {
    // Close dashboard panel and show chat
    var dashboardPanel = document.getElementById('dashboard-panel');
    if (dashboardPanel) dashboardPanel.style.display = 'none';

    showChatView();

    // Create a new chat for widget creation
    newChat();

    // Set a hint in the input
    var input = document.getElementById('message-input');
    if (input) {
        input.placeholder = 'Describe the widget you want to create...';
        input.focus();
    }
}

function editDashboardWidget(widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget) return;

    // If widget has a source chat, open that chat
    if (widget.chatId && chats[widget.chatId]) {
        // Close dashboard view properly (updates currentView)
        closeDashboardView();

        // Load the source chat
        selectChat(widget.chatId);

        // Scroll to the widget display inside the chat
        setTimeout(function() {
            // First try to scroll to the widget element itself
            var widgetEl = document.getElementById('widget-' + widgetId);
            if (widgetEl) {
                widgetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
            } else if (widget.msgIndex !== undefined) {
                // Fallback to message element if widget not found
                var msgEl = document.querySelector('[data-msg-index="' + widget.msgIndex + '"]');
                if (msgEl) msgEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }, 100);
    } else {
        console.warn('Widget has no valid source chat. chatId:', widget.chatId, 'available chats:', Object.keys(chats));
        showSnackbar('Source chat not found - widget may have been created in a deleted chat', 'warning');
    }
}

// Open widget editor using the main chat UI
function openWidgetInChatMode(widget, isNew) {
    // Hide dashboard panel
    var dashboardPanel = document.getElementById('dashboard-panel');
    if (dashboardPanel) dashboardPanel.style.display = 'none';

    // Show main area (it should already be visible, but ensure it)
    showChatView();

    // Show widget mode indicator in main header
    var mainHeader = document.querySelector('.main-header');
    if (mainHeader) {
        mainHeader.classList.add('widget-mode');
        mainHeader.dataset.widgetId = widget.id;
        mainHeader.dataset.widgetTitle = widget.title || 'New Widget';
    }

    // Update header title to show widget name
    var headerTitle = document.getElementById('header-chat-title');
    if (headerTitle) {
        headerTitle.innerHTML = '<span class="widget-mode-badge">Widget</span> ' + escapeHtml(widget.title || 'New Widget');
    }

    // Show back to dashboard button
    var backBtn = document.getElementById('widget-back-btn');
    if (!backBtn && mainHeader) {
        backBtn = document.createElement('button');
        backBtn.id = 'widget-back-btn';
        backBtn.className = 'skills-back-btn widget-back-btn';
        backBtn.title = 'Back to Dashboard';
        backBtn.innerHTML = '<span class="back-icon"></span>';
        backBtn.onclick = closeWidgetChatMode;
        mainHeader.insertBefore(backBtn, mainHeader.firstChild);
    }
    if (backBtn) backBtn.style.display = 'flex';

    // Render widget conversation in main chat
    renderWidgetInChat(widget);

    // Focus input
    var input = document.getElementById('message-input');
    if (input) input.focus();
}

function closeWidgetChatMode() {
    var widget = dashboardWidgets[currentEditingWidget];

    // If it's a new widget with no content, remove it
    if (widget && !widget.html && (!widget.conversation || widget.conversation.length === 0)) {
        delete dashboardWidgets[currentEditingWidget];
    }

    currentEditingWidget = null;
    activeWidgetStreamingId = null;

    // Hide widget mode indicator
    var mainHeader = document.querySelector('.main-header');
    if (mainHeader) {
        mainHeader.classList.remove('widget-mode');
        delete mainHeader.dataset.widgetId;
        delete mainHeader.dataset.widgetTitle;
    }

    // Hide back button
    var backBtn = document.getElementById('widget-back-btn');
    if (backBtn) backBtn.style.display = 'none';

    // Restore chat title
    var headerTitle = document.getElementById('header-chat-title');
    if (headerTitle && chats[currentChatId]) {
        headerTitle.textContent = chats[currentChatId].title || 'New Chat';
    }

    // Show dashboard
    openDashboardView();
}

function renderWidgetInChat(widget) {
    var container = document.getElementById('messages');
    if (!container) return;

    var conversation = widget ? (widget.conversation || []) : [];

    if (conversation.length === 0) {
        container.innerHTML = '<div class="widget-chat-empty">Describe the widget you want to create...</div>';
        return;
    }

    var html = '';
    conversation.forEach(function(msg, idx) {
        if (msg.role === 'user') {
            html += '<div class="message user"><div class="message-content"><span class="user-text">' + escapeHtml(msg.content) + '</span></div></div>';
        } else if (msg.role === 'assistant') {
            var content = msg.content || '';
            if (idx === conversation.length - 1 && widget && widget.isStreaming) {
                html += '<div class="message assistant streaming"><div class="message-content">' + formatContent(content) + '<span class="streaming-cursor"></span></div></div>';
            } else {
                html += '<div class="message assistant"><div class="message-content">' + formatContent(content) + '</div></div>';
            }
        }
    });

    if (widget && widget.isStreaming && (conversation.length === 0 || conversation[conversation.length - 1].role === 'user')) {
        html += '<div class="message assistant streaming"><div class="message-content"><span class="streaming-cursor"></span></div></div>';
    }

    container.innerHTML = html;
    container.scrollTop = container.scrollHeight;
}

function closeWidgetEditorPanel() {
    var widget = dashboardWidgets[currentEditingWidget];

    // If it's a new widget with no content, remove it
    if (widget && !widget.html && (!widget.conversation || widget.conversation.length === 0)) {
        delete dashboardWidgets[currentEditingWidget];
    }

    currentEditingWidget = null;
    activeWidgetStreamingId = null;

    var dashboardPanel = document.getElementById('dashboard-panel');
    if (dashboardPanel) { 
        dashboardPanel.style.display = 'flex'; 
        renderDashboard(); 
    }
}

// Revert widget to a previous version from history
async function revertWidgetToHistory(widgetId, historyIndex) {
    var widget = dashboardWidgets[widgetId];
    if (!widget || !widget.history || !widget.history[historyIndex]) {
        showSnackbar('History version not found', 'error');
        return;
    }

    var historyEntry = widget.history[historyIndex];

    // Save current as new history entry before reverting
    if (widget.html) {
        widget.history.push({
            html: widget.html,
            timestamp: Date.now(),
            prompt: widget.lastPrompt || 'Before revert'
        });
    }

    // Restore the old HTML
    widget.html = historyEntry.html;
    widget.error = null;

    await saveDashboardWidget(widget, true); // Skip history tracking since we're managing it manually
    renderDashboard();
    showSnackbar('Widget reverted to previous version', 'success');
}

// Show widget history panel
function showWidgetHistory(widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget || !widget.history || widget.history.length === 0) {
        showSnackbar('No history available for this widget', 'info');
        return;
    }

    var html = '<div class="widget-history-modal">';
    html += '<div class="widget-history-header"><span>Widget History</span><button onclick="closeWidgetHistory()">×</button></div>';
    html += '<div class="widget-history-list">';

    widget.history.forEach(function(entry, idx) {
        var date = new Date(entry.timestamp);
        var timeStr = date.toLocaleString();
        html += '<div class="widget-history-item" onclick="revertWidgetToHistory(\'' + widgetId + '\', ' + idx + '); closeWidgetHistory();">';
        html += '<div class="widget-history-time">' + timeStr + '</div>';
        html += '<div class="widget-history-prompt">' + escapeHtml((entry.prompt || 'No prompt').substring(0, 100)) + '</div>';
        html += '</div>';
    });

    html += '</div></div>';

    var modal = document.createElement('div');
    modal.id = 'widget-history-modal-overlay';
    modal.className = 'modal-overlay show';
    modal.innerHTML = html;
    modal.onclick = function(e) { if (e.target === modal) closeWidgetHistory(); };
    document.body.appendChild(modal);
}

function closeWidgetHistory() {
    var modal = document.getElementById('widget-history-modal-overlay');
    if (modal) modal.remove();
}

// Regenerate widget - creates a new chat with full history and runs the last prompt
async function regenerateDashboardWidget(widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget) {
        showSnackbar('Widget not found', 'error');
        return;
    }

    // Find the source chat and the prompt to regenerate
    var prompt = widget.prompt;
    var historyMessages = [];
    var lastUserMsgIndex = -1;
    var sourceChatTitle = null;

    // Try to get history from source chat
    if (widget.chatId && chats[widget.chatId]) {
        var sourceChat = chats[widget.chatId];
        sourceChatTitle = sourceChat.title;
        // Find the last user message before the widget was created
        var msgIndex = widget.msgIndex || sourceChat.messages.length;
        for (var i = msgIndex - 1; i >= 0; i--) {
            if (sourceChat.messages[i] && sourceChat.messages[i].role === 'user') {
                if (!prompt) prompt = sourceChat.messages[i].content;
                lastUserMsgIndex = i;
                break;
            }
        }

        // Copy all messages BEFORE the last user message as history
        if (lastUserMsgIndex > 0) {
            for (var i = 0; i < lastUserMsgIndex; i++) {
                var msg = sourceChat.messages[i];
                // Skip internal messages like approval, pending_tool, etc.
                if (msg.role === 'user' || msg.role === 'assistant' || msg.role === 'tool' || msg.role === 'system') {
                    // Clone the message to avoid modifying original
                    var clonedMsg = JSON.parse(JSON.stringify(msg));
                    // Remove streaming/transient properties
                    delete clonedMsg.isStreaming;
                    historyMessages.push(clonedMsg);
                }
            }
        }
    }

    // Also check widget conversation for user messages if no prompt found
    if (!prompt && widget.conversation && widget.conversation.length > 0) {
        for (var i = widget.conversation.length - 1; i >= 0; i--) {
            if (widget.conversation[i].role === 'user') {
                prompt = widget.conversation[i].content;
                break;
            }
        }
    }

    if (!prompt) {
        showSnackbar('No prompt found to regenerate', 'error');
        return;
    }

    // Store the prompt for future regenerations
    widget.prompt = prompt;

    // Close dashboard and show chat
    closeDashboardView();

    // Create a new chat for regeneration
    newChat();

    // Copy the source chat title to the new chat
    var chat = chats[currentChatId];
    if (sourceChatTitle && sourceChatTitle !== 'New Chat') {
        chat.title = sourceChatTitle;
        chat.isTemporary = false;
        renderChatList();
        updateChatTitleHeader();
    }

    // Copy cached tool results from source chat so cached_content_* tools work
    if (widget.chatId && chats[widget.chatId] && chats[widget.chatId].cachedToolResults) {
        chat.cachedToolResults = Object.assign({}, chats[widget.chatId].cachedToolResults);
    }

    // Store which widget we're regenerating so we can update it when done
    pendingWidgetRegeneration = widgetId;

    // Add history messages first, then the prompt

    // Add all history messages
    for (var i = 0; i < historyMessages.length; i++) {
        chat.messages.push(historyMessages[i]);
    }

    // Add the prompt as the last user message
    chat.messages.push({ role: 'user', content: prompt });
    renderMessages();

    // Run the agent - it will create a new widget via html_widget tool
    // The widget will be linked to this new chat
    runAgent();

    showSnackbar('Regenerating widget with full history...', 'info');
}

// Run a prompt for a widget in the background (for batch regeneration)
// Creates a real chat that stays in history, similar to single widget regenerate
async function runWidgetPrompt(widget, prompt) {
    if (!widget || !prompt) return;

    // Store original context to restore after
    var originalChatId = currentChatId;
    var originalEditingWidget = currentEditingWidget;

    // Get history from source chat if available
    var historyMessages = [];
    var sourceChatTitle = widget.title || 'Widget Regeneration';

    if (widget.chatId && chats[widget.chatId]) {
        var sourceChat = chats[widget.chatId];
        if (sourceChat.title && sourceChat.title !== 'New Chat') {
            sourceChatTitle = sourceChat.title;
        }
        // Find the last user message before the widget was created
        var msgIndex = widget.msgIndex || sourceChat.messages.length;
        var lastUserMsgIndex = -1;
        for (var i = msgIndex - 1; i >= 0; i--) {
            if (sourceChat.messages[i] && sourceChat.messages[i].role === 'user') {
                lastUserMsgIndex = i;
                break;
            }
        }
        // Copy all messages BEFORE the last user message as history
        if (lastUserMsgIndex > 0) {
            for (var i = 0; i < lastUserMsgIndex; i++) {
                var msg = sourceChat.messages[i];
                if (msg.role === 'user' || msg.role === 'assistant' || msg.role === 'tool' || msg.role === 'system') {
                    var clonedMsg = JSON.parse(JSON.stringify(msg));
                    delete clonedMsg.isStreaming;
                    historyMessages.push(clonedMsg);
                }
            }
        }
    }

    // Create a new real chat for this regeneration
    var newChatId = generateId();
    chats[newChatId] = {
        id: newChatId,
        title: sourceChatTitle,
        messages: [],
        createdAt: Date.now(),
        isTemporary: false
    };

    // Copy cached tool results from source chat
    if (widget.chatId && chats[widget.chatId] && chats[widget.chatId].cachedToolResults) {
        chats[newChatId].cachedToolResults = Object.assign({}, chats[widget.chatId].cachedToolResults);
    }

    // Add history messages
    for (var i = 0; i < historyMessages.length; i++) {
        chats[newChatId].messages.push(historyMessages[i]);
    }

    // Add the prompt as user message
    chats[newChatId].messages.push({ role: 'user', content: prompt });

    // Switch to the new chat context for agent execution
    currentChatId = newChatId;
    pendingWidgetRegeneration = widget.id;

    // Set widget as loading
    widget.isLoading = true;
    widget.isStreaming = true;
    activeWidgetStreamingId = widget.id;

    // Save the new chat
    saveChatsToStorage();
    renderChatList();

    // Run agent and wait for completion
    paused = false;
    await runAgent();

    // Update widget to link to new chat
    widget.chatId = newChatId;
    widget.isLoading = false;
    widget.isStreaming = false;
    activeWidgetStreamingId = null;
    pendingWidgetRegeneration = null;
    await saveDashboardWidget(widget);

    // Save chat after agent completes
    saveChatsToStorage();
    renderChatList();

    // Restore original context
    currentChatId = originalChatId;
    currentEditingWidget = originalEditingWidget;
}

async function refreshAllDashboardWidgets() {
    var widgetList = Object.values(dashboardWidgets);
    if (widgetList.length === 0) {
        showSnackbar('No widgets to refresh', 'error');
        return;
    }

    if (dashboardRefreshing) {
        showSnackbar('Already refreshing...', 'warning');
        return;
    }

    dashboardRefreshing = true;
    var refreshBtn = document.getElementById('dashboard-refresh-all-btn');
    if (refreshBtn) {
        refreshBtn.disabled = true;
        refreshBtn.innerHTML = '<span class="action-icon">' + UI_ICONS.spinner + '</span>Regenerating...';
    }

    var skippedWidgets = [];
    var regeneratedCount = 0;

    for (var i = 0; i < widgetList.length; i++) {
        var widget = widgetList[i];
        var prompt = widget.prompt;

        // Try to get prompt from source chat if not directly available
        if (!prompt && widget.chatId && chats[widget.chatId]) {
            var sourceChat = chats[widget.chatId];
            var msgIndex = widget.msgIndex || sourceChat.messages.length;
            for (var j = msgIndex - 1; j >= 0; j--) {
                if (sourceChat.messages[j] && sourceChat.messages[j].role === 'user') {
                    prompt = sourceChat.messages[j].content;
                    widget.prompt = prompt; // Store for future use
                    break;
                }
            }
        }

        // Check if we can regenerate this widget
        if (!prompt) {
            var reason = 'no prompt found';
            if (widget.chatId && !chats[widget.chatId]) {
                reason = 'source chat was deleted';
            }
            skippedWidgets.push({ title: widget.title, reason: reason });
            showSnackbar('Skipping "' + widget.title + '": ' + reason, 'warning');
            continue;
        }

        showSnackbar('Regenerating ' + (regeneratedCount + 1) + '/' + widgetList.length + ': ' + widget.title, 'success');

        // Show loading on this widget
        widget.isLoading = true;
        renderDashboard();

        widget.conversation = [];
        await runWidgetPrompt(widget, prompt);

        widget.isLoading = false;
        renderDashboard();
        regeneratedCount++;
    }

    dashboardRefreshing = false;
    if (refreshBtn) {
        refreshBtn.disabled = false;
        refreshBtn.innerHTML = '<span class="action-icon">' + UI_ICONS.refresh + '</span>Regenerate All';
    }

    // Show final status
    if (skippedWidgets.length > 0) {
        showSnackbar(regeneratedCount + ' widgets regenerated, ' + skippedWidgets.length + ' skipped', 'warning');
    } else {
        showSnackbar('All ' + regeneratedCount + ' widgets regenerated', 'success');
    }
}

async function confirmDeleteDashboardWidget(widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget) return;

    var confirmed = await showConfirmModal('Delete Widget', 'Are you sure you want to delete "' + escapeHtml(widget.title) + '"?');
    if (!confirmed) return;

    // Close widget editor if open for this widget
    if (currentEditingWidget === widgetId) {
        currentEditingWidget = null;
        var dashboardPanel = document.getElementById('dashboard-panel');
        if (dashboardPanel) dashboardPanel.style.display = 'flex';
    }

    await deleteDashboardWidget(widgetId);

    // Remove just this widget's DOM element instead of re-rendering all widgets
    var widgetEl = document.querySelector('.dashboard-widget[data-widget-id="' + widgetId + '"]');
    if (widgetEl) {
        // Clean up widget iframe event listeners to prevent memory leaks
        var iframe = widgetEl.querySelector('iframe');
        if (iframe && iframe.__widgetCleanup) iframe.__widgetCleanup();
        widgetEl.remove();
    }

    // Show empty state if no widgets left
    var container = document.getElementById('dashboard-grid');
    if (container && Object.keys(dashboardWidgets).length === 0) {
        container.innerHTML = '<div class="dashboard-empty"><span class="dashboard-empty-icon">' + UI_ICONS.widget + '</span><p>No widgets yet</p><p class="dashboard-empty-hint">Add widgets to your dashboard using prompts.</p></div>';
    }

    showSnackbar('Widget deleted', 'success');
}

function downloadDashboardWidget(widgetId) {
    var widget = dashboardWidgets[widgetId];
    if (!widget) return;

    var exportData = {
        type: 'appagent-dashboard-widget',
        version: 1,
        widget: widget
    };

    var blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'widget-' + (widget.title || widget.id).replace(/[^a-z0-9]/gi, '-').toLowerCase() + '.json';
    a.click();
    URL.revokeObjectURL(url);
    showSnackbar('Widget downloaded', 'success');
}

function openDashboardInNewTab() {
    // Open AppAgent in standalone dashboard mode (same page, no sidebar/header)
    var widgetList = Object.values(dashboardWidgets);
    if (widgetList.length === 0) {
        showSnackbar('No widgets to display', 'error');
        return;
    }
    window.open(window.location.pathname + '?standalone=dashboard', '_blank');
}

function exportDashboard() {
    var widgetList = Object.values(dashboardWidgets);
    if (widgetList.length === 0) {
        showSnackbar('No widgets to export', 'error');
        return;
    }

    var exportData = {
        type: 'appagent-dashboard',
        version: 1,
        widgets: widgetList
    };

    var blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'dashboard-' + new Date().toISOString().slice(0, 10) + '.json';
    a.click();
    URL.revokeObjectURL(url);
    showSnackbar('Dashboard exported', 'success');
}

async function importDashboard() {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async function(e) {
        var file = e.target.files[0];
        if (!file) return;

        try {
            var text = await file.text();
            var data = JSON.parse(text);

            var imported = 0;
            var updated = 0;

            if (data.type === 'appagent-dashboard-widget' && data.widget) {
                // Single widget import
                var widget = data.widget;
                if (dashboardWidgets[widget.id]) {
                    updated++;
                } else {
                    imported++;
                }
                await saveDashboardWidget(widget);
            } else if (data.type === 'appagent-dashboard' && data.widgets) {
                // Full dashboard import
                for (var i = 0; i < data.widgets.length; i++) {
                    var widget = data.widgets[i];
                    if (dashboardWidgets[widget.id]) {
                        updated++;
                    } else {
                        imported++;
                    }
                    await saveDashboardWidget(widget);
                }
            } else {
                showSnackbar('Invalid dashboard file format', 'error');
                return;
            }

            renderDashboard();
            var msg = 'Imported ' + imported + ' widget(s)';
            if (updated > 0) msg += ', updated ' + updated;
            showSnackbar(msg, 'success');
        } catch (e) {
            showSnackbar('Failed to import: ' + e.message, 'error');
        }
    };
    input.click();
}

function getSkillsSummaryForPrompt() {
    var skillList = Object.values(skills);
    if (skillList.length === 0) return '';

    // Only include active skills in the system prompt
    var activeList = skillList.filter(function(s) { return activeSkills[s.id]; });

    if (activeList.length === 0) return '';

    var summary = '\n\nACTIVE SKILLS:\n';
    activeList.forEach(function(skill) {
        var desc = skill.description ? ': ' + skill.description : '';
        summary += '- ' + (skill.name || skill.id) + ' (id: ' + skill.id + ')' + desc + '\n';
    });

    return summary;
}

async function loadChatsFromStorage() {
    try {
        var database = await openDatabase();
        var transaction = database.transaction([chatStoreName], 'readonly');
        var store = transaction.objectStore(chatStoreName);
        var request = store.getAll();

        return new Promise(function(resolve) {
            request.onsuccess = function() {
                var results = request.result || [];
                chats = {};
                results.forEach(function(chat) {
                    if (chat.messages && chat.messages.length > 0) {
                        chats[chat.id] = chat;
                    }
                });
                resolve();
            };
            request.onerror = function() {
                console.error('Failed to load chats from IndexedDB:', request.error);
                resolve();
            };
        });
    } catch (e) {
        console.error('IndexedDB error:', e);
    }
}

var saveChatsPending = false;
var saveChatsPendingAgain = false;

async function saveChatsToStorage() {
    // Prevent concurrent saves which can cause data loss
    if (saveChatsPending) {
        saveChatsPendingAgain = true;
        return;
    }
    saveChatsPending = true;

    try {
        var database = await openDatabase();
        var transaction = database.transaction([chatStoreName], 'readwrite');
        var store = transaction.objectStore(chatStoreName);

        // Clear and re-add all chats (simpler than tracking deletes)
        var clearRequest = store.clear();

        await new Promise(function(resolve) {
            clearRequest.onsuccess = function() {
                var chatIds = Object.keys(chats);
                var pending = 0;

                for (var i = 0; i < chatIds.length; i++) {
                    var chat = chats[chatIds[i]];
                    if (chat.messages && chat.messages.length > 0) {
                        pending++;
                        var addRequest = store.put(chat);
                        addRequest.onsuccess = function() {
                            pending--;
                            if (pending === 0) {
                                updateStorageIndicator();
                                resolve();
                            }
                        };
                        addRequest.onerror = function() { pending--; };
                    }
                }

                if (pending === 0) {
                    updateStorageIndicator();
                    resolve();
                }
            };
            clearRequest.onerror = function() {
                console.error('Failed to clear chat store:', clearRequest.error);
                resolve();
            };
        });
    } catch (e) {
        console.error('Failed to save chats to IndexedDB:', e);
    } finally {
        saveChatsPending = false;
        // If another save was requested while we were saving, do it now
        if (saveChatsPendingAgain) {
            saveChatsPendingAgain = false;
            saveChatsToStorage();
        }
    }
}

async function loadProviderFromStorage() {
    var stored = appStorage.getItem('appagent_provider');
    if (stored && getProviderById(stored)) {
        currentProvider = stored;
    }
}

async function loadCacheTokenLimit() {
    cacheTokenLimit = await getSetting('cacheTokenLimit', 4000);
}

async function saveCacheTokenLimit() {
    await setSetting('cacheTokenLimit', cacheTokenLimit);
}

async function updateCacheTokenLimit(value) {
    cacheTokenLimit = parseInt(value) || 4000;
    await saveCacheTokenLimit();
}

async function updateCacheTokenLimitFromK(valueInK) {
    var k = parseInt(valueInK) || 4;
    k = Math.max(1, Math.min(100, k)); // Clamp between 1K and 100K
    cacheTokenLimit = k * 1000;
    await saveCacheTokenLimit();
    // Sync both inputs if they exist
    var panelInput = document.getElementById('cache-token-limit');
    var pageInput = document.getElementById('settings-page-cache-limit');
    if (panelInput) panelInput.value = k;
    if (pageInput) pageInput.value = k;
}

async function loadToolPermissions() {
    toolPermissions = await getSetting('toolPermissions', {});
    // Initialize any missing permission keys with appropriate defaults
    PERMISSION_KEYS.forEach(function(key) {
        if (!toolPermissions[key]) {
            // Set read-only/safe tools to auto by default
            if (key === 'iframe_tool:navigate' || key === 'iframe_tool:get_visible_text' || key === 'iframe_tool:get_dom' ||
                key === 'iframe_tool:open_widget' || key === 'iframe_tool:scroll' || key === 'iframe_tool:resize' ||
                key === 'iframe_tool:get_properties' || key === 'iframe_tool:set_style' || key === 'set_chat_title' ||
                key === 'cached_content_outline' || key === 'cached_content_search' || key === 'cached_content_read' ||
                key === 'take_screenshot') {
                toolPermissions[key] = 'auto';
            } else if (key === 'manage_skill:activate') {
                // Skill activation disabled by default (security: skill tools run code)
                toolPermissions[key] = 'disabled';
            } else {
                toolPermissions[key] = 'ask';
            }
        }
    });
}

// Load local scope override from localStorage
function loadLocalScopeOverride() {
    var stored = appStorage.getItem('appagent_local_scope');
    if (stored) {
        var data = JSON.parse(stored);
        localScopeOverride = data.scope;
        platformScope = data.platformScope || 'global';
    }
}

// Save local scope override to localStorage
function saveLocalScopeOverride() {
    if (localScopeOverride !== null) {
        appStorage.setItem('appagent_local_scope', JSON.stringify({
            scope: localScopeOverride,
            platformScope: platformScope
        }));
    } else {
        appStorage.removeItem('appagent_local_scope');
    }
}

// Fetch current scope from platform (lazy loaded when POST tool needs it)
// Detects if platform scope changed and resets local override if so
async function fetchCurrentScope() {
    var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
    try {
        // Use cached user sys_id if available
        var userId = cachedUserSysId;
        if (!userId) {
            var userResp = await fetch('/api/now/table/sys_user?sysparm_query=user_name=' + encodeURIComponent(window.NOW?.user_name || 'admin') + '&sysparm_fields=sys_id&sysparm_limit=1', { headers: headers });
            var userData = await userResp.json();
            userId = userData.result && userData.result[0] ? userData.result[0].sys_id : null;
            if (userId) cachedUserSysId = userId;
        }

        var fetchedPlatformScope = 'global';
        if (userId) {
            var prefResp = await fetch('/api/now/table/sys_user_preference?sysparm_query=user=' + userId + '^name=apps.current_app&sysparm_fields=value&sysparm_limit=1', { headers: headers });
            var prefData = await prefResp.json();
            if (prefData.result && prefData.result[0] && prefData.result[0].value) {
                fetchedPlatformScope = prefData.result[0].value;
            }
        }

        // Check if platform scope changed from what we knew
        if (platformScope !== fetchedPlatformScope) {
            platformScope = fetchedPlatformScope;
            // Reset local override when platform scope changes
            localScopeOverride = null;
            saveLocalScopeOverride();
        }

        // Use local override if set, otherwise use platform scope
        currentScope = localScopeOverride !== null ? localScopeOverride : platformScope;

        // Fetch scope name for display in settings panel
        if (currentScope && currentScope !== 'global') {
            var scopeNameResp = await fetch('/api/now/table/sys_scope?sysparm_query=sys_id=' + currentScope + '&sysparm_fields=name&sysparm_limit=1', { headers: headers });
            var scopeNameData = await scopeNameResp.json();
            if (scopeNameData.result && scopeNameData.result[0]) {
                window.currentScopeName = scopeNameData.result[0].name;
            }
        } else {
            window.currentScopeName = 'Global';
        }
        scopeFetched = true;
    } catch (e) {
        console.error('Failed to fetch current scope:', e);
    }
}

async function fetchAndPopulateScopeDropdown() {
    var container = document.getElementById('settings-scope-container');
    if (!container) return;

    // Show loading state immediately
    var currentSelectedScope = localScopeOverride !== null ? localScopeOverride : platformScope;
    var currentLabel = 'Loading...';
    if (currentSelectedScope === 'global') {
        currentLabel = 'Global';
    } else if (window.currentScopeName) {
        currentLabel = window.currentScopeName;
    }

    // Show loading state with a loading indicator
    container.innerHTML = '<div class="custom-dropdown-loading"><span class="dropdown-label">' + currentLabel + '</span><span class="dropdown-loading-spinner"></span></div>';

    var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };

    try {
        // Fetch all application scopes that can be edited in studio
        var scopesResp = await fetch('/api/now/table/sys_scope?sysparm_fields=sys_id,scope,name&sysparm_query=can_edit_in_studio=true^ORDERBYname&sysparm_limit=200', { headers: headers });
        var scopesData = await scopesResp.json();

        // Determine which scope to show as selected (local override or platform)
        var selectedScope = localScopeOverride !== null ? localScopeOverride : platformScope;

        // Build options array
        var options = [{ value: 'global', label: 'Global' }];

        // Add all scopes
        if (scopesData.result) {
            scopesData.result.forEach(function(scope) {
                var label = scope.name || scope.scope;
                options.push({ value: scope.sys_id, label: label });
                if (selectedScope === scope.sys_id) {
                    window.currentScopeName = label;
                }
            });
        }

        // Render custom dropdown with search (scopes typically > 5)
        renderCustomSelect('settings-scope-container', options, selectedScope, changeScope, 'Select scope...');
    } catch (e) {
        console.error('Failed to fetch scopes:', e);
        renderCustomSelect('settings-scope-container', [{ value: 'global', label: 'Global' }], 'global', changeScope, 'Select scope...');
    }
}

// Change scope locally only - does NOT update platform
function changeScope(scopeId) {
    // If selecting the same as platform scope, clear local override
    if (scopeId === platformScope) {
        localScopeOverride = null;
    } else {
        localScopeOverride = scopeId;
    }
    currentScope = scopeId;
    scopeFetched = true; // User manually set scope
    saveLocalScopeOverride();
}
var changeLocalScope = changeScope; // Alias for settings page

function saveToolPermissions() {
    setSetting('toolPermissions', toolPermissions);
}

// Version History Functions
async function getRecordScope(table, sysId) {
    if (!sysId || !table) return null;
    // Validate table name - must not contain invalid characters
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(table)) {
        console.warn('Invalid table name for scope lookup:', table);
        return null;
    }
    try {
        var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
        var res = await fetch('/api/now/table/' + table + '/' + sysId + '?sysparm_fields=sys_scope', { headers: headers });
        if (!res.ok) return null;
        var data = await res.json();
        if (data.result && data.result.sys_scope) {
            return data.result.sys_scope.value || data.result.sys_scope;
        }
    } catch (e) {
        console.error('Failed to get record scope:', e);
    }
    return null;
}

// Common helper function for sys_upload.do with scope support
async function uploadXml(xml, table, sysId) {
    if (!xml) return { success: false, error: 'No XML provided' };

    try {
        // Get the record's scope for cross-scope operations
        var recordScope = sysId ? await getRecordScope(table, sysId) : null;

        var form = new FormData();
        var blob = new Blob([xml], { type: 'application/xml' });
        form.append('file', blob, 'import.xml');
        form.append('sysparm_referring_url', table + '_list.do');
        form.append('sysparm_target', table);

        // Build URL with scope as query parameter (like REST API calls)
        var uploadUrl = '/sys_upload.do';
        if (recordScope) {
            uploadUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
        }

        var res = await fetch(uploadUrl, {
            method: 'POST',
            headers: { 'X-UserToken': window.sessionToken },
            body: form
        });

        var responseText = await res.text();

        // Check for actual import success - sys_upload.do returns HTML
        var importFailed = responseText.includes('Import failed') || 
                          responseText.includes('Error during import') ||
                          responseText.includes('class="error"') ||
                          (responseText.includes('outputmsg_error') && !responseText.includes('outputmsg_success'));

        if (res.ok && !importFailed) {
            return { success: true };
        } else {
            console.error('Upload failed. Response:', responseText);
            return { success: false, error: importFailed ? 'Import failed' : 'HTTP ' + res.status, response: responseText };
        }
    } catch (e) {
        console.error('Upload exception:', e);
        return { success: false, error: e.message };
    }
}

async function getVersionXml(versionSysId) {
    if (!versionSysId) return null;
    try {
        var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
        var res = await fetch('/api/now/table/sys_update_version/' + versionSysId + '?sysparm_fields=payload', { headers: headers });
        var data = await res.json();
        if (data.result && data.result.payload) {
            return data.result.payload;
        }
    } catch (e) {
        console.error('Failed to get version XML:', e);
    }
    return null;
}

async function getRecordVersion(table, sysId) {
    if (!sysId) return null;
    try {
        var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
        var res = await fetch('/api/now/table/sys_update_version?sysparm_query=name=' + table + '_' + sysId + '^ORDERBYDESCsys_created_on&sysparm_fields=sys_id,sys_created_on,state&sysparm_limit=1', { headers: headers });
        var data = await res.json();
        if (data.result && data.result[0]) {
            return data.result[0];
        }
    } catch (e) {
        console.error('Failed to get record version:', e);
    }
    return null;
}

async function getRecordDisplayValue(table, sysId) {
    if (!sysId) return sysId;
    try {
        var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
        var res = await fetch('/api/now/table/' + table + '/' + sysId + '?sysparm_fields=sys_id,name,number,short_description&sysparm_limit=1', { headers: headers });
        var data = await res.json();
        if (data.result) {
            return data.result.name || data.result.number || data.result.short_description || sysId.substring(0, 8);
        }
    } catch (e) {
        console.error('Failed to get record display value:', e);
    }
    return sysId ? sysId.substring(0, 8) : 'New Record';
}

function addVersionHistoryEntry(entry) {
    versionHistory.push(entry);
    saveVersionHistory();
    renderVersionSidebar();
    updateVersionSidebarVisibility();
    // Re-render messages to show inline changes
    renderMessages();
}

// Get changes for a specific user message (all changes until next user message)
function getChangesForUserMessage(userMsgIndex) {
    var chat = chats[currentChatId];
    if (!chat) return [];

    // Find the next user message index
    var nextUserMsgIndex = chat.messages.length;
    for (var i = userMsgIndex + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserMsgIndex = i;
            break;
        }
    }

    // Get all version history entries for this message range (exclude reverted/invalidated)
    return versionHistory.filter(function(v) {
        return v.chatId === currentChatId && 
               v.messageIndex >= userMsgIndex && 
               v.messageIndex < nextUserMsgIndex &&
               v.action !== 'REVERT' &&
               !v.invalidated;
    });
}

// Get the first version (before chat started) for a record
function getFirstVersionForRecord(table, sysId) {
    var entries = versionHistory.filter(function(v) {
        return v.chatId === currentChatId && 
               v.table === table && 
               v.sysId === sysId &&
               v.action !== 'REVERT' &&
               !v.invalidated;
    });
    if (entries.length > 0) {
        // Sort by timestamp and return the beforeVersion of the first change
        entries.sort(function(a, b) { return a.timestamp - b.timestamp; });
        return entries[0].beforeVersion;
    }
    return null;
}

// Get all unique files changed in this chat
function getAllChangedFiles() {
    var files = {};
    versionHistory.forEach(function(v) {
        if (v.chatId === currentChatId && v.action !== 'REVERT' && v.action !== 'USER_DELETE' && !v.invalidated) {
            var key = v.table + '_' + v.sysId;
            if (!files[key]) {
                files[key] = {
                    table: v.table,
                    sysId: v.sysId,
                    displayName: v.displayName,
                    firstBeforeVersion: v.beforeVersion,
                    changes: []
                };
            }
            files[key].changes.push(v);
        }
    });
    return Object.values(files);
}

// Get reverted files that can be redone
function getRevertedFiles() {
    var reverted = {};
    versionHistory.forEach(function(v) {
        if (v.chatId === currentChatId && v.action === 'REVERT' && v.afterVersion && v.table !== 'batch') {
            var key = v.table + '_' + v.sysId;
            // Only show if the original changes are invalidated
            var hasInvalidated = versionHistory.some(function(h) {
                return h.chatId === currentChatId && h.table === v.table && h.sysId === v.sysId && h.invalidated;
            });
            if (hasInvalidated) {
                reverted[key] = {
                    table: v.table,
                    sysId: v.sysId,
                    displayName: v.displayName,
                    revertedToVersion: v.afterVersion,
                    revertTimestamp: v.timestamp
                };
            }
        }
    });
    return Object.values(reverted);
}

// Get the latest after version for a record (to redo changes)
function getLatestAfterVersion(table, sysId) {
    var entries = versionHistory.filter(function(v) {
        return v.chatId === currentChatId && 
               v.table === table && 
               v.sysId === sysId &&
               v.action !== 'REVERT' &&
               v.action !== 'USER_DELETE' &&
               v.afterVersion;
    });
    if (entries.length > 0) {
        entries.sort(function(a, b) { return b.timestamp - a.timestamp; });
        return entries[0].afterVersion;
    }
    return null;
}

// Download XML with all changed files in current chat
async function downloadChangesXml() {
    var changedFiles = getAllChangedFiles();
    if (changedFiles.length === 0) {
        showSnackbar('No changes to download', 'warning');
        return;
    }

    showSpinner('Preparing XML download...');

    try {
        // Collect all version XMLs for the latest state of each file
        var recordXmls = [];

        for (var i = 0; i < changedFiles.length; i++) {
            var file = changedFiles[i];
            var latestAfterVersion = getLatestAfterVersion(file.table, file.sysId);

            if (latestAfterVersion) {
                var xml = await getVersionXml(latestAfterVersion);
                if (xml) {
                    recordXmls.push(xml);
                }
            }
        }

        if (recordXmls.length === 0) {
            hideSpinner();
            showSnackbar('Could not retrieve version data for any files', 'error');
            return;
        }

        // Generate file name
        var chat = chats[currentChatId];
        var chatTitle = chat && chat.title ? chat.title.replace(/[^a-zA-Z0-9]/g, '_').substring(0, 30) : 'chat';
        var timestamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);
        var fileName = 'AppAgent_' + chatTitle + '_' + timestamp + '.xml';

        // Combine all record XMLs into one update set XML
        var combinedXml = buildUpdateSetXml(recordXmls);

        // Download the file
        var blob = new Blob([combinedXml], { type: 'application/xml' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        hideSpinner();

    } catch (e) {
        hideSpinner();
        showSnackbar('Error downloading XML: ' + e.message, 'error');
    }
}

// Build the update set XML from individual record XMLs
function buildUpdateSetXml(recordXmls) {
    var xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
    xml += '<unload unload_date="' + new Date().toISOString().replace('T', ' ').substring(0, 19) + '">\n';

    recordXmls.forEach(function(recXml) {
        // Extract the actual record element, removing <unload> and <record_update> wrappers
        var content = recXml;

        // Remove XML declaration
        content = content.replace(/<\?xml[^?]*\?>/gi, '');

        // Extract content from <unload> if present
        var unloadMatch = content.match(/<unload[^>]*>([\s\S]*)<\/unload>/i);
        if (unloadMatch) {
            content = unloadMatch[1];
        }

        // Remove <record_update> wrapper if present, keeping the inner record element
        var recordUpdateMatch = content.match(/<record_update[^>]*>([\s\S]*)<\/record_update>/i);
        if (recordUpdateMatch) {
            content = recordUpdateMatch[1];
        }

        xml += content.trim() + '\n';
    });

    xml += '</unload>';
    return xml;
}

// Legacy function for compatibility
function clearUpdateSet() {
    // No longer needed but kept for compatibility
}

// Get all changes for a user message (including reverted ones for display)
function getAllChangesForUserMessage(userMsgIndex) {
    var chat = chats[currentChatId];
    if (!chat) return { active: [], reverted: [] };

    // Find the next user message index
    var nextUserMsgIndex = chat.messages.length;
    for (var i = userMsgIndex + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserMsgIndex = i;
            break;
        }
    }

    var active = [];
    var reverted = [];

    versionHistory.forEach(function(v) {
        if (v.chatId === currentChatId && 
            v.messageIndex >= userMsgIndex && 
            v.messageIndex < nextUserMsgIndex &&
            v.action !== 'REVERT' &&
            v.action !== 'USER_DELETE') {
            if (v.invalidated) {
                reverted.push(v);
            } else {
                active.push(v);
            }
        }
    });

    return { active: active, reverted: reverted };
}

// Render inline changes for a message block
function renderInlineChanges(userMsgIdx) {
    var allChanges = getAllChangesForUserMessage(userMsgIdx);

    if (allChanges.active.length === 0 && allChanges.reverted.length === 0) return '';

    // Group active changes by file
    var activeByFile = {};
    allChanges.active.forEach(function(c) {
        var key = c.table + '_' + c.sysId;
        if (!activeByFile[key]) {
            activeByFile[key] = { displayName: c.displayName, table: c.table, sysId: c.sysId, entries: [], beforeVersion: c.beforeVersion, isNew: false };
        }
        activeByFile[key].entries.push(c);
        activeByFile[key].afterVersion = c.afterVersion;
        if (c.action === 'POST') activeByFile[key].isNew = true;
    });

    // Group reverted changes by file
    var revertedByFile = {};
    allChanges.reverted.forEach(function(c) {
        var key = c.table + '_' + c.sysId;
        if (!revertedByFile[key]) {
            revertedByFile[key] = { displayName: c.displayName, table: c.table, sysId: c.sysId, entries: [], isNew: false };
        }
        revertedByFile[key].entries.push(c);
        revertedByFile[key].afterVersion = c.afterVersion;
        if (c.action === 'POST') revertedByFile[key].isNew = true;
    });

    var activeFiles = Object.values(activeByFile);
    var revertedFiles = Object.values(revertedByFile);

    var totalFiles = activeFiles.length + revertedFiles.length;
    var html = '<div class="inline-changes">';
    html += '<div class="inline-changes-header">Artifacts' + (totalFiles === 1 ? '' : ' (' + totalFiles + ')');
    // Add Revert All button if there are active files, or Redo All if there are reverted files
    if (activeFiles.length > 0) {
        html += '<button class="inline-revert-all-btn" onclick="revertAllInlineChanges(' + userMsgIdx + ')" title="Undo all changes from this response"><span class="btn-icon">' + UI_ICONS.undo + '</span>Revert All</button>';
    }
    if (revertedFiles.length > 0) {
        html += '<button class="inline-redo-all-btn" onclick="redoAllInlineChanges(' + userMsgIdx + ')" title="Redo all reverted changes from this response"><span class="btn-icon">' + UI_ICONS.redo + '</span>Redo All</button>';
    }
    html += '</div>';
    html += '<div class="inline-changes-list">';

    // Show active changes with dropdown menu - new card design
    activeFiles.forEach(function(file, idx) {
        var beforeVer = file.beforeVersion;
        var isNew = file.isNew;
        var hasEdit = file.entries.some(function(e) { return e.action === 'PUT' || e.action === 'PATCH'; });
        var firstEntry = file.entries[0];
        var msgIdx = firstEntry ? firstEntry.messageIndex : -1;
        var tableIcon = getTableIcon(file.table);
        var tableDisplayName = getTableDisplayName(file.table);
        var statusBadge = isNew ? '<span class="sn-status-badge sn-status-new">NEW</span>' : (hasEdit ? '<span class="sn-status-badge sn-status-modified">MODIFIED</span>' : '');
        var dropdownId = 'inline-dropdown-' + userMsgIdx + '-' + idx;

        html += '<div class="sn-artifact-card" onclick="scrollToToolInResponse(' + userMsgIdx + ')" title="Click to go to this change">';
        html += '<div class="sn-artifact-icon sn-icon-' + file.table.replace(/_/g, '-') + '">' + tableIcon + '</div>';
        html += '<div class="sn-artifact-content">';
        html += '<div class="sn-artifact-name">' + escapeHtml(file.displayName) + '</div>';
        html += '<div class="sn-artifact-meta">(' + tableDisplayName + ') ' + statusBadge + '</div>';
        html += '</div>';
        html += '<div class="sn-artifact-actions">';
        html += '<button class="sn-artifact-menu" onclick="event.stopPropagation(); toggleDropdown(\'' + dropdownId + '\')" aria-label="More options" aria-haspopup="true">···</button>';
        html += '<div class="sn-dropdown" id="' + dropdownId + '">';
        html += '<button class="sn-dropdown-item" onclick="event.stopPropagation(); closeDropdowns(); scrollToToolInResponse(' + userMsgIdx + ')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>View Changes</button>';
        if (isNew) {
            html += '<div class="sn-dropdown-divider"></div>';
            html += '<button class="sn-dropdown-item danger" onclick="event.stopPropagation(); closeDropdowns(); deleteNewRecord(\'' + escapeHtml(file.table) + '\', \'' + escapeHtml(file.sysId) + '\', \'' + escapeHtml(file.displayName) + '\', ' + userMsgIdx + ')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>Delete</button>';
        } else if (beforeVer) {
            html += '<div class="sn-dropdown-divider"></div>';
            html += '<button class="sn-dropdown-item" onclick="event.stopPropagation(); closeDropdowns(); revertInlineChange(\'' + beforeVer + '\', \'' + escapeHtml(file.table) + '\', \'' + escapeHtml(file.sysId) + '\', \'' + escapeHtml(file.displayName) + '\', ' + userMsgIdx + ')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>Undo</button>';
        }
        html += '</div>';
        html += '</div>';
        html += '</div>';
    });

    // Show reverted changes with dropdown menu - new card design
    revertedFiles.forEach(function(file, idx) {
        var afterVer = file.afterVersion;
        var tableIcon = getTableIcon(file.table);
        var tableDisplayName = getTableDisplayName(file.table);
        var dropdownId = 'inline-dropdown-reverted-' + userMsgIdx + '-' + idx;

        html += '<div class="sn-artifact-card reverted">';
        html += '<div class="sn-artifact-icon sn-icon-reverted">' + tableIcon + '</div>';
        html += '<div class="sn-artifact-content">';
        html += '<div class="sn-artifact-name">' + escapeHtml(file.displayName) + '</div>';
        html += '<div class="sn-artifact-meta">(' + tableDisplayName + ') <span class="sn-status-badge sn-status-reverted">REVERTED</span></div>';
        html += '</div>';
        html += '<div class="sn-artifact-actions">';
        if (afterVer) {
            html += '<button class="sn-artifact-menu" onclick="event.stopPropagation(); toggleDropdown(\'' + dropdownId + '\')" aria-label="More options" aria-haspopup="true">···</button>';
            html += '<div class="sn-dropdown" id="' + dropdownId + '">';
            html += '<button class="sn-dropdown-item" onclick="event.stopPropagation(); closeDropdowns(); redoInlineChange(\'' + afterVer + '\', \'' + escapeHtml(file.table) + '\', \'' + escapeHtml(file.sysId) + '\', \'' + escapeHtml(file.displayName) + '\', ' + userMsgIdx + ')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 1 1-9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/></svg>Redo</button>';
            html += '</div>';
        }
        html += '</div>';
        html += '</div>';
    });

    html += '</div></div>';
    return html;
}

// Revert a single inline change (only for changes in a specific user message range)
async function revertInlineChange(versionSysId, table, sysId, displayName, userMsgIdx) {
    if (!await showConfirmModal('Undo Changes', 'Undo changes to "' + displayName + '"? This will restore the file to its state before this AI response.')) return;

    // Find the message range for this user message
    var chat = chats[currentChatId];
    var nextUserMsgIdx = chat.messages.length;
    for (var i = userMsgIdx + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserMsgIdx = i;
            break;
        }
    }

    try {
        showSpinner('Reverting ' + displayName + '...');

        var xml = await getVersionXml(versionSysId);
        if (!xml) {
            hideSpinner();
            showSnackbar('Could not get version data', 'error');
            return;
        }

        var result = await uploadXml(xml, table, sysId);
        hideSpinner();

        if (result.success) {
            // Only mark entries for this file within this message range as invalidated
            versionHistory.forEach(function(v, idx) {
                if (v.table === table && v.sysId === sysId && v.chatId === currentChatId &&
                    v.messageIndex >= userMsgIdx && v.messageIndex < nextUserMsgIdx &&
                    v.action !== 'REVERT') {
                    versionHistory[idx].invalidated = true;
                }
            });

            // Add revert entry with the user message index
            addVersionHistoryEntry({
                id: 'vh_' + Date.now(),
                chatId: currentChatId,
                timestamp: Date.now(),
                table: table,
                sysId: sysId,
                displayName: displayName,
                action: 'REVERT',
                messageIndex: userMsgIdx,
                revertedUserMsgIdx: userMsgIdx,
                afterVersion: versionSysId
            });

            showSnackbar('Successfully reverted "' + displayName + '"', 'success');
        } else {
            showSnackbar('Revert failed: ' + result.error, 'error');
        }
    } catch (e) {
        hideSpinner();
        showSnackbar('Revert failed: ' + e.message, 'error');
    }
}

// Revert all inline changes for a specific user message range
async function revertAllInlineChanges(userMsgIdx) {
    var allChanges = getAllChangesForUserMessage(userMsgIdx);
    if (allChanges.active.length === 0) {
        showSnackbar('No active changes to revert', 'warning');
        return;
    }

    // Group by file and track afterVersion for redo
    var filesByKey = {};
    allChanges.active.forEach(function(c) {
        var key = c.table + '_' + c.sysId;
        if (!filesByKey[key]) {
            filesByKey[key] = { table: c.table, sysId: c.sysId, displayName: c.displayName, beforeVersion: c.beforeVersion, afterVersion: c.afterVersion, isNew: c.action === 'POST' };
        }
        // Keep the latest afterVersion for redo
        if (c.afterVersion) {
            filesByKey[key].afterVersion = c.afterVersion;
        }
    });

    var files = Object.values(filesByKey);
    if (!await showConfirmModal('Revert All', 'Revert all ' + files.length + ' file(s) changed in this response?')) return;

    var chat = chats[currentChatId];
    var nextUserMsgIdx = chat.messages.length;
    for (var i = userMsgIdx + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserMsgIdx = i;
            break;
        }
    }

    showSpinner('Reverting ' + files.length + ' files...');
    var successCount = 0;
    var errors = [];

    for (var i = 0; i < files.length; i++) {
        var file = files[i];
        try {
            if (file.isNew) {
                // Delete new records - first check if it exists
                try {
                    var checkRes = await fetch('/api/now/table/' + file.table + '/' + file.sysId + '?sysparm_fields=sys_id', { 
                        method: 'GET', 
                        headers: { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' } 
                    });
                    if (checkRes.ok) {
                        // Record exists, delete it
                        var recordScope = await getRecordScope(file.table, file.sysId);
                        var deleteUrl = '/api/now/table/' + file.table + '/' + file.sysId;
                        if (recordScope) deleteUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
                        var res = await fetch(deleteUrl, { method: 'DELETE', headers: { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' } });
                        if (res.ok || res.status === 204) {
                            successCount++;
                        } else {
                            errors.push(file.displayName + ': Delete failed ' + res.status);
                        }
                    } else if (checkRes.status === 404) {
                        // Record already deleted, count as success
                        successCount++;
                    } else {
                        errors.push(file.displayName + ': Check failed ' + checkRes.status);
                    }
                } catch (checkErr) {
                    errors.push(file.displayName + ': ' + checkErr.message);
                }
                // Mark as invalidated regardless
                versionHistory.forEach(function(v, idx) {
                    if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId &&
                        v.messageIndex >= userMsgIdx && v.messageIndex < nextUserMsgIdx && v.action !== 'REVERT') {
                        versionHistory[idx].invalidated = true;
                    }
                });
                // Add REVERT entry for new files so they can be redone/recreated
                var latestAfterVersionNew = null;
                versionHistory.forEach(function(v) {
                    if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId && 
                        v.afterVersion && v.action !== 'REVERT') {
                        latestAfterVersionNew = v.afterVersion;
                    }
                });
                if (latestAfterVersionNew) {
                    versionHistory.push({
                        id: 'vh_' + Date.now() + '_new_' + i,
                        chatId: currentChatId,
                        timestamp: Date.now(),
                        table: file.table,
                        sysId: file.sysId,
                        displayName: file.displayName,
                        action: 'REVERT',
                        messageIndex: userMsgIdx,
                        revertedUserMsgIdx: userMsgIdx,
                        afterVersion: latestAfterVersionNew,
                        wasNew: true
                    });
                }
            } else if (file.beforeVersion) {
                // Revert existing records
                var xml = await getVersionXml(file.beforeVersion);
                if (xml) {
                    var result = await uploadXml(xml, file.table, file.sysId);
                    if (result.success) {
                        successCount++;
                        versionHistory.forEach(function(v, idx) {
                            if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId &&
                                v.messageIndex >= userMsgIdx && v.messageIndex < nextUserMsgIdx && v.action !== 'REVERT') {
                                versionHistory[idx].invalidated = true;
                            }
                        });
                        // Add REVERT entry so file appears in "Reverted Changes" for redo
                        var latestAfterVersion = null;
                        versionHistory.forEach(function(v) {
                            if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId && 
                                v.afterVersion && v.action !== 'REVERT') {
                                latestAfterVersion = v.afterVersion;
                            }
                        });
                        if (latestAfterVersion) {
                            versionHistory.push({
                                id: 'vh_' + Date.now() + '_' + i,
                                chatId: currentChatId,
                                timestamp: Date.now(),
                                table: file.table,
                                sysId: file.sysId,
                                displayName: file.displayName,
                                action: 'REVERT',
                                messageIndex: userMsgIdx,
                                revertedUserMsgIdx: userMsgIdx,
                                afterVersion: latestAfterVersion
                            });
                        }
                    } else {
                        errors.push(file.displayName + ': ' + result.error);
                    }
                }
            }
        } catch (e) {
            errors.push(file.displayName + ': ' + e.message);
        }
    }

    hideSpinner();
    saveVersionHistory();
    renderVersionSidebar();
    renderMessages();

    if (errors.length > 0) {
        showSnackbar('Reverted ' + successCount + ' of ' + files.length + ' files.\n\nErrors:\n' + errors.join('\n'), 'warning');
    } else {
        showSnackbar('Successfully reverted ' + successCount + ' files', 'success');
    }
}

// Redo an inline change that was reverted
async function redoInlineChange(versionSysId, table, sysId, displayName, userMsgIdx) {
    if (!await showConfirmModal('Redo Changes', 'Redo changes to "' + displayName + '"? This will restore the AI-made changes.')) return;

    // Find the message range for this user message
    var chat = chats[currentChatId];
    var nextUserMsgIdx = chat.messages.length;
    for (var i = userMsgIdx + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserMsgIdx = i;
            break;
        }
    }

    try {
        showSpinner('Restoring ' + displayName + '...');

        var xml = await getVersionXml(versionSysId);
        if (!xml) {
            hideSpinner();
            showSnackbar('Could not get version data', 'error');
            return;
        }

        var result = await uploadXml(xml, table, sysId);
        hideSpinner();

        if (result.success) {
            // Un-invalidate entries for this file within this message range
            versionHistory.forEach(function(v, idx) {
                if (v.table === table && v.sysId === sysId && v.chatId === currentChatId &&
                    v.messageIndex >= userMsgIdx && v.messageIndex < nextUserMsgIdx &&
                    v.action !== 'REVERT') {
                    versionHistory[idx].invalidated = false;
                }
            });

            // Remove the revert entry for this specific user message
            versionHistory = versionHistory.filter(function(v) {
                return !(v.table === table && v.sysId === sysId && v.chatId === currentChatId &&
                         v.action === 'REVERT' && v.revertedUserMsgIdx === userMsgIdx);
            });

            saveVersionHistory();
            renderVersionSidebar();
            renderMessages();

            showSnackbar('Successfully restored "' + displayName + '"', 'success');
        } else {
            showSnackbar('Redo failed: ' + result.error, 'error');
        }
    } catch (e) {
        hideSpinner();
        showSnackbar('Redo failed: ' + e.message, 'error');
    }
}

// Redo all inline changes that were reverted for a specific user message
async function redoAllInlineChanges(userMsgIdx) {
    var allChanges = getAllChangesForUserMessage(userMsgIdx);
    if (allChanges.reverted.length === 0) {
        showSnackbar('No reverted changes to redo', 'warning');
        return;
    }

    // Group by file
    var filesByKey = {};
    allChanges.reverted.forEach(function(c) {
        var key = c.table + '_' + c.sysId;
        if (!filesByKey[key]) {
            filesByKey[key] = { table: c.table, sysId: c.sysId, displayName: c.displayName, afterVersion: c.afterVersion };
        }
        if (c.afterVersion) {
            filesByKey[key].afterVersion = c.afterVersion;
        }
    });

    var files = Object.values(filesByKey);
    if (!await showConfirmModal('Redo All', 'Redo all ' + files.length + ' reverted file(s) from this response?')) return;

    var chat = chats[currentChatId];
    var nextUserMsgIdx = chat.messages.length;
    for (var i = userMsgIdx + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserMsgIdx = i;
            break;
        }
    }

    showSpinner('Restoring ' + files.length + ' files...');
    var successCount = 0;
    var errors = [];

    for (var i = 0; i < files.length; i++) {
        var file = files[i];
        try {
            // Find the latest afterVersion for this file
            var latestAfterVersion = null;
            versionHistory.forEach(function(v) {
                if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId && 
                    v.afterVersion && v.action !== 'REVERT') {
                    latestAfterVersion = v.afterVersion;
                }
            });

            if (!latestAfterVersion) {
                errors.push(file.displayName + ': No version to restore');
                continue;
            }

            var xml = await getVersionXml(latestAfterVersion);
            if (!xml) {
                errors.push(file.displayName + ': Could not get version data');
                continue;
            }

            var result = await uploadXml(xml, file.table, file.sysId);
            if (result.success) {
                successCount++;
                // Un-invalidate entries for this file within this message range
                versionHistory.forEach(function(v, idx) {
                    if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId &&
                        v.messageIndex >= userMsgIdx && v.messageIndex < nextUserMsgIdx &&
                        v.action !== 'REVERT') {
                        versionHistory[idx].invalidated = false;
                    }
                });
                // Remove REVERT entries for this file within this message range
                versionHistory = versionHistory.filter(function(v) {
                    return !(v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId && 
                             v.action === 'REVERT' && v.revertedUserMsgIdx === userMsgIdx);
                });
            } else {
                errors.push(file.displayName + ': ' + result.error);
            }
        } catch (e) {
            errors.push(file.displayName + ': ' + e.message);
        }
    }

    hideSpinner();
    saveVersionHistory();
    renderVersionSidebar();
    renderMessages();

    if (errors.length > 0) {
        showSnackbar('Restored ' + successCount + ' of ' + files.length + ' files.\n\nErrors:\n' + errors.join('\n'), 'warning');
    } else {
        showSnackbar('Successfully restored ' + successCount + ' files', 'success');
    }
}

// Delete a newly created record
async function deleteNewRecord(table, sysId, displayName, userMsgIdx) {
    if (!await showConfirmModal('Delete Record', 'Delete "' + displayName + '"? This will permanently delete this newly created record.')) return;

    try {
        showSpinner('Deleting ' + displayName + '...');

        var headers = { 
            'X-UserToken': window.sessionToken, 
            'Accept': 'application/json',
            'Content-Type': 'application/json'
        };

        // Get record's scope for delete request
        var recordScope = await getRecordScope(table, sysId);
        var deleteUrl = '/api/now/table/' + table + '/' + sysId;
        if (recordScope) {
            deleteUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
        }

        var res = await fetch(deleteUrl, {
            method: 'DELETE',
            headers: headers
        });

        hideSpinner();

        if (res.ok || res.status === 204) {
            // Find the message range for this user message
            var chat = chats[currentChatId];
            var nextUserMsgIdx = chat.messages.length;
            for (var i = userMsgIdx + 1; i < chat.messages.length; i++) {
                if (chat.messages[i].role === 'user') {
                    nextUserMsgIdx = i;
                    break;
                }
            }

            // Mark entries for this file within this message range as invalidated
            versionHistory.forEach(function(v, idx) {
                if (v.table === table && v.sysId === sysId && v.chatId === currentChatId &&
                    v.messageIndex >= userMsgIdx && v.messageIndex < nextUserMsgIdx &&
                    v.action !== 'REVERT') {
                    versionHistory[idx].invalidated = true;
                }
            });

            // Add delete entry
            addVersionHistoryEntry({
                id: 'vh_' + Date.now(),
                chatId: currentChatId,
                timestamp: Date.now(),
                table: table,
                sysId: sysId,
                displayName: displayName,
                action: 'USER_DELETE',
                messageIndex: userMsgIdx
            });

            showSnackbar('Successfully deleted "' + displayName + '"', 'success');
        } else {
            var errData = await res.json().catch(function() { return {}; });
            showSnackbar('Delete failed: ' + (errData.error?.message || res.status), 'error');
        }
    } catch (e) {
        hideSpinner();
        showSnackbar('Delete failed: ' + e.message, 'error');
    }
}

function saveVersionHistory() {
    if (currentChatId && chats[currentChatId]) {
        chats[currentChatId].versionHistory = versionHistory;
        saveChatsToStorage();
    }
}

function loadVersionHistory() {
    if (currentChatId && chats[currentChatId] && chats[currentChatId].versionHistory) {
        versionHistory = chats[currentChatId].versionHistory;
    } else {
        versionHistory = [];
    }
    renderVersionSidebar();
    updateVersionSidebarVisibility();
}

// Get all versions for a specific file in this chat
function getVersionsForFile(table, sysId) {
    var versions = [];
    versionHistory.forEach(function(v) {
        if (v.chatId === currentChatId && v.table === table && v.sysId === sysId &&
            v.action !== 'REVERT' && v.action !== 'USER_DELETE' && !v.invalidated) {
            if (v.beforeVersion) {
                var exists = versions.some(function(ver) { return ver.versionId === v.beforeVersion; });
                if (!exists) {
                    versions.push({
                        versionId: v.beforeVersion,
                        timestamp: v.timestamp,
                        label: new Date(v.timestamp).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}) + ' - Original',
                        isBefore: true,
                        isFromChat: true
                    });
                }
            }
            if (v.afterVersion) {
                var statusMsg = v.statusMessage;
                var actionLabel = statusMsg || (v.action === 'POST' ? 'Created' : (v.action === 'PUT' || v.action === 'PATCH' || v.action === 'EDIT' ? 'Updated' : v.action));
                versions.push({
                    versionId: v.afterVersion,
                    timestamp: v.timestamp,
                    label: new Date(v.timestamp).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}) + ' - ' + actionLabel,
                    isBefore: false,
                    isFromChat: true
                });
            }
        }
    });
    // Sort by timestamp
    versions.sort(function(a, b) { return a.timestamp - b.timestamp; });
    return versions;
}

// Fetch historical versions for a record from sys_update_version (before the chat)
async function getHistoricalVersions(table, sysId, excludeVersionIds) {
    try {
        var headers = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
        var res = await fetch('/api/now/table/sys_update_version?sysparm_query=name=' + table + '_' + sysId + '^ORDERBYDESCsys_created_on&sysparm_fields=sys_id,sys_created_on,sys_created_by&sysparm_limit=10', { headers: headers });
        var data = await res.json();
        if (data.result && data.result.length > 0) {
            return data.result
                .filter(function(v) { return !excludeVersionIds.includes(v.sys_id); })
                .map(function(v) {
                    var ts = new Date(v.sys_created_on).getTime();
                    return {
                        versionId: v.sys_id,
                        timestamp: ts,
                        label: new Date(ts).toLocaleDateString([], {month: 'short', day: 'numeric'}) + ' ' + new Date(ts).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}) + ' - ' + (v.sys_created_by || 'Unknown'),
                        isBefore: true,
                        isFromChat: false
                    };
                });
        }
    } catch (e) {
        console.error('Failed to get historical versions:', e);
    }
    return [];
}

// Normalize line endings to \n for consistent diff
function normalizeLineEndings(text) {
    if (!text) return '';
    // Replace \r\n (Windows) and \r (old Mac) with \n (Unix)
    return text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

// Format XML content for display (pretty print if compressed)
function formatXmlForDiff(xml) {
    if (!xml) return '';
    // Normalize line endings first
    xml = normalizeLineEndings(xml);
    // If XML appears to be on a single line (compressed), try to format it
    var lines = xml.split('\n');
    if (lines.length <= 3 && xml.length > 500) {
        // Attempt basic XML formatting - add newlines after tags
        var formatted = xml
            .replace(/>\s*</g, '>\n<')
            .replace(/(<[^\/][^>]*[^\/]>)([^<]+)(<\/)/g, '$1\n$2\n$3');
        return formatted;
    }
    return xml;
}

// Compute diff between two strings (simple line-based diff)
function computeDiff(oldText, newText) {
    // Normalize line endings before splitting
    var oldNormalized = normalizeLineEndings(oldText || '');
    var newNormalized = normalizeLineEndings(newText || '');

    var oldLines = oldNormalized.split('\n');
    var newLines = newNormalized.split('\n');
    var result = [];

    // LCS-based diff algorithm
    var m = oldLines.length;
    var n = newLines.length;

    // Build LCS table
    var lcs = [];
    for (var i = 0; i <= m; i++) {
        lcs[i] = [];
        for (var j = 0; j <= n; j++) {
            if (i === 0 || j === 0) {
                lcs[i][j] = 0;
            } else if (oldLines[i-1] === newLines[j-1]) {
                lcs[i][j] = lcs[i-1][j-1] + 1;
            } else {
                lcs[i][j] = Math.max(lcs[i-1][j], lcs[i][j-1]);
            }
        }
    }

    // Backtrack to find diff
    var diff = [];
    i = m;
    var j = n;
    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && oldLines[i-1] === newLines[j-1]) {
            diff.unshift({ type: 'same', oldLine: i, newLine: j, text: oldLines[i-1] });
            i--; j--;
        } else if (j > 0 && (i === 0 || lcs[i][j-1] >= lcs[i-1][j])) {
            diff.unshift({ type: 'add', oldLine: null, newLine: j, text: newLines[j-1] });
            j--;
        } else {
            diff.unshift({ type: 'remove', oldLine: i, newLine: null, text: oldLines[i-1] });
            i--;
        }
    }

    return diff;
}

// Compute word-level diff between two lines (for highlighting changed words)
function computeWordDiff(oldText, newText) {
    if (!oldText || !newText) return { oldHtml: escapeHtml(oldText || ''), newHtml: escapeHtml(newText || '') };

    // Split into words (preserving whitespace and punctuation as separate tokens)
    function tokenize(text) {
        return text.match(/\S+|\s+/g) || [];
    }

    var oldWords = tokenize(oldText);
    var newWords = tokenize(newText);
    var m = oldWords.length;
    var n = newWords.length;

    // For very long lines, skip word diff
    if (m > 200 || n > 200) {
        return { oldHtml: escapeHtml(oldText), newHtml: escapeHtml(newText) };
    }

    // Build LCS table for words
    var lcs = [];
    for (var i = 0; i <= m; i++) {
        lcs[i] = [];
        for (var j = 0; j <= n; j++) {
            if (i === 0 || j === 0) {
                lcs[i][j] = 0;
            } else if (oldWords[i-1] === newWords[j-1]) {
                lcs[i][j] = lcs[i-1][j-1] + 1;
            } else {
                lcs[i][j] = Math.max(lcs[i-1][j], lcs[i][j-1]);
            }
        }
    }

    // Backtrack to find word-level changes
    var oldResult = [];
    var newResult = [];
    i = m;
    var j = n;

    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && oldWords[i-1] === newWords[j-1]) {
            oldResult.unshift({ word: oldWords[i-1], changed: false });
            newResult.unshift({ word: newWords[j-1], changed: false });
            i--; j--;
        } else if (j > 0 && (i === 0 || lcs[i][j-1] >= lcs[i-1][j])) {
            newResult.unshift({ word: newWords[j-1], changed: true });
            j--;
        } else {
            oldResult.unshift({ word: oldWords[i-1], changed: true });
            i--;
        }
    }

    // Build HTML with highlights (whole words highlighted)
    function buildHtml(result, highlightClass) {
        var html = '';
        var inHighlight = false;
        result.forEach(function(item) {
            var isWhitespace = /^\s+$/.test(item.word);
            if (item.changed && !isWhitespace && !inHighlight) {
                html += '<span class="' + highlightClass + '">';
                inHighlight = true;
            } else if ((!item.changed || isWhitespace) && inHighlight) {
                html += '</span>';
                inHighlight = false;
            }
            html += escapeHtml(item.word);
        });
        if (inHighlight) html += '</span>';
        return html;
    }

    return {
        oldHtml: buildHtml(oldResult, 'diff-word-remove'),
        newHtml: buildHtml(newResult, 'diff-word-add')
    };
}

// Navigation state for diff viewer
var currentDiffChangeIndex = 0;
var diffChangeElements = [];

// Navigate to previous/next change in diff viewer
function navigateDiffChange(direction) {
    if (diffChangeElements.length === 0) return;

    currentDiffChangeIndex += direction;
    if (currentDiffChangeIndex < 0) currentDiffChangeIndex = diffChangeElements.length - 1;
    if (currentDiffChangeIndex >= diffChangeElements.length) currentDiffChangeIndex = 0;

    // Scroll to the change
    var element = diffChangeElements[currentDiffChangeIndex];
    if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        // Update counter
        var counter = document.getElementById('diff-nav-counter');
        if (counter) counter.textContent = (currentDiffChangeIndex + 1) + ' / ' + diffChangeElements.length;
    }
}

// State for diff viewer
var currentDiffFile = null;

// Open fullscreen diff viewer
async function openDiffViewer(table, sysId, displayName) {
    var versions = getVersionsForFile(table, sysId);

    var isNew = versionHistory.some(function(v) {
        return v.chatId === currentChatId && v.table === table && v.sysId === sysId &&
               v.action === 'POST' && !v.invalidated;
    });
    var firstBeforeVersion = getFirstVersionForRecord(table, sysId);
    var latestAfterVersion = getLatestAfterVersion(table, sysId);

    // Determine if we have versions to compare (excluding the current/latest version)
    var hasComparableVersions = versions.length > 1 || (versions.length === 1 && versions[0].versionId !== latestAfterVersion);

    currentDiffFile = { table: table, sysId: sysId, displayName: displayName, versions: versions, isNew: isNew, firstBeforeVersion: firstBeforeVersion, latestAfterVersion: latestAfterVersion, hasComparableVersions: hasComparableVersions };

    // Create overlay
    var overlay = document.createElement('div');
    overlay.className = 'diff-viewer-overlay';
    overlay.id = 'diff-viewer-overlay';
    overlay.onclick = function(e) { if (e.target === overlay) closeDiffViewer(); };

    // Create modal
    var modal = document.createElement('div');
    modal.className = 'diff-viewer-modal';

    // Header with actions
    var header = document.createElement('div');
    header.className = 'diff-viewer-header';
    header.id = 'diff-viewer-header';

    var revertBtnHtml = '';
    if (isNew) {
        revertBtnHtml = '<button class="diff-action-btn danger" onclick="revertFromDiffViewer()" title="Delete this new record">' + UI_ICONS.trash + '<span>Delete</span></button>';
    } else if (firstBeforeVersion) {
        revertBtnHtml = '<button class="diff-action-btn" onclick="revertFromDiffViewer()" title="Revert to before chat">' + UI_ICONS.undo + '<span>Revert</span></button>';
    }

    // Build compare section - either dropdown or "no earlier version" message
    var compareHtml = '';
    if (hasComparableVersions) {
        compareHtml = '<span class="diff-compare-label">Compare with:</span>' +
            '<select id="diff-compare-version" class="diff-version-select" onchange="updateDiffView()">' +
            '<option value="">Loading...</option></select>';
    } else {
        compareHtml = '<span class="diff-no-compare">No earlier version to compare against</span>';
    }

    // Open on instance URL
    var instanceUrl = '/' + table + '.do?sys_id=' + sysId;

    header.innerHTML = '<div class="diff-header-left">' +
        '<span class="diff-file-name">' + escapeHtml(displayName) + '</span>' +
        compareHtml +
        '</div>' +
        '<div class="diff-header-center" id="diff-header-stats"></div>' +
        '<div class="diff-header-right">' +
        '<a class="diff-action-btn" href="' + instanceUrl + '" target="_blank" title="Open on instance">' + UI_ICONS.externalLink + '<span>Open</span></a>' +
        '<button class="diff-action-btn" onclick="downloadFromDiffViewer()" title="Download XML">' + UI_ICONS.download + '<span>Download</span></button>' +
        revertBtnHtml +
        '<button class="diff-close-btn" onclick="closeDiffViewer()" title="Close">' + UI_ICONS.close + '</button>' +
        '</div>';

    // Content area
    var content = document.createElement('div');
    content.className = 'diff-viewer-content';
    content.id = 'diff-viewer-content';
    content.innerHTML = '<div class="diff-loading"><div class="spinner"></div>Loading...</div>';

    modal.appendChild(header);
    modal.appendChild(content);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    // Fetch historical versions and populate dropdown
    if (hasComparableVersions) {
        var chatVersionIds = versions.map(function(v) { return v.versionId; });
        var historicalVersions = await getHistoricalVersions(table, sysId, chatVersionIds);

        // Combine and sort all versions
        var allVersions = versions.concat(historicalVersions);
        allVersions.sort(function(a, b) { return a.timestamp - b.timestamp; });
        currentDiffFile.allVersions = allVersions;

        // Build dropdown with grouped options
        var dropdown = document.getElementById('diff-compare-version');
        if (dropdown) {
            var dropdownHtml = '';
            var chatVersions = allVersions.filter(function(v) { return v.isFromChat && v.versionId !== latestAfterVersion; });
            var histVersions = allVersions.filter(function(v) { return !v.isFromChat; });
            var currentVersion = allVersions.find(function(v) { return v.versionId === latestAfterVersion; });

            // Current version first (disabled)
            if (currentVersion) {
                dropdownHtml += '<option value="' + currentVersion.versionId + '" disabled class="diff-option-current">' + escapeHtml(currentVersion.label) + ' (Current)</option>';
            }

            // Chat versions (excluding current)
            if (chatVersions.length > 0) {
                dropdownHtml += '<optgroup label="This Chat">';
                chatVersions.forEach(function(ver, idx) {
                    var selected = idx === 0 ? ' selected' : '';
                    dropdownHtml += '<option value="' + ver.versionId + '"' + selected + '>' + escapeHtml(ver.label) + '</option>';
                });
                dropdownHtml += '</optgroup>';
            }

            // Historical versions
            if (histVersions.length > 0) {
                dropdownHtml += '<optgroup label="Earlier History">';
                var firstInGroup = chatVersions.length === 0;
                histVersions.forEach(function(ver, idx) {
                    var selected = firstInGroup && idx === 0 ? ' selected' : '';
                    dropdownHtml += '<option value="' + ver.versionId + '" class="diff-option-historical"' + selected + '>' + escapeHtml(ver.label) + '</option>';
                });
                dropdownHtml += '</optgroup>';
            }

            dropdown.innerHTML = dropdownHtml;
        }
    }

    // Load and display diff
    await updateDiffView();
}

// Update diff view when comparison version changes
async function updateDiffView() {
    if (!currentDiffFile) return;

    var content = document.getElementById('diff-viewer-content');
    var headerStats = document.getElementById('diff-header-stats');
    if (!content) return;

    content.innerHTML = '<div class="diff-loading"><div class="spinner"></div>Loading...</div>';
    if (headerStats) headerStats.innerHTML = '';

    var latestAfterVersion = getLatestAfterVersion(currentDiffFile.table, currentDiffFile.sysId);
    var isPreviewOnly = !currentDiffFile.hasComparableVersions;

    // Get compare version from dropdown if available
    var compareVersionId = null;
    var dropdown = document.getElementById('diff-compare-version');
    if (dropdown) {
        compareVersionId = dropdown.value;
    }

    // If preview only mode, just show the current version
    if (isPreviewOnly) {
        try {
            var xml = latestAfterVersion ? await getVersionXml(latestAfterVersion) : null;
            if (!xml) {
                content.innerHTML = '<div class="diff-error">Could not load version data.</div>';
                return;
            }
            var formattedXml = formatXmlForDiff(xml);
            var lines = formattedXml.split('\n');

            var html = '<div class="diff-container diff-preview">';
            html += '<div class="diff-lines">';
            lines.forEach(function(line, idx) {
                html += '<div class="diff-line">';
                html += '<span class="diff-line-num">' + (idx + 1) + '</span>';
                html += '<span class="diff-text">' + escapeHtml(line) + '</span>';
                html += '</div>';
            });
            html += '</div></div>';
            content.innerHTML = html;

            if (headerStats) headerStats.innerHTML = '<span class="diff-preview-label">' + lines.length + ' lines</span>';
        } catch (e) {
            content.innerHTML = '<div class="diff-error">Failed to load version data: ' + escapeHtml(e.message) + '</div>';
        }
        return;
    }

    // If comparing the same version, show a message
    if (compareVersionId === latestAfterVersion) {
        content.innerHTML = '<div class="diff-no-changes"><div class="diff-no-changes-icon">' + UI_ICONS.info + '</div><div class="diff-no-changes-text">This is the current version. Select an earlier version to compare.</div></div>';
        if (headerStats) headerStats.innerHTML = '';
        return;
    }

    try {
        var oldXml = await getVersionXml(compareVersionId);
        var newXml = latestAfterVersion ? await getVersionXml(latestAfterVersion) : oldXml;

        if (!oldXml) {
            content.innerHTML = '<div class="diff-error">Could not load version data. The version may have been deleted.</div>';
            return;
        }

        // Format XML for proper display with line breaks
        var oldContent = formatXmlForDiff(oldXml);
        var newContent = formatXmlForDiff(newXml);

        console.log('Diff comparison:', { compareVersionId: compareVersionId, latestAfterVersion: latestAfterVersion, oldLength: oldContent ? oldContent.length : 0, newLength: newContent ? newContent.length : 0 });

        var diff = computeDiff(oldContent, newContent);

        // Find pairs of adjacent remove/add lines for word-level diff
        var wordDiffs = {};
        for (var i = 0; i < diff.length - 1; i++) {
            if (diff[i].type === 'remove' && diff[i+1].type === 'add') {
                var wordDiff = computeWordDiff(diff[i].text, diff[i+1].text);
                wordDiffs[i] = wordDiff.oldHtml;
                wordDiffs[i+1] = wordDiff.newHtml;
            }
        }

        // Render diff - group consecutive changes into hunks
        var html = '<div class="diff-container">';
        html += '<div class="diff-gutter-old"></div>';
        html += '<div class="diff-gutter-new"></div>';
        html += '<div class="diff-lines">';

        var hunkIndex = -1;
        var inHunk = false;
        diff.forEach(function(line, idx) {
            var lineClass = 'diff-line';
            var oldLineNum = line.oldLine !== null ? line.oldLine : '';
            var newLineNum = line.newLine !== null ? line.newLine : '';
            var prefix = ' ';
            var textContent = escapeHtml(line.text);
            var isChange = line.type !== 'same';
            var hunkStartAttr = '';

            // Track hunks - a hunk is a group of consecutive changed lines
            if (isChange && !inHunk) {
                // Starting a new hunk
                hunkIndex++;
                inHunk = true;
                hunkStartAttr = ' data-hunk-start="' + hunkIndex + '"';
            } else if (!isChange && inHunk) {
                // Ending a hunk
                inHunk = false;
            }

            if (line.type === 'add') {
                lineClass += ' diff-add diff-change';
                prefix = '+';
                if (wordDiffs[idx]) textContent = wordDiffs[idx];
            } else if (line.type === 'remove') {
                lineClass += ' diff-remove diff-change';
                prefix = '-';
                if (wordDiffs[idx]) textContent = wordDiffs[idx];
            }

            html += '<div class="' + lineClass + '"' + hunkStartAttr + '>';
            html += '<span class="diff-line-num old">' + oldLineNum + '</span>';
            html += '<span class="diff-line-num new">' + newLineNum + '</span>';
            html += '<span class="diff-prefix">' + prefix + '</span>';
            html += '<span class="diff-text">' + textContent + '</span>';
            html += '</div>';
        });

        html += '</div></div>';

        content.innerHTML = html;

        // Update header stats with navigation
        var addCount = diff.filter(function(l) { return l.type === 'add'; }).length;
        var removeCount = diff.filter(function(l) { return l.type === 'remove'; }).length;
        var totalHunks = hunkIndex + 1;

        if (headerStats) {
            var statsHtml = '<span class="diff-stat add">+' + addCount + '</span>';
            statsHtml += '<span class="diff-stat remove">-' + removeCount + '</span>';
            if (totalHunks > 0) {
                statsHtml += '<div class="diff-nav">';
                statsHtml += '<button class="diff-nav-btn" onclick="navigateDiffChange(-1)" title="Previous change">' + UI_ICONS.arrowUp + '</button>';
                statsHtml += '<span id="diff-nav-counter" class="diff-nav-counter">1 / ' + totalHunks + '</span>';
                statsHtml += '<button class="diff-nav-btn" onclick="navigateDiffChange(1)" title="Next change">' + UI_ICONS.arrowDown + '</button>';
                statsHtml += '</div>';
            }
            headerStats.innerHTML = statsHtml;
        }

        // Initialize navigation - select hunk start elements only
        diffChangeElements = content.querySelectorAll('[data-hunk-start]');
        currentDiffChangeIndex = 0;

    } catch (e) {
        content.innerHTML = '<div class="diff-error">Failed to load version data: ' + escapeHtml(e.message) + '</div>';
    }
}

// Close diff viewer
function closeDiffViewer() {
    currentDiffFile = null;
    var overlay = document.getElementById('diff-viewer-overlay');
    if (overlay) overlay.remove();
}

// Download from diff viewer
async function downloadFromDiffViewer() {
    if (!currentDiffFile) return;

    var latestAfterVersion = getLatestAfterVersion(currentDiffFile.table, currentDiffFile.sysId);
    if (!latestAfterVersion) {
        showSnackbar('No version to download', 'warning');
        return;
    }

    showSpinner('Downloading...');
    try {
        var xml = await getVersionXml(latestAfterVersion);
        if (xml) {
            var blob = new Blob([xml], { type: 'application/xml' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = currentDiffFile.displayName.replace(/[^a-zA-Z0-9_-]/g, '_') + '.xml';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showSnackbar('Downloaded ' + currentDiffFile.displayName, 'success');
        }
    } catch (e) {
        showSnackbar('Download failed: ' + e.message, 'error');
    }
    hideSpinner();
}

// Revert from diff viewer
async function revertFromDiffViewer() {
    if (!currentDiffFile) return;

    if (currentDiffFile.isNew) {
        // Delete new record
        if (!await showConfirmModal('Delete Record', 'Delete "' + currentDiffFile.displayName + '"? This will permanently delete this newly created record.')) return;

        showSpinner('Deleting...');
        try {
            var recordScope = await getRecordScope(currentDiffFile.table, currentDiffFile.sysId);
            var deleteUrl = '/api/now/table/' + currentDiffFile.table + '/' + currentDiffFile.sysId;
            if (recordScope) {
                deleteUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
            }

            var res = await fetch(deleteUrl, {
                method: 'DELETE',
                headers: { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' }
            });

            if (res.ok || res.status === 204) {
                // Mark all changes as invalidated
                versionHistory.forEach(function(v, idx) {
                    if (v.table === currentDiffFile.table && v.sysId === currentDiffFile.sysId && v.chatId === currentChatId) {
                        versionHistory[idx].invalidated = true;
                    }
                });
                addVersionHistoryEntry({
                    id: 'vh_' + Date.now(),
                    chatId: currentChatId,
                    timestamp: Date.now(),
                    table: currentDiffFile.table,
                    sysId: currentDiffFile.sysId,
                    displayName: currentDiffFile.displayName,
                    action: 'USER_DELETE',
                    messageIndex: -1
                });
                showSnackbar('Deleted "' + currentDiffFile.displayName + '"', 'success');
                closeDiffViewer();
            } else {
                showSnackbar('Delete failed', 'error');
            }
        } catch (e) {
            showSnackbar('Delete failed: ' + e.message, 'error');
        }
        hideSpinner();
    } else if (currentDiffFile.firstBeforeVersion) {
        // Revert to before chat
        if (!await showConfirmModal('Revert Changes', 'Revert "' + currentDiffFile.displayName + '" to its state before this chat? You can redo this later.')) return;

        showSpinner('Reverting...');
        try {
            var xml = await getVersionXml(currentDiffFile.firstBeforeVersion);
            if (xml) {
                var result = await uploadXml(xml, currentDiffFile.table, currentDiffFile.sysId);
                if (result.success) {
                    // Mark all changes as invalidated
                    versionHistory.forEach(function(v, idx) {
                        if (v.table === currentDiffFile.table && v.sysId === currentDiffFile.sysId && v.chatId === currentChatId) {
                            versionHistory[idx].invalidated = true;
                        }
                    });
                    addVersionHistoryEntry({
                        id: 'vh_' + Date.now(),
                        chatId: currentChatId,
                        timestamp: Date.now(),
                        table: currentDiffFile.table,
                        sysId: currentDiffFile.sysId,
                        displayName: currentDiffFile.displayName,
                        action: 'REVERT',
                        messageIndex: -1,
                        afterVersion: currentDiffFile.firstBeforeVersion
                    });
                    showSnackbar('Reverted "' + currentDiffFile.displayName + '"', 'success');
                    closeDiffViewer();
                } else {
                    showSnackbar('Revert failed: ' + result.error, 'error');
                }
            }
        } catch (e) {
            showSnackbar('Revert failed: ' + e.message, 'error');
        }
        hideSpinner();
    }
}

// Download single file from sidebar
async function downloadSingleFile(table, sysId, displayName) {
    var latestAfterVersion = getLatestAfterVersion(table, sysId);
    if (!latestAfterVersion) {
        showSnackbar('No version to download', 'warning');
        return;
    }

    showSpinner('Downloading...');
    try {
        var xml = await getVersionXml(latestAfterVersion);
        if (xml) {
            var blob = new Blob([xml], { type: 'application/xml' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = displayName.replace(/[^a-zA-Z0-9_-]/g, '_') + '.xml';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showSnackbar('Downloaded ' + displayName, 'success');
        }
    } catch (e) {
        showSnackbar('Download failed: ' + e.message, 'error');
    }
    hideSpinner();
}

// Delete a new record from the sidebar (simpler version without userMsgIdx)
async function deleteNewRecordFromSidebar(table, sysId, displayName) {
    if (!await showConfirmModal('Delete Record', 'Delete "' + displayName + '"? This will permanently delete this newly created record.')) return;

    try {
        showSpinner('Deleting ' + displayName + '...');

        var recordScope = await getRecordScope(table, sysId);
        var deleteUrl = '/api/now/table/' + table + '/' + sysId;
        if (recordScope) {
            deleteUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
        }

        var res = await fetch(deleteUrl, {
            method: 'DELETE',
            headers: {
                'X-UserToken': window.sessionToken,
                'Accept': 'application/json'
            }
        });

        hideSpinner();

        if (res.ok || res.status === 204) {
            // Mark all entries for this file as invalidated
            versionHistory.forEach(function(v, idx) {
                if (v.table === table && v.sysId === sysId && v.chatId === currentChatId && v.action !== 'REVERT') {
                    versionHistory[idx].invalidated = true;
                }
            });

            // Add delete entry
            addVersionHistoryEntry({
                id: 'vh_' + Date.now(),
                chatId: currentChatId,
                timestamp: Date.now(),
                table: table,
                sysId: sysId,
                displayName: displayName,
                action: 'USER_DELETE',
                messageIndex: -1
            });

            saveVersionHistory();
            renderVersionSidebar();
            renderMessages();

            showSnackbar('Successfully deleted "' + displayName + '"', 'success');
        } else {
            showSnackbar('Delete failed: ' + res.status, 'error');
        }
    } catch (e) {
        hideSpinner();
        showSnackbar('Delete failed: ' + e.message, 'error');
    }
}

async function revertToVersion(versionSysId, historyIndex, revertType) {
    if (!versionSysId) {
        showSnackbar('No version available to revert to', 'warning');
        return;
    }

    var entry = versionHistory[historyIndex];
    if (!entry) return;

    var confirmMsg = 'Revert ' + entry.displayName + ' to ' + (revertType === 'before' ? 'before' : 'after') + ' this change?';
    if (!await showConfirmModal('Revert Change', confirmMsg)) return;

    try {
        showSpinner('Fetching version XML...');

        // Get the XML payload from sys_update_version
        var xml = await getVersionXml(versionSysId);
        if (!xml) {
            hideSpinner();
            showSnackbar('Failed to get version XML', 'error');
            return;
        }

        showSpinner('Importing XML to revert...');

        var result = await uploadXml(xml, entry.table, entry.sysId);
        hideSpinner();

        if (result.success) {
            // Mark subsequent entries for the same record as invalid
            for (var i = historyIndex + 1; i < versionHistory.length; i++) {
                if (versionHistory[i].table === entry.table && versionHistory[i].sysId === entry.sysId) {
                    versionHistory[i].invalidated = true;
                }
            }

            // Add a revert entry to history
            var revertEntry = {
                id: 'vh_' + Date.now(),
                chatId: currentChatId,
                timestamp: Date.now(),
                table: entry.table,
                sysId: entry.sysId,
                displayName: entry.displayName,
                action: 'REVERT',
                messageIndex: -1,
                revertedFrom: historyIndex,
                revertType: revertType
            };
            versionHistory.push(revertEntry);

            saveVersionHistory();
            renderVersionSidebar();
            updateVersionSidebarVisibility();
            showSnackbar('Successfully reverted ' + entry.displayName, 'success');
        } else {
            showSnackbar('Failed to import XML: ' + result.error, 'error');
        }
    } catch (e) {
        hideSpinner();
        console.error('Revert failed:', e);
        showSnackbar('Revert failed: ' + e.message, 'error');
    }
}

function scrollToMessage(messageIndex) {
    if (messageIndex < 0 || messageIndex === undefined || messageIndex === null) {
        return false;
    }

    clearToolHighlights();

    var msgEl = document.getElementById('msg-' + messageIndex);
    if (msgEl) {
        // Expand any tool call details in this message and scroll to first one
        var toolCalls = msgEl.querySelectorAll('details.tool-call, details.tool-result');
        var scrollTarget = msgEl;
        if (toolCalls.length > 0) {
            collapseOtherTools(toolCalls[0]);
            toolCalls[0].open = true;
            scrollTarget = toolCalls[0];
        } else {
            // For user messages, target the message-content div
            var contentEl = msgEl.querySelector('.message-content');
            if (contentEl) scrollTarget = contentEl;
        }

        scrollTarget.scrollIntoView({ behavior: 'smooth', block: 'center' });
        scrollTarget.classList.add('highlight-flash');
        setTimeout(function() { scrollTarget.classList.remove('highlight-flash'); }, 2000);
        return true;
    }
    return false;
}

// Clear any existing highlights and collapse other tool panels
function clearToolHighlights() {
    document.querySelectorAll('.highlight-flash').forEach(function(el) {
        el.classList.remove('highlight-flash');
    });
}

// Track tool call expansion state
function toggleToolCallExpanded(msgIndex, tcIdx, details) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages[msgIndex]) return;
    var msg = chat.messages[msgIndex];
    if (!msg.toolCallsExpanded) msg.toolCallsExpanded = {};
    // onclick may fire before browser toggle - use opposite of PREVIOUS stored state
    var wasOpen = msg.toolCallsExpanded.hasOwnProperty(tcIdx) ? msg.toolCallsExpanded[tcIdx] : !details.open;
    msg.toolCallsExpanded[tcIdx] = !wasOpen;
}

// Track tool result expansion state
function toggleToolResultExpanded(msgIndex, details) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages[msgIndex]) return;
    // onclick may fire before browser toggle - use opposite of PREVIOUS stored state
    var wasOpen = chat.messages[msgIndex].expanded === true;
    chat.messages[msgIndex].expanded = !wasOpen;
}

// Track compact area expansion state during streaming (persists in memory only)
function toggleCompactAreaState(msgIndex, details) {
    // Store in global state - ontoggle fires AFTER browser toggles, so use current state
    compactAreaExpandedState[msgIndex] = details.open;
}

// Track thinking section expansion state during streaming (persists in memory only)
function toggleThinkingState(key, details) {
    // Store in global state - ontoggle fires AFTER browser toggles, so use current state
    thinkingExpandedState[key] = details.open;
}

// Collapse all tool panels except the target
function collapseOtherTools(targetEl, container) {
    var scope = container || document;
    scope.querySelectorAll('details.tool-call[open], details.tool-result[open]').forEach(function(el) {
        if (el !== targetEl) el.open = false;
    });
}

// Scroll to tool calls in a response block (from userMsgIdx to next user message)
function scrollToToolInResponse(userMsgIdx) {
    var chat = chats[currentChatId];
    if (!chat) return;

    clearToolHighlights();

    // Determine which container to use (overlay or main)
    var isOverlayMode = document.getElementById('iframe-panel').classList.contains('fullscreen');
    var container = isOverlayMode ? document.getElementById('overlay-messages') : document.getElementById('messages');
    if (!container) return;

    // Find next user message index
    var nextUserIdx = chat.messages.length;
    for (var i = userMsgIdx + 1; i < chat.messages.length; i++) {
        if (chat.messages[i].role === 'user') {
            nextUserIdx = i;
            break;
        }
    }

    // Find first assistant message with tool_calls in this range
    for (var j = userMsgIdx + 1; j < nextUserIdx; j++) {
        var msg = chat.messages[j];
        if (msg.role === 'assistant' && msg.tool_calls && msg.tool_calls.length > 0) {
            var msgEl = isOverlayMode ? container.querySelector('.message.assistant:nth-child(' + (j + 1) + ')') : document.getElementById('msg-' + j);
            if (!msgEl && isOverlayMode) {
                // In overlay, find by searching all assistant messages
                var allMsgs = container.querySelectorAll('.message');
                if (allMsgs[j]) msgEl = allMsgs[j];
            }
            if (msgEl) {
                var toolCalls = msgEl.querySelectorAll('details.tool-call, details.tool-result');
                if (toolCalls.length > 0) {
                    collapseOtherTools(toolCalls[0], container);
                    toolCalls[0].open = true;
                    toolCalls[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
                    toolCalls[0].classList.add('highlight-flash');
                    setTimeout(function() { toolCalls[0].classList.remove('highlight-flash'); }, 2000);
                    return;
                }
            }
        }
    }

    // Fallback: search container for any tool-call or tool-result elements
    var allToolCalls = container.querySelectorAll('details.tool-call, details.tool-result');
    if (allToolCalls.length > 0) {
        var lastToolCall = allToolCalls[allToolCalls.length - 1];
        collapseOtherTools(lastToolCall, container);
        lastToolCall.open = true;
        lastToolCall.scrollIntoView({ behavior: 'smooth', block: 'center' });
        lastToolCall.classList.add('highlight-flash');
        setTimeout(function() { lastToolCall.classList.remove('highlight-flash'); }, 2000);
    }
}

// Scroll to first tool call in a specific message (for sidebar clicks)
function scrollToFirstToolCall(msgIdx) {
    if (msgIdx < 0) return;
    var chat = chats[currentChatId];
    if (!chat) return;

    clearToolHighlights();

    // Try the given index first
    var msgEl = document.getElementById('msg-' + msgIdx);
    if (msgEl) {
        var toolCalls = msgEl.querySelectorAll('details.tool-call, details.tool-result');
        if (toolCalls.length > 0) {
            collapseOtherTools(toolCalls[0]);
            toolCalls[0].open = true;
            toolCalls[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
            toolCalls[0].classList.add('highlight-flash');
            setTimeout(function() { toolCalls[0].classList.remove('highlight-flash'); }, 2000);
            return;
        }
    }

    // Fallback: search nearby messages (msgIdx might point to approval message)
    // Search backwards and forwards a few messages to find tool calls
    for (var offset = 1; offset <= 3; offset++) {
        // Try before
        if (msgIdx - offset >= 0) {
            var prevEl = document.getElementById('msg-' + (msgIdx - offset));
            if (prevEl) {
                var prevTcs = prevEl.querySelectorAll('details.tool-call, details.tool-result');
                if (prevTcs.length > 0) {
                    collapseOtherTools(prevTcs[0]);
                    prevTcs[0].open = true;
                    prevTcs[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
                    prevTcs[0].classList.add('highlight-flash');
                    setTimeout(function() { prevTcs[0].classList.remove('highlight-flash'); }, 2000);
                    return;
                }
            }
        }
    }

    // Last fallback: scroll to original message
    if (msgEl) {
        msgEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        msgEl.classList.add('highlight-flash');
        setTimeout(function() { msgEl.classList.remove('highlight-flash'); }, 2000);
    }
}

function scrollToBottom() {
    var container = document.getElementById('messages');
    if (container) {
        container.scrollTo({ top: container.scrollHeight, behavior: 'smooth' });
    }
}

function toggleFileChanges(fileKey) {
    var el = document.getElementById('changes-' + fileKey);
    if (!el) return;
    var isExpanded = el.style.display !== 'none';
    el.style.display = isExpanded ? 'none' : 'block';
    // Update expand icon
    var icon = document.getElementById('icon-' + fileKey);
    if (icon) {
        icon.textContent = isExpanded ? '\u25b6' : '\u25bc';
    }
}

var versionSidebarManuallyHidden = false;

function loadVersionSidebarState() {
    var saved = appStorage.getItem('versionSidebarHidden');
    // Default to open (false) if not set
    versionSidebarManuallyHidden = saved === 'true';
}

function saveVersionSidebarState() {
    appStorage.setItem('versionSidebarHidden', versionSidebarManuallyHidden ? 'true' : 'false');
}

function updateVersionSidebarVisibility() {
    var sidebar = document.getElementById('version-sidebar');
    var openBtn = document.getElementById('version-sidebar-open');
    if (!sidebar) return;

    // Always show sidebar based on user preference, regardless of content
    if (!versionSidebarManuallyHidden) {
        sidebar.classList.add('visible');
        if (openBtn) openBtn.classList.remove('visible');
    } else {
        sidebar.classList.remove('visible');
        if (openBtn) openBtn.classList.add('visible');
    }
}

function closeVersionSidebar() {
    versionSidebarManuallyHidden = true;
    saveVersionSidebarState();
    updateVersionSidebarVisibility();
    resizeAllWidgets();
}

function openVersionSidebar() {
    versionSidebarManuallyHidden = false;
    saveVersionSidebarState();
    updateVersionSidebarVisibility();
    resizeAllWidgets();
}

// Render user messages list for navigation
function renderUserMessagesList() {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return '';

    var userMessages = [];
    chat.messages.forEach(function(msg, idx) {
        // Skip hook messages (like auto-title) unless showHookMessages is enabled
        if (msg.role === 'user' && !(msg.isHookMessage && !hooksEnabled.showHookMessages)) {
            userMessages.push({ index: idx, content: msg.content });
        }
    });

    if (userMessages.length === 0) return '';

    var html = '<div class="user-messages-section">';
    html += '<div class="user-messages-header">Your Messages (' + userMessages.length + ')</div>';
    html += '<div class="user-messages-list">';

    userMessages.forEach(function(msg, i) {
        var preview = msg.content.substring(0, 60) + (msg.content.length > 60 ? '...' : '');
        html += '<div class="user-message-item" onclick="scrollToMessage(' + msg.index + ')" title="' + escapeHtml(msg.content.substring(0, 200)) + '">';
        html += '<span class="user-message-num">' + (i + 1) + '</span>';
        html += '<span class="user-message-preview">' + escapeHtml(preview) + '</span>';
        html += '</div>';
    });

    html += '</div>';
    html += '<button class="scroll-to-bottom-btn" onclick="scrollToBottom()"><span class="btn-icon">' + UI_ICONS.chevronDown + '</span>Scroll to Bottom</button>';
    html += '</div>';
    return html;
}

function getLastBrowserUrl() {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return null;

    var lastUrl = null;
    // Check browser_context messages and tool calls for iframe_tool navigate
    chat.messages.forEach(function(msg) {
        if (msg.role === 'browser_context' && msg.url) {
            lastUrl = msg.url;
        }
        // Also check tool calls for iframe_tool navigate actions
        if (msg.tool_calls) {
            msg.tool_calls.forEach(function(tc) {
                if (tc.function && tc.function.name === 'iframe_tool') {
                    try {
                        var args = JSON.parse(tc.function.arguments);
                        if (args.action === 'navigate' && args.url) {
                            lastUrl = args.url;
                        }
                    } catch (e) {
                        // Ignore JSON parse errors for malformed tool call arguments
                    }
                }
            });
        }
    });
    return lastUrl;
}

function reopenBrowser() {
    var url = getLastBrowserUrl();
    if (url) {
        openIframePanel();
        navigateIframe(url);
    }
}

function renderVersionSidebar() {
    var container = document.getElementById('version-history-list');
    if (!container) return;

    var changedFiles = getAllChangedFiles();
    var revertedFiles = getRevertedFiles();
    var userMessagesHtml = renderUserMessagesList();
    var lastBrowserUrl = getLastBrowserUrl();

    var html = '<div class="version-sidebar-content">';

    // Actions Section - Group all action buttons together
    var hasActions = lastBrowserUrl || changedFiles.length > 0;
    if (hasActions) {
        html += '<div class="version-actions-section">';
        html += '<div class="version-section-title">Actions</div>';
        html += '<div class="version-actions-list">';

        // Open Browser button
        if (lastBrowserUrl) {
            html += '<button class="version-action-btn" onclick="reopenBrowser()" title="' + escapeHtml(lastBrowserUrl) + '">';
            html += '<span class="action-icon">' + UI_ICONS.globe + '</span>Open Browser';
            html += '</button>';
        }

        // Download XML button
        if (changedFiles.length > 0) {
            html += '<button class="version-action-btn" onclick="downloadChangesXml()" title="Export all changes as one XML file">';
            html += '<span class="action-icon">' + UI_ICONS.download + '</span>Download All';
            html += '</button>';

            // Revert All button
            html += '<button class="version-action-btn danger" onclick="revertAllChanges()">';
            html += '<span class="action-icon">' + UI_ICONS.undo + '</span>Revert All';
            html += '</button>';
            html += '<div class="version-action-hint">' + changedFiles.length + ' file' + (changedFiles.length > 1 ? 's' : '') + ' changed</div>';
        }

        html += '</div>';
        html += '</div>';
    }

    // Widgets Section
    var widgets = getWidgetsForChat(currentChatId);
    if (widgets.length > 0) {
        html += '<div class="version-widgets-section">';
        html += '<div class="version-section-title">' + UI_ICONS.widget + ' Widgets (' + widgets.length + ')</div>';
        html += '<div id="widget-sidebar-list" class="widget-sidebar-list">';
        widgets.forEach(function(widget) {
            var isOnDashboard = dashboardWidgets && dashboardWidgets[widget.id];
            var dashboardBtnClass = isOnDashboard ? 'widget-sidebar-btn on-dashboard' : 'widget-sidebar-btn';
            var dashboardBtnTitle = isOnDashboard ? 'Remove from Dashboard' : 'Add to Dashboard';
            var dashboardBtnIcon = isOnDashboard ? UI_ICONS.pinFilled : UI_ICONS.pin;
            html += '<div class="widget-sidebar-item" onclick="scrollToWidget(\'' + widget.id + '\')">' +
                '<span class="widget-sidebar-icon">' + UI_ICONS.widget + '</span>' +
                '<span class="widget-sidebar-title">' + escapeHtml(widget.title) + '</span>' +
                '<div class="widget-sidebar-actions">' +
                '<button class="widget-sidebar-btn" onclick="event.stopPropagation();showWidgetInPanel(\'' + widget.id + '\')" title="Show in Panel">' + UI_ICONS.panelRight + '</button>' +
                '<button class="' + dashboardBtnClass + '" onclick="event.stopPropagation();toggleWidgetOnDashboard(\'' + widget.id + '\')" title="' + dashboardBtnTitle + '">' + dashboardBtnIcon + '</button>' +
                '<button class="widget-sidebar-btn" onclick="event.stopPropagation();openWidgetFullscreen(\'' + widget.id + '\')" title="Fullscreen">' + UI_ICONS.maximize + '</button>' +
                '</div>' +
            '</div>';
        });
        html += '</div>';
        html += '</div>';
    } else {
        html += '<div id="widget-sidebar-list" style="display:none;"></div>';
    }

    // Screenshots & PDFs Section
    var chat = chats[currentChatId];
    var screenshots = [];
    var pdfAttachments = [];
    var fileAttachments = [];
    if (chat && chat.messages) {
        chat.messages.forEach(function(msg, idx) {
            if (msg.role === 'screenshot') {
                screenshots.push({ msg: msg, idx: idx });
            } else if (msg.role === 'pdf') {
                pdfAttachments.push({ msg: msg, idx: idx });
            } else if (msg.role === 'file') {
                fileAttachments.push({ msg: msg, idx: idx });
            }
        });
    }
    if (screenshots.length > 0 || pdfAttachments.length > 0 || fileAttachments.length > 0) {
        html += '<div class="version-screenshots-section">';
        var attachTotalCount = screenshots.length + pdfAttachments.length + fileAttachments.length;
        html += '<div class="version-section-title">' + UI_ICONS.eye + ' Attachments (' + attachTotalCount + ')</div>';
        html += '<div class="screenshot-sidebar-list">';
        screenshots.forEach(function(item, i) {
            var screenshot = item.msg;
            var screenshotName = screenshot.name || screenshot.description || ('Screenshot ' + (i + 1));
            html += '<div class="screenshot-sidebar-item" onclick="scrollToMessage(' + item.idx + ')">' +
                '<img class="screenshot-sidebar-thumb" src="' + screenshot.base64 + '" alt="' + escapeHtml(screenshotName) + '" onclick="event.stopPropagation();openScreenshotModal(this.src, \'' + escapeHtml(screenshotName).replace(/'/g, "\\'") + '\')" />' +
                '<div class="screenshot-sidebar-info">' +
                '<span class="screenshot-sidebar-title">' + escapeHtml(screenshotName) + '</span>' +
                '<span class="screenshot-sidebar-size">' + screenshot.width + '×' + screenshot.height + '</span>' +
                '</div>' +
                '<button class="screenshot-sidebar-btn" onclick="event.stopPropagation();downloadScreenshotFromSidebar(\'' + i + '\')" title="Download">' + UI_ICONS.download + '</button>' +
            '</div>';
        });
        pdfAttachments.forEach(function(item, i) {
            var pdfMsg = item.msg;
            var pdfName = pdfMsg.name || pdfMsg.description || ('Document ' + (i + 1));
            html += '<div class="screenshot-sidebar-item" onclick="scrollToMessage(' + item.idx + ')">' +
                '<div class="screenshot-sidebar-thumb pdf-sidebar-thumb" onclick="event.stopPropagation();openPdfFromMessage(' + item.idx + ')">' +
                '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="width:24px;height:24px;"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>' +
                '</div>' +
                '<div class="screenshot-sidebar-info">' +
                '<span class="screenshot-sidebar-title">' + escapeHtml(pdfName) + '</span>' +
                '<span class="screenshot-sidebar-size">PDF</span>' +
                '</div>' +
                '<button class="screenshot-sidebar-btn" onclick="event.stopPropagation();downloadPdfFromSidebar(' + i + ')" title="Download">' + UI_ICONS.download + '</button>' +
            '</div>';
        });
        fileAttachments.forEach(function(item, i) {
            var fileMsg = item.msg;
            var fileName = fileMsg.name || ('File ' + (i + 1));
            var fileExt = fileName.split('.').pop().toUpperCase();
            var fileSize = fileMsg.size ? formatFileSize(fileMsg.size) : '';
            html += '<div class="screenshot-sidebar-item" onclick="scrollToMessage(' + item.idx + ')">' +
                '<div class="screenshot-sidebar-thumb" style="background:var(--secondary-lighter);border:1px solid var(--secondary-border);color:var(--success);display:flex;align-items:center;justify-content:center;cursor:pointer;" onclick="event.stopPropagation();openFileFromMessage(' + item.idx + ')">' +
                '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="width:24px;height:24px;"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>' +
                '</div>' +
                '<div class="screenshot-sidebar-info">' +
                '<span class="screenshot-sidebar-title">' + escapeHtml(fileName) + '</span>' +
                '<span class="screenshot-sidebar-size">' + fileExt + (fileSize ? ' · ' + fileSize : '') + '</span>' +
                '</div>' +
                '<button class="screenshot-sidebar-btn" onclick="event.stopPropagation();downloadFileFromSidebar(' + i + ')" title="Download">' + UI_ICONS.download + '</button>' +
            '</div>';
        });
        html += '</div>';
        html += '</div>';
    }

    // Show active changes section
    if (changedFiles.length > 0) {
        // Workspace Artifacts header
        html += '<div class="version-artifacts-header">Artifacts' + (changedFiles.length === 1 ? '' : ' (' + changedFiles.length + ')') + '</div>';

        // List each changed file with icon buttons
        html += '<div class="version-files-list">';
        changedFiles.forEach(function(file, fileIdx) {
            var isNew = file.changes.some(function(c) { return c.action === 'POST'; });
            var hasEdit = file.changes.some(function(c) { return c.action === 'PUT' || c.action === 'PATCH'; });
            var changeCount = file.changes.length;

            var firstBeforeVersion = getFirstVersionForRecord(file.table, file.sysId);
            var tableIcon = getTableIcon(file.table);
            var tableDisplayName = getTableDisplayName(file.table);
            var statusBadge = isNew ? '<span class="sn-status-badge sn-status-new">NEW</span>' : (hasEdit ? '<span class="sn-status-badge sn-status-modified">MODIFIED</span>' : '');
            var changesBadge = changeCount > 1 ? '<span class="sn-changes-badge">' + changeCount + ' changes</span>' : '';

            // Escape values for JS
            var jsTable = escapeHtml(file.table);
            var jsSysId = escapeHtml(file.sysId);
            var jsDisplayName = escapeHtml(file.displayName).replace(/'/g, "\\'");

            html += '<div class="sn-artifact-card sidebar-card">';
            html += '<div class="sn-artifact-icon sn-icon-' + file.table.replace(/_/g, '-') + '">' + tableIcon + '</div>';
            html += '<div class="sn-artifact-content">';
            html += '<div class="sn-artifact-name">' + escapeHtml(file.displayName) + '</div>';
            html += '<div class="sn-artifact-meta">(' + tableDisplayName + ') ' + statusBadge + changesBadge + '</div>';
            html += '</div>';
            html += '<div class="sn-artifact-actions-row">';
            // View diff button
            html += '<button class="sn-artifact-icon-btn" onclick="openDiffViewer(\'' + jsTable + '\', \'' + jsSysId + '\', \'' + jsDisplayName + '\')" title="View changes">' + UI_ICONS.eye + '</button>';
            // Download button
            html += '<button class="sn-artifact-icon-btn" onclick="downloadSingleFile(\'' + jsTable + '\', \'' + jsSysId + '\', \'' + jsDisplayName + '\')" title="Download XML">' + UI_ICONS.download + '</button>';
            // Open in browser for UI pages
            if (file.table === 'sys_ui_page') {
                html += '<button class="sn-artifact-icon-btn" onclick="openUIPageInBrowser(\'' + jsDisplayName + '\')" title="Open in Browser">' + UI_ICONS.globe + '</button>';
            }
            // Revert button (or delete for new files)
            if (isNew) {
                html += '<button class="sn-artifact-icon-btn danger" onclick="deleteNewRecordFromSidebar(\'' + jsTable + '\', \'' + jsSysId + '\', \'' + jsDisplayName + '\')" title="Delete">' + UI_ICONS.trash + '</button>';
            } else if (firstBeforeVersion) {
                html += '<button class="sn-artifact-icon-btn" onclick="revertFileToBeforeChat(\'' + firstBeforeVersion + '\', \'' + jsTable + '\', \'' + jsSysId + '\', \'' + jsDisplayName + '\')" title="Revert">' + UI_ICONS.undo + '</button>';
            }
            html += '</div>';
            html += '</div>';
        });
        html += '</div>';
    }

    html += '</div>'; // end version-sidebar-content

    // Show user messages list at the bottom (always, using flexbox to push to bottom)
    if (userMessagesHtml) {
        html += userMessagesHtml;
    }

    container.innerHTML = html;
}

// Redo changes that were previously reverted
async function redoFileChanges(versionSysId, table, sysId, displayName) {
    if (!await showConfirmModal('Redo Changes', 'Redo changes to "' + displayName + '"? This will restore the AI-made changes.')) return;

    try {
        showSpinner('Restoring ' + displayName + '...');

        var xml = await getVersionXml(versionSysId);
        if (!xml) {
            hideSpinner();
            showSnackbar('Could not get version data', 'error');
            return;
        }

        var result = await uploadXml(xml, table, sysId);
        hideSpinner();

        if (result.success) {
            // Un-invalidate the original changes
            versionHistory.forEach(function(v, idx) {
                if (v.table === table && v.sysId === sysId && v.chatId === currentChatId && v.action !== 'REVERT') {
                    versionHistory[idx].invalidated = false;
                }
            });

            // Remove the revert entry (or mark it as undone)
            versionHistory = versionHistory.filter(function(v) {
                return !(v.table === table && v.sysId === sysId && v.chatId === currentChatId && v.action === 'REVERT');
            });

            saveVersionHistory();
            renderVersionSidebar();
            renderMessages();

            showSnackbar('Successfully restored "' + displayName + '"', 'success');
        } else {
            showSnackbar('Redo failed: ' + result.error, 'error');
        }
    } catch (e) {
        hideSpinner();
        showSnackbar('Redo failed: ' + e.message, 'error');
    }
}

// Redo all reverted changes
async function redoAllChanges() {
    var revertedFiles = getRevertedFiles();
    if (revertedFiles.length === 0) {
        showSnackbar('No reverted changes to redo', 'warning');
        return;
    }

    if (!await showConfirmModal('Redo All', 'Redo all ' + revertedFiles.length + ' reverted file(s)? This will restore all AI-made changes.')) return;

    showSpinner('Restoring ' + revertedFiles.length + ' files...');
    var successCount = 0;
    var errors = [];

    for (var i = 0; i < revertedFiles.length; i++) {
        var file = revertedFiles[i];
        try {
            var latestAfterVersion = getLatestAfterVersion(file.table, file.sysId);
            if (!latestAfterVersion) {
                errors.push(file.displayName + ': No version to restore');
                continue;
            }

            var xml = await getVersionXml(latestAfterVersion);
            if (!xml) {
                errors.push(file.displayName + ': Could not get version data');
                continue;
            }

            var result = await uploadXml(xml, file.table, file.sysId);
            if (result.success) {
                successCount++;
                // Un-invalidate entries for this file
                versionHistory.forEach(function(v, idx) {
                    if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId && v.action !== 'REVERT') {
                        versionHistory[idx].invalidated = false;
                    }
                });
                // Remove revert entries for this file
                versionHistory = versionHistory.filter(function(v) {
                    return !(v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId && v.action === 'REVERT');
                });
            } else {
                errors.push(file.displayName + ': ' + result.error);
            }
        } catch (e) {
            errors.push(file.displayName + ': ' + e.message);
        }
    }

    hideSpinner();
    saveVersionHistory();
    renderVersionSidebar();
    renderMessages();

    if (errors.length > 0) {
        showSnackbar('Restored ' + successCount + ' of ' + revertedFiles.length + ' files.\n\nErrors:\n' + errors.join('\n'), 'warning');
    } else {
        showSnackbar('Successfully restored ' + successCount + ' files', 'success');
    }
}

// Revert a single file to its state before this chat
async function revertFileToBeforeChat(versionSysId, table, sysId, displayName) {
    if (!await showConfirmModal('Undo All Changes', 'Undo all changes to "' + displayName + '"? This will restore the file to how it was before this chat session.')) return;

    try {
        showSpinner('Reverting ' + displayName + '...');

        var xml = await getVersionXml(versionSysId);
        if (!xml) {
            hideSpinner();
            showSnackbar('Could not get version data', 'error');
            return;
        }

        var result = await uploadXml(xml, table, sysId);
        hideSpinner();

        if (result.success) {
            // Mark all entries for this file as invalidated
            versionHistory.forEach(function(v, idx) {
                if (v.table === table && v.sysId === sysId && v.chatId === currentChatId) {
                    versionHistory[idx].invalidated = true;
                }
            });

            // Add revert entry
            addVersionHistoryEntry({
                id: 'vh_' + Date.now(),
                chatId: currentChatId,
                timestamp: Date.now(),
                table: table,
                sysId: sysId,
                displayName: displayName,
                action: 'REVERT',
                messageIndex: -1,
                afterVersion: versionSysId
            });

            showSnackbar('Successfully reverted "' + displayName + '"', 'success');
        } else {
            showSnackbar('Revert failed: ' + result.error, 'error');
        }
    } catch (e) {
        hideSpinner();
        showSnackbar('Revert failed: ' + e.message, 'error');
    }
}

// Revert all changes in this chat
async function revertAllChanges() {
    var changedFiles = getAllChangedFiles();
    if (changedFiles.length === 0) {
        showSnackbar('No changes to revert', 'warning');
        return;
    }

    var fileNames = changedFiles.map(function(f) { return f.displayName; }).join(', ');
    if (!await showConfirmModal('Undo All Changes', 'Undo ALL changes made in this chat? This will revert: ' + changedFiles.map(function(f) { return f.displayName; }).join(', ') + '. You can always redo these changes later.')) return;

    var successCount = 0;
    var failCount = 0;

    showSpinner('Reverting all changes...');

    for (var i = 0; i < changedFiles.length; i++) {
        var file = changedFiles[i];
        var isNew = file.changes.some(function(c) { return c.action === 'POST'; });
        var firstBeforeVersion = getFirstVersionForRecord(file.table, file.sysId);

        try {
            if (isNew) {
                // New files need to be deleted, not reverted
                var recordScope = await getRecordScope(file.table, file.sysId);
                var deleteUrl = '/api/now/table/' + file.table + '/' + file.sysId;
                if (recordScope) {
                    deleteUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
                }

                var res = await fetch(deleteUrl, {
                    method: 'DELETE',
                    headers: {
                        'X-UserToken': window.sessionToken,
                        'Accept': 'application/json'
                    }
                });

                if (res.ok || res.status === 204) {
                    versionHistory.forEach(function(v, idx) {
                        if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId) {
                            versionHistory[idx].invalidated = true;
                        }
                    });
                    successCount++;
                } else {
                    failCount++;
                }
            } else if (firstBeforeVersion) {
                // Existing files get reverted to before version
                var xml = await getVersionXml(firstBeforeVersion);
                if (!xml) {
                    failCount++;
                    continue;
                }

                var result = await uploadXml(xml, file.table, file.sysId);
                if (result.success) {
                    versionHistory.forEach(function(v, idx) {
                        if (v.table === file.table && v.sysId === file.sysId && v.chatId === currentChatId) {
                            versionHistory[idx].invalidated = true;
                        }
                    });
                    successCount++;
                } else {
                    failCount++;
                }
            } else {
                failCount++;
            }
        } catch (e) {
            failCount++;
        }
    }

    // Add a single revert entry for the batch
    if (successCount > 0) {
        addVersionHistoryEntry({
            id: 'vh_' + Date.now(),
            chatId: currentChatId,
            timestamp: Date.now(),
            table: 'batch',
            sysId: 'all',
            displayName: successCount + ' files reverted',
            action: 'REVERT',
            messageIndex: -1
        });
    }

    hideSpinner();

    if (failCount === 0) {
        showSnackbar('Successfully reverted all ' + successCount + ' file(s)', 'success');
    } else {
        showSnackbar('Reverted ' + successCount + ' file(s), ' + failCount + ' failed', 'warning');
    }
}

// Data Management Functions
async function exportAllData() {
    try {
        // Use File System Access API for streaming large exports
        if (!window.showSaveFilePicker) {
            showSnackbar('Your browser does not support large exports. Use Chrome or Edge.', 'error');
            return;
        }

        var fileHandle = await window.showSaveFilePicker({
            suggestedName: 'appagent-backup-' + new Date().toISOString().split('T')[0] + '.json',
            types: [{ description: 'JSON Files', accept: { 'application/json': ['.json'] } }]
        });

        var writable = await fileHandle.createWritable();
        var database = await openDatabase();
        var chatCount = 0;

        // Write header
        await writable.write('{\n  "version": 3,\n  "exportDate": "' + new Date().toISOString() + '",\n  "chats": [\n');

        // First get all chat keys (small data, won't cause memory issues)
        var chatKeys = await new Promise(function(resolve, reject) {
            var transaction = database.transaction([chatStoreName], 'readonly');
            var store = transaction.objectStore(chatStoreName);
            var request = store.getAllKeys();
            request.onsuccess = function() { resolve(request.result || []); };
            request.onerror = function() { reject(request.error); };
        });

        // Fetch and write each chat individually with pretty printing
        for (var i = 0; i < chatKeys.length; i++) {
            var chat = await new Promise(function(resolve, reject) {
                var transaction = database.transaction([chatStoreName], 'readonly');
                var store = transaction.objectStore(chatStoreName);
                var request = store.get(chatKeys[i]);
                request.onsuccess = function() { resolve(request.result); };
                request.onerror = function() { reject(request.error); };
            });

            if (chat) {
                if (chatCount > 0) await writable.write(',\n');
                // Pretty print each chat with 4-space indent, then add 4 spaces to each line
                var prettyChat = JSON.stringify(chat, null, 4).split('\n').map(function(line) {
                    return '    ' + line;
                }).join('\n');
                await writable.write(prettyChat);
                chatCount++;
            }
        }

        // Get and write settings
        var settingsTransaction = database.transaction([settingsStoreName], 'readonly');
        var settingsStore = settingsTransaction.objectStore(settingsStoreName);
        var settingsData = await new Promise(function(resolve) {
            var request = settingsStore.getAll();
            request.onsuccess = function() { resolve(request.result || []); };
            request.onerror = function() { resolve([]); };
        });

        await writable.write('\n  ],\n  "settings": ');
        await writable.write(JSON.stringify(settingsData, null, 2).split('\n').map(function(line, idx) {
            return idx === 0 ? line : '  ' + line;
        }).join('\n'));

        // Get and write dashboard widgets
        var dashboardData = [];
        if (database.objectStoreNames.contains(dashboardWidgetsStoreName)) {
            var dashboardTransaction = database.transaction([dashboardWidgetsStoreName], 'readonly');
            var dashboardStore = dashboardTransaction.objectStore(dashboardWidgetsStoreName);
            dashboardData = await new Promise(function(resolve) {
                var request = dashboardStore.getAll();
                request.onsuccess = function() { resolve(request.result || []); };
                request.onerror = function() { resolve([]); };
            });
        }

        await writable.write(',\n  "dashboardWidgets": ');
        await writable.write(JSON.stringify(dashboardData, null, 2).split('\n').map(function(line, idx) {
            return idx === 0 ? line : '  ' + line;
        }).join('\n'));

        // Get and write API providers
        var apiProvidersData = [];
        if (database.objectStoreNames.contains(apiProvidersStoreName)) {
            var apiProvidersTransaction = database.transaction([apiProvidersStoreName], 'readonly');
            var apiProvidersStore = apiProvidersTransaction.objectStore(apiProvidersStoreName);
            apiProvidersData = await new Promise(function(resolve) {
                var request = apiProvidersStore.getAll();
                request.onsuccess = function() { resolve(request.result || []); };
                request.onerror = function() { resolve([]); };
            });
        }

        await writable.write(',\n  "apiProviders": ');
        await writable.write(JSON.stringify(apiProvidersData, null, 2).split('\n').map(function(line, idx) {
            return idx === 0 ? line : '  ' + line;
        }).join('\n'));
        await writable.write('\n}');

        await writable.close();

        showSnackbar('Data exported successfully! (' + chatCount + ' chats)', 'success');
    } catch (e) {
        if (e.name === 'AbortError') return; // User cancelled file picker
        console.error('Export failed:', e);
        showSnackbar('Export failed: ' + e.message, 'error');
    }
}

async function importAllData() {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async function(e) {
        var file = e.target.files[0];
        if (!file) return;

        try {
            var text = await file.text();
            var importData = JSON.parse(text);

            // Handle single chat import
            if (importData.exportType === 'single_chat' && importData.chat) {
                var importedChat = importData.chat;
                var newId = 'chat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
                importedChat.id = newId;
                importedChat.title = importedChat.title + ' (imported)';
                importedChat.createdAt = Date.now();
                chats[newId] = importedChat;
                await saveChatsToStorage();
                renderChatList();
                showSnackbar('Chat imported successfully', 'success');
                return;
            }

            // Handle full data import
            if (!importData.chats || !importData.settings) {
                throw new Error('Invalid backup file format');
            }

            if (!await showConfirmModal('Import Data', 'This will merge imported data with existing data. Continue?')) {
                return;
            }

            var database = await openDatabase();

            // Import chats
            var chatTransaction = database.transaction([chatStoreName], 'readwrite');
            var chatStore = chatTransaction.objectStore(chatStoreName);
            for (var i = 0; i < importData.chats.length; i++) {
                chatStore.put(importData.chats[i]);
            }

            // Import settings
            var settingsTransaction = database.transaction([settingsStoreName], 'readwrite');
            var settingsStore = settingsTransaction.objectStore(settingsStoreName);
            for (var j = 0; j < importData.settings.length; j++) {
                settingsStore.put(importData.settings[j]);
            }

            // Import dashboard widgets (if present)
            if (importData.dashboardWidgets && importData.dashboardWidgets.length > 0 && database.objectStoreNames.contains(dashboardWidgetsStoreName)) {
                var dashboardTransaction = database.transaction([dashboardWidgetsStoreName], 'readwrite');
                var dashboardStore = dashboardTransaction.objectStore(dashboardWidgetsStoreName);
                for (var k = 0; k < importData.dashboardWidgets.length; k++) {
                    dashboardStore.put(importData.dashboardWidgets[k]);
                }
            }

            // Import API providers (if present)
            if (importData.apiProviders && importData.apiProviders.length > 0 && database.objectStoreNames.contains(apiProvidersStoreName)) {
                var apiProvidersTransaction = database.transaction([apiProvidersStoreName], 'readwrite');
                var apiProvidersStore = apiProvidersTransaction.objectStore(apiProvidersStoreName);
                for (var m = 0; m < importData.apiProviders.length; m++) {
                    apiProvidersStore.put(importData.apiProviders[m]);
                }
            }

            showSnackbar('Data imported successfully! Reloading...', 'success');
            window.location.reload();
        } catch (e) {
            console.error('Import failed:', e);
            showSnackbar('Import failed: ' + e.message, 'error');
        }
    };
    input.click();
}

async function deleteAllData() {
    if (!await showConfirmModal('Delete All Data', 'Are you sure you want to delete ALL data? This cannot be undone!')) {
        return;
    }
    if (!await showConfirmModal('Confirm Delete', 'This will delete all chats, settings, and preferences. Are you REALLY sure?')) {
        return;
    }

    try {
        var database = await openDatabase();

        // Clear chats
        var chatTransaction = database.transaction([chatStoreName], 'readwrite');
        chatTransaction.objectStore(chatStoreName).clear();

        // Clear settings
        var settingsTransaction = database.transaction([settingsStoreName], 'readwrite');
        settingsTransaction.objectStore(settingsStoreName).clear();

        // Clear dashboard widgets
        if (database.objectStoreNames.contains(dashboardWidgetsStoreName)) {
            var dashboardTransaction = database.transaction([dashboardWidgetsStoreName], 'readwrite');
            dashboardTransaction.objectStore(dashboardWidgetsStoreName).clear();
        }

        showSnackbar('All data deleted! Reloading...', 'success');
        window.location.reload();
    } catch (e) {
        console.error('Delete failed:', e);
        showSnackbar('Delete failed: ' + e.message, 'error');
    }
}

function setToolPermission(toolName, permission) {
    toolPermissions[toolName] = permission;
    saveToolPermissions();
    renderToolPermissions();
}

function toggleSettingsPanel(e) {
    if (e) e.stopPropagation();
    settingsPanelOpen = !settingsPanelOpen;
    var panel = document.getElementById('settings-panel');
    if (settingsPanelOpen) {
        // Position panel under the clicked button
        var btn = e ? e.target.closest('.settings-btn') : document.querySelector('.settings-btn');
        if (btn) {
            var rect = btn.getBoundingClientRect();
            panel.style.top = (rect.bottom + 4) + 'px';
            panel.style.right = (window.innerWidth - rect.right) + 'px';
        }
        panel.classList.add('visible');
        populateProviderDropdown();
        renderToolPermissions();
        fetchAndPopulateScopeDropdown();
        // Close on outside click
        setTimeout(function() {
            document.addEventListener('click', closeSettingsPanelOnOutsideClick);
        }, 0);
    } else {
        panel.classList.remove('visible');
        document.removeEventListener('click', closeSettingsPanelOnOutsideClick);
    }
}

function closeSettingsPanelOnOutsideClick(e) {
    var panel = document.getElementById('settings-panel');
    var btns = document.querySelectorAll('.settings-btn');
    var clickedOnBtn = false;
    btns.forEach(function(btn) { if (btn.contains(e.target)) clickedOnBtn = true; });
    if (panel && !panel.contains(e.target) && !clickedOnBtn) {
        closeSettingsPanel();
    }
}

function closeSettingsPanel() {
    settingsPanelOpen = false;
    var panel = document.getElementById('settings-panel');
    if (panel) panel.classList.remove('visible');
    document.removeEventListener('click', closeSettingsPanelOnOutsideClick);
}

// Custom Dropdown/Radio Group Component
// Renders as radio group if options <= 3, otherwise as dropdown with search if options > 5
function renderCustomSelect(containerId, options, selectedValue, onChangeCallback, placeholder) {
    var container = document.getElementById(containerId);
    if (!container) return;

    placeholder = placeholder || 'Select...';

    // If 3 or fewer options, render as radio group
    if (options.length <= 3) {
        var html = '<div class="radio-group">';
        options.forEach(function(opt) {
            var isSelected = opt.value === selectedValue;
            html += '<div class="radio-option' + (isSelected ? ' selected' : '') + '" ' +
                'onclick="event.stopPropagation(); selectRadioOption(\'' + containerId + '\', \'' + opt.value + '\', ' + onChangeCallback + ')">' +
                escapeHtml(opt.label) + '</div>';
        });
        html += '</div>';
        container.innerHTML = html;
        return;
    }

    // Otherwise render as custom dropdown
    var selectedLabel = placeholder;
    options.forEach(function(opt) {
        if (opt.value === selectedValue) selectedLabel = opt.label;
    });

    var showSearch = options.length > 5;
    var dropdownId = containerId + '-dropdown';

    var html = '<div class="custom-dropdown" id="' + dropdownId + '">';
    html += '<div class="custom-dropdown-trigger" onclick="toggleCustomDropdown(\'' + dropdownId + '\')" tabindex="0">';
    html += '<span class="dropdown-label">' + escapeHtml(selectedLabel) + '</span>';
    html += '<span class="dropdown-arrow">' + UI_ICONS.chevronDown + '</span>';
    html += '</div>';
    html += '<div class="custom-dropdown-menu">';

    if (showSearch) {
        html += '<div class="custom-dropdown-search">';
        html += '<input type="text" placeholder="Search..." oninput="filterCustomDropdown(\'' + dropdownId + '\', this.value)" onclick="event.stopPropagation()">';
        html += '</div>';
    }

    html += '<div class="custom-dropdown-options">';
    options.forEach(function(opt) {
        var isSelected = opt.value === selectedValue;
        html += '<div class="custom-dropdown-option' + (isSelected ? ' selected' : '') + '" ' +
            'data-value="' + escapeHtml(opt.value) + '" data-label="' + escapeHtml(opt.label) + '" ' +
            'onclick="selectCustomDropdownOption(\'' + containerId + '\', \'' + dropdownId + '\', \'' + opt.value + '\', ' + onChangeCallback + ', event)">' +
            escapeHtml(opt.label) + '</div>';
    });
    html += '</div></div></div>';

    container.innerHTML = html;
}

function toggleCustomDropdown(dropdownId) {
    var dropdown = document.getElementById(dropdownId);
    if (!dropdown) return;

    // Close other open dropdowns first
    document.querySelectorAll('.custom-dropdown.open').forEach(function(d) {
        if (d.id !== dropdownId) d.classList.remove('open');
    });

    dropdown.classList.toggle('open');

    // Focus search input if exists
    if (dropdown.classList.contains('open')) {
        var searchInput = dropdown.querySelector('.custom-dropdown-search input');
        if (searchInput) setTimeout(function() { searchInput.focus(); }, 50);
    }
}

function filterCustomDropdown(dropdownId, query) {
    var dropdown = document.getElementById(dropdownId);
    if (!dropdown) return;

    var options = dropdown.querySelectorAll('.custom-dropdown-option');
    var q = query.toLowerCase();
    var hasVisible = false;

    options.forEach(function(opt) {
        var label = (opt.getAttribute('data-label') || '').toLowerCase();
        var match = label.indexOf(q) !== -1;
        opt.style.display = match ? 'block' : 'none';
        if (match) hasVisible = true;
    });

    // Show/hide empty message
    var optionsContainer = dropdown.querySelector('.custom-dropdown-options');
    var emptyMsg = dropdown.querySelector('.custom-dropdown-empty');
    if (!hasVisible && !emptyMsg) {
        optionsContainer.insertAdjacentHTML('beforeend', '<div class="custom-dropdown-empty">No matches found</div>');
    } else if (hasVisible && emptyMsg) {
        emptyMsg.remove();
    }
}

function selectCustomDropdownOption(containerId, dropdownId, value, callback, event) {
    if (event) event.stopPropagation();
    var dropdown = document.getElementById(dropdownId);
    if (dropdown) {
        dropdown.classList.remove('open');
        // Update the label
        var option = dropdown.querySelector('.custom-dropdown-option[data-value="' + value + '"]');
        var label = option ? option.getAttribute('data-label') : value;
        var labelEl = dropdown.querySelector('.dropdown-label');
        if (labelEl) labelEl.textContent = label;
        // Update selected state
        dropdown.querySelectorAll('.custom-dropdown-option').forEach(function(o) {
            o.classList.toggle('selected', o.getAttribute('data-value') === value);
        });
    }
    if (callback) callback(value);
}

function selectRadioOption(containerId, value, callback) {
    var container = document.getElementById(containerId);
    if (container) {
        container.querySelectorAll('.radio-option').forEach(function(opt, idx) {
            // Get value from the options array via index or match text
            opt.classList.remove('selected');
        });
        // Find and select the clicked option
        container.querySelectorAll('.radio-option').forEach(function(opt) {
            if (opt.textContent.trim() === value || opt.getAttribute('data-value') === value) {
                opt.classList.add('selected');
            }
        });
    }
    if (callback) callback(value);
}

// Close custom dropdowns when clicking outside
document.addEventListener('click', function(e) {
    if (!e.target.closest('.custom-dropdown')) {
        document.querySelectorAll('.custom-dropdown.open').forEach(function(d) {
            d.classList.remove('open');
        });
    }
});

function renderToolPermissions() {
    var container = document.getElementById('tool-permissions-list');
    if (!container) return;

    var html = '';
    var snMethods = ['servicenow_api:GET', 'servicenow_api:POST', 'servicenow_api:PUT', 'servicenow_api:PATCH', 'servicenow_api:DELETE'];
    var iframeActions = ['iframe_tool:navigate', 'iframe_tool:get_visible_text', 'iframe_tool:get_dom', 'iframe_tool:click', 'iframe_tool:fill', 'iframe_tool:get_console_logs', 'iframe_tool:get_network_requests', 'iframe_tool:close', 'iframe_tool:open_widget', 'iframe_tool:edit_html', 'iframe_tool:dispatch_event', 'iframe_tool:select_option', 'iframe_tool:scroll', 'iframe_tool:resize', 'iframe_tool:get_properties', 'iframe_tool:set_style'];
    var manageSkillActions = ['manage_skill:create', 'manage_skill:update', 'manage_skill:add_file', 'manage_skill:update_file', 'manage_skill:delete_file', 'manage_skill:activate', 'manage_skill:deactivate'];
    var otherTools = PERMISSION_KEYS.filter(function(k) { return snMethods.indexOf(k) === -1 && iframeActions.indexOf(k) === -1 && manageSkillActions.indexOf(k) === -1; });

    // Permission options (3 options = radio group)
    var permOptions = [
        { value: 'auto', label: 'Auto' },
        { value: 'ask', label: 'Ask' },
        { value: 'disabled', label: 'Off' }
    ];

    // Render other tools first
    otherTools.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var perm = toolPermissions[key] || 'ask';
        var containerId = 'perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });

    // Render ServiceNow API group
    html += '<div class="tool-permission-group">';
    html += '<div class="tool-permission-group-title">ServiceNow API</div>';
    snMethods.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item tool-permission-subitem">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });
    html += '</div>';

    // Render Manage Skill group
    html += '<div class="tool-permission-group">';
    html += '<div class="tool-permission-group-title">Manage Agent Skill</div>';
    manageSkillActions.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item tool-permission-subitem">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });
    html += '</div>';

    // Render Browser Control group
    html += '<div class="tool-permission-group">';
    html += '<div class="tool-permission-group-title">Browser Control</div>';
    iframeActions.forEach(function(key) {
        var displayName = TOOL_DISPLAY_NAMES[key] || key;
        var containerId = 'perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        html += '<div class="tool-permission-item tool-permission-subitem">' +
            '<span class="tool-permission-name">' + displayName + '</span>' +
            '<div class="tool-permission-control" id="' + containerId + '"></div>' +
        '</div>';
    });
    html += '</div>';

    // Render active skill tools
    var skillToolKeys = [];
    var activeSkillIds = Object.keys(activeSkills);
    activeSkillIds.forEach(function(skillId) {
        var skill = skills[skillId];
        var skillToolsForSkill = skillTools[skillId] || {};
        var toolNames = Object.keys(skillToolsForSkill);
        if (toolNames.length > 0) {
            var skillName = skill ? (skill.name || skill.id) : skillId;
            html += '<div class="tool-permission-group">';
            html += '<div class="tool-permission-group-title">Skill: ' + escapeHtml(skillName) + '</div>';
            toolNames.forEach(function(toolName) {
                var permKey = 'skill:' + toolName;
                var containerId = 'perm-' + permKey.replace(/[^a-zA-Z0-9]/g, '-');
                skillToolKeys.push(permKey);
                html += '<div class="tool-permission-item tool-permission-subitem">' +
                    '<span class="tool-permission-name">' + escapeHtml(toolName) + '</span>' +
                    '<div class="tool-permission-control" id="' + containerId + '"></div>' +
                '</div>';
            });
            html += '</div>';
        }
    });

    container.innerHTML = html;

    // Now render the radio groups for each permission
    var allKeys = otherTools.concat(snMethods).concat(manageSkillActions).concat(iframeActions).concat(skillToolKeys);
    allKeys.forEach(function(key) {
        var perm = toolPermissions[key] || 'ask';
        var containerId = 'perm-' + key.replace(/[^a-zA-Z0-9]/g, '-');
        renderPermissionRadioGroup(containerId, perm, key);
    });
}

function renderPermissionRadioGroup(containerId, selectedValue, permKey) {
    var container = document.getElementById(containerId);
    if (!container) return;

    var options = [
        { value: 'auto', label: 'Auto' },
        { value: 'ask', label: 'Ask' },
        { value: 'disabled', label: 'Off' }
    ];

    var html = '<div class="radio-group radio-group-small">';
    options.forEach(function(opt) {
        var isSelected = opt.value === selectedValue;
        html += '<div class="radio-option' + (isSelected ? ' selected' : '') + '" ' +
            'data-value="' + opt.value + '" ' +
            'onclick="event.stopPropagation(); setToolPermissionFromRadio(\'' + permKey + '\', \'' + opt.value + '\', this)">' +
            opt.label + '</div>';
    });
    html += '</div>';
    container.innerHTML = html;
}

function setToolPermissionFromRadio(permKey, value, element) {
    // Update visual selection
    var parent = element.parentElement;
    parent.querySelectorAll('.radio-option').forEach(function(o) {
        o.classList.remove('selected');
    });
    element.classList.add('selected');

    // Save permission
    setToolPermission(permKey, value);
}

function getDisabledTools() {
    var disabled = [];
    PERMISSION_KEYS.forEach(function(key) {
        if (toolPermissions[key] === 'disabled') {
            disabled.push(key);
        }
    });
    return disabled;
}

function getEnabledTools() {
    var baseTools = TOOLS.filter(function(tool) {
        var name = tool.function.name;
        // For servicenow_api, check if ALL methods are disabled
        if (name === 'servicenow_api') {
            var methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'];
            var allDisabled = methods.every(function(m) {
                return toolPermissions['servicenow_api:' + m] === 'disabled';
            });
            return !allDisabled;
        }
        return toolPermissions[name] !== 'disabled';
    });

    // Add active skill tools
    var skillToolDefs = getActiveSkillTools();
    return baseTools.concat(skillToolDefs);
}

function getToolPermission(toolName, methodOrAction) {
    var permKey = toolName;
    if (methodOrAction) {
        permKey = toolName + ':' + methodOrAction;
    }

    // Check session permissions first (highest priority)
    if (sessionPermissions[permKey] === 'auto') {
        return 'auto';
    }

    // Then check stored permissions
    if (toolPermissions[permKey]) {
        return toolPermissions[permKey];
    }

    // Default based on tool type
    return 'ask';
}

function getToolDisplayName(toolName, methodOrAction) {
    if (toolName === 'servicenow_api' && methodOrAction) {
        return TOOL_DISPLAY_NAMES['servicenow_api:' + methodOrAction] || toolName;
    }
    if (toolName === 'iframe_tool' && methodOrAction) {
        return TOOL_DISPLAY_NAMES['iframe_tool:' + methodOrAction] || toolName;
    }
    if (toolName === 'manage_skill' && methodOrAction) {
        return TOOL_DISPLAY_NAMES['manage_skill:' + methodOrAction] || toolName;
    }
    return TOOL_DISPLAY_NAMES[toolName] || toolName;
}

// Central permission checking for all tool calls
// Options: { toolCallId, batch, chatId }
// - toolCallId: ID from actual tool call (for agent flow), auto-generated if not provided
// - batch: if true, uses showToolApprovalPromptBatch (caller must render after all prompts added)
// - chatId: target chat for approval prompt
// Returns: { allowed: true, permission, displayName, permissionKey } or { allowed: false, error, permission, displayName, permissionKey }
async function requestProgrammaticToolApproval(toolName, args, options) {
    options = options || {};
    var methodOrAction = null;
    if (toolName === 'servicenow_api' && args && args.method) {
        methodOrAction = args.method.toUpperCase();
    } else if (toolName === 'manage_skill' && args && args.action) {
        methodOrAction = args.action;
    } else if (toolName === 'iframe_tool' && args && args.action) {
        methodOrAction = args.action;
    }

    var permission = getToolPermission(toolName, methodOrAction);
    var displayName = getToolDisplayName(toolName, methodOrAction);
    var permissionKey = methodOrAction ? toolName + ':' + methodOrAction : toolName;

    var baseResult = { permission: permission, displayName: displayName, permissionKey: permissionKey };

    if (permission === 'disabled') {
        return Object.assign({ allowed: false, error: displayName + ' is disabled by user settings' }, baseResult);
    }

    if (permission === 'auto') {
        return Object.assign({ allowed: true }, baseResult);
    }

    // permission === 'ask' - check if this specific toolCallId was already approved
    var targetChatId = options.chatId || activeStreamingChatId || currentChatId;
    var toolCallId = options.toolCallId || ('prog_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9));

    // Check for existing approval for this toolCallId
    var chat = chats[targetChatId];
    if (chat && chat.messages && toolCallId) {
        for (var i = 0; i < chat.messages.length; i++) {
            var msg = chat.messages[i];
            if (msg.role === 'approval' && msg.toolCallId === toolCallId) {
                if (msg.status === 'allowed' || msg.status === 'session_allowed' || msg.status === 'always_allowed') {
                    return Object.assign({ allowed: true }, baseResult);
                } else if (msg.status === 'denied') {
                    return Object.assign({ allowed: false, error: displayName + ' was DENIED by user. STOP immediately — do NOT retry or work around this. Acknowledge the denial and ask the user how to proceed.' }, baseResult);
                }
                // status === 'pending' should not happen here (means approval in progress)
                break;
            }
        }
    }

    // Show approval prompt and wait for user response
    var promptFn = options.batch ? showToolApprovalPromptBatch : showToolApprovalPrompt;
    var approved = await promptFn(displayName, args, permissionKey, toolCallId, toolName, targetChatId, options);

    if (approved) {
        return Object.assign({ allowed: true }, baseResult);
    } else {
        return Object.assign({ allowed: false, error: displayName + ' was DENIED by user. STOP immediately — do NOT retry or work around this. Acknowledge the denial and ask the user how to proceed.' }, baseResult);
    }
}

// Check if a context (chatId or 'home') has pending draft items (text or images)
function chatHasPendingItems(contextKey) {
    return (chatPendingImages[contextKey] && chatPendingImages[contextKey].length > 0) ||
           (chatPendingTexts[contextKey] && chatPendingTexts[contextKey].length > 0);
}

// Update the pending-draft indicator on the New Chat sidebar button
function updateHomePendingIndicator() {
    var dot = document.getElementById('home-pending-dot');
    if (dot) dot.style.display = chatHasPendingItems('home') ? 'inline-block' : 'none';
}

// Check if a chat has any pending tool approvals
function chatHasPendingApproval(chatId) {
    var chat = chats[chatId];
    if (!chat || !chat.messages) return false;
    return chat.messages.some(function(m) {
        return m.role === 'approval' && m.status === 'pending';
    });
}

// Show notifications for pending approvals when opening a chat (e.g., after page reload)
function showPendingApprovalNotifications(chatId) {
    var chat = chats[chatId];
    if (!chat || !chat.messages) return;

    // First, check if there are any pending approvals for this chat
    var pendingApprovals = [];
    for (var i = 0; i < chat.messages.length; i++) {
        var msg = chat.messages[i];
        if (msg.role === 'approval' && msg.status === 'pending') {
            pendingApprovals.push({ index: i, msg: msg });
        }
    }

    // If no pending approvals, nothing to show
    if (pendingApprovals.length === 0) return;

    // Clear any existing notifications for this chat to avoid duplicates
    approvalNotificationQueue = approvalNotificationQueue.filter(function(n) {
        return n.chatId !== chatId;
    });

    // If currently showing notifications for this chat, clear them
    if (Array.isArray(currentApprovalNotification) &&
        currentApprovalNotification.length > 0 &&
        currentApprovalNotification[0].chatId === chatId) {
        currentApprovalNotification = null;
        isShowingApprovalNotification = false;
        var snackbar = document.getElementById('snackbar');
        if (snackbar) snackbar.classList.remove('show');
    }

    // Now add notifications for each pending approval
    for (var j = 0; j < pendingApprovals.length; j++) {
        var approval = pendingApprovals[j];
        var chatTitle = chat.title || 'A chat';
        var statusMessage = (approval.msg.args && approval.msg.args.status_message) ? approval.msg.args.status_message : null;
        showApprovalNotification(chatTitle, approval.msg.toolName, chatId, statusMessage, approval.index, approval.msg.args);
    }
}

function showToolApprovalPrompt(displayName, args, permissionKey, toolCallId, actualToolName, targetChatId, options) {
    options = options || {};
    return new Promise(function(resolve) {
        // Use targetChatId if provided (for background streaming), otherwise currentChatId
        var chatId = targetChatId || currentChatId;
        var chat = chats[chatId];
        var approvalIndex = chat.messages.length;

        // Add approval message to chat
        chat.messages.push({
            role: 'approval',
            toolName: displayName,
            actualToolName: actualToolName || displayName,
            args: args,
            permissionKey: permissionKey,
            toolCallId: toolCallId,
            status: 'pending'
        });
        saveChatsToStorage();

        // Store resolve function BEFORE rendering (so it's available for handleApproval)
        var approvalKey = chatId + ':' + approvalIndex;
        pendingToolApprovals[approvalKey] = { resolve: resolve, approvalIndex: approvalIndex, chatId: chatId };

        // For programmatic tool calls (from widgets/js_eval), always use notification
        // This avoids calling renderMessages() which would destroy widget iframes
        // Notifications work everywhere: chat view, dashboard, any view
        var isProgrammaticCall = toolCallId && toolCallId.startsWith('prog_');
        if (isProgrammaticCall) {
            // Use widget name if provided (from widget tool calls), otherwise fallback to 'Widget'
            var notificationTitle = options.widgetName || 'Widget';
            var statusMessage = (args && args.status_message) ? args.status_message : null;
            showApprovalNotification(notificationTitle, displayName, chatId, statusMessage, approvalIndex, args);
        } else if (currentChatId === chatId && currentView === 'chat') {
            // For agent tool calls on current chat, show notification popup instead of inline
            var chatTitle = chat.title || 'A chat';
            var statusMessage = (args && args.status_message) ? args.status_message : null;
            showApprovalNotification(chatTitle, displayName, chatId, statusMessage, approvalIndex, args);
            renderMessages(); // Still render to update chat but notification handles approval
            scrollToBottomIfAllowed();
        } else {
            // Show notification when user is on a different chat or different view
            var chatTitle = chat.title || 'A chat';
            var statusMessage = (args && args.status_message) ? args.status_message : null;
            showApprovalNotification(chatTitle, displayName, chatId, statusMessage, approvalIndex, args);
        }
        // Always update chat list to show attention indicator
        renderChatList();
    });
}

// Batch version: adds approval message without rendering/notifying immediately
// Used when adding multiple approvals at once - caller handles render and notifications after all are added
function showToolApprovalPromptBatch(displayName, args, permissionKey, toolCallId, actualToolName, targetChatId, options) {
    options = options || {};
    return new Promise(function(resolve) {
        var chatId = targetChatId || currentChatId;
        var chat = chats[chatId];
        var approvalIndex = chat.messages.length;

        // Add approval message to chat
        chat.messages.push({
            role: 'approval',
            toolName: displayName,
            actualToolName: actualToolName || displayName,
            args: args,
            permissionKey: permissionKey,
            toolCallId: toolCallId,
            status: 'pending'
        });

        // Store resolve function
        var approvalKey = chatId + ':' + approvalIndex;
        pendingToolApprovals[approvalKey] = { resolve: resolve, approvalIndex: approvalIndex, chatId: chatId };

        // Queue notification (will be shown after all approvals are added)
        // Always show notification popup (not just when on different chat/view)
        var isProgrammaticCall = toolCallId && toolCallId.startsWith('prog_');
        var notificationTitle = isProgrammaticCall ? (options.widgetName || 'Widget') : (chat.title || 'A chat');
        var statusMessage = (args && args.status_message) ? args.status_message : null;
        showApprovalNotification(notificationTitle, displayName, chatId, statusMessage, approvalIndex, args);
    });
}

// Global approval handler - called from onclick in rendered HTML
// skipNotificationClear: true when called from notification (notification handles its own state)
// targetChatId: optional - used when approving from notification where chatId is known
async function handleApproval(approvalIndex, action, skipNotificationClear, targetChatId) {
    // Find the pending approval for this approvalIndex
    var chatId = targetChatId || currentChatId;
    var approvalKey = null;

    // Search for the matching pending approval (may override targetChatId if found)
    for (var key in pendingToolApprovals) {
        if (pendingToolApprovals[key].approvalIndex === approvalIndex) {
            chatId = pendingToolApprovals[key].chatId;
            approvalKey = key;
            break;
        }
    }

    var chat = chats[chatId];
    if (!chat || !chat.messages[approvalIndex]) return;

    var msg = chat.messages[approvalIndex];
    if (msg.role !== 'approval' || msg.status !== 'pending') return;

    var approved = action !== 'deny';

    // Update status based on action
    if (action === 'allow') {
        msg.status = 'allowed';
    } else if (action === 'session') {
        msg.status = 'session_allowed';
        if (msg.permissionKey) {
            sessionPermissions[msg.permissionKey] = 'auto';
        }
    } else if (action === 'auto') {
        msg.status = 'always_allowed';
        if (msg.permissionKey) {
            setToolPermission(msg.permissionKey, 'auto');
        }
    } else if (action === 'deny') {
        msg.status = 'denied';
    }

    saveChatsToStorage();

    // Check if this is a programmatic approval (from widget/js_eval)
    // Programmatic approvals use notifications, so no need to call renderMessages()
    var isProgrammaticApproval = msg.toolCallId && msg.toolCallId.startsWith('prog_');

    if (!isProgrammaticApproval) {
        // For agent tool calls, use full renderMessages()
        renderMessages();
    }

    renderChatList(); // Update chat list to remove attention indicator

    // Clear any notifications for this chat since approval was handled from chat
    // Skip if called from notification (notification handles its own state)
    if (!skipNotificationClear && typeof clearApprovalNotificationsForChat === 'function') {
        clearApprovalNotificationsForChat(chatId);
    }

    // If there's an active conversation waiting for this approval, resolve it
    if (approvalKey && pendingToolApprovals[approvalKey]) {
        var resolve = pendingToolApprovals[approvalKey].resolve;
        delete pendingToolApprovals[approvalKey];
        resolve(approved);
        return;
    }

    // No active conversation - run agent which will detect and execute approved tools
    // Skip if called from notification - caller will trigger runAgent after UI is updated
    if (!skipNotificationClear) {
        await runAgent();
    }
}

function saveProviderToStorage() {
    appStorage.setItem('appagent_provider', currentProvider);
}

function changeProvider(providerId) {
    if (getProviderById(providerId)) {
        currentProvider = providerId;
        saveProviderToStorage();
        updateModelDisplay();
        // Re-render the provider dropdown to update selection
        populateProviderDropdown();
    }
}

function updateModelDisplay() {
    var provider = getProviderById(currentProvider);
    var modelNameEl = document.getElementById('model-name');
    var homeModelNameEl = document.getElementById('home-model-name');
    if (modelNameEl && provider) {
        modelNameEl.textContent = provider.name;
        modelNameEl.style.display = '';
    }
    if (homeModelNameEl && provider) homeModelNameEl.textContent = provider.name;
}

// Update model display with actual model from OpenRouter response
function updateModelDisplayWithProvider(actualModel) {
    var modelNameEl = document.getElementById('model-name');
    var homeModelNameEl = document.getElementById('home-model-name');
    if (!actualModel) return;
    // Format the model name: remove provider prefix and clean up
    var displayName = actualModel;
    if (actualModel.indexOf('/') !== -1) {
        displayName = actualModel.split('/').pop(); // Get part after last /
    }
    // Capitalize and clean up common patterns
    displayName = displayName.replace(/-/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
    if (modelNameEl) {
        modelNameEl.textContent = displayName;
        modelNameEl.style.display = '';
    }
    if (homeModelNameEl) homeModelNameEl.textContent = displayName;
}

async function fetchCredits() {
    var creditsEl = document.getElementById('credits-display');
    var homeCreditsEl = document.getElementById('home-credits-display');

    // Show cached usage immediately to prevent layout shift
    var cachedUsage = appStorage.getItem('cachedCredits');
    if (cachedUsage) {
        if (creditsEl) {
            creditsEl.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>' + cachedUsage;
            creditsEl.className = 'credits-display';
            creditsEl.style.display = '';
        }
        if (homeCreditsEl) {
            homeCreditsEl.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>' + cachedUsage;
            homeCreditsEl.className = 'credits-display';
        }
    }

    // Only show loading if no cached value
    if (!cachedUsage) {
        if (creditsEl) {
            creditsEl.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>...';
            creditsEl.className = 'credits-display loading';
        }
        if (homeCreditsEl) {
            homeCreditsEl.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>...';
            homeCreditsEl.className = 'credits-display loading';
        }
    }

    // Derive credits URL from current provider's endpoint (extract base up to /v1/)
    var provider = getProviderByName(currentProvider);
    if (!provider || !provider.endpoint) return;
    var v1Idx = provider.endpoint.indexOf('/v1/');
    if (v1Idx === -1) return;
    var creditsUrl = provider.endpoint.substring(0, v1Idx) + '/v1/credits';

    try {
        var headers = {};
        if (provider.apiKey) headers['Authorization'] = 'Bearer ' + provider.apiKey;
        var res = await fetch(creditsUrl, { method: 'GET', headers: headers });

        if (!res.ok) {
            throw new Error('Failed to fetch credits');
        }

        var data = await res.json();
        var displayText = '';
        var creditTitle = 'Click to refresh';
        var cssClass = 'credits-display';

        if (data.data && data.data.total_credits !== undefined) {
            // OpenRouter format
            var remaining = (data.data.total_credits - data.data.total_usage).toFixed(2);
            displayText = '$' + remaining;
            creditTitle = 'Credits: $' + data.data.total_credits.toFixed(2) + ' | Used: $' + data.data.total_usage.toFixed(2) + ' | Click to refresh';
        } else if (data.five_hour) {
            // Claude usage format
            var fiveHour = data.five_hour.utilization;
            var resetStr = '';
            if (data.five_hour.resets_at) {
                var resetTime = new Date(data.five_hour.resets_at);
                var diffMs = resetTime - Date.now();
                if (diffMs > 0) {
                    var diffMin = Math.floor(diffMs / 60000);
                    var h = Math.floor(diffMin / 60);
                    var m = diffMin % 60;
                    resetStr = h > 0 ? h + 'h' + (m > 0 ? m + 'mn' : '') : m + 'mn';
                }
            }
            displayText = Math.round(fiveHour) + '%' + (resetStr ? ' for ' + resetStr : '');
            creditTitle = fiveHour.toFixed(1) + '% used' + (resetStr ? ' \u00b7 resets in ' + resetStr : '') + ' | Click to refresh';
            if (fiveHour > 80) cssClass += ' error';
        }

        if (!displayText) return;

        appStorage.setItem('cachedCredits', displayText);
        var creditHtml = '<span class="credits-icon">' + UI_ICONS.money + '</span>' + displayText;

        if (creditsEl) {
            creditsEl.innerHTML = creditHtml;
            creditsEl.className = cssClass;
            creditsEl.title = creditTitle;
            creditsEl.style.display = '';
        }
        if (homeCreditsEl) {
            homeCreditsEl.innerHTML = creditHtml;
            homeCreditsEl.className = cssClass;
            homeCreditsEl.title = creditTitle;
        }
    } catch (e) {
        console.error('Failed to fetch credits:', e);
        if (creditsEl) {
            creditsEl.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>Error';
            creditsEl.className = 'credits-display error';
        }
        if (homeCreditsEl) {
            homeCreditsEl.innerHTML = '<span class="credits-icon">' + UI_ICONS.money + '</span>Error';
            homeCreditsEl.className = 'credits-display error';
        }
    }
}

async function updateStorageIndicator() {
    var storageEl = document.getElementById('storage-display');
    if (!storageEl) return;

    try {
        // Estimate IndexedDB usage via navigator.storage API
        if (navigator.storage && navigator.storage.estimate) {
            var estimate = await navigator.storage.estimate();
            var usedMB = (estimate.usage || 0) / (1024 * 1024);
            var quotaMB = (estimate.quota || 0) / (1024 * 1024);
            var remainingMB = quotaMB - usedMB;

            // Only show indicator if less than 5MB remaining
            if (remainingMB >= 5) {
                storageEl.style.display = 'none';
                return;
            }

            storageEl.style.display = '';
            var displayText = remainingMB.toFixed(1) + 'MB left';
            var className;

            if (remainingMB < 1) {
                className = 'storage-display critical';
            } else if (remainingMB < 3) {
                className = 'storage-display warning';
            } else {
                className = 'storage-display';
            }

            storageEl.innerHTML = '<span class="storage-icon">' + UI_ICONS.storage + '</span>' + displayText;
            storageEl.className = className;
            storageEl.title = 'IndexedDB Storage: ' + usedMB.toFixed(1) + 'MB used / ' + quotaMB.toFixed(0) + 'MB quota';
        } else {
            // Can't estimate - hide indicator
            storageEl.style.display = 'none';
        }
    } catch (e) {
        storageEl.style.display = 'none';
    }
}

function generateId() {
    return 'chat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
}

// Track pending summary request
var pendingSummaryRequest = null; // { chatId, chatTitle }

// Summarize current conversation and start a new chat with the summary
async function summarizeAndStartNewChat() {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages || chat.messages.length < 3) {
        showSnackbar('Not enough conversation to summarize', 'warning');
        return;
    }

    // Check if agent is already running
    if (isRunning) {
        showSnackbar('Please wait for the current request to complete', 'warning');
        return;
    }

    // Store info for after the summary is generated
    pendingSummaryRequest = {
        chatId: currentChatId,
        chatTitle: chat.title || 'Chat'
    };

    // Add summary request as a user message
    var summaryPrompt = 'Please provide a concise summary of this conversation for context continuity. Include:\n' +
        '1. User\'s main questions/goals\n' +
        '2. Current progress and accomplishments\n' +
        '3. Any unresolved issues or blockers\n' +
        '4. Suggested next steps\n\n' +
        'Keep it brief but comprehensive. Do not include tool call details, just outcomes. Do not use any tools for this task.';

    chat.messages.push({
        role: 'user',
        content: summaryPrompt,
        isSummaryRequest: true
    });

    saveChatsToStorage();
    renderMessages();

    // Run the agent to generate the summary
    isFollowingScroll = true;
    paused = false;
    document.getElementById('pause-btn').innerHTML = '<span class="btn-icon">' + UI_ICONS.pause + '</span>Pause';
    await runAgent();

    // After agent completes, check if we need to create a new chat with the summary
    if (pendingSummaryRequest && pendingSummaryRequest.chatId === currentChatId) {
        completeSummaryAndCreateNewChat();
    }
}

// Called after agent completes a summary request to create the new chat
function completeSummaryAndCreateNewChat() {
    if (!pendingSummaryRequest) return;

    var chat = chats[pendingSummaryRequest.chatId];
    if (!chat || !chat.messages || chat.messages.length === 0) {
        pendingSummaryRequest = null;
        return;
    }

    // Find the last assistant message (the summary)
    var summary = null;
    for (var i = chat.messages.length - 1; i >= 0; i--) {
        var msg = chat.messages[i];
        if (msg.role === 'assistant' && msg.content && !msg.isSummary) {
            summary = msg.content;
            // Mark as summary so it's not counted in metrics
            msg.isSummary = true;
            break;
        }
        if (msg.role === 'user') break; // Stop if we hit user message without finding assistant
    }

    if (!summary) {
        showSnackbar('Failed to generate summary', 'error');
        pendingSummaryRequest = null;
        return;
    }

    // Create new chat with summary as first message
    var newChatId = generateId();
    var summaryMessage = '**Continuing from previous conversation:**\n\n' + summary + '\n\n---\n\nPlease continue helping me with the above context.';

    chats[newChatId] = {
        id: newChatId,
        title: 'Continued: ' + pendingSummaryRequest.chatTitle,
        messages: [{ role: 'user', content: summaryMessage }],
        createdAt: Date.now()
    };

    pendingSummaryRequest = null;

    currentChatId = newChatId;
    appStorage.setItem('lastChatId', currentChatId);
    saveChatsToStorage();

    versionHistory = [];
    clearUpdateSet();
    renderChatList();
    renderMessages();
    renderVersionSidebar();
    updateChatTitleHeader();

    showSnackbar('New chat created with summary', 'success');

    // Auto-start agent to get AI response
    isFollowingScroll = true;
    paused = false;
    document.getElementById('pause-btn').innerHTML = '<span class="btn-icon">' + UI_ICONS.pause + '</span>Pause';
    runAgent();
}

function newChat() {
    // Save pending state for current context before switching
    var prevContext = getCurrentPendingContext();
    savePendingImagesForContext(prevContext);
    savePendingTextForContext(prevContext);

    // Close skills or dashboard view if open
    if (currentView === 'skills') {
        closeSkillsView();
    } else if (currentView === 'dashboard') {
        closeDashboardView();
    } else if (currentView === 'home') {
        closeHomeView();
    } else if (currentView === 'tools') {
        closeToolsView();
    } else if (currentView === 'settings-page') {
        closeSettingsPageView();
    }

    // Reset UI state for new chat (don't clear pendingToolApprovals - they're per-chat)
    isRunning = false;
    hidePauseButton();

    // Preserve browser state
    var browserPanel = document.getElementById('iframe-panel');
    var browserWasOpen = browserPanel && browserPanel.classList.contains('visible');
    var browserUrl = currentIframeUrl;

    currentChatId = generateId();
    chats[currentChatId] = { id: currentChatId, title: 'New Chat', messages: [], createdAt: Date.now(), isTemporary: true };

    appStorage.setItem('lastChatId', currentChatId);
    // Don't save empty chat
    versionHistory = [];
    clearUpdateSet();
    renderChatList();
    renderMessages();
    renderVersionSidebar();
    updateChatTitleHeader();

    // Temporarily close the right sidebar without affecting stored state
    var sidebar = document.getElementById('version-sidebar');
    var openBtn = document.getElementById('version-sidebar-open');
    if (sidebar) sidebar.classList.remove('visible');
    if (openBtn) openBtn.classList.add('visible');
    updateInputPosition();

    // New chat starts with empty input
    var inputEl = document.getElementById('message-input');
    if (inputEl) {
        inputEl.value = '';
        inputEl.style.height = 'auto';
        inputEl.focus();
    }

    // Keep browser open at same URL if it was open
    if (browserWasOpen && browserUrl) {
        currentIframeUrl = browserUrl;
    }

    // Start with empty pending images for the new chat
    pendingImageAttachments = [];
    renderPendingImages();

    // Push browser history state
    pushHistoryState('chat', currentChatId);
}

function selectChat(chatId, options) {
    options = options || {};
    // Save pending state for current context before switching
    var prevContext = getCurrentPendingContext();
    savePendingImagesForContext(prevContext);
    savePendingTextForContext(prevContext);

    // Reset UI state for new chat context (unless this chat is actively streaming)
    if (activeStreamingChatId !== chatId) {
        hidePauseButton();
        isRunning = false;
    } else {
        // Restore streaming UI state when returning to the actively streaming chat
        isRunning = true;
        showPauseButton();
    }
    currentChatId = chatId;
    appStorage.setItem('lastChatId', chatId);
    clearUpdateSet();
    loadVersionHistory();
    renderChatList();
    renderMessages();
    updateInputPosition();
    updateChatTitleHeader();
    // Close any non-chat view when selecting a chat
    if (currentView !== 'chat') {
        hideAllPanels();
        showChatView();
        currentView = 'chat';
        appStorage.setItem('currentView', 'chat');
        updateAllButtonStates();
    }
    // Restore pending state for the target chat
    restorePendingImagesForContext(chatId);
    restorePendingTextForContext(chatId);
    // Push browser history state
    pushHistoryState('chat', chatId);
    // Show notifications for any pending tool approvals in this chat
    // Skip if user came from "Go to chat" button (they'll handle approvals inline)
    if (!options.skipApprovalNotifications) {
        showPendingApprovalNotifications(chatId);
    }
}

function updateChatTitleHeader() {
    var titleEl = document.getElementById('header-chat-title');
    if (!titleEl) return;
    var chat = chats[currentChatId];
    if (chat && chat.title && chat.title !== 'New Chat') {
        titleEl.textContent = chat.title;
    } else {
        titleEl.textContent = '';
    }
}

async function deleteChat(chatId, e) {
    e.stopPropagation();
    var chat = chats[chatId];
    var title = chat ? chat.title : 'this chat';

    // Check if any dashboard widgets are linked to this chat
    var linkedWidgets = [];
    for (var widgetId in dashboardWidgets) {
        var widget = dashboardWidgets[widgetId];
        if (widget.chatId === chatId) {
            linkedWidgets.push(widget.title || 'Untitled Widget');
        }
    }

    var message = 'Delete "' + escapeHtml(title) + '"? This action cannot be undone.';
    if (linkedWidgets.length > 0) {
        var escapedWidgets = linkedWidgets.map(function(w) { return escapeHtml(w); });
        message = 'Delete "' + escapeHtml(title) + '"?<br><br>⚠️ <strong>Warning:</strong> This chat is linked to ' + linkedWidgets.length +
            ' dashboard widget' + (linkedWidgets.length > 1 ? 's' : '') + ':<br>• ' + escapedWidgets.join('<br>• ') +
            '<br><br>Deleting this chat will prevent these widgets from being regenerated with their original context.';
    }

    var result = await showModal('Delete Chat', message, [
        { label: 'Cancel', value: 'cancel', class: 'secondary' },
        { label: 'Delete', value: 'delete', class: 'danger' }
    ]);
    if (result !== 'delete') return;
    delete chats[chatId];
    saveChatsToStorage();
    if (currentChatId === chatId) {
        var ids = Object.keys(chats);
        ids.length > 0 ? selectChat(ids[0]) : newChat();
    } else renderChatList();
    renderHistoryPage();
    showSnackbar('Chat deleted', 'success');
}

function togglePinChat(chatId) {
    var chat = chats[chatId];
    if (!chat) return;
    chat.pinned = !chat.pinned;
    saveChatsToStorage();
    renderChatList();
    renderVersionSidebar();
}

function deleteChatFromSidebar() {
    if (!currentChatId) return;
    deleteChat(currentChatId, { stopPropagation: function() {} });
}

// Search chats by title and content (including tool calls and results)
// Uses indexOf for fast matching - returns true on first match (early exit)
function chatMatchesSearch(chat, query) {
    if (!query || query.length < 2) return true; // Require at least 2 chars
    var q = query.toLowerCase();
    // Check title first (fast check)
    if (chat.title && chat.title.toLowerCase().indexOf(q) !== -1) return true;
    // Check all messages for complete results
    if (chat.messages) {
        for (var i = 0; i < chat.messages.length; i++) {
            var msg = chat.messages[i];
            // Check message content
            if (msg.content && msg.content.toLowerCase().indexOf(q) !== -1) return true;
            // Check tool calls
            if (msg.tool_calls) {
                for (var j = 0; j < msg.tool_calls.length; j++) {
                    var tc = msg.tool_calls[j];
                    if (tc.function && tc.function.name && tc.function.name.toLowerCase().indexOf(q) !== -1) return true;
                    if (tc.function && tc.function.arguments && tc.function.arguments.toLowerCase().indexOf(q) !== -1) return true;
                }
            }
            // Check tool results
            if (msg.role === 'tool' && msg.content) {
                var resultContent = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);
                if (resultContent.toLowerCase().indexOf(q) !== -1) return true;
            }
        }
    }
    return false;
}

var chatSearchDebounceTimer = null;
var lastSearchQuery = ''; // Cache to avoid redundant searches

// Global search - searches chats, skills, tools, widgets
function handleGlobalSearch(e) {
    var value = e.target.value;
    var sidebar = document.getElementById('sidebar');

    // Update sidebar class immediately for responsive UI
    if (sidebar) {
        if (value) {
            sidebar.classList.add('searching');
        } else {
            sidebar.classList.remove('searching');
        }
    }

    // Skip if query hasn't changed
    if (value === lastSearchQuery) return;

    // Debounce the actual search
    if (chatSearchDebounceTimer) {
        clearTimeout(chatSearchDebounceTimer);
    }

    chatSearchDebounceTimer = setTimeout(function() {
        lastSearchQuery = value;
        chatSearchQuery = value;
        searchMatchesCache = {}; // Clear cache on new search
        renderChatList();
    }, 250); // 250ms debounce for better typing experience
}

function clearGlobalSearch() {
    chatSearchQuery = '';
    lastSearchQuery = ''; // Reset cache
    var input = document.getElementById('chat-search-input');
    if (input) input.value = '';
    var sidebar = document.getElementById('sidebar');
    if (sidebar) sidebar.classList.remove('searching');
    searchMatchesCache = {}; // Clear cache
    window.currentSearchHighlight = null; // Remove highlights
    renderChatList();
    renderMessages(); // Re-render to remove highlights
}

function renderChatList() {
    var list = document.getElementById('chat-list');
    if (!list) return;

    var html = '';
    var q = chatSearchQuery ? chatSearchQuery.toLowerCase() : '';

    // If searching, show matching skills, tools, widgets first
    if (q && q.length >= 2) {
        // Search skills
        var matchingSkills = Object.values(skills).filter(function(s) {
            var name = (s.name || s.id || '').toLowerCase();
            var desc = (s.description || '').toLowerCase();
            return name.indexOf(q) !== -1 || desc.indexOf(q) !== -1;
        });
        if (matchingSkills.length > 0) {
            html += '<div class="search-section-header">' + UI_ICONS.skill + ' Skills</div>';
            matchingSkills.forEach(function(s) {
                html += '<div class="search-result-item" onclick="toggleSkillsView();setTimeout(function(){openSkillEditor(\'' + escapeHtml(s.id) + '\')},100)">' +
                    '<span class="search-result-icon">' + UI_ICONS.skill + '</span>' +
                    '<span class="search-result-text">' + escapeHtml(s.name || s.id) + '</span>' +
                '</div>';
            });
        }

        // Search tools
        var matchingTools = TOOLS.filter(function(t) {
            var name = (t.function.name || '').toLowerCase();
            var displayName = (TOOL_DISPLAY_NAMES[t.function.name] || '').toLowerCase();
            var desc = (t.function.description || '').toLowerCase();
            return name.indexOf(q) !== -1 || displayName.indexOf(q) !== -1 || desc.indexOf(q) !== -1;
        });
        if (matchingTools.length > 0) {
            html += '<div class="search-section-header">' + UI_ICONS.tool + ' Tools</div>';
            matchingTools.forEach(function(t) {
                var displayName = TOOL_DISPLAY_NAMES[t.function.name] || t.function.name;
                html += '<div class="search-result-item" onclick="toggleToolsView()">' +
                    '<span class="search-result-icon">' + getToolIcon(t.function.name) + '</span>' +
                    '<span class="search-result-text">' + escapeHtml(displayName) + '</span>' +
                '</div>';
            });
        }

        // Search widgets
        var matchingWidgets = Object.values(dashboardWidgets).filter(function(w) {
            var title = (w.title || '').toLowerCase();
            return title.indexOf(q) !== -1;
        });
        if (matchingWidgets.length > 0) {
            html += '<div class="search-section-header">' + UI_ICONS.widget + ' Widgets</div>';
            matchingWidgets.forEach(function(w) {
                html += '<div class="search-result-item" onclick="toggleDashboardView()">' +
                    '<span class="search-result-icon">' + UI_ICONS.widget + '</span>' +
                    '<span class="search-result-text">' + escapeHtml(w.title) + '</span>' +
                '</div>';
            });
        }

        // Add chats header if we have other results
        if (matchingSkills.length > 0 || matchingTools.length > 0 || matchingWidgets.length > 0) {
            html += '<div class="search-section-header">' + UI_ICONS.chat + ' Chats</div>';
        }
    }

    // Only show non-empty chats, filtered by search
    var sorted = Object.values(chats)
        .filter(function(c) { return c.messages && c.messages.length > 0 && chatMatchesSearch(c, chatSearchQuery); })
        .sort(function(a, b) {
            // Pinned chats first, then by date
            if (a.pinned && !b.pinned) return -1;
            if (!a.pinned && b.pinned) return 1;
            return b.createdAt - a.createdAt;
        });

    // Separate pinned and unpinned for divider
    var pinned = sorted.filter(function(c) { return c.pinned; });
    var unpinned = sorted.filter(function(c) { return !c.pinned; });

    // Render pinned chats
    pinned.forEach(function(c) {
        html += renderChatItem(c);
    });

    // Add divider if both pinned and unpinned exist
    if (pinned.length > 0 && unpinned.length > 0) {
        html += '<div class="chat-list-divider"></div>';
    }

    // Render unpinned chats
    unpinned.forEach(function(c) {
        html += renderChatItem(c);
    });

    list.innerHTML = html;
}

// Find ALL search matches in a chat with metadata for navigation
var MAX_MATCHES_PER_CHAT = 50; // Limit displayed matches per chat
function findAllSearchMatches(chat, query) {
    if (!query || query.length < 2) return []; // Require at least 2 chars
    var q = query.toLowerCase();
    var snippetLength = 40; // chars before and after match
    var matches = [];

    // Helper to create a snippet with bolded match
    function createSnippet(text, matchIdx, queryLen) {
        var start = Math.max(0, matchIdx - snippetLength);
        var end = Math.min(text.length, matchIdx + queryLen + snippetLength);
        var snippet = text.substring(start, end);
        var prefix = start > 0 ? '...' : '';
        var suffix = end < text.length ? '...' : '';
        var localMatchStart = matchIdx - start;
        var before = escapeHtml(snippet.substring(0, localMatchStart));
        var match = escapeHtml(snippet.substring(localMatchStart, localMatchStart + queryLen));
        var after = escapeHtml(snippet.substring(localMatchStart + queryLen));
        return prefix + before + '<strong>' + match + '</strong>' + after + suffix;
    }

    // Search in messages content and tool calls
    if (chat.messages) {
        for (var i = 0; i < chat.messages.length; i++) {
            var msg = chat.messages[i];

            // Check message content (user/assistant messages)
            if (msg.content && (msg.role === 'user' || msg.role === 'assistant')) {
                var contentLower = msg.content.toLowerCase();
                var searchPos = 0;
                var idx;
                var occurrenceInContent = 0;
                while ((idx = contentLower.indexOf(q, searchPos)) !== -1) {
                    if (matches.length >= MAX_MATCHES_PER_CHAT) break;
                    matches.push({
                        type: 'content',
                        msgIndex: i,
                        role: msg.role,
                        occurrenceIndex: occurrenceInContent,
                        snippet: createSnippet(msg.content, idx, query.length)
                    });
                    occurrenceInContent++;
                    searchPos = idx + 1;
                }
            }
            if (matches.length >= MAX_MATCHES_PER_CHAT) break;

            // Check tool calls
            if (msg.tool_calls && matches.length < MAX_MATCHES_PER_CHAT) {
                for (var j = 0; j < msg.tool_calls.length && matches.length < MAX_MATCHES_PER_CHAT; j++) {
                    var tc = msg.tool_calls[j];
                    if (tc.function && tc.function.arguments) {
                        var argsLower = tc.function.arguments.toLowerCase();
                        var argSearchPos = 0;
                        var argIdx;
                        var occurrenceInToolCall = 0;
                        while ((argIdx = argsLower.indexOf(q, argSearchPos)) !== -1) {
                            if (matches.length >= MAX_MATCHES_PER_CHAT) break;
                            matches.push({
                                type: 'tool_call',
                                msgIndex: i,
                                toolCallIndex: j,
                                toolName: tc.function.name,
                                occurrenceIndex: occurrenceInToolCall,
                                snippet: createSnippet(tc.function.arguments, argIdx, query.length)
                            });
                            occurrenceInToolCall++;
                            argSearchPos = argIdx + 1;
                        }
                    }
                }
            }

            // Check tool results
            if (msg.role === 'tool' && msg.content && matches.length < MAX_MATCHES_PER_CHAT) {
                var resultContent = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);
                var resultLower = resultContent.toLowerCase();
                var resultSearchPos = 0;
                var resultIdx;
                var occurrenceInResult = 0;
                while ((resultIdx = resultLower.indexOf(q, resultSearchPos)) !== -1) {
                    if (matches.length >= MAX_MATCHES_PER_CHAT) break;
                    matches.push({
                        type: 'tool_result',
                        msgIndex: i,
                        toolName: msg.name,
                        occurrenceIndex: occurrenceInResult,
                        snippet: createSnippet(resultContent, resultIdx, query.length)
                    });
                    occurrenceInResult++;
                    resultSearchPos = resultIdx + 1;
                }
            }
        }
    }

    return matches;
}

// Navigate to a search match
function navigateToSearchMatch(chatId, match) {
    // Select the chat first
    if (currentChatId !== chatId) {
        selectChat(chatId);
    }

    // First enable highlighting
    window.currentSearchHighlight = chatSearchQuery;
    renderMessages();

    // Helper to get the nth highlight element
    function getNthHighlight(container, n) {
        var highlights = container.querySelectorAll('mark.search-highlight');
        return highlights[n] || highlights[0];
    }

    // Wait for render, then scroll to the exact match
    setTimeout(function() {
        var msgEl = document.getElementById('msg-' + match.msgIndex);
        if (!msgEl) return;

        var occIdx = match.occurrenceIndex || 0;

        // If it's a tool call, expand and scroll to it
        if (match.type === 'tool_call') {
            // Find the details element for this tool call
            var allDetails = msgEl.querySelectorAll('details.tool-call');
            var tcEl = allDetails[match.toolCallIndex];
            if (tcEl) {
                tcEl.open = true;
                // Wait for expansion, then scroll to the specific highlight
                setTimeout(function() {
                    var highlight = getNthHighlight(tcEl, occIdx);
                    if (highlight) {
                        highlight.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        highlight.classList.add('search-highlight-current');
                        setTimeout(function() { highlight.classList.remove('search-highlight-current'); }, 3000);
                    } else {
                        tcEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }
                }, 50);
            }
        } else if (match.type === 'tool_result') {
            // Find the tool result details
            var resultDetails = msgEl.querySelector('details.tool-result');
            if (resultDetails) {
                resultDetails.open = true;
                setTimeout(function() {
                    var highlight = getNthHighlight(resultDetails, occIdx);
                    if (highlight) {
                        highlight.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        highlight.classList.add('search-highlight-current');
                        setTimeout(function() { highlight.classList.remove('search-highlight-current'); }, 3000);
                    } else {
                        resultDetails.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    }
                }, 50);
            }
        } else {
            // Regular content - find the nth highlight in this message content
            var contentEl = msgEl.querySelector('.message-content');
            var highlight = contentEl ? getNthHighlight(contentEl, occIdx) : getNthHighlight(msgEl, occIdx);
            if (highlight) {
                highlight.scrollIntoView({ behavior: 'smooth', block: 'center' });
                highlight.classList.add('search-highlight-current');
                setTimeout(function() { highlight.classList.remove('search-highlight-current'); }, 3000);
            } else {
                msgEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }

        // Flash the message
        msgEl.classList.add('highlight-flash');
        setTimeout(function() { msgEl.classList.remove('highlight-flash'); }, 2000);
    }, 100);
}

// Highlight search terms in messages
function highlightSearchTerms(query) {
    if (!query) {
        removeSearchHighlights();
        return;
    }
    // Store the query for rendering
    window.currentSearchHighlight = query;
    renderMessages();
}

// Remove search highlights
function removeSearchHighlights() {
    window.currentSearchHighlight = null;
    renderMessages();
}

// Store matches for click handling
var searchMatchesCache = {};

function renderChatItem(c) {
    // Don't highlight any chat as active when Dashboard or Skills is open
    var active = (currentView === 'chat' && c.id === currentChatId) ? 'active' : '';
    var pinIcon = c.pinned ? '<span class="pin-icon" title="Pinned">' + UI_ICONS.pinFilled + '</span>' : '';
    var pinLabel = c.pinned ? 'Unpin Chat' : 'Pin Chat';
    var dropdownId = 'chat-dropdown-' + c.id;

    // Show all snippets when searching, otherwise show title
    var displayContent;
    if (chatSearchQuery) {
        var matches = findAllSearchMatches(c, chatSearchQuery);
        searchMatchesCache[c.id] = matches; // Cache for click handling

        var snippetsHtml = '';
        matches.forEach(function(match, idx) {
            var typeIcon = match.type === 'content' ? (match.role === 'user' ? '<span class="snippet-icon">' + UI_ICONS.user + '</span>' : '<span class="snippet-icon">' + UI_ICONS.bot + '</span>') : 
                          (match.type === 'tool_call' ? '<span class="snippet-icon">' + getToolIcon(match.toolName) + '</span>' : '<span class="snippet-icon">' + UI_ICONS.result + '</span>');
            var typeLabel = match.type === 'content' ? (match.role === 'user' ? 'You' : 'AI') :
                           (match.type === 'tool_call' ? (TOOL_DISPLAY_NAMES[match.toolName] || match.toolName) : 
                           (TOOL_DISPLAY_NAMES[match.toolName] || match.toolName) + ' result');
            snippetsHtml += '<div class="chat-result-snippet-item" onclick="event.stopPropagation(); handleSearchSnippetClick(\'' + c.id + '\', ' + idx + ')">' +
                '<span class="snippet-type">' + typeIcon + ' ' + typeLabel + '</span>' +
                '<span class="snippet-text">' + match.snippet + '</span>' +
            '</div>';
        });

        // Title row with menu button
        var titleRow = '<div class="chat-result-title-row">' +
            pinIcon +
            '<div class="chat-result-title">' + escapeHtml(c.title) + ' <span class="match-count">(' + matches.length + ' match' + (matches.length !== 1 ? 'es' : '') + ')</span></div>' +
            '<div class="chat-menu-wrapper">' +
            '<button class="chat-menu-btn" onclick="event.stopPropagation(); toggleChatDropdown(\'' + dropdownId + '\')" title="More options">···</button>' +
            '<div class="chat-dropdown" id="' + dropdownId + '">' +
            '<button class="chat-dropdown-item" onclick="event.stopPropagation(); closeChatDropdowns(); openRenameModal(\'' + c.id + '\')"><span class="dropdown-icon">' + UI_ICONS.edit + '</span>Rename</button>' +
            '<button class="chat-dropdown-item" onclick="event.stopPropagation(); closeChatDropdowns(); downloadChat(\'' + c.id + '\')"><span class="dropdown-icon">' + UI_ICONS.download + '</span>Download</button>' +
            '<button class="chat-dropdown-item" onclick="event.stopPropagation(); closeChatDropdowns(); togglePinChat(\'' + c.id + '\')"><span class="dropdown-icon">' + (c.pinned ? UI_ICONS.pinFilled : UI_ICONS.pin) + '</span>' + pinLabel + '</button>' +
            '<div class="chat-dropdown-divider"></div>' +
            '<button class="chat-dropdown-item danger" onclick="event.stopPropagation(); closeChatDropdowns(); deleteChat(\'' + c.id + '\', event)"><span class="dropdown-icon">' + UI_ICONS.trash + '</span>Delete</button>' +
            '</div>' +
            '</div>' +
        '</div>';

        displayContent = '<div class="chat-search-result">' +
            titleRow +
            '<div class="chat-result-snippets">' + snippetsHtml + '</div>' +
        '</div>';

        return '<div class="chat-item ' + active + ' searching">' + displayContent + '</div>';
    } else {
        var attentionIndicator = chatHasPendingApproval(c.id) ? '<span class="chat-attention-dot" title="Requires permission"></span>' : '';
        var pendingIndicator = chatHasPendingItems(c.id) ? '<span class="chat-pending-dot" title="Has pending draft"></span>' : '';
        displayContent = attentionIndicator + pendingIndicator + '<span class="chat-title">' + escapeHtml(c.title) + '</span>';
    }

    return '<div class="chat-item ' + active + '" onclick="selectChat(\'' + c.id + '\')">'+
        pinIcon +
        displayContent +
        '<div class="chat-menu-wrapper">' +
        '<button class="chat-menu-btn" onclick="event.stopPropagation(); toggleChatDropdown(\'' + dropdownId + '\')" title="More options">···</button>' +
        '<div class="chat-dropdown" id="' + dropdownId + '">' +
        '<button class="chat-dropdown-item" onclick="event.stopPropagation(); closeChatDropdowns(); openRenameModal(\'' + c.id + '\')"><span class="dropdown-icon">' + UI_ICONS.edit + '</span>Rename</button>' +
        '<button class="chat-dropdown-item" onclick="event.stopPropagation(); closeChatDropdowns(); downloadChat(\'' + c.id + '\')"><span class="dropdown-icon">' + UI_ICONS.download + '</span>Download</button>' +
        '<button class="chat-dropdown-item" onclick="event.stopPropagation(); closeChatDropdowns(); togglePinChat(\'' + c.id + '\')"><span class="dropdown-icon">' + (c.pinned ? UI_ICONS.pinFilled : UI_ICONS.pin) + '</span>' + pinLabel + '</button>' +
        '<div class="chat-dropdown-divider"></div>' +
        '<button class="chat-dropdown-item danger" onclick="event.stopPropagation(); closeChatDropdowns(); deleteChat(\'' + c.id + '\', event)"><span class="dropdown-icon">' + UI_ICONS.trash + '</span>Delete</button>' +
        '</div>' +
        '</div>' +
    '</div>';
}

// Handle click on search snippet
function handleSearchSnippetClick(chatId, matchIndex) {
    var matches = searchMatchesCache[chatId];
    if (!matches || !matches[matchIndex]) return;
    navigateToSearchMatch(chatId, matches[matchIndex]);
}

function escapeHtml(t) {
    var d = document.createElement('div');
    d.textContent = t;
    return d.innerHTML;
}

function formatFileSize(bytes) {
    if (bytes === 0) return '0 B';
    var k = 1024;
    var sizes = ['B', 'KB', 'MB', 'GB'];
    var i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
}

// Extract status_message from partial/streaming JSON arguments using regex
// This works even when the JSON is incomplete during streaming
function extractStatusMessage(argsString) {
    if (!argsString || typeof argsString !== 'string') return null;
    // Try full JSON parse first
    try {
        var parsed = JSON.parse(argsString);
        if (parsed.status_message) return parsed.status_message;
    } catch (e) {
        // JSON incomplete, try regex extraction
    }
    // Regex to extract status_message value from partial JSON
    // Matches: "status_message": "value" or "status_message":"value"
    var match = argsString.match(/"status_message"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/);
    if (match && match[1]) {
        // Unescape basic JSON escape sequences
        return match[1].replace(/\\n/g, '\n').replace(/\\t/g, '\t').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
    }
    return null;
}

// Format JSON string with pretty printing if valid JSON
// Renders arrays with expand/collapse buttons and removes quotes from strings
function formatJsonPretty(str) {
    if (!str || typeof str !== 'string') return str;
    try {
        var parsed = JSON.parse(str);
        return formatJsonValue(parsed, 0);
    } catch (e) {
        return str; // Return original if not valid JSON
    }
}

// Recursively format JSON values with collapsible arrays and objects
function formatJsonValue(value, indent) {
    var indentStr = '  '.repeat(indent);
    var nextIndent = '  '.repeat(indent + 1);

    if (value === null) return '<span class="json-null">null</span>';
    if (typeof value === 'boolean') return '<span class="json-bool">' + value + '</span>';
    if (typeof value === 'number') return '<span class="json-num">' + value + '</span>';
    if (typeof value === 'string') {
        var escaped = escapeHtml(value);
        var valueLines = value.split('\n');
        var lineCount = valueLines.length;
        // Collapse if multiple lines or single line > 80 chars
        if (lineCount > 1 || value.length > 80) {
            var collapseId = 'json-str-' + Math.random().toString(36).substr(2, 9);
            var firstLine = valueLines[0];
            if (firstLine.length > 80) firstLine = firstLine.substring(0, 77) + '...';
            var preview = escapeHtml(firstLine);
            if (lineCount > 2) {
                preview += '<span class="json-preview"> +' + (lineCount - 1) + ' lines</span>';
            } else if (lineCount === 2) {
                preview += '<span class="json-preview"> +1 line</span>';
            }
            return '<span class="json-collapse" onclick="toggleJsonCollapse(\'' + collapseId + '\', event)">−</span>' +
                '<span id="' + collapseId + '" class="json-collapsible json-str">' + escaped + '</span>' +
                '<span id="' + collapseId + '-collapsed" class="json-collapsed json-str" style="display:none">' + preview + '</span>';
        }
        return '<span class="json-str">' + escaped + '</span>';
    }

    if (Array.isArray(value)) {
        if (value.length === 0) return '[]';
        var collapseId = 'json-arr-' + Math.random().toString(36).substr(2, 9);
        var items = value.map(function(item, idx) {
            return nextIndent + formatJsonValue(item, indent + 1) + (idx < value.length - 1 ? ',' : '');
        }).join('\n');
        return '<span class="json-collapse" onclick="toggleJsonCollapse(\'' + collapseId + '\', event)">−</span>' +
            '<span id="' + collapseId + '" class="json-collapsible">[\n' + items + '\n' + indentStr + ']</span>' +
            '<span id="' + collapseId + '-collapsed" class="json-collapsed" style="display:none">[<span class="json-preview">' + value.length + ' items</span>]</span>';
    }

    if (typeof value === 'object') {
        var keys = Object.keys(value);
        if (keys.length === 0) return '{}';
        var entries = keys.map(function(key, idx) {
            return nextIndent + '<span class="json-key">' + escapeHtml(key) + '</span>: ' + formatJsonValue(value[key], indent + 1) + (idx < keys.length - 1 ? ',' : '');
        }).join('\n');
        // Add collapse button for all objects
        var collapseId = 'json-obj-' + Math.random().toString(36).substr(2, 9);
        return '<span class="json-collapse" onclick="toggleJsonCollapse(\'' + collapseId + '\', event)">−</span>' +
            '<span id="' + collapseId + '" class="json-collapsible">{\n' + entries + '\n' + indentStr + '}</span>' +
            '<span id="' + collapseId + '-collapsed" class="json-collapsed" style="display:none">{<span class="json-preview">' + keys.length + ' keys</span>}</span>';
    }

    return String(value);
}

// Toggle JSON array collapse
function toggleJsonCollapse(id, event) {
    event.stopPropagation();
    var expanded = document.getElementById(id);
    var collapsed = document.getElementById(id + '-collapsed');
    var btn = event.target;
    if (!expanded || !collapsed) return;

    if (expanded.style.display === 'none') {
        expanded.style.display = 'inline';
        collapsed.style.display = 'none';
        btn.textContent = '−';
    } else {
        expanded.style.display = 'none';
        collapsed.style.display = 'inline';
        btn.textContent = '+';
    }
}

// Toggle tool args expand to full height
function toggleToolExpand(btn, event) {
    event.stopPropagation();
    var wrapper = btn.closest('.tool-args-wrapper') || btn.closest('.tool-result-wrapper');
    var details = btn.closest('.tool-call') || btn.closest('.tool-result');
    var pre = wrapper.querySelector('.tool-args') || wrapper.querySelector('pre');
    if (!pre) return;

    // Track expanded state in message data
    var msgEl = details ? details.closest('.message') : null;
    var msgIndex = msgEl ? parseInt(msgEl.id.replace('msg-', '')) : -1;
    var isToolCall = details && details.classList.contains('tool-call');
    var tcIdx = -1;
    if (isToolCall && details.id) {
        var parts = details.id.split('-');
        tcIdx = parseInt(parts[parts.length - 1]);
    }

    var isExpanding = !pre.classList.contains('expanded');

    if (!isExpanding) {
        pre.classList.remove('expanded');
        if (details) {
            details.classList.remove('expanded');
            details.classList.remove('stuck');
            // Clean up observer
            if (details._stickyObserver) {
                details._stickyObserver.disconnect();
                details._stickyObserver = null;
            }
        }
        btn.textContent = '⤢';
        btn.title = 'Expand';
    } else {
        pre.classList.add('expanded');
        if (details) {
            details.classList.add('expanded');
            // Set up IntersectionObserver to detect when header should stick
            setupStickyObserver(details);
        }
        btn.textContent = '⤡';
        btn.title = 'Collapse';
    }

    // Save expanded state to message data
    var chat = chats[currentChatId];
    if (chat && msgIndex >= 0 && chat.messages[msgIndex]) {
        var msg = chat.messages[msgIndex];
        if (isToolCall && tcIdx >= 0) {
            if (!msg.toolCallsFullHeight) msg.toolCallsFullHeight = {};
            msg.toolCallsFullHeight[tcIdx] = isExpanding;
        } else if (details && details.classList.contains('tool-result')) {
            msg.fullHeight = isExpanding;
        }
    }
}

// Set up IntersectionObserver to add/remove stuck class
function setupStickyObserver(details) {
    var summary = details.querySelector('summary');
    if (!summary) return;

    var scrollContainer = details.closest('.messages');
    if (!scrollContainer) return;

    // Clean up existing observer
    if (details._stickyObserver) {
        details._stickyObserver.disconnect();
    }

    // Create sentinel element at the top of details
    var sentinel = details.querySelector('.sticky-sentinel');
    if (!sentinel) {
        sentinel = document.createElement('div');
        sentinel.className = 'sticky-sentinel';
        sentinel.style.cssText = 'position: absolute; top: 0; left: 0; right: 0; height: 1px; pointer-events: none;';
        details.style.position = 'relative';
        details.insertBefore(sentinel, details.firstChild);
    }

    var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            // When sentinel is not visible (scrolled past), header should be stuck
            if (!entry.isIntersecting) {
                details.classList.add('stuck');
            } else {
                details.classList.remove('stuck');
            }
        });
    }, {
        root: scrollContainer,
        threshold: 0,
        rootMargin: '0px 0px 0px 0px'
    });

    observer.observe(sentinel);
    details._stickyObserver = observer;
}

// Toggle code block expand/collapse
function toggleCodeBlockExpand(btn, event) {
    event.stopPropagation();
    var wrapper = btn.closest('.code-block-wrapper');
    var pre = wrapper.querySelector('.code-block');
    if (!pre) return;

    if (pre.classList.contains('collapsed')) {
        pre.classList.remove('collapsed');
        wrapper.classList.add('expanded');
        btn.textContent = '⤡';
        btn.title = 'Collapse';
    } else {
        pre.classList.add('collapsed');
        wrapper.classList.remove('expanded');
        btn.textContent = '⤢';
        btn.title = 'Expand';
    }
}

// Global store for raw content to copy
window._rawCopyStore = window._rawCopyStore || {};
var _rawCopyId = 0;
function storeRawCopy(content) {
    var id = 'rc-' + (++_rawCopyId);
    window._rawCopyStore[id] = content;
    return id;
}

// Copy code block content - get raw text without formatting
function copyCodeBlock(btn, event) {
    event.stopPropagation();
    var wrapper = btn.closest('.code-block-wrapper') || btn.closest('.tool-args-wrapper') || btn.closest('.tool-result-wrapper');
    if (!wrapper) return;

    var text = '';
    // Check if wrapper has raw copy ID
    var copyId = wrapper.getAttribute('data-copy-id');
    if (copyId && window._rawCopyStore[copyId]) {
        text = window._rawCopyStore[copyId];
    } else {
        // Fallback: get text content
        var code = wrapper.querySelector('code') || wrapper.querySelector('pre');
        if (code) text = code.textContent || code.innerText;
    }

    navigator.clipboard.writeText(text).then(function() {
        showSnackbar('Copied to clipboard', 'success');
    });
}

// Chat dropdown menu helpers
function toggleChatDropdown(dropdownId) {
    var dropdown = document.getElementById(dropdownId);
    if (!dropdown) return;
    var isOpen = dropdown.classList.contains('open');
    closeChatDropdowns();
    if (!isOpen) {
        dropdown.classList.add('open');
    }
}

function closeChatDropdowns() {
    document.querySelectorAll('.chat-dropdown.open').forEach(function(d) {
        d.classList.remove('open');
    });
}

// Close chat dropdowns when clicking outside
document.addEventListener('click', function(e) {
    if (!e.target.closest('.chat-menu-wrapper')) {
        closeChatDropdowns();
    }
});

// Rename current chat from header button
function renameCurrentChat() {
    if (!currentChatId || !chats[currentChatId]) return;
    openRenameModal(currentChatId);
}

// Rename chat modal
function openRenameModal(chatId) {
    var chat = chats[chatId];
    if (!chat) return;

    var overlay = document.getElementById('modal-overlay');
    var header = document.getElementById('modal-header');
    var body = document.getElementById('modal-body');
    var actions = document.getElementById('modal-actions');

    header.textContent = 'Rename Chat';
    body.innerHTML = '<input type="text" id="rename-chat-input" class="modal-input" value="' + escapeHtml(chat.title) + '" placeholder="Enter new name..." style="width:100%;padding:10px;border:1px solid #ddd;border-radius:6px;font-size:14px;box-sizing:border-box;" />';
    actions.innerHTML = '<button class="modal-btn secondary" onclick="closeModal()">Cancel</button>' +
        '<button class="modal-btn primary" onclick="confirmRenameChat(\'' + chatId + '\')">Rename</button>';

    overlay.classList.add('show');

    setTimeout(function() {
        var input = document.getElementById('rename-chat-input');
        if (input) {
            input.focus();
            input.select();
        }
    }, 100);
}

function confirmRenameChat(chatId) {
    var input = document.getElementById('rename-chat-input');
    if (!input) return;

    var newTitle = input.value.trim();
    if (!newTitle) {
        showSnackbar('Please enter a valid name', 'error');
        return;
    }

    var chat = chats[chatId];
    if (chat) {
        chat.title = newTitle;
        saveChatsToStorage();
        renderChatList();
        if (chatId === currentChatId) updateChatTitleHeader();
        showSnackbar('Chat renamed', 'success');
    }

    closeModal();
}

// Download chat as JSON
function downloadChat(chatId) {
    var chat = chats[chatId];
    if (!chat) return;

    var exportData = {
        exportType: 'single_chat',
        exportDate: new Date().toISOString(),
        chat: chat
    };

    var blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'chat_' + chat.title.replace(/[^a-z0-9]/gi, '_').substring(0, 30) + '_' + new Date().toISOString().slice(0, 10) + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    showSnackbar('Chat downloaded', 'success');
}

// Import a single chat from JSON file
function importSingleChat() {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async function(e) {
        var file = e.target.files[0];
        if (!file) return;

        try {
            var text = await file.text();
            var data = JSON.parse(text);

            // Validate the import data
            if (data.exportType !== 'single_chat' || !data.chat) {
                showSnackbar('Invalid chat file format', 'error');
                return;
            }

            var importedChat = data.chat;

            // Generate a new ID to avoid conflicts
            var newId = 'chat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            importedChat.id = newId;
            importedChat.title = importedChat.title + ' (imported)';
            importedChat.createdAt = Date.now();

            // Add to chats without affecting existing ones
            chats[newId] = importedChat;
            await saveChatsToStorage();
            renderChatList();

            showSnackbar('Chat imported successfully', 'success');
        } catch (err) {
            console.error('Import error:', err);
            showSnackbar('Failed to import chat: ' + err.message, 'error');
        }
    };
    input.click();
}

// Notification System
var snackbarTimeout = null;
function showSnackbar(message, type, duration) {
    var snackbar = document.getElementById('snackbar');
    if (!snackbar) return;

    // Handle both string type ('error'/'success'/'warning') and legacy boolean isError
    var isError = type === 'error' || type === true;
    var isWarning = type === 'warning';
    var typeClass = isError ? ' error' : (isWarning ? ' warning' : ' success');

    // Build snackbar content with close button for errors and warnings
    var closeBtn = (isError || isWarning) ? '<button class="snackbar-close" onclick="hideSnackbar()">' + UI_ICONS.close + '</button>' : '';
    snackbar.innerHTML = '<span class="snackbar-message">' + escapeHtml(message) + '</span>' + closeBtn;
    snackbar.className = 'snackbar show' + typeClass;

    if (snackbarTimeout) clearTimeout(snackbarTimeout);

    // Don't auto-close errors or warnings - user must dismiss manually
    if (!isError && !isWarning) {
        snackbarTimeout = setTimeout(function() {
            snackbar.classList.remove('show');
        }, duration || 3000);
    }
}

function hideSnackbar() {
    var snackbar = document.getElementById('snackbar');
    if (snackbar) snackbar.classList.remove('show');
    if (snackbarTimeout) clearTimeout(snackbarTimeout);
}

// Notification queue for tool approvals
var approvalNotificationQueue = [];
var isShowingApprovalNotification = false;
var currentApprovalNotification = null; // Track which notification is currently showing

// Show notification for tool approval with action button to go to the chat
function showApprovalNotification(chatTitle, toolName, chatId, statusMessage, approvalIndex, args) {
    // Check if this approval is already in the queue or currently showing
    var alreadyQueued = approvalNotificationQueue.some(function(n) {
        return n.chatId === chatId && n.approvalIndex === approvalIndex;
    });
    var alreadyShowing = Array.isArray(currentApprovalNotification) &&
        currentApprovalNotification.some(function(n) {
            return n.chatId === chatId && n.approvalIndex === approvalIndex;
        });
    if (alreadyQueued || alreadyShowing) {
        return;
    }

    var newNotification = { chatTitle: chatTitle, toolName: toolName, chatId: chatId, statusMessage: statusMessage, approvalIndex: approvalIndex, args: args };

    if (!isShowingApprovalNotification) {
        // No notification showing, start fresh
        approvalNotificationQueue.push(newNotification);
        showNextApprovalNotification();
    } else if (Array.isArray(currentApprovalNotification) && currentApprovalNotification.length > 0 && currentApprovalNotification[0].chatId === chatId) {
        // Current notification is for the SAME chat - add to it and re-render in batch mode
        currentApprovalNotification.push(newNotification);
        rerenderCurrentNotification();
    } else {
        // Different chat - add to queue and update badge
        approvalNotificationQueue.push(newNotification);
        updateNotificationQueueBadge();
    }
}

// Re-render the current notification (used when adding more tools from same chat)
function rerenderCurrentNotification() {
    if (!Array.isArray(currentApprovalNotification) || currentApprovalNotification.length === 0) return;

    var snackbar = document.getElementById('snackbar');
    if (!snackbar) return;

    var chatNotifications = currentApprovalNotification;
    var chatId = chatNotifications[0].chatId;
    var firstNotification = chatNotifications[0];

    // Count remaining notifications from OTHER chats
    var otherChatsCount = approvalNotificationQueue.length;
    var queueBadge = otherChatsCount > 0 ? '<span class="notification-queue-badge">+' + otherChatsCount + ' from other chats</span>' : '';

    var bodyHtml = '';
    var actionsHtml = '';

    if (chatNotifications.length === 1) {
        // Single notification: show full buttons with expandable params
        var notification = chatNotifications[0];
        var statusLine = notification.statusMessage
            ? '<div class="notification-status">' + escapeHtml(notification.statusMessage) + '</div>'
            : '';

        var paramsHtml = '';
        if (notification.args) {
            var argsStr = typeof notification.args === 'string' ? notification.args : JSON.stringify(notification.args, null, 2);
            paramsHtml = '<details class="notification-params">' +
                '<summary class="notification-params-toggle">' + UI_ICONS.code + ' Parameters</summary>' +
                '<div class="notification-params-content"><pre>' + formatJsonPretty(argsStr) + '</pre></div>' +
                '</details>';
        }

        bodyHtml =
            '<span class="notification-message"><strong>' + escapeHtml(notification.chatTitle) + '</strong> wants to run <strong>' + escapeHtml(notification.toolName) + '</strong></span>' +
            statusLine +
            paramsHtml;

        actionsHtml =
            '<button class="tool-approval-btn allow" onclick="approveFromNotification(' + notification.approvalIndex + ', \'' + chatId + '\', \'allow\')">' + UI_ICONS.check + 'Allow</button>' +
            '<button class="tool-approval-btn session" onclick="approveFromNotification(' + notification.approvalIndex + ', \'' + chatId + '\', \'session\')">' + UI_ICONS.clock + 'Until Close</button>' +
            '<button class="tool-approval-btn deny" onclick="approveFromNotification(' + notification.approvalIndex + ', \'' + chatId + '\', \'deny\')">' + UI_ICONS.close + 'Deny</button>' +
            '<button class="tool-approval-btn" onclick="goToApprovalChat(\'' + chatId + '\')">' + UI_ICONS.chat + 'Go to chat</button>';
    } else {
        // Multiple notifications: show grouped format with expandable params for each
        var toolsHtml = '';
        var approvalIndices = [];
        for (var j = 0; j < chatNotifications.length; j++) {
            var notif = chatNotifications[j];
            approvalIndices.push(notif.approvalIndex);
            var statusLine = notif.statusMessage
                ? '<div class="notification-tool-status">' + escapeHtml(notif.statusMessage) + '</div>'
                : '';

            var paramsHtml = '';
            if (notif.args) {
                var argsStr = typeof notif.args === 'string' ? notif.args : JSON.stringify(notif.args, null, 2);
                paramsHtml = '<details class="notification-params notification-params-compact">' +
                    '<summary class="notification-params-toggle">' + UI_ICONS.code + '</summary>' +
                    '<div class="notification-params-content"><pre>' + formatJsonPretty(argsStr) + '</pre></div>' +
                    '</details>';
            }

            toolsHtml +=
                '<div class="notification-tool-item">' +
                    '<div class="notification-tool-info">' +
                        '<strong>' + escapeHtml(notif.toolName) + '</strong>' +
                        statusLine +
                    '</div>' +
                    '<div class="notification-tool-actions">' +
                        paramsHtml +
                        '<button class="tool-approval-btn allow" onclick="approveFromNotification(' + notif.approvalIndex + ', \'' + chatId + '\', \'allow\')">' + UI_ICONS.check + '</button>' +
                        '<button class="tool-approval-btn session" onclick="approveFromNotification(' + notif.approvalIndex + ', \'' + chatId + '\', \'session\')">' + UI_ICONS.clock + '</button>' +
                        '<button class="tool-approval-btn deny" onclick="approveFromNotification(' + notif.approvalIndex + ', \'' + chatId + '\', \'deny\')">' + UI_ICONS.close + '</button>' +
                    '</div>' +
                '</div>';
        }

        var indicesJson = JSON.stringify(approvalIndices).replace(/"/g, '&quot;');
        var bulkActionsHtml =
            '<div class="notification-bulk-actions">' +
                '<button class="tool-approval-btn allow" onclick="approveAllFromNotification(' + indicesJson + ', \'' + chatId + '\', \'allow\')">' + UI_ICONS.check + 'Allow All (' + chatNotifications.length + ')</button>' +
                '<button class="tool-approval-btn session" onclick="approveAllFromNotification(' + indicesJson + ', \'' + chatId + '\', \'session\')">' + UI_ICONS.clock + 'All Until Close</button>' +
                '<button class="tool-approval-btn deny" onclick="approveAllFromNotification(' + indicesJson + ', \'' + chatId + '\', \'deny\')">' + UI_ICONS.close + 'Deny All</button>' +
            '</div>';

        bodyHtml =
            '<span class="notification-message"><strong>' + escapeHtml(firstNotification.chatTitle) + '</strong> wants to run:</span>' +
            '<div class="notification-tools-list">' + toolsHtml + '</div>' +
            bulkActionsHtml;

        actionsHtml =
            '<button class="tool-approval-btn" onclick="goToApprovalChat(\'' + chatId + '\')">' + UI_ICONS.chat + 'Go to chat</button>';
    }

    snackbar.innerHTML =
        '<div class="notification-header">' +
            '<span class="notification-icon">' + UI_ICONS.bell + '</span>' +
            '<span class="notification-title">Permission Required</span>' +
            queueBadge +
            '<button class="notification-close" onclick="dismissApprovalNotification()">' + UI_ICONS.close + '</button>' +
        '</div>' +
        '<div class="notification-body">' + bodyHtml + '</div>' +
        '<div class="notification-actions">' + actionsHtml + '</div>';
}

function updateNotificationQueueBadge() {
    var badge = document.querySelector('.notification-queue-badge');
    var queueCount = approvalNotificationQueue.length;
    if (queueCount > 0) {
        if (badge) {
            badge.textContent = '+' + queueCount + ' more';
        } else {
            // Add badge if it doesn't exist
            var title = document.querySelector('.notification-title');
            if (title) {
                var newBadge = document.createElement('span');
                newBadge.className = 'notification-queue-badge';
                newBadge.textContent = '+' + queueCount + ' more';
                title.insertAdjacentElement('afterend', newBadge);
            }
        }
    }
}

