        // TO REVERT TO ALL SPANS: Replace the selector below with just 'span', then uncomment the
        // getComputedStyle checks to filter only inline spans with block children:
        //   var spanStyle = win.getComputedStyle(span);
        //   if (spanStyle.display !== 'inline') return;
        //   if (!span.children.length) return;
        //   var firstChildStyle = win.getComputedStyle(span.children[0]);
        //   if (firstChildStyle.display !== 'block' && firstChildStyle.display !== 'flex') return;
        var restoreMarginFix = [];
        try {
            var doc = targetNode.ownerDocument || targetNode;
            var widgetSpans = doc.querySelectorAll('span[ng-switch-default][ng-repeat*="rectangle"], span[ng-repeat*="widget"]');
            var processed = new Set();
            widgetSpans.forEach(function(span) {
                var parent = span.parentElement;
                if (!parent || processed.has(parent)) return;
                processed.add(parent);
                var origDisplay = parent.style.display;
                var origFlexDir = parent.style.flexDirection;
                parent.style.setProperty('display', 'flex', 'important');
                parent.style.setProperty('flex-direction', 'column', 'important');
                restoreMarginFix.push({ el: parent, display: origDisplay, flexDir: origFlexDir });
            });
        } catch (e) { /* ignore */ }

        var dataUrl;
        try {
            var svgDataUrl = await _htiToSvg(targetNode, htiOpts);
            var ratio = htiOpts.pixelRatio || 1;
            dataUrl = await svgToPng(sanitizeSvgDataUrl(svgDataUrl), htiOpts.width, htiOpts.height, ratio);
        } finally {
            restoreGCS();
            // Restore margin fix styles
            restoreMarginFix.forEach(function(item) {
                if (item.display) item.el.style.display = item.display;
                else item.el.style.removeProperty('display');
                if (item.flexDir) item.el.style.flexDirection = item.flexDir;
                else item.el.style.removeProperty('flex-direction');
            });
        }

        var elapsed = Math.round(performance.now() - startTime);
        _screenshotDataUrl = dataUrl;
        showScreenshotPreview(dataUrl, 'Screenshot (' + elapsed + 'ms)', iframe.clientWidth, iframe.clientHeight);

    } catch (err) {
        console.error('[Screenshot] error:', err);
        showSnackbar('Screenshot failed: ' + err.message, 'error');
    } finally {
        if (btn) btn.disabled = false;
    }
}

function showScreenshotPreview(dataUrl, title, cssWidth, cssHeight) {
    var panel = document.getElementById('screenshot-preview-panel');
    var img = document.getElementById('screenshot-preview-img');
    var titleEl = document.getElementById('screenshot-preview-title');
    var mainArea = document.getElementById('main-area');
    img.src = dataUrl;
    if (cssWidth && cssHeight) {
        img.style.width = cssWidth + 'px';
        img.style.height = cssHeight + 'px';
    } else {
        img.style.width = '';
        img.style.height = '';
    }
    titleEl.textContent = title;
    // Hide main chat area and show screenshot panel in its place
    if (mainArea) mainArea.style.display = 'none';
    panel.classList.add('visible');
    document.addEventListener('keydown', screenshotEscHandler);
}

function closeScreenshotPreview() {
    var panel = document.getElementById('screenshot-preview-panel');
    var mainArea = document.getElementById('main-area');
    var img = document.getElementById('screenshot-preview-img');
    panel.classList.remove('visible');
    // Restore main chat area
    if (mainArea) mainArea.style.display = '';
    document.removeEventListener('keydown', screenshotEscHandler);
    // Clear image src to release memory from large data URL
    if (img) img.src = '';
    _screenshotDataUrl = null;
}

function screenshotEscHandler(e) {
    if (e.key === 'Escape') closeScreenshotPreview();
}

function downloadScreenshotPreview() {
    if (!_screenshotDataUrl) return;
    var link = document.createElement('a');
    link.href = _screenshotDataUrl;
    link.download = 'screenshot-' + Date.now() + '.png';
    link.click();
}

// Chat overlay functions for fullscreen mode
function toggleChatOverlay() {
    chatOverlayMinimized = !chatOverlayMinimized;
    var overlay = document.getElementById('chat-overlay');
    if (chatOverlayMinimized) {
        overlay.classList.add('minimized');
    } else {
        overlay.classList.remove('minimized');
        renderOverlayMessages();
    }
}

function showChatOverlay() {
    var overlay = document.getElementById('chat-overlay');
    overlay.classList.add('visible');
    renderOverlayMessages();
}

function hideChatOverlay() {
    var overlay = document.getElementById('chat-overlay');
    overlay.classList.remove('visible');
}

function renderOverlayMessages() {
    var container = document.getElementById('overlay-messages');
    var chat = chats[currentChatId];
    var inputArea = document.getElementById('overlay-input-area');
    var overlayTitle = document.querySelector('.chat-overlay-title');

    // Update overlay title with chat title
    if (overlayTitle && chat) {
        overlayTitle.textContent = chat.title || 'Chat';
    }

    if (!chat || chat.messages.length === 0) {
        container.innerHTML = '<div class="empty-state">Start a conversation</div>';
        inputArea.classList.add('centered');
        return;
    }
    inputArea.classList.remove('centered');

    // Build user message indices for tracking artifacts
    var userMsgIndices = [];
    chat.messages.forEach(function(m, i) { if (m.role === 'user') userMsgIndices.push(i); });

    // Save collapsed state of attachment groups
    var closedOverlayGroups = {};
    container.querySelectorAll('details.attachments-details').forEach(function(d) {
        if (!d.open) closedOverlayGroups[d.dataset.groupIdx] = true;
    });

    var overlayProcessedAttachments = {};
    container.innerHTML = chat.messages.map(function(msg, index) {
        var html = '';

        // Check for attachment grouping (skip hidden messages)
        var isAttachment = isAttachmentRole(msg.role);

        // If this attachment was already rendered as part of a group, return hidden placeholder
        if (isAttachment && overlayProcessedAttachments[index]) {
            return '';
        }

        var prevVisibleMsg = findAdjacentForAttachmentGroup(chat.messages, index, -1);
        var prevIsAttachment = prevVisibleMsg && isAttachmentRole(prevVisibleMsg.role);

        // Render entire attachment group at the first attachment's position
        if (isAttachment && !prevIsAttachment) {
            var groupIndices = [index];
            var j = index + 1;
            while (j < chat.messages.length) {
                if (chat.messages[j].role === 'user') break;
                if (isAttachmentRole(chat.messages[j].role)) groupIndices.push(j);
                j++;
            }
            var attachCount = groupIndices.length;
            var groupLabel = 'Screenshots' + (attachCount > 1 ? ' (' + attachCount + ')' : '');
            var groupOpen = closedOverlayGroups[index] ? '' : ' open';
            html += '<details class="attachments-details" data-group-idx="' + index + '"' + groupOpen + '><summary class="attachments-summary"><span class="screenshot-icon">' + UI_ICONS.eye + '</span> ' + groupLabel + '</summary><div class="attachments-row">';
            for (var gi = 0; gi < groupIndices.length; gi++) {
                html += renderAttachmentContent(chat.messages[groupIndices[gi]], groupIndices[gi]);
                if (gi > 0) overlayProcessedAttachments[groupIndices[gi]] = true;
            }
            html += '</div></details>';
            return html;
        }

        // Determine if this is the last message before next user or end
        var prevUserMsgIdx = -1;
        var isLastBeforeNextUser = false;
        for (var i = 0; i < userMsgIndices.length; i++) {
            if (userMsgIndices[i] <= index) {
                prevUserMsgIdx = userMsgIndices[i];
                var nextUserIdx = userMsgIndices[i + 1] || chat.messages.length;
                if (index === nextUserIdx - 1) {
                    isLastBeforeNextUser = true;
                }
            }
        }

        if (msg.role === 'user') {
            return '<div class="message user"><div class="msg-actions"><button class="edit-msg-btn" onclick="editMessage(' + index + ')" title="Edit and branch">' + UI_ICONS.edit + '</button><button class="copy-msg-btn" onclick="copyMessageText(' + index + ')" title="Copy message">' + UI_ICONS.copy + '</button></div><div class="message-content"><span class="user-text">' + escapeHtml(msg.content) + '</span></div></div>';
        } else if (msg.role === 'assistant') {
            var html = '<div class="message assistant">';
            // Show thinking in overlay too
            if (msg.thinking || msg.isStreaming) {
                var isStreaming = msg.isStreaming === true;
                var hasThinking = msg.thinking && msg.thinking.length > 0;
                var isCollapsed = msg.thinkingCollapsed === true && !isStreaming;
                var openAttr = isCollapsed ? '' : 'open';
                var statusClass = isStreaming ? 'active' : (isCollapsed ? 'collapsed' : '');
                var statusText = isStreaming ? (hasThinking ? 'Thinking...' : 'Processing...') : (isCollapsed ? 'Thought process' : 'Thought process');
                var thinkingContent = hasThinking ? escapeHtml(msg.thinking) : '';
                html += '<details class="thinking ' + statusClass + '" ' + openAttr + '>' +
                    '<summary><span class="thinking-status">' + statusText + '</span>' +
                    (isStreaming ? '<span class="thinking-indicator"></span>' : '') +
                    '</summary>' +
                    '<div class="thinking-content">' + thinkingContent + '</div></details>';
            }
            if (msg.content) html += '<div class="message-content">' + formatContent(msg.content) + '</div>';

            // Show tool calls in overlay
            if (msg.tool_calls) {
                msg.tool_calls.forEach(function(tc, tcIdx) {
                    if (tc.function.name === 'set_chat_title' && !showApiStats) return;
                    var tcKey = 'overlay-tc-' + index + '-' + tcIdx;
                    html += '<details class="tool-call" id="' + tcKey + '">';
                    html += '<summary><span class="tool-name">' + getToolIcon(tc.function.name) + ' ' + (TOOL_DISPLAY_NAMES[tc.function.name] || tc.function.name) + '</span></summary>';
                    var overlayCopyId = storeRawCopy(tc.function.arguments);
                    html += '<div class="tool-args-wrapper" data-copy-id="' + overlayCopyId + '">';
                    html += '<button class="tool-expand-btn" onclick="toggleToolExpand(this, event)" title="Expand">⤢</button>';
                    html += '<pre class="tool-args">' + formatJsonPretty(tc.function.arguments) + '</pre>';
                    html += '<button class="tool-copy-btn" onclick="copyCodeBlock(this, event)" title="Copy">' + UI_ICONS.copy + '</button></div>';
                    html += '</details>';
                });
            }

            // Add metrics display if available and setting enabled
            if (msg.metrics && showApiStats) {
                html += formatMetrics(msg.metrics);
            }

            // Add inline changes (artifacts) if this is the last message before next user message
            if (isLastBeforeNextUser && prevUserMsgIdx >= 0) {
                html += renderInlineChanges(prevUserMsgIdx);
                html += '<div class="assistant-actions visible"><button class="copy-ai-btn" onclick="copyAiMessage(' + prevUserMsgIdx + ')">' + UI_ICONS.copy + ' Copy Answer</button></div>';
            }

            html += '</div>';
            return html;
        } else if (msg.role === 'tool') {
            // Show tool results in overlay
            if (msg.name === 'set_chat_title' && !showApiStats) {
                return '';
            }
            var content = typeof msg.content === 'string' ? formatJsonPretty(msg.content) : formatJsonValue(msg.content, 0);
            var rawContent = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content, null, 2);
            var overlayResultCopyId = storeRawCopy(rawContent);
            var toolResultOpen = msg.expanded === true;
            var toolHtml = '<div class="message tool"><details class="tool-result" onclick="toggleToolResultExpanded(' + index + ', this)"' + (toolResultOpen ? ' open' : '') + '>' +
                '<summary><span class="tool-label">' + getToolIcon(msg.name) + ' ' + (TOOL_DISPLAY_NAMES[msg.name] || msg.name) + ' result</span></summary>' +
                '<div class="tool-result-wrapper" data-copy-id="' + overlayResultCopyId + '">' +
                '<button class="tool-result-expand-btn" onclick="toggleToolExpand(this, event)" title="Expand">⤢</button>' +
                '<pre>' + content + '</pre>' +
                '<button class="tool-copy-btn" onclick="copyCodeBlock(this, event)" title="Copy">' + UI_ICONS.copy + '</button></div>' +
            '</details>';

            // Add inline changes if this is the last message before next user message
            if (isLastBeforeNextUser && prevUserMsgIdx >= 0) {
                toolHtml += renderInlineChanges(prevUserMsgIdx);
            }

            toolHtml += '</div>';
            return toolHtml;
        }
        return '';
    }).join('');

    scrollToBottomIfAllowed(container);
}

// Screenshot navigation state
var screenshotNav = { list: [], index: -1 };

function getScreenshotList() {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return [];
    var list = [];
    chat.messages.forEach(function(msg) {
        if (msg.role === 'screenshot') list.push(msg);
    });
    return list;
}

function navigateScreenshot(delta) {
    var newIndex = screenshotNav.index + delta;
    if (newIndex < 0 || newIndex >= screenshotNav.list.length) return;
    var s = screenshotNav.list[newIndex];
    screenshotNav.index = newIndex;
    var body = document.getElementById('modal-body');
    var header = document.getElementById('modal-header');
    var titleText = escapeHtml(s.name || s.description || 'Screenshot');
    var sizeText = (s.width && s.height) ? ' <span class="screenshot-modal-size">' + s.width + ' × ' + s.height + 'px</span>' : '';
    var url = s.url || '';
    var urlBtn = url ? '<button class="modal-close-icon" onclick="window.open(\'' + escapeHtml(url).replace(/'/g, "\\'") + '\', \'_blank\')" title="Open URL">' + UI_ICONS.externalLink + '</button>' : '';
    var counterText = '<span class="screenshot-modal-counter">' + (newIndex + 1) + ' / ' + screenshotNav.list.length + '</span>';
    header.innerHTML = '<div class="screenshot-modal-title">' + titleText + sizeText + counterText + '</div><div class="modal-header-actions">' + urlBtn + '<button class="modal-close-icon" onclick="downloadScreenshot()" title="Download">' + UI_ICONS.download + '</button><button class="modal-close-icon" onclick="closeModal()" title="Close">' + UI_ICONS.close + '</button></div>';
    body.querySelector('img').src = s.base64;
    body.querySelector('img').dataset.fullSrc = s.base64;
    updateNavArrows();
}

function updateNavArrows() {
    var prevBtn = document.querySelector('.screenshot-nav-prev');
    var nextBtn = document.querySelector('.screenshot-nav-next');
    if (prevBtn) prevBtn.style.display = screenshotNav.index > 0 ? '' : 'none';
    if (nextBtn) nextBtn.style.display = screenshotNav.index < screenshotNav.list.length - 1 ? '' : 'none';
}

function screenshotModalKeyHandler(e) {
    var overlay = document.getElementById('modal-overlay');
    if (!overlay.classList.contains('screenshot-modal') || !overlay.classList.contains('show')) return;
    if (e.key === 'ArrowRight') { e.preventDefault(); navigateScreenshot(1); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); navigateScreenshot(-1); }
}

// Open screenshot in modal for full view
function openScreenshotModal(src, title, width, height, url) {
    var overlay = document.getElementById('modal-overlay');
    var header = document.getElementById('modal-header');
    var body = document.getElementById('modal-body');
    var actions = document.getElementById('modal-actions');

    overlay.classList.add('screenshot-modal');

    // Build navigation state
    screenshotNav.list = getScreenshotList();
    screenshotNav.index = -1;
    for (var i = 0; i < screenshotNav.list.length; i++) {
        if (screenshotNav.list[i].base64 === src) { screenshotNav.index = i; break; }
    }
    var hasNav = screenshotNav.list.length > 1 && screenshotNav.index >= 0;

    var titleText = escapeHtml(title || 'Screenshot');
    var sizeText = (width && height) ? ' <span class="screenshot-modal-size">' + width + ' × ' + height + 'px</span>' : '';
    var counterText = hasNav ? '<span class="screenshot-modal-counter">' + (screenshotNav.index + 1) + ' / ' + screenshotNav.list.length + '</span>' : '';
    var urlBtn = url ? '<button class="modal-close-icon" onclick="window.open(\'' + escapeHtml(url).replace(/'/g, "\\'") + '\', \'_blank\')" title="Open URL">' + UI_ICONS.externalLink + '</button>' : '';

    header.innerHTML = '<div class="screenshot-modal-title">' + titleText + sizeText + counterText + '</div><div class="modal-header-actions">' + urlBtn + '<button class="modal-close-icon" onclick="downloadScreenshot()" title="Download">' + UI_ICONS.download + '</button><button class="modal-close-icon" onclick="closeModal()" title="Close">' + UI_ICONS.close + '</button></div>';

    var navPrev = hasNav ? '<button class="screenshot-nav-prev" onclick="event.stopPropagation();navigateScreenshot(-1)" title="Previous (Left Arrow)"' + (screenshotNav.index <= 0 ? ' style="display:none"' : '') + '>' + UI_ICONS.chevronLeft + '</button>' : '';
    var navNext = hasNav ? '<button class="screenshot-nav-next" onclick="event.stopPropagation();navigateScreenshot(1)" title="Next (Right Arrow)"' + (screenshotNav.index >= screenshotNav.list.length - 1 ? ' style="display:none"' : '') + '>' + UI_ICONS.chevronRight + '</button>' : '';

    body.innerHTML = navPrev + '<img src="' + src + '" />' + navNext;
    actions.innerHTML = '';

    // Store full src for download
    body.querySelector('img').dataset.fullSrc = src;

    // Attach keyboard navigation
    document.addEventListener('keydown', screenshotModalKeyHandler);

    overlay.classList.add('show');
}

function downloadScreenshot() {
    var img = document.querySelector('#modal-body img');
    if (!img || !img.dataset.fullSrc) return;

    var link = document.createElement('a');
    link.href = img.dataset.fullSrc;
    link.download = 'screenshot-' + Date.now() + '.png';
    link.click();
}

function downloadScreenshotFromSidebar(screenshotIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return;

    var screenshots = [];
    chat.messages.forEach(function(msg) {
        if (msg.role === 'screenshot') screenshots.push(msg);
    });

    var screenshot = screenshots[parseInt(screenshotIndex)];
    if (!screenshot || !screenshot.base64) return;

    var link = document.createElement('a');
    link.href = screenshot.base64;
    var filename = (screenshot.name || screenshot.description || 'screenshot').replace(/[^a-zA-Z0-9_-]/g, '_');
    link.download = filename + '-' + Date.now() + '.png';
    link.click();
}

function downloadPdfFromSidebar(pdfIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return;

    var pdfs = [];
    chat.messages.forEach(function(msg) {
        if (msg.role === 'pdf') pdfs.push(msg);
    });

    var pdf = pdfs[parseInt(pdfIndex)];
    if (!pdf || !pdf.base64) return;

    var link = document.createElement('a');
    link.href = pdf.base64;
    var filename = (pdf.name || pdf.description || 'document').replace(/[^a-zA-Z0-9_.-]/g, '_');
    if (!filename.endsWith('.pdf')) filename += '.pdf';
    link.download = filename;
    link.click();
}

function downloadFileFromSidebar(fileIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return;

    var files = [];
    chat.messages.forEach(function(msg) {
        if (msg.role === 'file') files.push(msg);
    });

    var file = files[parseInt(fileIndex)];
    if (!file || !file.content) return;

    var blob = new Blob([file.content], { type: file.mimeType || 'text/plain' });
    var url = URL.createObjectURL(blob);
    var link = document.createElement('a');
    link.href = url;
    link.download = file.name || 'file.txt';
    link.click();
    URL.revokeObjectURL(url);
}

function handleOverlayKeyDown(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendOverlayMessage();
    }
}

async function sendOverlayMessage() {
    var input = document.getElementById('overlay-message-input');
    var message = input.value.trim();
    if (!message || isRunning) return;

    // Use the main sendMessage logic but sync the input
    document.getElementById('message-input').value = message;
    input.value = '';
    input.style.height = 'auto';
    await sendMessage();
    renderOverlayMessages();
}

// Single iframe management
var browserIframe = null;

function ensureIframeExists() {
    if (browserIframe) return browserIframe;

    var container = document.getElementById('iframe-container');
    if (!container) return null;

    var iframe = document.createElement('iframe');
    iframe.id = 'browser-iframe';
    iframe.name = 'browser-iframe';
    iframe.sandbox = 'allow-same-origin allow-scripts allow-forms';
    iframe.style.width = '100%';
    iframe.style.height = '100%';
    iframe.style.border = 'none';
    iframe.style.background = '#fff';

    container.appendChild(iframe);

    iframe.onload = function() {
        updateIframeUrl();
        setupIframeInterceptors(iframe, currentIframeUrl);
    };

    browserIframe = iframe;
    return iframe;
}

function updateIframeUrl() {
    try {
        var iframe = browserIframe;
        if (!iframe) return;
        var newUrl = iframe.contentWindow.location.href;
        // Convert absolute URL to relative path
        if (newUrl.startsWith(window.location.origin)) {
            newUrl = newUrl.substring(window.location.origin.length);
        }
        if (currentIframeUrl !== newUrl) {
            currentIframeUrl = newUrl;
            appStorage.setItem('browserUrl', newUrl);
            var headerUrlEl = document.getElementById('iframe-header-url');
            var browserUrlEl = document.getElementById('browser-url-input');
            if (headerUrlEl) headerUrlEl.value = newUrl;
            if (browserUrlEl) browserUrlEl.value = newUrl;
            logToDevtools('Navigation: ' + newUrl, 'log');
            // Clear screenshot caches on URL change to prevent memory leaks
            _htiResCache = {};
            _screenshotDataUrl = null;
        }
    } catch(e) {
        // Cross-origin - can't access URL
    }
}

function getActiveIframe() {
    return browserIframe;
}

function getWidgetIframe(widgetId) {
    // Find widget iframe by widget_id - check iframe panel, chat messages, and dashboard

    // Check if widget is deactivated
    var widget = getWidgetById(widgetId);
    if (!widget && dashboardWidgets[widgetId]) widget = dashboardWidgets[widgetId];
    if (widget && widget.deactivated) return null;

    // First check if widget is open in iframe panel
    if (iframePanelWidgetId === widgetId && browserIframe) {
        return browserIframe;
    }

    // Try inline widget in chat
    var inlineWidget = document.querySelector('.widget-inline[data-widget-id="' + widgetId + '"] iframe.widget-iframe');
    if (inlineWidget) return inlineWidget;

    // Try dashboard widget
    var dashboardWidget = document.querySelector('.dashboard-widget[data-widget-id="' + widgetId + '"]');
    if (dashboardWidget) {
        // Dashboard widgets use shadow DOM
        var shadowHost = dashboardWidget.querySelector('.widget-shadow-host');
        if (shadowHost && shadowHost.shadowRoot) {
            var iframe = shadowHost.shadowRoot.querySelector('iframe');
            if (iframe) return iframe;
        }
        // Fallback: direct iframe
        var directIframe = dashboardWidget.querySelector('iframe');
        if (directIframe) return directIframe;
    }

    return null;
}

function navigateIframe(url) {
    // Reset widget mode if active
    if (iframePanelWidgetId) {
        iframePanelWidgetId = null;
        setIframePanelMode('browser');
    }

    var iframe = ensureIframeExists();
    if (!iframe) return;

    currentIframeUrl = url;
    appStorage.setItem('browserUrl', url);
    var headerUrl = document.getElementById('iframe-header-url');
    var browserUrl = document.getElementById('browser-url-input');
    if (headerUrl) headerUrl.value = url;
    if (browserUrl) browserUrl.value = url;
    logToDevtools('Navigating to: ' + url, 'log');

    // Use fetch + script injection to capture errors from the very beginning
    navigateWithErrorCapture(iframe, url);
}

function navigateWithErrorCapture(iframe, url) {
    // Simple direct navigation - error capture happens via setupIframeInterceptors after load
    iframe.onload = function() {
        updateIframeUrl();
        setupIframeInterceptors(iframe, url);
        // Clear screenshot caches on page navigation to prevent memory leaks
        _htiFontCache = null;
        _htiResCache = {};
        _screenshotDataUrl = null;
        setTimeout(function() {
            try {
                var doc = iframe.contentDocument;
                if (!doc) return;
                // Collect all reachable documents by traversing shadow roots and iframes
                var docs = [];
                function collectDocs(root) {
                    if (!root) return;
                    if (root.documentElement) docs.push(root);
                    var allEls = root.querySelectorAll ? root.querySelectorAll('*') : [];
                    for (var i = 0; i < allEls.length; i++) {
                        if (allEls[i].shadowRoot) collectDocs(allEls[i].shadowRoot);
                        if (allEls[i].tagName === 'IFRAME') {
                            try {
                                var subDoc = allEls[i].contentDocument;
                                if (subDoc) collectDocs(subDoc);
                            } catch (e) {}
                        }
                    }
                }
                collectDocs(doc);
                console.log('[font-cache] found ' + docs.length + ' documents to collect fonts from');
                var fontsReady = docs.map(function(d) { return d.fonts ? d.fonts.ready : Promise.resolve(); });
                Promise.all(fontsReady).then(function() {
                    var cssPromises = docs.map(function(d) {
                        return collectFontCSS(d.documentElement).catch(function() { return ''; });
                    });
                    Promise.all(cssPromises).then(function(results) {
                        _htiFontCache = results.filter(Boolean).join('\n');
                        console.log('[font-cache] fonts pre-cached (' + _htiFontCache.length + ' bytes from ' + results.filter(Boolean).length + ' sources)');
                    }).catch(function() { _htiFontCache = ''; });
                }).catch(function() {});
            } catch (e) { console.error('[font-cache] error:', e); }
        }, 2000);
    };
    iframe.src = url;
}

// Error capture script for early error detection (used when earlyErrorCapture is enabled)
var earlyErrorCaptureScript = '<scr' + 'ipt>(function(){' +
    'window.__earlyErrors=[];window.__earlyLogs=[];' +
    'window.onerror=function(m,f,l,c,e){' +
        'var s=e&&e.stack?e.stack:"";' +
        'window.__earlyErrors.push({type:"error",message:m,file:f,line:l,col:c,stack:s,timestamp:Date.now()});' +
        'return false;' +
    '};' +
    'window.addEventListener("unhandledrejection",function(e){' +
        'var r=e.reason,m=r instanceof Error?r.message:String(r),s=r instanceof Error&&r.stack?r.stack:"";' +
        'window.__earlyErrors.push({type:"rejection",message:m,stack:s,timestamp:Date.now()});' +
    '});' +
    'var oc=window.console;' +
    'window.console={' +
        'log:function(){window.__earlyLogs.push({type:"log",args:Array.from(arguments),timestamp:Date.now()});oc.log.apply(oc,arguments);},' +
        'warn:function(){window.__earlyLogs.push({type:"warn",args:Array.from(arguments),timestamp:Date.now()});oc.warn.apply(oc,arguments);},' +
        'error:function(){window.__earlyLogs.push({type:"error",args:Array.from(arguments),timestamp:Date.now()});oc.error.apply(oc,arguments);},' +
        'info:function(){window.__earlyLogs.push({type:"info",args:Array.from(arguments),timestamp:Date.now()});oc.info.apply(oc,arguments);},' +
        'debug:function(){window.__earlyLogs.push({type:"debug",args:Array.from(arguments),timestamp:Date.now()});oc.debug.apply(oc,arguments);},' +
        'clear:oc.clear.bind(oc),dir:oc.dir.bind(oc),table:oc.table.bind(oc),trace:oc.trace.bind(oc),assert:oc.assert.bind(oc),' +
        'group:oc.group.bind(oc),groupCollapsed:oc.groupCollapsed.bind(oc),groupEnd:oc.groupEnd.bind(oc),' +
        'time:oc.time.bind(oc),timeEnd:oc.timeEnd.bind(oc),count:oc.count.bind(oc)' +
    '};' +
'})()<\/scr' + 'ipt>';

function collectEarlyErrors(iframe) {
    try {
        var win = iframe.contentWindow;
        if (win.__earlyErrors && win.__earlyErrors.length > 0) {
            win.__earlyErrors.forEach(function(err) {
                var msg = err.type === 'error'
                    ? '[Error] ' + err.message + ' at ' + (err.file || '') + ':' + (err.line || 0) + (err.stack ? '\n' + err.stack : '')
                    : '[Unhandled Promise Rejection] ' + err.message + (err.stack ? '\n' + err.stack : '');
                logToDevtools(msg, 'error');
            });
        }
        if (win.__earlyLogs && win.__earlyLogs.length > 0) {
            win.__earlyLogs.forEach(function(log) {
                logToDevtools('[console.' + log.type + '] ' + log.args.join(' '), log.type === 'error' ? 'error' : (log.type === 'warn' ? 'warn' : 'log'));
            });
        }
    } catch(e) { /* Cross-origin access failed */ }
}

// Async version for tool actions that returns via callback
// earlyErrorCapture: if true, uses blob URL injection to capture errors before page load (may break some pages)
function navigateWithErrorCaptureAsync(iframe, url, resolve, earlyErrorCapture) {
    if (!earlyErrorCapture) {
        // Default: simple direct navigation
        iframe.onload = function() {
            setupIframeInterceptors(iframe, url);
            logToDevtools('Page loaded: ' + url, 'log');
            resolve({ success: true, message: 'Navigated to ' + url });
        };
        iframe.onerror = function() {
            resolve({ success: false, error: 'Failed to load page' });
        };
        iframe.src = url;
        return;
    }

    // Early error capture mode: fetch HTML and inject error capture script via blob URL
    // WARNING: This may break some pages (frame-busting, service workers, etc.)
    logToDevtools('Using early error capture mode (may break some pages)', 'warn');
    fetch(url, { credentials: 'include' })
        .then(function(response) {
            if (!response.ok) throw new Error('HTTP ' + response.status);
            var contentType = response.headers.get('content-type') || '';
            if (!contentType.includes('text/html')) {
                // Non-HTML content - load directly
                iframe.onload = function() {
                    logToDevtools('Page loaded: ' + url, 'log');
                    resolve({ success: true, message: 'Navigated to ' + url });
                };
                iframe.onerror = function() { resolve({ success: false, error: 'Failed to load page' }); };
                iframe.src = url;
                return null;
            }
            return response.text();
        })
        .then(function(html) {
            if (html === null) return;

            // Inject error capture script at the beginning of <head>
            var headMatch = html.match(/<head[^>]*>/i);
            var injectedHtml;
            if (headMatch) {
                var insertPos = headMatch.index + headMatch[0].length;
                injectedHtml = html.slice(0, insertPos) + earlyErrorCaptureScript + html.slice(insertPos);
            } else {
                injectedHtml = earlyErrorCaptureScript + html;
            }

            // Set base tag to preserve relative URL resolution
            var baseTag = '<base href="' + new URL(url, window.location.origin).href + '">';
            var baseMatch = injectedHtml.match(/<head[^>]*>/i);
            if (baseMatch) {
                var afterScript = injectedHtml.indexOf('<\/scr' + 'ipt>', baseMatch.index) + 9;
                injectedHtml = injectedHtml.slice(0, afterScript) + baseTag + injectedHtml.slice(afterScript);
            }

            var blob = new Blob([injectedHtml], { type: 'text/html' });
            var blobUrl = URL.createObjectURL(blob);

            iframe.onload = function() {
                URL.revokeObjectURL(blobUrl);
                collectEarlyErrors(iframe);
                setupIframeInterceptors(iframe, url);
                logToDevtools('Page loaded: ' + url, 'log');
                resolve({ success: true, message: 'Navigated to ' + url });
            };
            iframe.onerror = function() {
                URL.revokeObjectURL(blobUrl);
                resolve({ success: false, error: 'Failed to load page' });
            };
            iframe.src = blobUrl;
        })
        .catch(function(err) {
            logToDevtools('Early error capture failed, using direct navigation: ' + err.message, 'warn');
            iframe.onload = function() {
                setupIframeInterceptors(iframe, url);
                logToDevtools('Page loaded: ' + url, 'log');
                resolve({ success: true, message: 'Navigated to ' + url });
            };
            iframe.onerror = function() { resolve({ success: false, error: 'Failed to load page' }); };
            iframe.src = url;
        });
}

// Set up early error and console capture - polls rapidly to catch new documents before scripts run
function setupEarlyErrorCapture(iframe) {
    var lastDoc = null;
    var attempts = 0;

    function tryInstall() {
        if (attempts++ > 200) return; // Stop after 2 seconds

        try {
            var doc = iframe.contentDocument;
            if (doc && doc !== lastDoc) {
                lastDoc = doc;
                var win = iframe.contentWindow;

                // Intercept console methods early
                var origLog = win.console.log;
                var origWarn = win.console.warn;
                var origError = win.console.error;
                win.console.log = function() {
                    logToDevtools('[console.log] ' + Array.from(arguments).join(' '), 'log');
                    origLog.apply(win.console, arguments);
                };
                win.console.warn = function() {
                    logToDevtools('[console.warn] ' + Array.from(arguments).join(' '), 'warn');
                    origWarn.apply(win.console, arguments);
                };
                win.console.error = function() {
                    logToDevtools('[console.error] ' + Array.from(arguments).join(' '), 'error');
                    origError.apply(win.console, arguments);
                };

                // Capture uncaught errors
                win.addEventListener('error', function(e) {
                    var stack = e.error && e.error.stack ? '\n' + e.error.stack : '';
                    logToDevtools('[Error] ' + (e.message || 'Unknown error') + ' at ' + (e.filename || '') + ':' + (e.lineno || 0) + stack, 'error');
                }, true);
                win.addEventListener('unhandledrejection', function(e) {
                    var r = e.reason;
                    var msg = r instanceof Error ? r.message : String(r);
                    var stack = r instanceof Error && r.stack ? '\n' + r.stack : '';
                    logToDevtools('[Unhandled Promise Rejection] ' + msg + stack, 'error');
                }, true);
            }
        } catch (e) { /* cross-origin */ }

        setTimeout(tryInstall, 10); // Fast polling
    }

    tryInstall();
}

function setupIframeInterceptors(iframe, url) {
    try {
        var iframeWindow = iframe.contentWindow;
        var iframeDoc = iframe.contentDocument;

        var originalConsole = {
            log: iframeWindow.console.log,
            warn: iframeWindow.console.warn,
            error: iframeWindow.console.error
        };

        iframeWindow.console.log = function() {
            logToDevtools('[console.log] ' + Array.from(arguments).join(' '), 'log');
            originalConsole.log.apply(iframeWindow.console, arguments);
        };
        iframeWindow.console.warn = function() {
            logToDevtools('[console.warn] ' + Array.from(arguments).join(' '), 'warn');
            originalConsole.warn.apply(iframeWindow.console, arguments);
        };
        iframeWindow.console.error = function() {
            logToDevtools('[console.error] ' + Array.from(arguments).join(' '), 'error');
            originalConsole.error.apply(iframeWindow.console, arguments);
        };

        var originalFetch = iframeWindow.fetch;
        iframeWindow.fetch = function(url, options) {
            var method = (options && options.method) || 'GET';
            var startTime = Date.now();
            logToDevtools('[Fetch] ' + method + ' ' + url, 'network');
            var requestInfo = { type: 'fetch', method: method, url: String(url), timestamp: startTime, status: null, duration: null };
            networkRequests.push(requestInfo);
            return originalFetch.apply(iframeWindow, arguments).then(function(response) {
                var duration = Date.now() - startTime;
                requestInfo.status = response.status;
                requestInfo.duration = duration;
                logToDevtools('[Fetch Response] ' + response.status + ' ' + url + ' (' + duration + 'ms)', 'network');
                return response;
            }).catch(function(err) {
                var duration = Date.now() - startTime;
                requestInfo.status = 'error';
                requestInfo.duration = duration;
                logToDevtools('[Fetch Error] ' + err.message + ' ' + url + ' (' + duration + 'ms)', 'error');
                throw err;
            });
        };

        // Intercept XMLHttpRequest
        var OriginalXHR = iframeWindow.XMLHttpRequest;
        iframeWindow.XMLHttpRequest = function() {
            var xhr = new OriginalXHR();
            var xhrMethod = 'GET';
            var xhrUrl = '';
            var xhrStartTime = null;
            var requestInfo = null;

            var originalOpen = xhr.open;
            xhr.open = function(method, url) {
                xhrMethod = method;
                xhrUrl = url;
                xhrStartTime = Date.now();
                logToDevtools('[XHR] ' + method + ' ' + url, 'network');
                requestInfo = { type: 'xhr', method: method, url: String(url), timestamp: xhrStartTime, status: null, duration: null };
                networkRequests.push(requestInfo);
                return originalOpen.apply(xhr, arguments);
            };

            var originalSend = xhr.send;
            xhr.send = function() {
                xhr.addEventListener('load', function() {
                    var duration = Date.now() - xhrStartTime;
                    if (requestInfo) {
                        requestInfo.status = xhr.status;
                        requestInfo.duration = duration;
                    }
                    logToDevtools('[XHR Response] ' + xhr.status + ' ' + xhrUrl + ' (' + duration + 'ms)', 'network');
                });
                xhr.addEventListener('error', function() {
                    var duration = Date.now() - xhrStartTime;
                    if (requestInfo) {
                        requestInfo.status = 'error';
                        requestInfo.duration = duration;
                    }
                    logToDevtools('[XHR Error] ' + xhrUrl + ' (' + duration + 'ms)', 'error');
                });
                return originalSend.apply(xhr, arguments);
            };

            return xhr;
        };

        // Track SPA-style navigation (pushState/replaceState) and popstate
        var origPushState = iframeWindow.history.pushState;
        var origReplaceState = iframeWindow.history.replaceState;
        iframeWindow.history.pushState = function() {
            origPushState.apply(this, arguments);
            updateIframeUrl();
        };
        iframeWindow.history.replaceState = function() {
            origReplaceState.apply(this, arguments);
            updateIframeUrl();
        };
        iframeWindow.addEventListener('popstate', function() { updateIframeUrl(); });
        // Track hash changes
        iframeWindow.addEventListener('hashchange', function() { updateIframeUrl(); });

        // Apply mobile emulation if mobile mode is active
        if (iframeMobileMode) {
            applyMobileEmulationDeep(iframe, false);
        }

    } catch(e) {
        logToDevtools('Could not inject interceptors (cross-origin): ' + e.message, 'warn');
    }
}

// Iframe navigation functions
function iframeGoBack() {
    var iframe = getActiveIframe();
    if (iframe) {
        try {
            iframe.contentWindow.history.back();
            logToDevtools('Navigated back', 'log');
            setTimeout(updateIframeUrl, 200);
        } catch(e) {
            logToDevtools('Cannot go back: ' + e.message, 'warn');
        }
    }
}

function iframeGoForward() {
    var iframe = getActiveIframe();
    if (iframe) {
        try {
            iframe.contentWindow.history.forward();
            logToDevtools('Navigated forward', 'log');
            setTimeout(updateIframeUrl, 200);
        } catch(e) {
            logToDevtools('Cannot go forward: ' + e.message, 'warn');
        }
    }
}

function iframeReload() {
    // Handle widget mode - reload widget HTML
    if (iframePanelWidgetId) {
        reloadWidgetInPanel();
        logToDevtools('Reloading widget', 'log');
        return;
    }

    var iframe = getActiveIframe();
    if (iframe) {
        try {
            iframe.contentWindow.location.reload();
            logToDevtools('Reloading page', 'log');
        } catch(e) {
            // Fallback: reload using src
            iframe.src = iframe.src;
            logToDevtools('Reloading page (fallback)', 'log');
        }
    }
}

// Get the gsft_main iframe document (ServiceNow main content area)
// Handles both classic UI and modern UI with shadow DOM (macroponents)
function getGsftMainDocument(doc) {
    if (!doc) return null;

    try {
        // First try direct getElementById
        var mainFrame = doc.getElementById('gsft_main');
        if (mainFrame && mainFrame.contentDocument) {
            return getGsftMainDocument(mainFrame.contentDocument) || mainFrame.contentDocument;
        }

        // Try querySelector with name
        var namedFrame = doc.querySelector('iframe[name="gsft_main"]');
        if (namedFrame && namedFrame.contentDocument) {
            return getGsftMainDocument(namedFrame.contentDocument) || namedFrame.contentDocument;
        }

        // Check shadow DOMs (modern ServiceNow UI uses macroponents with shadow DOM)
        var allElements = doc.querySelectorAll('*');
        for (var i = 0; i < allElements.length; i++) {
            var el = allElements[i];
            if (el.shadowRoot) {
                // Search inside shadow root for gsft_main
                var shadowFrame = el.shadowRoot.getElementById('gsft_main');
                if (shadowFrame && shadowFrame.contentDocument) {
                    return getGsftMainDocument(shadowFrame.contentDocument) || shadowFrame.contentDocument;
                }
                // Also try querySelector in shadow root
                shadowFrame = el.shadowRoot.querySelector('iframe[name="gsft_main"]');
                if (shadowFrame && shadowFrame.contentDocument) {
                    return getGsftMainDocument(shadowFrame.contentDocument) || shadowFrame.contentDocument;
                }
            }
        }

        // Check regular iframes as fallback
        var iframes = doc.querySelectorAll('iframe');
        for (var j = 0; j < iframes.length; j++) {
            var iframe = iframes[j];
            if (iframe.id === 'gsft_main' || iframe.name === 'gsft_main') {
                try {
                    if (iframe.contentDocument) {
                        return getGsftMainDocument(iframe.contentDocument) || iframe.contentDocument;
                    }
                } catch(e) {
                    // Cross-origin, skip
                }
            }
        }
    } catch(e) {
        // Error accessing document
    }

    return null;
}

// Recursively search same-origin iframes and shadow DOMs for first matching element
function pierceIframes(doc, selector) {
    try {
        var el = doc.querySelector(selector);
        if (el) return el;
        var iframes = doc.querySelectorAll('iframe');
        for (var i = 0; i < iframes.length; i++) {
            try {
                if (iframes[i].contentDocument) {
                    el = pierceIframes(iframes[i].contentDocument, selector);
                    if (el) return el;
                }
            } catch(e) {}
        }
        var allEls = doc.querySelectorAll('*');
        for (var j = 0; j < allEls.length; j++) {
            if (allEls[j].shadowRoot) {
                el = pierceIframes(allEls[j].shadowRoot, selector);
                if (el) return el;
            }
        }
    } catch(e) {}
    return null;
}

// Recursively search same-origin iframes and shadow DOMs for all matching elements
function pierceIframesAll(doc, selector) {
    var results = [];
    try {
        var els = doc.querySelectorAll(selector);
        for (var i = 0; i < els.length; i++) results.push(els[i]);
        var iframes = doc.querySelectorAll('iframe');
        for (var i = 0; i < iframes.length; i++) {
            try {
                if (iframes[i].contentDocument) {
                    results = results.concat(pierceIframesAll(iframes[i].contentDocument, selector));
                }
            } catch(e) {}
        }
        var allEls = doc.querySelectorAll('*');
        for (var j = 0; j < allEls.length; j++) {
            if (allEls[j].shadowRoot) {
                results = results.concat(pierceIframesAll(allEls[j].shadowRoot, selector));
            }
        }
    } catch(e) {}
    return results;
}

// Find the largest scrollable container in a document (fallback when window.scrollTo doesn't work)
// Recursively searches shadow DOMs for ServiceNow Next Experience/Polaris pages
function findScrollContainer(doc) {
    var win = doc.defaultView;
    if (!win) return null;
    var se = doc.scrollingElement;
    if (se && se.scrollHeight > se.clientHeight + 1) return se;
    var best = null;
    var bestArea = 0;
    function searchNode(root) {
        var allEls = root.querySelectorAll('*');
        for (var i = 0; i < allEls.length; i++) {
            var el = allEls[i];
            if (el.scrollHeight <= el.clientHeight + 1) continue; // not scrollable
            try {
                var cs = (el.ownerDocument.defaultView || win).getComputedStyle(el);
                var ov = (cs.overflow || '') + (cs.overflowY || '');
                if (ov.indexOf('auto') !== -1 || ov.indexOf('scroll') !== -1) {
                    var area = el.clientWidth * el.clientHeight;
                    if (area > bestArea) {
                        bestArea = area;
                        best = el;
                    }
                }
            } catch(e) {}
            if (el.shadowRoot) {
                searchNode(el.shadowRoot);
            }
        }
    }
    searchNode(doc);
    return best;
}

function getCurrentIframeUrl() {
    return currentIframeUrl;
}

function logToDevtools(message, type) {
    var devtools = document.getElementById('iframe-devtools');
    var typeClass = type === 'error' ? 'console-error' : (type === 'warn' ? 'console-warn' : (type === 'network' ? 'network-req' : 'console-log'));
    var entry = document.createElement('div');
    entry.className = typeClass;
    entry.textContent = '[' + new Date().toLocaleTimeString() + '] ' + message;
    devtools.appendChild(entry);
    devtools.scrollTop = devtools.scrollHeight;

    iframeLogs.push({ type: type, message: message, timestamp: Date.now() });
}

function clearDevtools() {
    document.getElementById('iframe-devtools').innerHTML = '';
    iframeLogs = [];
    networkRequests = [];
}

async function executeIframeTool(args) {
    var action = args.action;
    var widgetId = args.widget_id;

    // Validate required action parameter
    if (!action) {
        return { success: false, error: 'Missing required parameter "action". Valid actions: navigate, get_visible_text, get_dom, click, fill, get_console_logs, get_network_requests, close' };
    }

    // Helper to get the target iframe (widget or browser)
    function getTargetIframe() {
        if (widgetId) {
            var _tgtWidget = getWidgetById(widgetId);
            if (!_tgtWidget && dashboardWidgets[widgetId]) _tgtWidget = dashboardWidgets[widgetId];
            if (_tgtWidget && _tgtWidget.deactivated) {
                return { error: 'Widget "' + (_tgtWidget.title || widgetId) + '" is deactivated. The user has deactivated this widget. Ask the user to activate it first, or proceed differently.' };
            }
            var widgetIframe = getWidgetIframe(widgetId);
            if (!widgetIframe) {
                return { error: 'Widget not found: ' + widgetId + '. Make sure the widget is visible in the chat or dashboard.' };
            }
            return { iframe: widgetIframe, isWidget: true };
        }
        var browserIframe = getActiveIframe();
        if (!browserIframe) {
            return { error: 'No active iframe. Use navigate action first to open a page.' };
        }
        return { iframe: browserIframe, isWidget: false };
    }

    try {
        switch(action) {
            case 'navigate':
                if (widgetId) {
                    return { success: false, error: 'Navigate action is not supported for widgets. Widgets are self-contained HTML - modify the widget HTML instead.' };
                }
                if (!args.url) return { success: false, error: 'URL is required for navigate action' };
                openIframePanel();
                clearDevtools();

                var iframe = ensureIframeExists();
                currentIframeUrl = args.url;
                document.getElementById('iframe-header-url').value = args.url;
                document.getElementById('browser-url-input').value = args.url;

                return new Promise(function(resolve) {
                    navigateWithErrorCaptureAsync(iframe, args.url, resolve, args.early_error_capture);
                });

            case 'get_visible_text':
                try {
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var iframe = target.iframe;
                    var doc = iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content (cross-origin)' };
                    // Get gsft_main iframe content if it exists
                    doc = getGsftMainDocument(doc) || doc;

                    var visible = [];
                    var scanElements = function(root) {
                        if (!root) return;

                        var processed = new Set();
                        // Tags to skip entirely (like screen readers)
                        var hiddenTags = ['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'META', 'LINK', 'HEAD'];

                        var isVisibleToScreenReader = function(el) {
                            if (!el || el.nodeType !== 1) return true;
                            // Skip hidden tags
                            if (hiddenTags.indexOf(el.tagName) !== -1) return false;
                            // Check aria-hidden
                            if (el.getAttribute('aria-hidden') === 'true') return false;
                            // Check CSS visibility
                            var style = window.getComputedStyle(el);
                            if (style.display === 'none') return false;
                            if (style.visibility === 'hidden') return false;
                            if (style.opacity === '0') return false;
                            // Check if element is in viewport with actual size
                            var rect = el.getBoundingClientRect();
                            if (rect.width === 0 && rect.height === 0) return false;
                            return true;
                        };

                        var walk = function(node) {
                            if (!node) return;

                            // Handle Document (9), Element (1), or DocumentFragment/ShadowRoot (11)
                            if (node.nodeType !== 1 && node.nodeType !== 9 && node.nodeType !== 11) return;

                            if (processed.has(node)) return;
                            processed.add(node);

                            // Skip hidden elements and their children (like screen readers)
                            if (node.nodeType === 1 && !isVisibleToScreenReader(node)) return;

                            var rect = (node.nodeType === 1) ? node.getBoundingClientRect() : null;

                            if (node.nodeType === 1) {
                                var isInteractive = ['INPUT', 'SELECT', 'TEXTAREA', 'BUTTON', 'A'].indexOf(node.tagName) !== -1;
                                var isMedia = node.tagName === 'IMG' || node.tagName === 'VIDEO' || node.tagName === 'SVG';
                                var isHeading = ['H1', 'H2', 'H3', 'H4', 'H5', 'H6'].indexOf(node.tagName) !== -1;
                                var isLabel = node.tagName === 'LABEL' || node.tagName === 'LEGEND';

                                // Detect direct text content (only text nodes, not nested elements)
                                var directText = "";
                                for (var i = 0; i < node.childNodes.length; i++) {
                                    if (node.childNodes[i].nodeType === 3) {
                                        directText += node.childNodes[i].textContent.trim();
                                    }
                                }

                                // Capture if it has direct text OR is a specific interactive/media type
                                if (directText.length > 0 || isInteractive || isMedia || isHeading || isLabel) {
                                    // For inputs, get value; for others get only direct text to avoid duplication
                                    var textValue = "";
                                    if (node.tagName === 'INPUT') {
                                        textValue = node.value || node.placeholder || "";
                                    } else if (node.tagName === 'TEXTAREA') {
                                        textValue = node.value || "";
                                    } else if (node.tagName === 'IMG') {
                                        textValue = node.alt || node.title || "";
                                    } else {
                                        textValue = directText;
                                    }

                                    if (textValue.trim().length > 0 || isInteractive) {
                                        // Determine semantic role for AI readability
                                        var role = node.getAttribute('role') || '';
                                        var ariaLabel = node.getAttribute('aria-label') || '';
                                        var type = isHeading ? 'heading' : isInteractive ? (node.tagName === 'A' ? 'link' : node.tagName === 'BUTTON' ? 'button' : 'input') : isMedia ? 'media' : isLabel ? 'label' : 'text';

                                        // Find associated label for form fields
                                        var fieldLabel = '';
                                        if (node.id && (node.tagName === 'INPUT' || node.tagName === 'SELECT' || node.tagName === 'TEXTAREA')) {
                                            var labelEl = root.querySelector ? root.querySelector('label[for=\"' + node.id + '\"]') : null;
                                            if (labelEl) fieldLabel = labelEl.textContent.trim();
                                        }

                                        // Build element data based on deep flag
                                        var elemData;
                                        if (args.deep) {
                                            elemData = {
                                                tag: node.tagName.toLowerCase(),
                                                type: type,
                                                text: textValue.trim().substring(0, 500),
                                                id: node.id || null,
                                                fieldLabel: fieldLabel || null,
                                                ariaLabel: ariaLabel || null,
                                                role: role || null,
                                                inputType: node.type || null,
                                                selector: node.id ? '#' + node.id : (node.className && typeof node.className === 'string' ? '.' + node.className.split(' ')[0] : node.tagName.toLowerCase()),
                                                rect: rect ? { 
                                                    x: Math.round(rect.x), 
                                                    y: Math.round(rect.y), 
                                                    w: Math.round(rect.width), 
                                                    h: Math.round(rect.height) 
                                                } : null
                                            };
                                        } else {
                                            // Simplified output: only text
                                            elemData = {
                                                tag: node.tagName.toLowerCase(),
                                                type: type,
                                                text: textValue.trim().substring(0, 500)
                                            };
                                        }
                                        visible.push(elemData);
                                    }
                                }
                            }

                            // Recurse into children
                            var children = node.children || [];
                            for (var j = 0; j < children.length; j++) {
                                walk(children[j]);
                            }

                            // Recurse into Shadow DOM
                            if (node.shadowRoot) {
                                walk(node.shadowRoot);
                            }

                            // Recurse into iframes (if accessible)
                            if (node.tagName === 'IFRAME') {
                                try {
                                    if (node.contentDocument) {
                                        walk(node.contentDocument);
                                    }
                                } catch(e) {
                                    // Cross-origin, ignore
                                }
                            }
                        };

                        walk(root);
                    };

                    scanElements(doc);

                    // Limit to 1000 elements to ensure we capture enough detail on complex forms
                    return { 
                        success: true, 
                        visibleElements: visible.slice(0, 1000), 
                        note: 'Returning visible elements (including shadow DOM content) for analysis.' 
                    };
                } catch(e) {
                    return { success: false, error: 'Get visible text failed: ' + e.message };
                }

            case 'get_dom':
                try {
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var iframe = target.iframe;
                    var doc = iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content (cross-origin)' };

                    // For browser iframe, get gsft_main content if it exists (ServiceNow main content)
                    var targetDoc = target.isWidget ? doc : (getGsftMainDocument(doc) || doc);
                    var iframeInfo = target.isWidget ? ' (from widget)' : (targetDoc !== doc ? ' (from gsft_main iframe)' : '');

                    var html = targetDoc.documentElement.outerHTML;
                    if (html.length > 50000) {
                        html = html.substring(0, 50000) + '\n... [truncated, total: ' + html.length + ' chars]';
                    }

                    return { success: true, html: html, note: 'DOM retrieved' + iframeInfo };
                } catch(e) {
                    return { success: false, error: 'Get DOM failed: ' + e.message };
                }

            case 'click':
                if (!args.selector) return { success: false, error: 'Selector is required for click action' };
                try {
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var iframe = target.iframe;
                    var doc = iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content (cross-origin)' };
                    // For browser iframe, get gsft_main content if it exists
                    doc = target.isWidget ? doc : (getGsftMainDocument(doc) || doc);
                    var el = doc.querySelector(args.selector);
                    if (!el) return { success: false, error: 'Element not found: ' + args.selector };
                    el.click();
                    logToDevtools('[Click] ' + args.selector + (target.isWidget ? ' (widget)' : ''), 'log');
                    return { success: true, message: 'Clicked element: ' + args.selector + (target.isWidget ? ' in widget' : '') };
                } catch(e) {
                    return { success: false, error: 'Click failed: ' + e.message };
                }

            case 'fill':
                if (!args.selector) return { success: false, error: 'Selector is required for fill action' };
                if (args.value === undefined) return { success: false, error: 'Value is required for fill action' };
                try {
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var iframe = target.iframe;
                    var doc = iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content (cross-origin)' };
                    // For browser iframe, get gsft_main content if it exists
                    doc = target.isWidget ? doc : (getGsftMainDocument(doc) || doc);
                    var el = doc.querySelector(args.selector);
                    if (!el) return { success: false, error: 'Element not found: ' + args.selector };
                    el.value = args.value;
                    el.dispatchEvent(new Event('input', { bubbles: true }));
                    el.dispatchEvent(new Event('change', { bubbles: true }));
                    logToDevtools('[Fill] ' + args.selector + ' = ' + args.value + (target.isWidget ? ' (widget)' : ''), 'log');
                    return { success: true, message: 'Filled element: ' + args.selector + ' with value' + (target.isWidget ? ' in widget' : '') };
                } catch(e) {
                    return { success: false, error: 'Fill failed: ' + e.message };
                }

            case 'get_console_logs':
                return { success: true, logs: iframeLogs.filter(function(l) { return l.type !== 'network'; }) };

            case 'get_network_requests':
                return { success: true, requests: networkRequests };

            case 'close':
                if (widgetId) {
                    return { success: false, error: 'Close action is not supported for widgets. Widgets are embedded in chat messages.' };
                }
                closeIframePanel();
                return { success: true, message: 'Iframe panel closed' };

            case 'open_widget':
                if (!widgetId) return { success: false, error: 'widget_id is required for open_widget action' };
                var widget = getWidgetById(widgetId);
                if (!widget) return { success: false, error: 'Widget not found: ' + widgetId };
                var opened = openWidgetInIframePanel(widgetId, false);
                if (!opened) return { success: false, error: 'Failed to open widget in panel' };
                return { 
                    success: true, 
                    message: 'Widget "' + widget.title + '" opened in panel. You can now use get_visible_text, get_dom, click, fill, or edit_html actions with widget_id="' + widgetId + '".'
                };

            case 'edit_html':
                if (!widgetId) return { success: false, error: 'widget_id is required for edit_html action' };
                if (!args.edits || !Array.isArray(args.edits)) return { success: false, error: 'edits array is required for edit_html action. Format: [{ find: "old text", replace: "new text" }]' };
                var widget = getWidgetById(widgetId);
                if (!widget) return { success: false, error: 'Widget not found: ' + widgetId };

                var editResult = applySearchReplaceEdits(widget.html, args.edits);
                if (editResult.error) {
                    return { success: false, error: 'Edit failed', validationErrors: editResult.messages };
                }

                // Update widget HTML
                widget.html = editResult.content;

                // Persist changes
                var chat = chats[widget.chatId || currentChatId];
                if (chat && chat.widgets) {
                    var idx = chat.widgets.findIndex(function(w) { return w.id === widgetId; });
                    if (idx !== -1) chat.widgets[idx].html = widget.html;
                    saveChatsToStorage();
                }

                // Refresh widget display if open in panel
                if (iframePanelWidgetId === widgetId) {
                    reloadWidgetInPanel();
                }

                // Refresh inline widget if visible
                var inlineContainer = document.getElementById('widget-content-' + widgetId);
                if (inlineContainer) {
                    inlineContainer.innerHTML = '';
                    renderWidgetInContainer(widget, inlineContainer);
                }

                var result = { success: true, message: 'Widget HTML updated', appliedEdits: editResult.appliedEdits.length };
                if (editResult.partialSuccess) {
                    result.warning = 'Some edits failed';
                    result.failedEdits = editResult.failedEdits;
                }
                return result;

            // Hidden actions (not in tool schema - used by skill tools via executeTool)
            case 'scroll':
                try {
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var doc = target.iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content' };

                    var beh = args.behavior || 'instant';

                    if (args.selector) {
                        var el = target.isWidget ? doc.querySelector(args.selector) : pierceIframes(doc, args.selector);
                        if (!el) return { success: false, error: 'Element not found: ' + args.selector };
                        el.scrollIntoView({ block: 'start', behavior: beh });
                        return { success: true };
                    }

                    var st = null;
                    if (!target.isWidget) {
                        (function searchAll(d) {
                            try {
                                var c = findScrollContainer(d);
                                if (c && (!st || c.scrollHeight > st.scrollHeight)) st = c;
                                var iframes = d.querySelectorAll('iframe');
                                for (var i = 0; i < iframes.length; i++) {
                                    try { if (iframes[i].contentDocument) searchAll(iframes[i].contentDocument); } catch(e) {}
                                }
                                // Also recurse shadow DOMs (ServiceNow Next Experience/Polaris uses web components)
                                var allEls = d.querySelectorAll('*');
                                for (var j = 0; j < allEls.length; j++) {
                                    if (allEls[j].shadowRoot) searchAll(allEls[j].shadowRoot);
                                }
                            } catch(e) {}
                        })(doc);
                    }
                    if (!st) st = doc.scrollingElement || doc.documentElement || doc.body;
                    if (!st) return { success: false, error: 'No scrollable element found' };

                    var targetTop = (args.position === 'top') ? 0 : (args.position === 'bottom') ? st.scrollHeight : (args.y || 0);
                    st.scrollTo({ top: targetTop, left: args.x || st.scrollLeft, behavior: beh });

                    return { success: true, scrollTop: st.scrollTop, scrollHeight: st.scrollHeight };
                } catch(e) {
                    return { success: false, error: 'scroll failed: ' + e.message };
                }

            case 'resize':
                try {
                    var presets = { mobile: {w:375,h:812}, tablet: {w:768,h:1024}, desktop: {w:1440,h:900}, fullhd: {w:1920,h:1080} };
                    var w, h;
                    if (args.preset && presets[args.preset]) {
                        w = presets[args.preset].w;
                        h = presets[args.preset].h;
                    } else {
                        w = args.width;
                        h = args.height;
                    }
                    if (!w && !h) return { success: false, error: 'Provide width/height or a preset (mobile, tablet, desktop, fullhd)' };
                    var iframe = getActiveIframe();
                    if (!iframe) return { success: false, error: 'No active iframe. Use navigate action first.' };
                    if (w) iframe.style.width = w + 'px';
                    if (h) iframe.style.height = h + 'px';
                    iframe.style.margin = '0 auto';
                    iframe.style.display = 'block';
                    var isMobile = (w === 375 && h === 812);
                    var wasMobile = iframeMobileMode;
                    iframeMobileMode = isMobile;
                    var mobileBtn = document.getElementById('iframe-mobile-btn');
                    if (mobileBtn) { mobileBtn.style.color = isMobile ? 'var(--primary)' : ''; mobileBtn.style.background = isMobile ? 'var(--primary-light)' : ''; mobileBtn.style.borderColor = isMobile ? 'var(--primary)' : ''; }
                    // Apply or remove mobile emulation based on mode change
                    if (isMobile && !wasMobile) applyMobileEmulationDeep(iframe, false);
                    else if (!isMobile && wasMobile) applyMobileEmulationDeep(iframe, true);
                    return { success: true, width: w || parseInt(iframe.style.width), height: h || parseInt(iframe.style.height) };
                } catch(e) {
                    return { success: false, error: 'resize failed: ' + e.message };
                }

            case 'get_properties':
                try {
                    if (!args.selector) return { success: false, error: 'selector is required for get_properties action' };
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var doc = target.iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content' };
                    var elements = target.isWidget ? Array.prototype.slice.call(doc.querySelectorAll(args.selector)) : pierceIframesAll(doc, args.selector);
                    if (!elements.length) return { success: false, error: 'No elements found: ' + args.selector };
                    var include = args.include || ['rect', 'styles', 'value', 'attributes'];
                    var results = [];
                    var limit = Math.min(elements.length, 20);
                    for (var i = 0; i < limit; i++) {
                        var el = elements[i];
                        var elWin = el.ownerDocument.defaultView || target.iframe.contentWindow;
                        var info = { tagName: el.tagName.toLowerCase(), visible: el.offsetParent !== null || el.offsetWidth > 0 || el.offsetHeight > 0 };
                        if (include.indexOf('rect') !== -1) {
                            var rect = el.getBoundingClientRect();
                            info.rect = { x: Math.round(rect.x), y: Math.round(rect.y), width: Math.round(rect.width), height: Math.round(rect.height) };
                        }
                        if (include.indexOf('styles') !== -1) {
                            var cs = elWin.getComputedStyle(el);
                            info.styles = { display: cs.display, visibility: cs.visibility, color: cs.color, backgroundColor: cs.backgroundColor, fontSize: cs.fontSize, fontWeight: cs.fontWeight, overflow: cs.overflow, position: cs.position, opacity: cs.opacity };
                        }
                        if (include.indexOf('value') !== -1) {
                            info.value = el.value !== undefined ? el.value : null;
                            info.textContent = (el.textContent || '').substring(0, 200);
                            info.checked = el.checked !== undefined ? el.checked : null;
                        }
                        if (include.indexOf('attributes') !== -1) {
                            info.attributes = {};
                            for (var a = 0; a < el.attributes.length; a++) {
                                info.attributes[el.attributes[a].name] = el.attributes[a].value;
                            }
                        }
                        results.push(info);
                    }
                    return { success: true, count: elements.length, elements: results };
                } catch(e) {
                    return { success: false, error: 'get_properties failed: ' + e.message };
                }

            case 'set_style':
                try {
                    if (!args.selector) return { success: false, error: 'selector is required for set_style action' };
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var doc = target.iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content' };
                    var elements = target.isWidget ? Array.prototype.slice.call(doc.querySelectorAll(args.selector)) : pierceIframesAll(doc, args.selector);
                    if (!elements.length) return { success: false, error: 'No elements found: ' + args.selector };
                    for (var i = 0; i < elements.length; i++) {
                        if (args.styles && typeof args.styles === 'object') {
                            for (var prop in args.styles) {
                                elements[i].style[prop] = args.styles[prop];
                            }
                        }
                        if (args.className) {
                            var parts = args.className.split(':');
                            if (parts[0] === 'add' && parts[1]) elements[i].classList.add(parts[1]);
                            else if (parts[0] === 'remove' && parts[1]) elements[i].classList.remove(parts[1]);
                            else if (parts[0] === 'toggle' && parts[1]) elements[i].classList.toggle(parts[1]);
                        }
                    }
                    return { success: true, modifiedCount: elements.length };
                } catch(e) {
                    return { success: false, error: 'set_style failed: ' + e.message };
                }

            case 'dispatch_event':
                try {
                    if (!args.selector) return { success: false, error: 'selector is required for dispatch_event action' };
                    if (!args.event) return { success: false, error: 'event is required for dispatch_event action' };
                    var allowedEvents = ['click', 'change', 'input', 'focus', 'blur', 'submit', 'mouseenter', 'mouseleave', 'keydown', 'keyup'];
                    if (allowedEvents.indexOf(args.event) === -1) return { success: false, error: 'Event "' + args.event + '" not allowed. Allowed: ' + allowedEvents.join(', ') };
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var doc = target.iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content' };
                    var el = target.isWidget ? doc.querySelector(args.selector) : pierceIframes(doc, args.selector);
                    if (!el) return { success: false, error: 'Element not found: ' + args.selector };
                    var elWin = el.ownerDocument.defaultView || target.iframe.contentWindow;
                    var eventObj;
                    if (args.event === 'keydown' || args.event === 'keyup') {
                        eventObj = new elWin.KeyboardEvent(args.event, { key: args.key || '', bubbles: true, cancelable: true });
                    } else if (args.event === 'mouseenter' || args.event === 'mouseleave') {
                        eventObj = new elWin.MouseEvent(args.event, { bubbles: true, cancelable: true });
                    } else {
                        eventObj = new elWin.Event(args.event, { bubbles: true, cancelable: true });
                    }
                    el.dispatchEvent(eventObj);
                    return { success: true, event: args.event, selector: args.selector };
                } catch(e) {
                    return { success: false, error: 'dispatch_event failed: ' + e.message };
                }

            case 'select_option':
                try {
                    if (!args.selector) return { success: false, error: 'selector is required for select_option action' };
                    var target = getTargetIframe();
                    if (target.error) return { success: false, error: target.error };
                    var doc = target.iframe.contentDocument;
                    if (!doc) return { success: false, error: 'Cannot access iframe content' };
                    var selectEl = target.isWidget ? doc.querySelector(args.selector) : pierceIframes(doc, args.selector);
                    if (!selectEl) return { success: false, error: 'Element not found: ' + args.selector };
                    if (selectEl.tagName !== 'SELECT') return { success: false, error: 'Element is not a <select>: ' + selectEl.tagName };
                    var matched = false;
                    for (var i = 0; i < selectEl.options.length; i++) {
                        var opt = selectEl.options[i];
                        if ((args.value !== undefined && opt.value === args.value) || (args.text !== undefined && opt.text === args.text)) {
                            selectEl.selectedIndex = i;
                            matched = true;
                            break;
                        }
                    }
                    if (!matched) {
                        var available = Array.prototype.slice.call(selectEl.options).map(function(o) { return { value: o.value, text: o.text }; });
                        return { success: false, error: 'Option not found', availableOptions: available };
                    }
                    var elWin = selectEl.ownerDocument.defaultView || target.iframe.contentWindow;
                    selectEl.dispatchEvent(new elWin.Event('change', { bubbles: true }));
                    return { success: true, selectedValue: selectEl.value, selectedText: selectEl.options[selectEl.selectedIndex].text };
                } catch(e) {
                    return { success: false, error: 'select_option failed: ' + e.message };
                }

            case 'impersonate':
                if (!args.user) return { success: false, error: 'user is required (username, name, sys_id, or "stop")' };
                try {
                    var impHeaders = { 'X-UserToken': window.sessionToken, 'Accept': 'application/json' };
                    if (args.user === 'stop') {
                        if (!impersonateOriginalUserSysId) {
                            return { success: false, error: 'No active impersonation to stop (original user sys_id not stored).' };
                        }
                        var stopRes = await fetch('/api/now/ui/impersonate/' + impersonateOriginalUserSysId, {
                            method: 'POST',
                            headers: Object.assign({ 'Content-Type': 'application/json' }, impHeaders)
                        });
                        if (!stopRes.ok) return { success: false, error: 'Failed to stop impersonation: HTTP ' + stopRes.status };
                        logToDevtools('[impersonate] Switched back to original user ' + impersonateOriginalUserSysId, 'log');
                        impersonateOriginalUserSysId = null;
                        appStorage.removeItem('impersonateOriginalUserSysId');
                        if (browserIframe && currentIframeUrl) browserIframe.src = currentIframeUrl;
                        return { success: true, message: 'Impersonation ended. Switched back to original user. Iframe reloaded.' };
                    }
                    // Store original user sys_id before first impersonation
                    if (!impersonateOriginalUserSysId) {
                        if (cachedUserSysId) {
                            impersonateOriginalUserSysId = cachedUserSysId;
                            appStorage.setItem('impersonateOriginalUserSysId', impersonateOriginalUserSysId);
                        } else {
                            var meRes = await fetch('/api/now/table/sys_user?sysparm_query=user_name=' + encodeURIComponent(window.NOW?.user_name || 'admin') + '&sysparm_fields=sys_id&sysparm_limit=1', { headers: impHeaders });
                            var meData = await meRes.json();
                            if (meData.result && meData.result[0]) {
                                impersonateOriginalUserSysId = meData.result[0].sys_id;
                                appStorage.setItem('impersonateOriginalUserSysId', impersonateOriginalUserSysId);
                                cachedUserSysId = impersonateOriginalUserSysId;
                            }
                        }
                    }
                    // Resolve user sys_id
                    var userSysId = args.user;
                    if (!/^[0-9a-f]{32}$/.test(args.user)) {
                        var lookupRes = await fetch('/api/now/table/sys_user?sysparm_query=user_name=' + encodeURIComponent(args.user) + '^ORnameLIKE' + encodeURIComponent(args.user) + '&sysparm_fields=sys_id,user_name,name&sysparm_limit=5', { headers: impHeaders });
                        var lookupData = await lookupRes.json();
                        if (!lookupData.result || lookupData.result.length === 0) {
                            return { success: false, error: 'User not found: ' + args.user };
                        }
                        userSysId = lookupData.result[0].sys_id;
                        logToDevtools('[impersonate] Resolved "' + args.user + '" to ' + lookupData.result[0].user_name + ' (' + userSysId + ')', 'log');
                    }
                    // Call impersonation API
                    var impRes = await fetch('/api/now/ui/impersonate/' + userSysId, {
                        method: 'POST',
                        headers: Object.assign({ 'Content-Type': 'application/json' }, impHeaders)
                    });
                    if (!impRes.ok) {
                        return { success: false, error: 'Impersonation failed: HTTP ' + impRes.status };
                    }
                    logToDevtools('[impersonate] Now impersonating user ' + userSysId, 'log');
                    if (browserIframe && currentIframeUrl) browserIframe.src = currentIframeUrl;
                    return { success: true, message: 'Now impersonating user (sys_id: ' + userSysId + '). Iframe reloaded.' };
                } catch(e) {
                    return { success: false, error: 'Impersonate failed: ' + e.message };
                }

            default:
                return { success: false, error: 'Unknown action: ' + action };
        }
    } catch(e) {
        return { success: false, error: e.message };
    }
}

// Execute set_chat_title tool
function executeSetChatTitle(args) {
    if (!args.title || typeof args.title !== 'string') {
        return { success: false, error: 'Title is required' };
    }

    var title = args.title.trim().substring(0, 60);
    if (title.length === 0) {
        return { success: false, error: 'Title cannot be empty' };
    }

    var chat = chats[currentChatId];
    if (!chat) {
        return { success: false, error: 'No active chat' };
    }

    chat.title = title;
    saveChatsToStorage();
    renderChatList();
    updateChatTitleHeader();

    return { success: true, message: 'Chat title updated to: ' + title };
}

// Apply search-and-replace edits to content (no line numbers needed)
function applySearchReplaceEdits(content, edits) {
    var errors = [];
    var modifiedContent = content;
    var appliedEdits = [];

    for (var i = 0; i < edits.length; i++) {
        var edit = edits[i];

        // Validate edit is an object
        if (!edit || typeof edit !== 'object') {
            errors.push('Edit ' + i + ': Expected object with {find, replace}, got: ' + JSON.stringify(edit));
            continue;
        }

        // Support common alternative property names (LLMs sometimes use these)
        var findText = edit.find !== undefined ? edit.find :
                       edit.old_string !== undefined ? edit.old_string :
                       edit.search !== undefined ? edit.search :
                       edit.old !== undefined ? edit.old :
                       edit.text !== undefined ? edit.text : undefined;
        var replaceText = edit.replace !== undefined ? edit.replace :
                          edit.new_string !== undefined ? edit.new_string :
                          edit.replacement !== undefined ? edit.replacement :
                          edit.new !== undefined ? edit.new : undefined;

        // Validate required fields - show what keys were actually provided
        if (findText === undefined || findText === null) {
            var receivedKeys = Object.keys(edit).join(', ') || 'none';
            errors.push('Edit ' + i + ': Missing "find" property. Received keys: [' + receivedKeys + ']. Expected: {find: "...", replace: "..."}');
            continue;
        }
        if (replaceText === undefined || replaceText === null) {
            var receivedKeys = Object.keys(edit).join(', ') || 'none';
            errors.push('Edit ' + i + ': Missing "replace" property. Received keys: [' + receivedKeys + ']. Expected: {find: "...", replace: "..."}');
            continue;
        }

        // Count occurrences
        var occurrences = 0;
        var searchPos = 0;
        var foundIndex = -1;
        while ((searchPos = modifiedContent.indexOf(findText, searchPos)) !== -1) {
            if (occurrences === 0) foundIndex = searchPos;
            occurrences++;
            searchPos += 1;
        }

        if (occurrences === 0) {
            errors.push('Edit ' + i + ': Text not found: "' + findText.substring(0, 80) + (findText.length > 80 ? '...' : '') + '"');
            continue;
        }

        if (occurrences > 1) {
            // Find all occurrence positions and show context
            var positions = [];
            var lines = modifiedContent.split('\n');
            var charCount = 0;
            for (var lineNum = 0; lineNum < lines.length; lineNum++) {
                var lineStart = charCount;
                var lineEnd = charCount + lines[lineNum].length;
                var pos = modifiedContent.indexOf(findText, lineStart);
                while (pos !== -1 && pos < lineEnd + findText.length) {
                    if (pos >= lineStart) {
                        positions.push('line ' + (lineNum + 1) + ' (char ' + pos + ')');
                    }
                    pos = modifiedContent.indexOf(findText, pos + 1);
                }
                charCount = lineEnd + 1; // +1 for newline
            }
            errors.push('Edit ' + i + ': Text found ' + occurrences + ' times at: ' + positions.join(', ') + '. Add more surrounding context to make it unique. Text: "' + findText.substring(0, 50) + '..."');
            continue;
        }

        // Apply the edit
        modifiedContent = modifiedContent.substring(0, foundIndex) + replaceText + modifiedContent.substring(foundIndex + findText.length);
        appliedEdits.push({ index: i, action: 'replace', at: foundIndex, removed: findText.length, added: replaceText.length });
    }

    if (errors.length > 0) {
        // If some edits succeeded, return partial success with the modified content
        if (appliedEdits.length > 0) {
            return { error: false, partialSuccess: true, content: modifiedContent, appliedEdits: appliedEdits, failedEdits: errors };
        }
        // All edits failed - return error without any content changes
        return { error: true, messages: errors, partialEdits: [] };
    }

    return { error: false, content: modifiedContent, appliedEdits: appliedEdits };
}

// Execute diff edit tool (search-and-replace based)
async function executeDiffEdit(args, messageIndex) {
    try {
        var currentContent;

        // Capture version before the change
        var versionBefore = await getRecordVersion(args.table, args.sys_id);
        var beforeVersion = versionBefore ? versionBefore.sys_id : null;

        // Always fetch the full content from the server to ensure we have the complete field
        // (current_content parameter is ignored to prevent accidental data loss from partial content)
        var getUrl = '/api/now/table/' + args.table + '/' + args.sys_id + '?sysparm_fields=' + args.field;
        var getRes = await fetch(getUrl, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-UserToken': window.sessionToken || ''
            }
        });

        if (!getRes.ok) {
            var errData = await getRes.json();
            return { success: false, error: 'Failed to fetch record: ' + (errData.error?.message || getRes.status) };
        }

        var getData = await getRes.json();
        currentContent = getData.result[args.field] || '';

        var originalLength = currentContent.length;

        // Apply search-and-replace edits
        var editResult = applySearchReplaceEdits(currentContent, args.edits);

        // Check for validation errors - only fail if ALL edits failed
        if (editResult.error) {
            return { 
                success: false, 
                error: 'All edits failed validation', 
                validationErrors: editResult.messages,
                hint: 'Ensure find text is unique and exists in the document. Include more context lines if needed.'
            };
        }

        var newContent = editResult.content;
        var failedEdits = editResult.failedEdits || [];
        var isPartialSuccess = editResult.partialSuccess || false;

        // PUT the updated content using record's scope
        var putUrl = '/api/now/table/' + args.table + '/' + args.sys_id;
        var recordScope = await getRecordScope(args.table, args.sys_id);
        if (recordScope) {
            putUrl += '?sysparm_record_scope=' + encodeURIComponent(recordScope);
        }
        var putData = {};
        putData[args.field] = newContent;

        var putRes = await fetch(putUrl, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-UserToken': window.sessionToken || ''
            },
            body: JSON.stringify(putData)
        });

        if (!putRes.ok) {
            var errData = await putRes.json();
            return { success: false, error: 'Failed to update record: ' + (errData.error?.message || putRes.status) };
        }

        // Capture version after the change and track it
        await new Promise(function(r) { setTimeout(r, 200); });
        var versionAfter = await getRecordVersion(args.table, args.sys_id);
        var afterVersion = versionAfter ? versionAfter.sys_id : null;

        // Get display name for the record
        var displayName = await getRecordDisplayValue(args.table, args.sys_id);

        // Add to version history
        addVersionHistoryEntry({
            id: 'vh_' + Date.now(),
            chatId: currentChatId,
            timestamp: Date.now(),
            table: args.table,
            sysId: args.sys_id,
            field: args.field,
            displayName: displayName,
            action: 'EDIT',
            statusMessage: args.status_message || null,
            messageIndex: messageIndex || -1,
            beforeVersion: beforeVersion,
            afterVersion: afterVersion
        });

        var result = {
            success: true,
            originalLength: originalLength,
            newLength: newContent.length,
            editsApplied: editResult.appliedEdits
        };

        if (isPartialSuccess) {
            result.message = 'Partially applied ' + editResult.appliedEdits.length + ' of ' + args.edits.length + ' edit(s) to ' + args.field;
            result.partialSuccess = true;
            result.failedEdits = failedEdits;
            result.warning = 'Some edits failed validation but successful edits were saved. Review failedEdits for details.';
        } else {
            result.message = 'Successfully applied ' + args.edits.length + ' edit(s) to ' + args.field;
        }

        return result;
    } catch (e) {
        return { success: false, error: e.message };
    }
}

// Single entry point for all tool execution - always checks permissions
// options: { batch, toolCallId, chatId } - passed through to requestProgrammaticToolApproval
async function executeTool(name, args, messageIndex, options) {
    var approval = await requestProgrammaticToolApproval(name, args, options);
    if (!approval.allowed) {
        return { success: false, error: approval.error, _denied: true };
    }

    // Execute the tool
    if (name === 'js_eval') {
        var sandbox = null;
        try {
            var chatId = (options && options.chatId) || activeStreamingChatId || currentChatId;

            // Create isolated sandbox iframe with srcdoc (avoids cross-origin document access)
            sandbox = document.createElement('iframe');
            sandbox.style.display = 'none';
            sandbox.sandbox = 'allow-scripts';

            // Sanitize code: convert Unicode lookalike characters to ASCII equivalents
            // This fixes issues where AI generates fancy quotes/backticks that look correct but break eval
            var sanitizedCode = args.code
                .replace(/[\u2018\u2019\u02BC\u02B9]/g, "'")  // Convert fancy single quotes to ASCII '
                .replace(/[\u201C\u201D]/g, '"')              // Convert fancy double quotes to ASCII "
                .replace(/[\u02CB\u0060\u2032\u02B4]/g, '`'); // Normalize backtick-like chars to ASCII `

            // Only closing-script-tags need escaping for srcdoc embedding
            var escapedCode = sanitizedCode.replace(/<\/script>/gi, '<\\/script>');

            // Build the HTML content with embedded script
            var htmlContent = '<!DOCTYPE html><html><head></head><body><script>' +
                'window._pendingCalls = {};' +
                'window._callId = 0;' +
                'window.executeTool = function(name, args) {' +
                    'return new Promise(function(resolve, reject) {' +
                        'var id = ++window._callId;' +
                        'window._pendingCalls[id] = { resolve: resolve, reject: reject };' +
                        'window.parent.postMessage({ type: "jsEvalToolCall", id: id, name: name, args: args }, "*");' +
                    '});' +
                '};' +
                'window.addEventListener("message", function(e) {' +
                    'if (e.data && e.data.type === "jsEvalToolResult" && window._pendingCalls[e.data.id]) {' +
                        'var cb = window._pendingCalls[e.data.id];' +
                        'delete window._pendingCalls[e.data.id];' +
                        'if (e.data.error) cb.reject(new Error(e.data.error));' +
                        'else cb.resolve(e.data.result);' +
                    '}' +
                '});' +
                '(async () => {' +
                    'try {' +
                        'var result = await (async () => { ' + escapedCode + ' })();' +
                        'window.parent.postMessage({ type: "jsEvalDone", result: result }, "*");' +
                    '} catch (e) {' +
                        'window.parent.postMessage({ type: "jsEvalDone", error: e.message }, "*");' +
                    '}' +
                '})();' +
            '<\/script></body></html>';

            // Store listener reference outside Promise for cleanup on error
            var sandboxMessageHandler = null;

            // Promise to wait for result
            var resultPromise = new Promise(function(resolveMain, rejectMain) {
                // Handle tool calls from sandbox
                function handleSandboxMessage(e) {
                    if (e.source !== sandbox.contentWindow) return;
                    if (e.data && e.data.type === 'jsEvalToolCall') {
                        executeTool(e.data.name, e.data.args, null, { chatId: chatId })
                            .then(function(result) {
                                // Persist screenshot to chat.screenshots map so screenshot_by_id can find it after reload
                                // (NOT chat.messages — inserting there breaks tool_use/tool_result ordering for the API)
                                if (result && result._screenshotMessage) {
                                    var ssMsg = result._screenshotMessage;
                                    if (ssMsg.screenshot_id) {
                                        var jsChat = chats[chatId];
                                        if (jsChat) {
                                            if (!jsChat.screenshots) jsChat.screenshots = {};
                                            jsChat.screenshots[ssMsg.screenshot_id] = { base64: ssMsg.base64, name: ssMsg.name, width: ssMsg.width, height: ssMsg.height, timestamp: ssMsg.timestamp, description: ssMsg.description };
                                            saveChatsToStorage();
                                        }
                                    }
                                    result.base64 = ssMsg.base64;
                                    result.width = ssMsg.width;
                                    result.height = ssMsg.height;
                                    result.screenshot_id = ssMsg.screenshot_id || result.screenshot_id;
                                    delete result._screenshotMessage;
                                }
                                sandbox.contentWindow.postMessage({ type: 'jsEvalToolResult', id: e.data.id, result: result }, '*');
                            })
                            .catch(function(err) {
                                sandbox.contentWindow.postMessage({ type: 'jsEvalToolResult', id: e.data.id, error: err.message }, '*');
                            });
                    } else if (e.data && e.data.type === 'jsEvalDone') {
                        window.removeEventListener('message', handleSandboxMessage);
                        sandboxMessageHandler = null; // Clear reference
                        if (e.data.error) rejectMain(new Error(e.data.error));
                        else resolveMain(e.data.result);
                    }
                }
                sandboxMessageHandler = handleSandboxMessage;
                window.addEventListener('message', handleSandboxMessage);

                // Set srcdoc to load the iframe with the script
                sandbox.srcdoc = htmlContent;
                document.body.appendChild(sandbox);
            });

            var result = await resultPromise;
            document.body.removeChild(sandbox);
            var jsEvalResult = { success: true, result: result };
            // Extract _images from result: model-controlled image passing
            // The model returns _images array when it wants images sent to its vision
            // Works for screenshots, canvas-generated images, or any base64 image
            if (result && result._images && Array.isArray(result._images) && result._images.length > 0) {
                var imgs = result._images;
                delete result._images;
                var screenshotMsgs = imgs.map(function(img) {
                    var ssId = 'ss_' + (++_screenshotIdCounter) + '_' + Date.now();
                    var ssTimestamp = Date.now();
                    return {
                        role: 'screenshot',
                        base64: img.base64,
                        name: img.name || null,
                        description: img.description || 'Image from js_eval',
                        timestamp: ssTimestamp,
                        width: img.width || null,
                        height: img.height || null,
                        screenshot_id: ssId
                    };
                });
                if (screenshotMsgs.length === 1) {
                    jsEvalResult._screenshotMessage = screenshotMsgs[0];
                } else {
                    jsEvalResult._screenshotMessages = screenshotMsgs;
                }
            }
            return jsEvalResult;
        } catch (e) {
            // Clean up listener on error to prevent memory leak
            if (sandboxMessageHandler) {
                window.removeEventListener('message', sandboxMessageHandler);
            }
            if (sandbox && sandbox.parentNode) sandbox.parentNode.removeChild(sandbox);
            return { success: false, error: e.message };
        }
    } else if (name === 'servicenow_api' && args.table === 'attachment' && args.method === 'POST' && args.attachment_data) {
        // Attachment upload via /api/now/attachment/file
        try {
            if (!args.attachment_file_name) return { success: false, error: 'attachment_file_name is required for attachment upload' };
            if (!args.attachment_table_name) return { success: false, error: 'attachment_table_name is required for attachment upload' };
            if (!args.attachment_table_sys_id) return { success: false, error: 'attachment_table_sys_id is required for attachment upload' };

            // Detect content type from file extension if not provided
            var contentType = args.attachment_content_type;
            if (!contentType) {
                var ext = (args.attachment_file_name.split('.').pop() || '').toLowerCase();
                var mimeMap = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', svg: 'image/svg+xml', pdf: 'application/pdf', json: 'application/json', xml: 'application/xml', txt: 'text/plain', csv: 'text/csv', html: 'text/html', zip: 'application/zip', js: 'text/javascript', css: 'text/css' };
                contentType = mimeMap[ext] || 'application/octet-stream';
            }

            // Decode base64 data (handle data URL prefix)
            var base64Raw = args.attachment_data;
            if (base64Raw.indexOf(',') !== -1) {
                base64Raw = base64Raw.split(',')[1];
            }
            var binaryStr = atob(base64Raw);
            var bytes = new Uint8Array(binaryStr.length);
            for (var bi = 0; bi < binaryStr.length; bi++) {
                bytes[bi] = binaryStr.charCodeAt(bi);
            }

            var attachUrl = '/api/now/attachment/file?table_name=' + encodeURIComponent(args.attachment_table_name) +
                '&table_sys_id=' + encodeURIComponent(args.attachment_table_sys_id) +
                '&file_name=' + encodeURIComponent(args.attachment_file_name);
            var res = await fetch(attachUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': contentType,
                    'Accept': 'application/json',
                    'X-UserToken': window.sessionToken || ''
                },
                body: bytes.buffer
            });
            var data = await res.json();
            return { success: res.ok, status: res.status, data: data };
        } catch (e) {
            return { success: false, error: e.message };
        }
    } else if (name === 'servicenow_api') {
        var url = '/api/now/table/' + args.table;
        if (args.sys_id) url += '/' + args.sys_id;
        var params = [];
        if (args.query) params.push('sysparm_query=' + encodeURIComponent(args.query));
        if (args.fields) params.push('sysparm_fields=' + encodeURIComponent(args.fields));
        if (args.limit) params.push('sysparm_limit=' + args.limit);
        // Exclude reference links by default (returns just the value instead of {link, value} object)
        params.push('sysparm_exclude_reference_link=true');
        if (args.url_params && typeof args.url_params === 'object') {
            Object.keys(args.url_params).forEach(function(key) {
                params.push(encodeURIComponent(key) + '=' + encodeURIComponent(args.url_params[key]));
            });
        }
        // Handle sysparm_record_scope for modifying methods (POST, PUT, PATCH, DELETE)
        if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(args.method)) {
            var recordScope = args.scope || (args.data && args.data.sys_scope);
            if (!recordScope) {
                return { success: false, error: args.method + ' requests require a scope. Provide "scope" parameter or include "sys_scope" in data.' };
            }
            params.push('sysparm_record_scope=' + encodeURIComponent(recordScope));
        }
        if (params.length) url += '?' + params.join('&');
        try {
            var beforeVersion = null;
            var isModifyingRequest = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(args.method);
            if (isModifyingRequest && args.sys_id) {
                var versionBefore = await getRecordVersion(args.table, args.sys_id);
                beforeVersion = versionBefore ? versionBefore.sys_id : null;
            }

            var opts = {
                method: args.method,
                headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-UserToken': window.sessionToken || '' }
            };
            if (args.data && ['POST', 'PUT', 'PATCH'].includes(args.method)) {
                opts.body = JSON.stringify(args.data);
            }
            var res = await fetch(url, opts);
            var data = await res.json();

            if (res.ok && isModifyingRequest) {
                var recordSysId = args.sys_id || (data.result && data.result.sys_id);
                if (recordSysId) {
                    await new Promise(function(r) { setTimeout(r, 200); });
                    var versionAfter = await getRecordVersion(args.table, recordSysId);
                    var afterVersion = versionAfter ? versionAfter.sys_id : null;
                    var displayName = await getRecordDisplayValue(args.table, recordSysId);
                    addVersionHistoryEntry({
                        id: 'vh_' + Date.now(),
                        chatId: currentChatId,
                        timestamp: Date.now(),
                        table: args.table,
                        sysId: recordSysId,
                        displayName: displayName,
                        action: args.method,
                        statusMessage: args.status_message || null,
                        messageIndex: messageIndex || -1,
                        beforeVersion: beforeVersion,
                        afterVersion: afterVersion
                    });
                }
            }

            return { success: res.ok, status: res.status, data: data };
        } catch (e) {
            return { success: false, error: e.message };
        }
    } else if (name === 'servicenow_diff_edit') {
        return await executeDiffEdit(args, messageIndex);
    } else if (name === 'iframe_tool') {
        return await executeIframeTool(args);
    } else if (name === 'set_chat_title') {
        return executeSetChatTitle(args);
    } else if (name === 'cached_content_outline') {
        var ccoChatId = activeStreamingChatId || currentChatId;
        return executeCachedContentOutline(ccoChatId, args);
    } else if (name === 'cached_content_search') {
        var ccsChatId = activeStreamingChatId || currentChatId;
        return executeCachedContentSearch(ccsChatId, args);
    } else if (name === 'cached_content_read') {
        var ccrChatId = activeStreamingChatId || currentChatId;
        return executeCachedContentRead(ccrChatId, args);
    } else if (name === 'get_skill') {
        return await executeGetSkill(args);
    } else if (name === 'manage_skill') {
        return await executeManageSkill(args);
    } else if (name === 'html_widget') {
        return executeHtmlWidget(args, messageIndex);
    } else if (name === 'take_screenshot') {
        return await executeTakeScreenshot(args);
    } else if (name === 'screenshot_by_id') {
        return executeScreenshotById(args);
    } else if (name === 'read_attached_file') {
        return executeReadAttachedFile(args);
    } else if (isSkillTool(name)) {
        return await executeSkillTool(name, args, options);
    }
    return { success: false, error: 'Unknown tool' };
}

// =============================================
// NATIVE SCREENSHOT CAPTURE - getDisplayMedia (no external libraries)
// =============================================

async function captureElementToCanvas(element) {
    // Get the element's bounding rect (position relative to viewport)
    var rect = element.getBoundingClientRect();

    // For iframe content, we need the iframe's position, not its body
    var targetElement = element;
    if (element.tagName === 'BODY' || element.tagName === 'HTML') {
        // Find the iframe that contains this element
        var win = element.ownerDocument.defaultView;
        if (win && win.frameElement) {
            targetElement = win.frameElement;
            rect = targetElement.getBoundingClientRect();
        }
    }

    // Request screen capture with preference for current tab
    var stream;
    try {
        stream = await navigator.mediaDevices.getDisplayMedia({
            video: {
                displaySurface: 'browser'
            },
            preferCurrentTab: true
        });
    } catch (e) {
        throw new Error('Screen capture cancelled or denied: ' + e.message);
    }

    try {
        // Create video element to capture a frame
        var video = document.createElement('video');
        video.srcObject = stream;
        video.muted = true;

        // Wait for metadata
        await new Promise(function(resolve, reject) {
            video.onloadedmetadata = resolve;
            video.onerror = reject;
            setTimeout(function() { reject(new Error('Video load timeout')); }, 5000);
        });

        await video.play();

        // Wait for frame to render
        await new Promise(function(resolve) {
            requestAnimationFrame(function() {
                requestAnimationFrame(resolve);
            });
        });

        // Video dimensions (full captured area)
        var videoWidth = video.videoWidth;
        var videoHeight = video.videoHeight;

        // Device pixel ratio for HiDPI displays
        var dpr = window.devicePixelRatio || 1;

        // Calculate crop coordinates
        var cropX = Math.round(rect.left * dpr);
        var cropY = Math.round(rect.top * dpr);
        var cropWidth = Math.round(rect.width * dpr);
        var cropHeight = Math.round(rect.height * dpr);

        // Clamp to video bounds
        cropX = Math.max(0, Math.min(cropX, videoWidth - 1));
        cropY = Math.max(0, Math.min(cropY, videoHeight - 1));
        cropWidth = Math.min(cropWidth, videoWidth - cropX);
        cropHeight = Math.min(cropHeight, videoHeight - cropY);

        // Ensure valid dimensions
        if (cropWidth <= 0 || cropHeight <= 0) {
            throw new Error('Invalid crop dimensions');
        }

        // Create canvas and draw cropped region
        var canvas = document.createElement('canvas');
        canvas.width = cropWidth;
        canvas.height = cropHeight;
        var ctx = canvas.getContext('2d');

        ctx.drawImage(video,
            cropX, cropY, cropWidth, cropHeight,
            0, 0, cropWidth, cropHeight
        );

        return canvas;

    } finally {
        // Always stop the stream
        stream.getTracks().forEach(function(track) { track.stop(); });
    }
}

// =============================================
// READ ATTACHED FILE TOOL - Read user-attached text files (CSV, etc.)
// =============================================

function executeReadAttachedFile(args) {
    var filename = args.filename;
    if (!filename) {
        return { success: false, error: 'filename is required' };
    }

    var chat = chats[currentChatId];
    if (!chat || !chat.messages) {
        return { success: false, error: 'No active chat found' };
    }

    // Find the file attachment in chat messages
    var fileMsg = null;
    for (var i = 0; i < chat.messages.length; i++) {
        var msg = chat.messages[i];
        if (msg.role === 'file' && msg.name && msg.name.toLowerCase() === filename.toLowerCase()) {
            fileMsg = msg;
            break;
        }
    }

    if (!fileMsg) {
        // List available files
        var availableFiles = chat.messages
            .filter(function(m) { return m.role === 'file'; })
            .map(function(m) { return m.name; });

        if (availableFiles.length === 0) {
            return { success: false, error: 'No files attached in this conversation. Ask the user to attach a file first.' };
        }
        return { success: false, error: 'File not found: ' + filename + '. Available files: ' + availableFiles.join(', ') };
    }

    var content = fileMsg.content;

    // Return text file content directly
    return {
        success: true,
        filename: fileMsg.name,
        mimeType: fileMsg.mimeType,
        size: fileMsg.size,
        format: 'text',
        content: content
    };
}

// =============================================
// TAKE SCREENSHOT TOOL - Capture real PNG screenshots for AI vision
// =============================================

async function executeTakeScreenshot(args) {
    var target = args.target;
    var widgetId = args.widget_id;
    var selector = args.selector;
    var maxWidth = args.max_width || 1600;

    if (!target) {
        return { success: false, error: 'target is required. Use "browser", "widget", or "element"' };
    }

    try {
        var elementToCapture = null;
        var captureDescription = '';

        if (target === 'browser') {
            // Capture the iframe panel content
            var iframe = getActiveIframe();
            if (!iframe) {
                return { success: false, error: 'No active browser iframe. Use iframe_tool navigate first to open a page.' };
            }
            // Try to access iframe content document
            try {
                var iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
                elementToCapture = iframeDoc.body || iframeDoc.documentElement;
                captureDescription = 'browser iframe at ' + (currentIframeUrl || '/');
            } catch (e) {
                // Cross-origin - capture the iframe element itself
                elementToCapture = iframe;
                captureDescription = 'browser iframe (cross-origin, outer frame only)';
            }
        } else if (target === 'widget') {
            if (!widgetId) {
                return { success: false, error: 'widget_id is required when target is "widget"' };
            }
            var _ssWidget = getWidgetById(widgetId);
            if (!_ssWidget && dashboardWidgets[widgetId]) _ssWidget = dashboardWidgets[widgetId];
            if (_ssWidget && _ssWidget.deactivated) {
                return { success: false, error: 'Widget "' + (_ssWidget.title || widgetId) + '" is deactivated. The user has deactivated this widget. Ask the user to activate it first, or proceed differently.' };
            }
            var widgetIframe = getWidgetIframe(widgetId);
            if (!widgetIframe) {
                return { success: false, error: 'Widget not found: ' + widgetId + '. Make sure the widget is visible in the chat or dashboard.' };
            }
            try {
                var widgetDoc = widgetIframe.contentDocument || widgetIframe.contentWindow.document;
                elementToCapture = widgetDoc.body || widgetDoc.documentElement;
                captureDescription = 'widget ' + widgetId;
            } catch (e) {
                elementToCapture = widgetIframe;
                captureDescription = 'widget ' + widgetId + ' (outer frame)';
            }
        } else if (target === 'element') {
            if (!selector) {
                return { success: false, error: 'selector is required when target is "element"' };
            }
            elementToCapture = document.querySelector(selector);
            if (!elementToCapture) {
                return { success: false, error: 'Element not found: ' + selector };
            }
            captureDescription = 'element ' + selector;
        } else {
            return { success: false, error: 'Invalid target. Use "browser", "widget", or "element"' };
        }

        if (!elementToCapture) {
            return { success: false, error: 'Could not find element to capture' };
        }

        var base64Data;
        var finalWidth, finalHeight;

        if (screenshotMethod === 'display-media') {
            // Browser Display Media capture (requires user permission dialog)
            var canvas = await captureElementToCanvas(elementToCapture);
            var finalCanvas = canvas;
            if (canvas.width > maxWidth) {
                var scale = maxWidth / canvas.width;
                var resizedCanvas = document.createElement('canvas');
                resizedCanvas.width = maxWidth;
                resizedCanvas.height = Math.round(canvas.height * scale);
                var ctx = resizedCanvas.getContext('2d');
                ctx.drawImage(canvas, 0, 0, resizedCanvas.width, resizedCanvas.height);
                finalCanvas = resizedCanvas;
                // Release original canvas memory
                canvas.width = 0;
                canvas.height = 0;
            }
            base64Data = finalCanvas.toDataURL('image/png');
            finalWidth = finalCanvas.width;
            finalHeight = finalCanvas.height;
            // Release final canvas memory
            finalCanvas.width = 0;
            finalCanvas.height = 0;
        } else {
            // html-to-image capture (default, no permission dialog)
            var containerEl = elementToCapture;
            // For body/html, find the containing iframe for dimensions
            var iframeEl = null;
            if (containerEl.tagName === 'BODY' || containerEl.tagName === 'HTML') {
                var win = containerEl.ownerDocument.defaultView;
                if (win && win.frameElement) iframeEl = win.frameElement;
            }
            var w = iframeEl ? iframeEl.clientWidth : containerEl.scrollWidth;
            var h = iframeEl ? iframeEl.clientHeight : containerEl.scrollHeight;
            var ratio = window.devicePixelRatio || 1;
            var htiOpts = {
                width: w, height: h, pixelRatio: ratio,
                filter: screenshotFilter
            };
            if (_htiFontCache != null) htiOpts.fontEmbedCSS = _htiFontCache;
            var restoreGCS = patchScrollStyles(containerEl);

            // Fix margin rendering: convert parents of inline spans (containing block children) to flex layout.
            // See comment in captureScreenshot() for full explanation of WHY and how TO REVERT TO ALL SPANS.
            var restoreMarginFix = [];
            try {
                var doc = containerEl.ownerDocument || containerEl;
                var widgetSpans = doc.querySelectorAll('span[ng-switch-default][ng-repeat*="rectangle"], span[ng-repeat*="widget"]');
                var processed = new Set();
                widgetSpans.forEach(function(span) {
                    var parent = span.parentElement;
                    if (!parent || processed.has(parent)) return;
                    processed.add(parent);
                    var origDisplay = parent.style.display;
                    var origFlexDir = parent.style.flexDirection;
                    parent.style.setProperty('display', 'flex', 'important');
                    parent.style.setProperty('flex-direction', 'column', 'important');
                    restoreMarginFix.push({ el: parent, display: origDisplay, flexDir: origFlexDir });
                });
            } catch (e) { /* ignore */ }

            try {
                var svgDataUrl = await _htiToSvg(containerEl, htiOpts);
                base64Data = await svgToPng(sanitizeSvgDataUrl(svgDataUrl), w, h, ratio);
            } finally {
                restoreGCS();
                restoreMarginFix.forEach(function(item) {
                    if (item.display) item.el.style.display = item.display;
                    else item.el.style.removeProperty('display');
                    if (item.flexDir) item.el.style.flexDirection = item.flexDir;
                    else item.el.style.removeProperty('flex-direction');
                });
            }
            // Resize if wider than maxWidth
            finalWidth = Math.round(w * ratio);
            finalHeight = Math.round(h * ratio);
            if (finalWidth > maxWidth) {
                var resizeScale = maxWidth / finalWidth;
                var resizedCanvas = document.createElement('canvas');
                resizedCanvas.width = maxWidth;
                resizedCanvas.height = Math.round(finalHeight * resizeScale);
                var rctx = resizedCanvas.getContext('2d');
                var img = new Image();
                await new Promise(function(resolve, reject) {
                    img.onload = resolve;
                    img.onerror = reject;
                    img.src = base64Data;
                });
                rctx.drawImage(img, 0, 0, resizedCanvas.width, resizedCanvas.height);
                base64Data = resizedCanvas.toDataURL('image/png');
                finalWidth = resizedCanvas.width;
                finalHeight = resizedCanvas.height;
                // Release memory
                resizedCanvas.width = 0;
                resizedCanvas.height = 0;
                img.src = '';
            }
        }

        // Generate unique ID for later retrieval via screenshot_by_id (data persisted in chat messages)
        var screenshotId = 'ss_' + (++_screenshotIdCounter) + '_' + Date.now();
        var screenshotName = args.name || null;
        var screenshotTimestamp = Date.now();

        return {
            success: true,
            screenshot_id: screenshotId,
            message: 'Screenshot captured: ' + captureDescription,
            dimensions: finalWidth + 'x' + finalHeight,
            size_bytes: Math.round(base64Data.length * 0.75),
            note: 'The screenshot image is now attached to this conversation. I can see it and will analyze the visual content. Use screenshot_id "' + screenshotId + '" with screenshot_by_id tool or executeTool("screenshot_by_id", {id: "' + screenshotId + '"}) in widgets/js_eval to retrieve the image data.',
            _screenshotMessage: {
                role: 'screenshot',
                base64: base64Data,
                name: screenshotName,
                description: captureDescription,
                url: (target === 'browser' ? currentIframeUrl : null) || null,
                timestamp: screenshotTimestamp,
                width: finalWidth,
                height: finalHeight,
                screenshot_id: screenshotId
            }
        };

    } catch (e) {
        return { success: false, error: 'Screenshot capture failed: ' + e.message };
    }
}

// =============================================
// SCREENSHOT BY ID - Retrieve stored screenshot data
// =============================================

function executeScreenshotById(args) {
    var id = args.id;
    if (!id) {
        return { success: false, error: 'id is required' };
    }
    // Search two places: chat.screenshots map (widget/js_eval origin) and chat.messages (agent origin)
    var screenshot = null;
    var availableIds = [];
    var chatIds = Object.keys(chats);
    for (var ci = 0; ci < chatIds.length; ci++) {
        var c = chats[chatIds[ci]];
        // Check chat.screenshots map first (from widget/js_eval bridge)
        if (c.screenshots) {
            if (c.screenshots[id]) {
                screenshot = c.screenshots[id];
                break;
            }
            var mapIds = Object.keys(c.screenshots);
            for (var si = 0; si < mapIds.length; si++) availableIds.push(mapIds[si]);
        }
        // Check chat.messages (from agent take_screenshot calls)
        if (c.messages) {
            for (var mi = 0; mi < c.messages.length; mi++) {
                var msg = c.messages[mi];
                if (msg.role === 'screenshot' && msg.screenshot_id) {
                    if (msg.screenshot_id === id) {
                        screenshot = msg;
                        break;
                    }
                    availableIds.push(msg.screenshot_id);
                }
            }
            if (screenshot) break;
        }
    }
    if (!screenshot) {
        if (availableIds.length === 0) {
            return { success: false, error: 'Screenshot not found: ' + id + '. No screenshots have been taken yet.' };
        }
        return { success: false, error: 'Screenshot not found: ' + id + '. Available screenshot IDs: ' + availableIds.join(', ') };
    }
    return {
        success: true,
        id: id,
        base64: screenshot.base64,
        name: screenshot.name || null,
        width: screenshot.width || null,
        height: screenshot.height || null,
        timestamp: screenshot.timestamp || null,
        description: screenshot.description || null
    };
}

// =============================================
// HTML WIDGET TOOL - Display interactive widgets inline
// =============================================

function executeHtmlWidget(args, messageIndex) {
    var title = args.title || 'Widget';
    var html = args.html || '';
    var height = args.height || '400px';
    var width = args.width || '400px';

    if (!html) {
        return { success: false, error: 'html content is required' };
    }

    // Use activeStreamingChatId if available (preserves correct chat during navigation)
    // Otherwise fall back to currentChatId
    var widgetChatId = activeStreamingChatId || currentChatId;

    // Create widget object
    // The tool result message will be added at the current messages length after this returns
    var chat = chats[widgetChatId];
    var toolResultMsgIndex = chat ? chat.messages.length : -1;

    var widgetId = 'widget_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    var widget = {
        id: widgetId,
        title: title,
        html: html,
        height: height,
        width: width,
        createdAt: Date.now(),
        msgIndex: toolResultMsgIndex,
        chatId: widgetChatId
    };

    // Store widget in chat object for persistence
    if (!chat.widgets) {
        chat.widgets = [];
    }
    chat.widgets.push(widget);

    // Sync in-memory cache with chat.widgets (they should be the same reference)
    chatWidgets[widgetChatId] = chat.widgets;

    // Ensure chat is saved with the widget (remove temporary flag if present)
    delete chat.isTemporary;
    saveChatsToStorage();

    // If this is a regeneration, update the dashboard widget with new HTML
    if (pendingWidgetRegeneration && dashboardWidgets[pendingWidgetRegeneration]) {
        var dashWidget = dashboardWidgets[pendingWidgetRegeneration];
        dashWidget.html = html;
        dashWidget.title = title;
        dashWidget.chatId = widgetChatId;
        dashWidget.msgIndex = toolResultMsgIndex;
        dashWidget.error = null;
        saveDashboardWidget(dashWidget);
        pendingWidgetRegeneration = null;
    }

    // Update sidebar widget list
    renderWidgetSidebar();

    return { 
        success: true, 
        message: 'Widget "' + title + '" created successfully',
        widgetId: widgetId,
        _debug_hint: 'To debug this widget, use iframe_tool with widget_id="' + widgetId + '". Actions: get_visible_text (extract text), get_dom (get HTML), click (click elements), fill (fill inputs). For visual analysis, use take_screenshot tool.'
    };
}

function getWidgetsForChat(chatId) {
    // First check in-memory cache
    if (chatWidgets[chatId] && chatWidgets[chatId].length > 0) {
        return chatWidgets[chatId];
    }
    // Fall back to chat object (persisted widgets)
    var chat = chats[chatId];
    if (chat && chat.widgets && chat.widgets.length > 0) {
        // Populate cache from persisted data
        chatWidgets[chatId] = chat.widgets;
        return chat.widgets;
    }
    return [];
}

function getWidgetById(widgetId) {
    // First check in-memory cache
    var allCachedWidgets = Object.values(chatWidgets).flat();
    var found = allCachedWidgets.find(function(w) { return w.id === widgetId; });
    if (found) return found;

    // Fall back to searching persisted widgets in all chats
    var chatIds = Object.keys(chats);
    for (var i = 0; i < chatIds.length; i++) {
        var chat = chats[chatIds[i]];
        if (chat.widgets) {
            var widget = chat.widgets.find(function(w) { return w.id === widgetId; });
            if (widget) {
                // Populate cache
                if (!chatWidgets[chatIds[i]]) chatWidgets[chatIds[i]] = [];
                if (!chatWidgets[chatIds[i]].find(function(w) { return w.id === widgetId; })) {
                    chatWidgets[chatIds[i]] = chat.widgets;
                }
                return widget;
            }
        }
    }
    return null;
}

function toggleWidgetRunning(widgetId, event) {
    if (event) event.stopPropagation();
    // Find the widget object and check persisted deactivated state
    var widget = getWidgetById(widgetId);
    if (!widget && dashboardWidgets[widgetId]) widget = dashboardWidgets[widgetId];
    if (!widget) return;

    var isDeactivated = widget.deactivated;

    // Find the widget container (inline or dashboard)
    var container = document.getElementById('widget-content-' + widgetId)
        || document.getElementById('dashboard-widget-content-' + widgetId);

    if (isDeactivated) {
        // Activate: clear deactivated flag and re-render
        widget.deactivated = false;
        if (container) {
            container.innerHTML = '';
            renderWidgetInContainer(widget, container);
        }
    } else {
        // Deactivate: kill iframe and persist
        widget.deactivated = true;
        if (container) {
            var iframe = container.querySelector('iframe');
            if (iframe) {
                iframe.srcdoc = '';
                iframe.remove();
            }
            container.innerHTML = '<div style="padding:20px;color:var(--text-secondary);text-align:center;font-size:13px;">Widget deactivated.</div>';
        }
    }

    // Persist deactivated state
    saveChatsToStorage();

    // Update all toggle buttons for this widget
    var buttons = document.querySelectorAll('.widget-stop-btn[data-widget-id="' + widgetId + '"]');
    buttons.forEach(function(btn) {
        btn.innerHTML = isDeactivated ? UI_ICONS.stop : UI_ICONS.play;
        btn.title = isDeactivated ? 'Deactivate Widget' : 'Activate Widget';
    });
}

function renderWidgetInContainer(widget, container, options) {
    options = options || {};
    var isFullscreen = options.fullscreen || false;
    // Create iframe for complete CSS and script isolation
    var iframe = document.createElement('iframe');
    iframe.className = 'widget-iframe';
    iframe.style.cssText = 'width:100%; border:none; display:block; overflow:hidden;';
    iframe.setAttribute('scrolling', 'no');

    var isThumbnail = container.closest('.widgets-container') !== null;

    container.appendChild(iframe);

    // Write widget HTML to iframe with executeTool bridge injected
    var iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
    try {
        iframeDoc.open();
        iframeDoc.write(injectWidgetBridge(widget.html, widget.title));
        iframeDoc.close();
    } catch (e) {
        console.error('Widget render error (' + widget.title + '):', e.message);
        iframeDoc.open();
        iframeDoc.write('<body style="margin:12px;font-family:sans-serif;color:#e88"><b>Widget failed to render</b><br><small>' + e.message + '</small></body>');
        iframeDoc.close();
    }

    // Thumbnail mode: pure CSS scaled preview, no auto-resize
    if (isThumbnail) {
        iframe.style.cssText = 'position:absolute;top:0;left:0;border:none;transform:scale(0.4);transform-origin:top left;width:250%;height:250%;';
        return iframe;
    }

    // Set initial height from last known value to prevent layout shift on re-render
    if (!isFullscreen && widget.lastHeight > 0) {
        iframe.style.height = widget.lastHeight + 'px';
    }

    // Auto-resize iframe to fit content
    var isResizing = false; // Prevent infinite loop from MutationObserver
    function resizeIframe() {
        if (isFullscreen || isResizing) return;
        isResizing = true;
        try {
            var body = iframe.contentDocument.body;
            if (body) {
                body.style.margin = '0';
                body.style.overflow = 'hidden';
                var h = body.scrollHeight;
                if (h > 0) {
                    iframe.style.height = h + 'px';
                    widget.lastHeight = h; // Persist for next re-render
                }
            }
        } catch (e) {
            // Ignore cross-origin iframe access errors
        }
        isResizing = false;
    }

    iframe.onload = function() {
        resizeIframe();
        setTimeout(resizeIframe, 100);
        setTimeout(resizeIframe, 500);
        try {
            // Only observe childList and subtree, NOT attributes to avoid infinite loop
            // when resizeIframe sets body.style properties
            new MutationObserver(resizeIframe).observe(iframe.contentDocument.body, {
                childList: true, subtree: true, attributes: false
            });
        } catch (e) {
            // Ignore cross-origin iframe access errors
        }
    };

    // Register resize function globally so sidebar toggles can call it
    if (!window.__widgetResizeFns) window.__widgetResizeFns = [];
    window.__widgetResizeFns.push(resizeIframe);

    // Resize on window resize
    window.addEventListener('resize', resizeIframe);

    // Store cleanup function on iframe for proper resource cleanup when removed
    iframe.__widgetCleanup = function() {
        window.removeEventListener('resize', resizeIframe);
        var idx = window.__widgetResizeFns ? window.__widgetResizeFns.indexOf(resizeIframe) : -1;
        if (idx > -1) window.__widgetResizeFns.splice(idx, 1);
    };

    // For fullscreen, fill the container
    if (isFullscreen) {
        iframe.style.height = '100%';
        iframe.style.flex = '1';
        iframe.removeAttribute('scrolling');
        iframe.style.overflow = 'auto';
    }

    return iframe;
}

function toggleChatWidgetExpand(widgetId, event) {
    if (event) {
        event.stopPropagation();
        event.preventDefault();
    }

    var widgetEl = document.getElementById('widget-' + widgetId);
    if (!widgetEl) {
        console.warn('Widget element not found:', widgetId);
        return;
    }

    var content = widgetEl.querySelector('.widget-content');
    if (!content) {
        console.warn('Widget content not found for:', widgetId);
        return;
    }

    // Toggle collapsed state (widgets are expanded by default)
    var isCollapsed = content.classList.toggle('collapsed');
    widgetEl.classList.toggle('collapsed', isCollapsed);

    // Persist collapsed state on the widget object so it survives re-renders
    var widget = getWidgetById(widgetId);
    if (widget) widget.collapsed = isCollapsed;

    // Update button icon - show expand when collapsed, collapse when expanded
    var expandBtn = widgetEl.querySelector('.widget-expand-btn');
    if (expandBtn) {
        expandBtn.innerHTML = isCollapsed
            ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg>'
            : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 14h6v6M14 4h6v6M10 14l-7 7M21 3l-7 7"/></svg>';
        expandBtn.title = isCollapsed ? 'Expand' : 'Collapse';
    }
}

function openWidgetFullscreen(widgetId, event) {
    if (event) {
        event.stopPropagation();
        event.preventDefault();
    }
    var widget = getWidgetById(widgetId);
    if (!widget) return;

    // Remove any existing fullscreen overlay first
    closeWidgetFullscreen();

    // Create fullscreen overlay
    var overlay = document.createElement('div');
    overlay.className = 'widget-fullscreen-overlay';
    overlay.id = 'widget-fullscreen-overlay';

    var modal = document.createElement('div');
    modal.className = 'widget-fullscreen-modal';

    // Header with all control icons
    var header = document.createElement('div');
    header.className = 'widget-fullscreen-header';
    var isOnDash = dashboardWidgets[widget.id] ? true : false;
    var dashBtn = isOnDash
        ? '<button class="widget-ctrl-btn widget-dashboard-btn on-dashboard" onclick="removeWidgetFromDashboard(\'' + widget.id + '\', event);closeWidgetFullscreen()" title="Remove from Dashboard">' + UI_ICONS.pinFilled + '</button>'
        : '<button class="widget-ctrl-btn widget-dashboard-btn" onclick="addWidgetToDashboard(\'' + widget.id + '\', event);closeWidgetFullscreen()" title="Add to Dashboard">' + UI_ICONS.pin + '</button>';
    header.innerHTML = '<span class="widget-icon">' + UI_ICONS.widget + '</span>' +
        '<span class="widget-title">' + escapeHtml(widget.title) + '</span>' +
        '<div class="widget-modal-controls">' +
            '<button class="widget-ctrl-btn widget-stop-btn" onclick="toggleWidgetRunning(\'' + widget.id + '\', event);closeWidgetFullscreen()" title="' + (widget.deactivated ? 'Activate Widget' : 'Deactivate Widget') + '">' + (widget.deactivated ? UI_ICONS.play : UI_ICONS.stop) + '</button>' +
            '<button class="widget-ctrl-btn" onclick="closeWidgetFullscreen();openWidgetInIframePanel(\'' + widget.id + '\')" title="Open in Panel">' + UI_ICONS.panelRight + '</button>' +
            dashBtn +
            '<button class="widget-ctrl-btn" onclick="closeWidgetFullscreen();editWidgetCode(\'' + widget.id + '\')" title="Edit Code">' + UI_ICONS.edit + '</button>' +
            '<button class="widget-close-btn" onclick="closeWidgetFullscreen()">' + UI_ICONS.close + '</button>' +
        '</div>';

    // Content
    var content = document.createElement('div');
    content.className = 'widget-fullscreen-content';

    modal.appendChild(header);
    modal.appendChild(content);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    // Render widget
    renderWidgetInContainer(widget, content, { fullscreen: true });

    // Close on backdrop click
    overlay.addEventListener('click', function(e) {
        if (e.target === overlay) closeWidgetFullscreen();
    });

}

function closeWidgetFullscreen() {
    var overlay = document.getElementById('widget-fullscreen-overlay');
    if (overlay) overlay.remove();
    expandedWidgetId = null;
}

// Edit widget code manually
function editWidgetCode(widgetId) {
    var widget = getWidgetById(widgetId);
    if (!widget) { showSnackbar('Widget not found', 'error'); return; }

    // Create modal for editing
    var overlay = document.createElement('div');
    overlay.className = 'widget-modal-overlay';
    overlay.id = 'widget-edit-overlay';

    var modal = document.createElement('div');
    modal.className = 'widget-modal';
    modal.style.width = '80vw';
    modal.style.height = '80vh';

    var header = document.createElement('div');
    header.className = 'widget-modal-header';
    header.innerHTML = '<span class="widget-icon">' + UI_ICONS.edit + '</span>' +
        '<span class="widget-title">Edit Widget: ' + escapeHtml(widget.title) + '</span>' +
        '<div class="widget-modal-controls">' +
            '<button class="widget-ctrl-btn primary" onclick="saveWidgetCodeEdit(\'' + widget.id + '\')" title="Save">' + UI_ICONS.save + '</button>' +
            '<button class="widget-close-btn" onclick="closeWidgetCodeEdit()">' + UI_ICONS.close + '</button>' +
        '</div>';

    var content = document.createElement('div');
    content.className = 'widget-modal-content';
    content.style.height = 'calc(100% - 50px)';
    content.innerHTML = '<textarea id="widget-code-editor" style="width:100%;height:100%;font-family:monospace;font-size:13px;padding:12px;border:none;resize:none;box-sizing:border-box;">' + escapeHtml(widget.html || '') + '</textarea>';

    modal.appendChild(header);
    modal.appendChild(content);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    // Focus editor
    setTimeout(function() {
        var editor = document.getElementById('widget-code-editor');
        if (editor) editor.focus();
    }, 100);

    // Close on backdrop click
    overlay.addEventListener('click', function(e) {
        if (e.target === overlay) closeWidgetCodeEdit();
    });
}

function closeWidgetCodeEdit() {
    var overlay = document.getElementById('widget-edit-overlay');
    if (overlay) overlay.remove();
}

async function saveWidgetCodeEdit(widgetId) {
    var editor = document.getElementById('widget-code-editor');
    if (!editor) return;

    var widget = getWidgetById(widgetId);
    if (!widget) { showSnackbar('Widget not found', 'error'); return; }

    widget.html = editor.value;
    widget.updatedAt = Date.now();

    // Save to appropriate store
    if (dashboardWidgets[widgetId]) {
        await saveDashboardWidget(widget);
    }
    if (chatWidgets[currentChatId]) {
        var idx = chatWidgets[currentChatId].findIndex(function(w) { return w.id === widgetId; });
        if (idx >= 0) {
            chatWidgets[currentChatId][idx] = widget;
            await saveChatsToStorage();
        }
    }

    closeWidgetCodeEdit();
    renderMessages();
    renderDashboard();
    showSnackbar('Widget saved', 'success');
}

function openWidgetModal(widgetId) {
    var widget = getWidgetById(widgetId);
    if (!widget) return;

    // Create modal overlay
    var overlay = document.createElement('div');
    overlay.className = 'widget-modal-overlay';
    overlay.id = 'widget-modal-overlay';

    var modal = document.createElement('div');
    modal.className = 'widget-modal';
    modal.style.width = widget.width === '100%' ? '80%' : widget.width;

    // Header
    var header = document.createElement('div');
    header.className = 'widget-modal-header';
    header.innerHTML = '<span class="widget-icon">' + UI_ICONS.widget + '</span>' +
        '<span class="widget-title">' + escapeHtml(widget.title) + '</span>' +
        '<div class="widget-modal-controls">' +
            '<button class="widget-ctrl-btn" onclick="closeWidgetModal();openWidgetFullscreen(\'' + widget.id + '\')" title="Fullscreen">' + UI_ICONS.maximize + '</button>' +
            '<button class="widget-close-btn" onclick="closeWidgetModal()">' + UI_ICONS.close + '</button>' +
        '</div>';

    // Content
    var content = document.createElement('div');
    content.className = 'widget-modal-content';
    content.style.height = widget.height || '300px';

    modal.appendChild(header);
    modal.appendChild(content);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    // Render widget
    renderWidgetInContainer(widget, content);

    // Close on backdrop click
    overlay.addEventListener('click', function(e) {
        if (e.target === overlay) closeWidgetModal();
    });
}

function closeWidgetModal() {
    var overlay = document.getElementById('widget-modal-overlay');
    if (overlay) overlay.remove();
}

function renderWidgetSidebar() {
    var widgets = getWidgetsForChat(currentChatId);
    var container = document.getElementById('widget-sidebar-list');
    if (!container) return;

    if (widgets.length === 0) {
        container.innerHTML = '<div class="widget-sidebar-empty">No widgets yet</div>';
        return;
    }

    var html = '';
    widgets.forEach(function(widget) {
        var isOnDashboard = dashboardWidgets && dashboardWidgets[widget.id];
        var dashboardBtnClass = isOnDashboard ? 'widget-sidebar-btn on-dashboard' : 'widget-sidebar-btn';
        var dashboardBtnTitle = isOnDashboard ? 'Remove from Dashboard' : 'Add to Dashboard';
        var dashboardBtnIcon = isOnDashboard ? UI_ICONS.pinFilled : UI_ICONS.pin;
        html += '<div class="widget-sidebar-item" onclick="scrollToWidget(\'' + widget.id + '\')">' +
            '<span class="widget-sidebar-icon">' + UI_ICONS.widget + '</span>' +
            '<span class="widget-sidebar-title">' + escapeHtml(widget.title) + '</span>' +
            '<div class="widget-sidebar-actions">' +
            '<button class="widget-sidebar-btn" onclick="event.stopPropagation();showWidgetInPanel(\'' + widget.id + '\')" title="Show in Panel">' + UI_ICONS.panelRight + '</button>' +
            '<button class="' + dashboardBtnClass + '" onclick="event.stopPropagation();toggleWidgetOnDashboard(\'' + widget.id + '\')" title="' + dashboardBtnTitle + '">' + dashboardBtnIcon + '</button>' +
            '<button class="widget-sidebar-btn" onclick="event.stopPropagation();openWidgetFullscreen(\'' + widget.id + '\')" title="Fullscreen">' + UI_ICONS.maximize + '</button>' +
            '</div>' +
        '</div>';
    });

    container.innerHTML = html;
}

function scrollToWidget(widgetId) {
    var widgetEl = document.getElementById('widget-' + widgetId);
    if (widgetEl) {
        widgetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        // Briefly highlight the widget
        widgetEl.classList.add('highlight');
        setTimeout(function() {
            widgetEl.classList.remove('highlight');
        }, 1500);
    } else {
        // Widget not in view, open modal instead
        openWidgetModal(widgetId);
    }
}

function getWidgetHtmlForMessage(msgIndex) {
    var widgets = getWidgetsForChat(currentChatId);
    var msgWidgets = widgets.filter(function(w) { return w.msgIndex === msgIndex; });

    if (msgWidgets.length === 0) return '';

    var html = '';
    msgWidgets.forEach(function(widget) {
        var isOnDashboard = dashboardWidgets[widget.id] ? true : false;
        var dashboardBtn = isOnDashboard 
            ? '<button class="widget-ctrl-btn widget-dashboard-btn on-dashboard" onclick="removeWidgetFromDashboard(\'' + widget.id + '\', event)" title="Remove from Dashboard">' + UI_ICONS.pinFilled + '</button>'
            : '<button class="widget-ctrl-btn widget-dashboard-btn" onclick="addWidgetToDashboard(\'' + widget.id + '\', event)" title="Add to Dashboard">' + UI_ICONS.pin + '</button>';

        var isCollapsed = widget.collapsed;
        var collapsedClass = isCollapsed ? ' collapsed' : '';
        var expandIcon = isCollapsed
            ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg>'
            : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 14h6v6M14 4h6v6M10 14l-7 7M21 3l-7 7"/></svg>';
        var expandTitle = isCollapsed ? 'Expand' : 'Collapse';
        html += '<div class="widget-inline' + collapsedClass + '" id="widget-' + widget.id + '" data-widget-id="' + widget.id + '">' +
            '<div class="widget-header">' +
                '<span class="widget-icon">' + UI_ICONS.widget + '</span>' +
                '<span class="widget-title">' + escapeHtml(widget.title) + '</span>' +
                '<div class="widget-controls">' +
                    dashboardBtn +
                    '<button class="widget-ctrl-btn widget-stop-btn" data-widget-id="' + widget.id + '" onclick="toggleWidgetRunning(\'' + widget.id + '\', event)" title="' + (widget.deactivated ? 'Activate Widget' : 'Deactivate Widget') + '">' +
                        (widget.deactivated ? UI_ICONS.play : UI_ICONS.stop) +
                    '</button>' +
                    '<button class="widget-ctrl-btn widget-edit-btn" onclick="editWidgetCode(\'' + widget.id + '\')" title="Edit Code">' +
                        UI_ICONS.edit +
                    '</button>' +
                    '<button class="widget-ctrl-btn widget-panel-btn" onclick="openWidgetInIframePanel(\'' + widget.id + '\', false, event)" title="Open in Panel">' +
                        UI_ICONS.panelRight +
                    '</button>' +
                    '<button class="widget-ctrl-btn widget-expand-btn" onclick="toggleChatWidgetExpand(\'' + widget.id + '\', event)" title="' + expandTitle + '">' +
                        expandIcon +
                    '</button>' +
                    '<button class="widget-ctrl-btn widget-fullscreen-btn" onclick="openWidgetFullscreen(\'' + widget.id + '\', event)" title="Fullscreen">' +
                        UI_ICONS.maximize +
                    '</button>' +
                '</div>' +
            '</div>' +
            '<div class="widget-content' + collapsedClass + '" id="widget-content-' + widget.id + '"></div>' +
        '</div>';
    });

    return html;
}

function initializeWidgetsInView() {
    var widgets = getWidgetsForChat(currentChatId);
    widgets.forEach(function(widget) {
        var container = document.getElementById('widget-content-' + widget.id);
        if (container && !container.hasChildNodes()) {
            if (widget.deactivated) {
                container.innerHTML = '<div style="padding:20px;color:var(--text-secondary);text-align:center;font-size:13px;">Widget deactivated.</div>';
            } else {
                renderWidgetInContainer(widget, container);
            }
        }
    });
}

async function executeGetSkill(args) {
    var skillId = args.skill_id;
    var action = args.action || 'get';

    if (!skillId) return { success: false, error: 'skill_id is required' };
    var skill = skills[skillId];
    if (!skill) return { success: false, error: 'Skill not found: ' + skillId };

    if (action === 'read_file') {
        var filename = args.filename;
        if (!filename) return { success: false, error: 'filename is required for read_file action' };
        var asset = await getSkillAsset(skillId, filename);
        if (!asset) return { success: false, error: 'File not found: ' + filename };
        return { success: true, filename: asset.filename, type: asset.type, content: asset.content };
    }

    // Default action: get skill with file list
    var assets = await getSkillAssets(skillId);
    var fileList = assets.map(function(a) { return { filename: a.filename, type: a.type }; });

    return { 
        success: true, 
        skill: { 
            id: skill.id, 
            title: skill.title, 
            content: skill.body, 
            tags: skill.tags || [],
            is_active: !!activeSkills[skillId]
        },
        files: fileList,
        hint: fileList.length > 0 ? 'Use get_skill with action="read_file" and filename to read specific files' : null
    };
}

async function executeManageSkill(args) {
    var action = args.action;
    var skillId = args.skill_id;

    if (action === 'create') {
        var name = args.name || 'untitled-skill';
        var description = args.description || '';
        var body = args.body || '';

        // Generate ID from name
        var id = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
        if (!id) id = 'skill-' + Date.now();
        if (skills[id]) id = id + '-' + Date.now();

        await saveSkill({
            id: id,
            name: name,
            description: description,
            body: body,
            createdAt: Date.now(),
            updatedAt: Date.now()
        });

        renderSkillsList();
        return { success: true, skill_id: id, message: 'Skill created: ' + name };
    }

    if (!skillId) return { success: false, error: 'skill_id is required for action: ' + action };
    var skill = skills[skillId];
    if (!skill && action !== 'create') return { success: false, error: 'Skill not found: ' + skillId };

    if (action === 'update') {
        if (args.name) skill.name = args.name;
        if (args.description !== undefined) skill.description = args.description;
        if (args.body !== undefined) skill.body = args.body;
        skill.updatedAt = Date.now();
        await saveSkill(skill);
        renderSkillsList();
        return { success: true, message: 'Skill updated: ' + (skill.name || skill.id) };
    }

    if (action === 'add_file' || action === 'update_file') {
        var filename = args.filename;
        var content = args.file_content;
        if (!filename) return { success: false, error: 'filename is required' };
        if (content === undefined) return { success: false, error: 'file_content is required' };

        var ext = filename.split('.').pop().toLowerCase();
        if (!['xml', 'md', 'js'].includes(ext)) {
            return { success: false, error: 'File type must be .xml, .md, or .js' };
        }

        await saveSkillAsset(skillId, filename, ext, content);

        // If skill is active and it's a JS file, reload tools immediately
        // XML files require reactivation to upload to instance
        if (activeSkills[skillId] && ext === 'js') {
            await loadSkillTools(skillId);
        }

        var msg = 'File ' + (action === 'add_file' ? 'added' : 'updated') + ': ' + filename;
        if (activeSkills[skillId] && ext === 'xml') {
            msg += '. Deactivate and reactivate the skill to upload XML to instance.';
        }

        return { success: true, message: msg };
    }

    if (action === 'delete_file') {
        var filename = args.filename;
        if (!filename) return { success: false, error: 'filename is required' };
        var delExt = filename.split('.').pop().toLowerCase();
        await deleteSkillAsset(skillId, filename);

        // Reload tools if skill is active and it was a JS file
        if (activeSkills[skillId] && delExt === 'js') {
            await loadSkillTools(skillId);
        }

        var msg = 'File deleted: ' + filename;
        if (activeSkills[skillId] && delExt === 'xml') {
            msg += '. Deactivate and reactivate the skill to revert XML changes.';
        }

        return { success: true, message: msg };
    }

    if (action === 'activate') {
        var result = await activateSkill(skillId);
        return result;
    }

    if (action === 'deactivate') {
        var result = await deactivateSkill(skillId);
        return result;
    }

    return { success: false, error: 'Unknown action: ' + action };
}

async function callLLMStreaming(chatMessages, onThinking, onContent, onToolCall, onDone, onStreamStatus) {
    var apiMsgs = buildAPIMessages(chatMessages);
    return callOpenRouterStreaming(currentProvider, apiMsgs, onThinking, onContent, onToolCall, onDone, onStreamStatus);
}

async function callOpenRouterStreaming(currentProvider, messages, onThinking, onContent, onToolCall, onDone, onStreamStatus) {
    var provider = getProviderById(currentProvider);

    if (!provider) {
        throw new Error('Provider "' + currentProvider + '" not found. Please select a valid model in settings.');
    }

    // For Anthropic: normalize ALL messages to array format, then add cache_control at branching points
    // Cache points: system prompt + last 2 user messages + last message
    // This allows branching without cache invalidation
    var messagesWithCache = messages.map(function(m) { return Object.assign({}, m); });
    var modelLower = provider.model.toLowerCase();
    var isAnthropic = (modelLower.includes('anthropic') || modelLower.includes('claude'));
    if (isAnthropic && messagesWithCache.length > 0) {
        // Step 1: Normalize ALL messages to array format for consistent structure
        for (var j = 0; j < messagesWithCache.length; j++) {
            var m = messagesWithCache[j];
            if (typeof m.content === 'string' && m.content.length > 0) {
                messagesWithCache[j] = Object.assign({}, m, {
                    content: [{ type: 'text', text: m.content }]
                });
            }
        }

        // Step 2: Cache last 2 user messages + last block
        var cacheIndices = [];

        // Find last 2 user messages
        var userMsgCount = 0;
        for (var i = messagesWithCache.length - 1; i >= 0 && userMsgCount < 2; i--) {
            if (messagesWithCache[i].role === 'user') {
                cacheIndices.push(i);
                userMsgCount++;
            }
        }

        // Always cache the last message
        if (messagesWithCache.length > 0) {
            var lastIdx = messagesWithCache.length - 1;
            if (cacheIndices.indexOf(lastIdx) === -1) {
                cacheIndices.push(lastIdx);
            }
        }

        // Apply cache_control to selected indices
        cacheIndices.forEach(function(idx) {
            var msg = messagesWithCache[idx];
            if (Array.isArray(msg.content) && msg.content.length > 0) {
                var contentCopy = msg.content.map(function(c) { return Object.assign({}, c); });
                contentCopy[contentCopy.length - 1].cache_control = { type: 'ephemeral' };
                messagesWithCache[idx] = Object.assign({}, msg, { content: contentCopy });
            }
        });
    }

    // Build system message fresh each time (not stored in chat.messages)
    // This ensures branched chats work even after browser reload when cache expires
    var systemPromptText = getSystemPromptWithContext();
    var systemMessage;
    if (isAnthropic) {
        // For Anthropic: use array format with cache_control on the system prompt
        systemMessage = {
            role: 'system',
            content: [{ type: 'text', text: systemPromptText, cache_control: { type: 'ephemeral' } }]
        };
    } else {
        systemMessage = { role: 'system', content: systemPromptText };
    }

    var requestBody = {
        model: provider.model,
        messages: [systemMessage].concat(messagesWithCache),
        tools: getEnabledTools(),
        tool_choice: 'auto',
        parallel_tool_calls: true,
        stream: true,
        temperature: 1,
        //top_p: 0.95,
        //top_k: 40,
        max_tokens: provider.maxTokens,
        usage: { include: true }  // Required to get cache info in response
    };
    // For Anthropic models, disable transforms to pass through cache_control
    if (isAnthropic) {
        requestBody.transforms = [];
    }
    // Enable reasoning - OpenRouter handles the format normalization
    if (provider.thinkingBudget) {
        requestBody.reasoning = { max_tokens: provider.thinkingBudget };
    }
    if (provider.effort) {
        if (!requestBody.reasoning) requestBody.reasoning = {};
        requestBody.reasoning.effort = provider.effort;
    }
	if (provider.provider) {
		requestBody.provider = {
			only: [provider.provider],
			//allow_fallbacks: false
		};
	}

    // If messages contain PDF files, tell OpenRouter to use native file handling
    // (avoids format conversion conflicts between type:'file' and tool_result blocks)
    var hasPdfContent = messagesWithCache.some(function(m) {
        return Array.isArray(m.content) && m.content.some(function(c) { return c.type === 'file'; });
    });
    if (hasPdfContent) {
        requestBody.plugins = [{ id: 'file-parser', pdf: { engine: 'native' } }];
    }

    // Store request body in metrics for debugging
    lastRequestMetrics.requestBody = requestBody;

    var res = await fetch(provider.endpoint, {
        method: 'POST',
        headers: {
            'Authorization': 'Bearer ' + provider.apiKey,
            'Content-Type': 'application/json',
            'HTTP-Referer': window.location.href
        },
        body: JSON.stringify(requestBody)
    });

    if (!res.ok) {
        var errorText = await res.text();
        var requestBodyStr = JSON.stringify(requestBody);
        console.error('API Error Response:', errorText);
        console.error('Request size:', Math.round(requestBodyStr.length / 1024) + 'KB, messages:', requestBody.messages.length);
        console.error('Provider config:', JSON.stringify({ model: provider.model, provider: provider.provider, endpoint: provider.endpoint }));
        console.error('Request provider setting:', JSON.stringify(requestBody.provider));
        // Log last 5 message roles to help debug
        var lastMsgs = requestBody.messages.slice(-5).map(function(m) {
            return { role: m.role, hasToolCalls: !!m.tool_calls, hasContent: !!(m.content && (typeof m.content === 'string' ? m.content.length : m.content.length) > 0), hasReasoning: !!m.reasoning_details };
        });
        console.error('Last 5 messages:', JSON.stringify(lastMsgs));
        try {
            var errorData = JSON.parse(errorText);
            // Try to get detailed error from metadata.raw first
            var rawError = errorData.error?.metadata?.raw;
            if (rawError) {
                try {
                    var rawParsed = JSON.parse(rawError);
                    throw new Error(rawParsed.message || rawError);
                } catch (parseErr) {
                    throw new Error(rawError);
                }
            }
            throw new Error(errorData.error?.message || 'API request failed');
        } catch (e) {
            if (e.message && !e.message.includes('JSON')) throw e;
            throw new Error('API request failed: ' + errorText);
        }
    }

    var reader = res.body.getReader();
    var decoder = new TextDecoder();
    var buffer = '';
    var thinking = '';
    var content = '';
    var toolCalls = [];
    var toolCallBuffers = {};
    var reasoningDetails = []; // Preserve for API continuity
    var reasoningDetailsMap = {}; // Merge streaming fragments by index
    var isAnthropicModel = modelLower.includes('anthropic') || modelLower.includes('claude');

    var chunkCount = 0;
    var lastUpdateTime = Date.now();

    var streamDone = false;
    while (!streamDone) {
        var result = await reader.read();
        streamDone = result.done;

        // Decode chunk
        var chunk = decoder.decode(result.value, { stream: !streamDone });
        buffer += chunk;

        var lines = buffer.split('\n');
        buffer = streamDone ? '' : (lines.pop() || '');

        for (var i = 0; i < lines.length; i++) {
            var line = lines[i].trim();
            if (!line || line === 'data: [DONE]') continue;
            if (!line.startsWith('data: ')) continue;

            // Skip OpenRouter processing placeholder messages
            if (line.includes('OPENROUTER PROCESSING') || line.includes(': OPENROUTER')) {
                chunkCount++;
                // Notify about stream activity even during processing
                if (onStreamStatus && Date.now() - lastUpdateTime > 500) {
                    onStreamStatus('processing', chunkCount);
                    lastUpdateTime = Date.now();
                }
                continue;
            }

            var jsonStr = line.substring(6);

            try {
                var data = JSON.parse(jsonStr);

                // Detect error responses in stream (backend errors sent mid-stream)
                if (data.error) {
                    var errMsg = data.error.message || (typeof data.error === 'string' ? data.error : JSON.stringify(data.error));
                    throw new Error(errMsg);
                }

                // Capture usage data from OpenRouter
                if (data.usage) {
                    lastRequestMetrics = lastRequestMetrics || {};
                    if (data.usage.prompt_tokens) lastRequestMetrics.input_tokens = data.usage.prompt_tokens;
                    if (data.usage.completion_tokens) lastRequestMetrics.output_tokens = data.usage.completion_tokens;
                    if (data.usage.total_tokens) lastRequestMetrics.total_tokens = data.usage.total_tokens;
                    // Capture cache info from OpenRouter (Anthropic models via OpenRouter)
                    if (data.usage.cache_creation_input_tokens) lastRequestMetrics.cache_creation_tokens = data.usage.cache_creation_input_tokens;
                    if (data.usage.cache_read_input_tokens) lastRequestMetrics.cache_read_tokens = data.usage.cache_read_input_tokens;
                    // Also check prompt_tokens_details for cache info
                    if (data.usage.prompt_tokens_details) {
                        if (data.usage.prompt_tokens_details.cached_tokens) lastRequestMetrics.cache_read_tokens = data.usage.prompt_tokens_details.cached_tokens;
                        if (data.usage.prompt_tokens_details.cache_write_tokens) lastRequestMetrics.cache_write_tokens = data.usage.prompt_tokens_details.cache_write_tokens;
                    }
                    // Capture cost
                    if (data.usage.cost !== undefined) lastRequestMetrics.cost = data.usage.cost;
                    // Capture reasoning tokens from completion_tokens_details
                    if (data.usage.completion_tokens_details) {
                        if (data.usage.completion_tokens_details.reasoning_tokens) lastRequestMetrics.reasoning_tokens = data.usage.completion_tokens_details.reasoning_tokens;
                    }
                }
                // Check for cache_discount at top level of response (OpenRouter cache savings)
                if (data.cache_discount !== undefined) {
                    lastRequestMetrics = lastRequestMetrics || {};
                    lastRequestMetrics.cache_discount = data.cache_discount;
                }
                // Capture the actual model/provider used (OpenRouter returns the routed model)
                if (data.model) {
                    lastRequestMetrics = lastRequestMetrics || {};
                    lastRequestMetrics.actualModel = data.model;
                    // Update header display with full model name
                    updateModelDisplayWithProvider(data.model);
                }
                // Capture the actual provider from the response (e.g., "Parasail")
                if (data.provider) {
                    lastRequestMetrics = lastRequestMetrics || {};
                    lastRequestMetrics.providerName = data.provider;
                }

                chunkCount++;

                var choice = data.choices && data.choices[0];
                if (!choice) continue;

                var delta = choice.delta;
                var thinkingChunk = null;

                // Check for thinking/reasoning in delta
                if (delta) {

                    // ALWAYS accumulate reasoning_details when present (for API continuity)
                    // Also extract text for display as fallback
                    var reasoningDetailsText = '';
                    if (delta.reasoning_details && Array.isArray(delta.reasoning_details)) {
                        delta.reasoning_details.forEach(function(rd) {
                            // Extract text for display
                            if (rd.text) {
                                reasoningDetailsText += rd.text;
                            } else if (rd.thinking) {
                                reasoningDetailsText += rd.thinking;
                            } else if (rd.content) {
                                reasoningDetailsText += rd.content;
                            }

                            // Merge by index for API continuity
                            var idx = rd.index !== undefined ? rd.index : 0;
                            if (reasoningDetailsMap[idx]) {
                                var existing = reasoningDetailsMap[idx];
                                if (rd.text) existing.text = (existing.text || '') + rd.text;
                                if (rd.thinking) existing.thinking = (existing.thinking || '') + rd.thinking;
                                if (rd.content) existing.content = (existing.content || '') + rd.content;
                                if (rd.signature && rd.signature.length > 0) existing.signature = rd.signature;
                                if (rd.data) existing.data = rd.data;
                            } else {
                                reasoningDetailsMap[idx] = Object.assign({}, rd);
                            }
                        });
                    }

                    // Priority order for DISPLAY: reasoning > reasoning_content > thinking > reasoning_details
                    var thinkingSource = null;
                    if (delta.reasoning) {
                        thinkingChunk = delta.reasoning;
                        thinkingSource = 'delta.reasoning';
                    } else if (delta.reasoning_content) {
                        thinkingChunk = delta.reasoning_content;
                        thinkingSource = 'delta.reasoning_content';
                    } else if (delta.thinking) {
                        thinkingChunk = delta.thinking;
                        thinkingSource = 'delta.thinking';
                    } else if (reasoningDetailsText) {
                        thinkingChunk = reasoningDetailsText;
                        thinkingSource = 'reasoning_details.text';
                    }

                    if (thinkingChunk) {
                        thinking += thinkingChunk;
                        onThinking(thinking);
                    }

                    if (typeof delta.content === 'string' && delta.content) {
                        content += delta.content;
                        onContent(content);
                    }

                    if (delta.tool_calls) {
                        delta.tool_calls.forEach(function(tc) {
                            // Use index as key - this is the standard OpenAI streaming protocol
                            // ID is only sent on first chunk, subsequent chunks use index to correlate
                            var idx = tc.index;
                            if (!toolCallBuffers[idx]) {
                                toolCallBuffers[idx] = {
                                    id: tc.id || '',
                                    type: 'function',
                                    function: { name: '', arguments: '' }
                                };
                            }
                            // Capture ID from first chunk (subsequent chunks have id: null)
                            if (tc.id) toolCallBuffers[idx].id = tc.id;
                            if (tc.function) {
                                if (tc.function.name) toolCallBuffers[idx].function.name += tc.function.name;
                                if (tc.function.arguments) toolCallBuffers[idx].function.arguments += tc.function.arguments;
                            }
                        });
                        toolCalls = Object.keys(toolCallBuffers).map(function(k) {
                            return toolCallBuffers[k];
                        });
                        onToolCall(toolCalls);
                    }
                }

                // Handle choice-level and message-level thinking (non-delta format)
                // Only add if we didn't already get thinking from delta in this chunk
                if (!thinkingChunk) {
                    var choiceThinking = null;

                    if (choice.reasoning) {
                        choiceThinking = choice.reasoning;
                    } else if (choice.message) {
                        // Priority: reasoning > thinking > reasoning_details
                        if (choice.message.reasoning) {
                            choiceThinking = choice.message.reasoning;
                        } else if (choice.message.thinking) {
                            choiceThinking = choice.message.thinking;
                        } else if (choice.message.reasoning_details && Array.isArray(choice.message.reasoning_details)) {
                            var detailText = '';
                            for (var rd = 0; rd < choice.message.reasoning_details.length; rd++) {
                                var detail = choice.message.reasoning_details[rd];
                                if (detail.thinking) detailText += detail.thinking;
                                else if (detail.content) detailText += detail.content;
                            }
                            if (detailText) choiceThinking = detailText;
                        }
                    }

                    if (choiceThinking && !thinking.includes(choiceThinking)) {
                        thinking += choiceThinking;
                        onThinking(thinking);
                    }
                }

                // Capture content and tool_calls from choice.message (non-streaming format)
                if (choice.message) {
                    if (choice.message.content && !content.includes(choice.message.content)) {
                        content += choice.message.content;
                        onContent(content);
                    }

                    if (choice.message.tool_calls && choice.message.tool_calls.length > 0) {
                        // Only use choice.message.tool_calls if we haven't accumulated any from delta streaming
                        // Some models send incomplete tool_calls in choice.message that would overwrite good streamed data
                        if (toolCalls.length === 0) {
                            toolCalls = choice.message.tool_calls;
                            onToolCall(toolCalls);
                        }
                    }

                    // Preserve reasoning_details for API continuity - this is the complete version with signatures
                    if (choice.message.reasoning_details) {
                        reasoningDetails = choice.message.reasoning_details;
                    }
                }

            } catch (e) {
                // Re-throw real errors (e.g. API errors detected in stream)
                // Only silently continue for JSON parse errors
                if (e.message && !e.message.includes('JSON') && !e.message.includes('Unexpected token')) throw e;
            }
        }
    }

    // Build reasoningDetails array from merged map (if not already set by choice.message)
    if (reasoningDetails.length === 0 && Object.keys(reasoningDetailsMap).length > 0) {
        // Sort by index and build array
        var indices = Object.keys(reasoningDetailsMap).map(Number).sort(function(a, b) { return a - b; });
        indices.forEach(function(idx) {
            reasoningDetails.push(reasoningDetailsMap[idx]);
        });
    }

    // Capture usage from OpenRouter if available in final data
    // OpenRouter typically includes usage in X-headers or final message

    // IMPORTANT: Only pass back reasoning_details that came from the API
    // Do NOT construct it ourselves - that can cause issues with subsequent calls
    onDone({
        thinking: thinking,
        content: content,
        tool_calls: toolCalls.length > 0 ? toolCalls : null,
        reasoning_details: reasoningDetails.length > 0 ? reasoningDetails : null
    });
}

function buildAPIMessages(chatMessages) {
    // Clone messages to avoid mutating originals
    var cloned = chatMessages.map(function(m) { return Object.assign({}, m); });

    var result = cloned.map(function(m) {
        if (m.role === 'user') return { role: 'user', content: m.content };
        if (m.role === 'assistant') {
            var msg = { role: 'assistant' };
            if (m.content) msg.content = m.content;
            if (m.tool_calls) msg.tool_calls = m.tool_calls;
            // Pass reasoning_details through COMPLETELY unchanged - OpenRouter handles normalization
            // DO NOT filter or modify - sequence must match exactly what the model generated
            if (m.reasoning_details && m.reasoning_details.length > 0) {
                msg.reasoning_details = m.reasoning_details;
            }
            // Skip empty assistant messages (streaming placeholders) - they have no content,
            // no tool_calls, and no reasoning. Sending them causes hangs with image+tool combos.
            if (!msg.content && !msg.tool_calls && !msg.reasoning_details) return null;
            return msg;
        }
        if (m.role === 'tool') return { role: 'tool', tool_call_id: m.tool_call_id, content: typeof m.content === 'string' ? m.content : JSON.stringify(m.content) };
        if (m.role === 'browser_context') return { role: 'user', content: '[Browser Context] The user is viewing a page in the embedded browser at URL: ' + m.url + '. When they ask about "this page" or "the page", they are referring to this URL.' };
        // Handle screenshot messages - convert to multimodal user message with image
        if (m.role === 'screenshot') {
            var screenshotLabel = m.name || m.description || 'screenshot';
            return {
                role: 'user',
                content: [
                    { type: 'text', text: '[Screenshot captured: ' + screenshotLabel + ' (' + m.width + 'x' + m.height + ')]\nAnalyze this image to help the user. Describe what you see and identify any issues, UI elements, or relevant details.' },
                    { type: 'image_url', image_url: { url: m.base64 } }
                ]
            };
        }
        // Handle PDF messages - send full file every time, don't rewrite history
        if (m.role === 'pdf') {
            var pdfLabel = m.name || m.description || 'document.pdf';
            var pdfFilename = pdfLabel.endsWith('.pdf') ? pdfLabel : pdfLabel + '.pdf';
            return {
                role: 'user',
                content: [
                    { type: 'text', text: '[PDF attached: ' + pdfLabel + ']' },
                    { type: 'file', file: { filename: pdfFilename, file_data: m.base64 } }
                ]
            };
        }
        // Handle file attachments (spreadsheets, etc.) - inform Agent to use read_attached_file tool
        if (m.role === 'file') {
            var fileLabel = m.name || 'file';
            var fileSize = m.size ? ' (' + formatFileSize(m.size) + ')' : '';
            return {
                role: 'user',
                content: '[File attached: ' + fileLabel + fileSize + ']\nUse the read_attached_file tool to read this file\'s content. The file is stored in this conversation and can be searched/cached.'
            };
        }
        return null;
    }).filter(Boolean);
    return result;
}

function togglePause() {
    var wasPaused = paused;
    paused = !paused;
    var pauseBtn = document.getElementById('pause-btn');
    pauseBtn.innerHTML = paused ? '<span class="btn-icon">' + UI_ICONS.play + '</span>Resume' : '<span class="btn-icon">' + UI_ICONS.pause + '</span>Pause';

    // If resuming from paused state and not currently running, restart the agent
    if (wasPaused && !paused && !isRunning) {
        runAgent();
    }
}

function showPauseButton() {
    var pauseBtn = document.getElementById('pause-btn');
    if (pauseBtn) pauseBtn.classList.add('visible');
}

function hidePauseButton() {
    var pauseBtn = document.getElementById('pause-btn');
    if (pauseBtn) pauseBtn.classList.remove('visible');
}

function showRetryButton() {
    var retryBtn = document.getElementById('retry-btn');
    if (retryBtn) retryBtn.classList.add('visible');
}

function hideRetryButton() {
    var retryBtn = document.getElementById('retry-btn');
    if (retryBtn) retryBtn.classList.remove('visible');
}

function retryLastCall() {
    if (!lastApiError) return;
    hideRetryButton();
    lastApiError = null;
    setTimeout(function() {
        runAgent();
    }, 1000);
}

// Inject placeholder results for any tool calls that were interrupted (orphan tool_use without tool_result)
function injectInterruptedToolResults(chat) {
    if (!chat || !chat.messages) return false;

    var injected = false;
    for (var i = 0; i < chat.messages.length; i++) {
        var msg = chat.messages[i];
        if (msg.role !== 'assistant' || !msg.tool_calls || msg.tool_calls.length === 0) continue;

        for (var j = 0; j < msg.tool_calls.length; j++) {
            var tc = msg.tool_calls[j];
            var hasResult = false;

            // Look for matching tool result after this message
            for (var k = i + 1; k < chat.messages.length; k++) {
                if (chat.messages[k].role === 'tool' && chat.messages[k].tool_call_id === tc.id) {
                    hasResult = true;
                    break;
                }
            }

            if (!hasResult) {
                // Inject placeholder result for this orphan tool call
                chat.messages.push({
                    role: 'tool',
                    tool_call_id: tc.id,
                    name: tc.function ? tc.function.name : 'unknown',
                    content: '[Tool call interrupted by user - no result available]'
                });
                // Clear streaming state on the interrupted message
                msg.isStreaming = false;
                injected = true;
            }
        }
    }
    return injected;
}

// Execute any approved tool calls that don't have a corresponding result yet
async function executePendingApprovedTools(chat) {
    if (!chat || !chat.messages) return;

    // Find approved tool calls that don't have a corresponding tool result
    for (var i = 0; i < chat.messages.length; i++) {
        var msg = chat.messages[i];
        if (msg.role !== 'approval') continue;
        if (msg.status !== 'allowed' && msg.status !== 'session_allowed' && msg.status !== 'always_allowed') continue;
        // Skip programmatic tool calls (from js_eval chaining) - they're handled internally
        if (msg.toolCallId && msg.toolCallId.startsWith('prog_')) continue;

        // Check if there's already a tool result for this tool call
        var hasResult = false;
        for (var j = i + 1; j < chat.messages.length; j++) {
            if (chat.messages[j].role === 'tool' && chat.messages[j].tool_call_id === msg.toolCallId) {
                hasResult = true;
                break;
            }
        }

        if (!hasResult) {
            // Execute this pending tool
            var toolName = msg.actualToolName || msg.toolName;
            var args = msg.args;

            // Find the assistant message index
            var assistantMsgIndex = -1;
            for (var k = i - 1; k >= 0; k--) {
                if (chat.messages[k].role === 'assistant' && chat.messages[k].tool_calls) {
                    assistantMsgIndex = k;
                    break;
                }
            }

            showSpinner('Executing ' + msg.toolName + '...');
            try {
                // executeTool checks for existing approval via requestProgrammaticToolApproval
                var result = await executeTool(toolName, args, assistantMsgIndex, { toolCallId: msg.toolCallId, chatId: chat.id });
                hideSpinner();

                var processed = processToolResultForCache(chat.id, msg.toolCallId, toolName, result);
                chat.messages.push({
                    role: 'tool',
                    tool_call_id: msg.toolCallId,
                    name: toolName,
                    content: processed.content
                });
                saveChatsToStorage();
                renderMessages();
            } catch (e) {
                hideSpinner();
                chat.messages.push({
                    role: 'tool',
                    tool_call_id: msg.toolCallId,
                    name: toolName,
                    content: JSON.stringify({ success: false, error: e.message })
                });
                saveChatsToStorage();
                renderMessages();
            }
        }
    }
}

async function runAgent() {
    if (isRunning) return;
    isRunning = true;
    isFollowingStreamingScroll = true; // Reset scroll tracking
    lastApiError = null; // Clear any previous error
    hideRetryButton(); // Hide retry button when starting new run
    showPauseButton();
    var messagesEl = document.getElementById('messages');
    if (messagesEl) messagesEl.classList.add('is-streaming');
    var streamingChatId = currentChatId; // Capture chat ID at start - streaming continues even if user navigates away
    activeStreamingChatId = streamingChatId; // Set global tracker for navigation handling
    var chat = chats[streamingChatId];

    // Execute any approved tool calls that don't have results yet
    await executePendingApprovedTools(chat);

    // Track aggregate metrics across all API calls in this run
    // Initialize from existing messages to preserve stats across page reloads
    var callNumber = 0;
    var aggregateMetrics = {
        input_tokens: 0,
        output_tokens: 0,
        cache_read_tokens: 0,
        cache_creation_tokens: 0,
        cache_write_tokens: 0,
        reasoning_tokens: 0,
        cost: 0,
        duration: 0,
        callCount: 0
    };

    // Find the last user message index to determine current conversation turn
    var lastUserMsgIndex = -1;
    for (var mi = chat.messages.length - 1; mi >= 0; mi--) {
        if (chat.messages[mi].role === 'user') {
            lastUserMsgIndex = mi;
            break;
        }
    }

    // Accumulate metrics from assistant messages in this turn (after last user message)
    // This preserves stats when continuing after page reload
    if (lastUserMsgIndex >= 0) {
        for (var mi = lastUserMsgIndex + 1; mi < chat.messages.length; mi++) {
            var m = chat.messages[mi];
            if (m.role === 'assistant' && m.metrics && !m.isSummary) {
                aggregateMetrics.callCount++;
                aggregateMetrics.input_tokens += m.metrics.input_tokens || 0;
                aggregateMetrics.output_tokens += m.metrics.output_tokens || 0;
                aggregateMetrics.cache_read_tokens += m.metrics.cache_read_tokens || 0;
                aggregateMetrics.cache_creation_tokens += m.metrics.cache_creation_tokens || 0;
                aggregateMetrics.cache_write_tokens += m.metrics.cache_write_tokens || 0;
                aggregateMetrics.reasoning_tokens += m.metrics.reasoning_tokens || 0;
                aggregateMetrics.cost += m.metrics.cost || 0;
                aggregateMetrics.duration += m.metrics.duration || 0;
                callNumber = Math.max(callNumber, m.metrics.callNumber || 0);
            }
        }
    }

    // Initialize scroll flag based on current position before streaming starts
    isFollowingScroll = isNearBottom();

    // Check if there are unprocessed tool calls from a previous pause
    // Find the last assistant message with tool_calls and check which ones need processing
    var pendingToolCalls = null;
    var pendingAssistantMsgIndex = -1;
    for (var pi = chat.messages.length - 1; pi >= 0; pi--) {
        var pm = chat.messages[pi];
        if (pm.role === 'user') break; // Stop at last user message
        if (pm.role === 'assistant' && pm.tool_calls && pm.tool_calls.length > 0 && !pm.isSummary) {
            // Check which tool calls don't have results yet
            var unprocessed = [];
            for (var pti = 0; pti < pm.tool_calls.length; pti++) {
                var ptc = pm.tool_calls[pti];
                var hasResult = false;
                for (var pri = pi + 1; pri < chat.messages.length; pri++) {
                    if (chat.messages[pri].role === 'tool' && chat.messages[pri].tool_call_id === ptc.id) {
                        hasResult = true;
                        break;
                    }
                }
                if (!hasResult) {
                    unprocessed.push({ tc: ptc, index: pti });
                }
            }
            if (unprocessed.length > 0) {
                pendingToolCalls = unprocessed;
                pendingAssistantMsgIndex = pi;
            }
            break;
        }
    }

    // Process pending tool calls from previous pause first
    if (pendingToolCalls && pendingToolCalls.length > 0) {
        var assistantMsgIndex = pendingAssistantMsgIndex;

        for (var pci = 0; pci < pendingToolCalls.length; pci++) {
            if (paused) break;
            var tc = pendingToolCalls[pci].tc;
            var toolName = tc.function.name;
            var args;
            try {
                args = JSON.parse(tc.function.arguments || '{}');
            } catch (parseErr) {
                console.error('Failed to parse tool arguments:', tc.function.arguments, parseErr);
                chat.messages.push({
                    role: 'tool',
                    tool_call_id: tc.id,
                    name: toolName,
                    content: JSON.stringify({ success: false, error: 'Invalid tool arguments: ' + parseErr.message })
                });
                saveChatsToStorage();
                if (currentChatId === streamingChatId) renderMessages();
                continue;
            }

            var displayName = getToolDisplayName(toolName, args.method || args.action);
            showSpinner('Executing ' + displayName + '...');
            var result = await executeTool(toolName, args, assistantMsgIndex, { toolCallId: tc.id, chatId: streamingChatId });
            hideSpinner();

            delete result._denied;
            var screenshotMsg = result._screenshotMessage;
            var screenshotMsgs = result._screenshotMessages;
            delete result._screenshotMessage;
            delete result._screenshotMessages;
            var processed = processToolResultForCache(streamingChatId, tc.id, toolName, result);
            chat.messages.push({
                role: 'tool',
                tool_call_id: tc.id,
                name: toolName,
                content: processed.content
            });
            if (screenshotMsg) chat.messages.push(screenshotMsg);
            if (screenshotMsgs) screenshotMsgs.forEach(function(sm) { chat.messages.push(sm); });
            saveChatsToStorage();
            if (currentChatId === streamingChatId) renderMessages();
        }

        // Flush any user message injected during tool execution
        if (pendingInjection) {
            chat.messages.push({ role: 'user', content: pendingInjection });
            pendingInjection = null;
            saveChatsToStorage();
            if (currentChatId === streamingChatId) renderMessages();
        }

        if (paused) {
            // Paused during pending tool processing - exit cleanly
            hideSpinner();
            isRunning = false;
            showSnackbar('Agent paused. Click Resume to continue.');
            isFollowingScroll = true;
            fetchCredits();
            return;
        }
    }

    while (!paused) {
        showSpinner('Waiting for response...');
        callNumber++;

        // Reset metrics and start timing for this request
        var currentProviderObj = getProviderById(currentProvider);
        lastRequestMetrics = { startTime: Date.now(), callNumber: callNumber, providerName: currentProviderObj ? currentProviderObj.name : 'Unknown' };

        var assistantMsg = {
            role: 'assistant',
            content: '',
            thinking: '',
            tool_calls: null,
            isStreaming: true,
            thinkingCollapsed: false
        };
        var msgIndex = chat.messages.length;
        chat.messages.push(assistantMsg);
        if (currentChatId === streamingChatId) renderMessages();
        hideSpinner();

        try {
            var streamUpdateInterval = setInterval(function() {
                // Force UI update while streaming to show activity
                if (assistantMsg.isStreaming) {
                    try {
                        updateStreamingMessage(msgIndex, assistantMsg, streamingChatId);
                    } catch (e) {
                        console.error('Stream interval update error:', e);
                    }
                }
            }, 1000);

            await callLLMStreaming(
                chat.messages,
                function(thinking) {
                    assistantMsg.thinking = thinking;
                    try {
                        updateStreamingMessage(msgIndex, assistantMsg, streamingChatId);
                    } catch (e) {
                        console.error('Thinking update error:', e);
                    }
                },
                function(content) {
                    assistantMsg.content = content;
                    try {
                        updateStreamingMessage(msgIndex, assistantMsg, streamingChatId);
                    } catch (e) {
                        console.error('Content update error:', e);
                    }
                },
                function(toolCalls) {
                    assistantMsg.tool_calls = toolCalls;
                    try {
                        updateStreamingMessage(msgIndex, assistantMsg, streamingChatId);
                    } catch (e) {
                        console.error('Tool calls update error:', e);
                    }
                },
                function(final) {
                    assistantMsg.thinking = final.thinking || '';
                    assistantMsg.thinkingSignature = final.thinkingSignature || null; // Preserve for Anthropic multi-turn
                    assistantMsg.content = final.content || '';
                    assistantMsg.tool_calls = final.tool_calls;
                    assistantMsg.reasoning_details = final.reasoning_details; // Preserve for OpenRouter API continuity
                    assistantMsg.isStreaming = false;
                },
                function(status, count) {
                    // Stream status callback - model is processing
                }
            );

            clearInterval(streamUpdateInterval);
        } catch (e) {
            clearInterval(streamUpdateInterval);
            isFollowingScroll = true; // Reset scroll flag on error
            lastApiError = { message: e.message, chatId: streamingChatId, timestamp: Date.now() };
            showSnackbar('API Error: ' + e.message, 'error');
            chat.messages.pop();
            if (currentChatId === streamingChatId) renderMessages();
            showRetryButton(); // Show retry button for network errors
            break;
        }

        assistantMsg.isStreaming = false;
        if (assistantMsg.thinking) {
            assistantMsg.thinkingCollapsed = true;
        }

        // Capture performance metrics
        if (lastRequestMetrics) {
            lastRequestMetrics.endTime = Date.now();
            lastRequestMetrics.duration = lastRequestMetrics.endTime - lastRequestMetrics.startTime;

            // Accumulate to aggregate metrics
            aggregateMetrics.callCount++;
            aggregateMetrics.duration += lastRequestMetrics.duration || 0;
            aggregateMetrics.input_tokens += lastRequestMetrics.input_tokens || 0;
            aggregateMetrics.output_tokens += lastRequestMetrics.output_tokens || 0;
            aggregateMetrics.cache_read_tokens += lastRequestMetrics.cache_read_tokens || 0;
            aggregateMetrics.cache_creation_tokens += lastRequestMetrics.cache_creation_tokens || 0;
            aggregateMetrics.cache_write_tokens += lastRequestMetrics.cache_write_tokens || 0;
            aggregateMetrics.reasoning_tokens += lastRequestMetrics.reasoning_tokens || 0;
            aggregateMetrics.cost += lastRequestMetrics.cost || 0;

            // Copy metrics but exclude requestBody to prevent memory bloat
            // (requestBody contains full conversation history with base64 images)
            var metricsToStore = Object.assign({}, lastRequestMetrics);
            delete metricsToStore.requestBody;
            assistantMsg.metrics = metricsToStore;
        }

        if (!assistantMsg.thinking) delete assistantMsg.thinking;
        if (!assistantMsg.content) assistantMsg.content = '';

        // Track model and accumulate cost on chat
        chat.model = currentProvider;
        chat.totalCost = (chat.totalCost || 0) + (lastRequestMetrics.cost || 0);

        delete chat.isTemporary;
        saveChatsToStorage();
        if (currentChatId === streamingChatId) renderMessages();
        renderChatList();

        if (!assistantMsg.tool_calls || assistantMsg.tool_calls.length === 0) {
            // If there's a pending injection, push it and continue the loop
            // so the agent sees the user's message in the next API call
            if (pendingInjection) {
                chat.messages.push({ role: 'user', content: pendingInjection });
                pendingInjection = null;
                saveChatsToStorage();
                if (currentChatId === streamingChatId) renderMessages();
                continue; // Next iteration calls callLLMStreaming with the injected message
            }
            break;
        }

        // Calculate assistant message index
        var assistantMsgIndex = chat.messages.length - 1;

        for (var i = 0; i < assistantMsg.tool_calls.length; i++) {
            if (paused) break;
            var tc = assistantMsg.tool_calls[i];
            var toolName = tc.function.name;
            var args;
            try {
                args = JSON.parse(tc.function.arguments || '{}');
            } catch (parseErr) {
                console.error('Failed to parse tool arguments:', tc.function.arguments, parseErr);
                chat.messages.push({
                    role: 'tool',
                    tool_call_id: tc.id,
                    name: toolName,
                    content: JSON.stringify({ success: false, error: 'Invalid tool arguments: ' + parseErr.message })
                });
                saveChatsToStorage();
                if (currentChatId === streamingChatId) renderMessages();
                continue;
            }

            var displayName = getToolDisplayName(toolName, args.method || args.action);
            showSpinner('Executing ' + displayName + '...');
            var result = await executeTool(toolName, args, assistantMsgIndex, { toolCallId: tc.id, chatId: streamingChatId });
            hideSpinner();

            delete result._denied;
            var screenshotMsg = result._screenshotMessage;
            var screenshotMsgs = result._screenshotMessages;
            delete result._screenshotMessage;
            delete result._screenshotMessages;
            var processed = processToolResultForCache(streamingChatId, tc.id, toolName, result);
            var toolResultIdx = chat.messages.length;
            chat.messages.push({
                role: 'tool',
                tool_call_id: tc.id,
                name: toolName,
                content: processed.content
            });
            // Correct widget msgIndex if approval messages shifted it
            if (result.widgetId) {
                var wList = getWidgetsForChat(streamingChatId);
                for (var wi = 0; wi < wList.length; wi++) {
                    if (wList[wi].id === result.widgetId) { wList[wi].msgIndex = toolResultIdx; break; }
                }
            }
            if (screenshotMsg) chat.messages.push(screenshotMsg);
            if (screenshotMsgs) screenshotMsgs.forEach(function(sm) { chat.messages.push(sm); });
            saveChatsToStorage();
            if (currentChatId === streamingChatId) renderMessages();

        }

        // Flush any user message injected during tool execution
        if (pendingInjection) {
            chat.messages.push({ role: 'user', content: pendingInjection });
            pendingInjection = null;
            saveChatsToStorage();
            if (currentChatId === streamingChatId) renderMessages();
        }

        if (paused) break;
    }

    // Show aggregate summary if there were multiple API calls
    if (aggregateMetrics.callCount > 1) {
        var summaryMetrics = {
            input_tokens: aggregateMetrics.input_tokens,
            output_tokens: aggregateMetrics.output_tokens,
            cache_read_tokens: aggregateMetrics.cache_read_tokens || undefined,
            cache_creation_tokens: aggregateMetrics.cache_creation_tokens || undefined,
            cache_write_tokens: aggregateMetrics.cache_write_tokens || undefined,
            reasoning_tokens: aggregateMetrics.reasoning_tokens || undefined,
            cost: aggregateMetrics.cost || undefined,
            duration: aggregateMetrics.duration,
            isAggregate: true,
            callCount: aggregateMetrics.callCount
        };
        chat.messages.push({
            role: 'assistant',
            content: '',
            metrics: summaryMetrics,
            isSummary: true
        });
        saveChatsToStorage();
        if (currentChatId === streamingChatId) renderMessages();
    }

    hideSpinner();
    isRunning = false;
    pendingInjection = null; // Clear any undelivered injection
    activeStreamingChatId = null; // Clear streaming tracker
    var messagesEl = document.getElementById('messages');
    if (messagesEl) {
        messagesEl.classList.remove('is-streaming');
    }
    // Reset silent hook flag before final render so messages are properly displayed
    var wasSilentHook = _silentHookRunning;
    _silentHookRunning = false;
    if (currentChatId === streamingChatId) renderMessages();
    updateContextIndicator(); // Update now that streaming is done

    // Only hide pause button if not paused - keep visible so user can resume
    if (paused) {
        showSnackbar('Agent paused. Click Resume to continue.');
    } else {
        hidePauseButton();
    }
    isFollowingScroll = true; // Reset scroll flag when agent run fully completes

    // Execute after-response hooks (only if not paused and no error occurred)
    if (!paused && !lastApiError) {
        executeAfterResponseHooks(streamingChatId);
    }

    // Refresh credits after API calls complete
    fetchCredits();
}

async function sendMessage() {
    var input = document.getElementById('message-input');
    var message = input.value.trim();

    // Allow sending if we have a message OR pending images
    if (!message && pendingImageAttachments.length === 0) return;

    // During streaming: queue message to inject after current tool results
    if (isRunning) {
        if (!message) return; // Only text injection supported during streaming
        pendingInjection = message;
        input.value = '';
        input.style.height = 'auto';
        showSnackbar('Message queued — will be sent with the next tool result.');
        return;
    }

    // Check if we're in widget editing mode
    if (currentEditingWidget) {
        await sendWidgetMessage(message);
        return;
    }

    // Reset scroll flag when user sends a new message
    isFollowingScroll = true;

    // Clear pending input since we're sending it
    delete chatPendingTexts[getCurrentPendingContext()];
    persistPendingTextsToStorage();

    var chat = chats[currentChatId];

    // Add user message (even if empty when attachments present, provide context)
    var imageCount = pendingImageAttachments.filter(function(a) { return !a.fileType || a.fileType === 'image'; }).length;
    var pdfCount = pendingImageAttachments.filter(function(a) { return a.fileType === 'pdf'; }).length;
    var fileCount = pendingImageAttachments.filter(function(a) { return a.fileType === 'file'; }).length;
    var attachLabel = '';
    if (imageCount > 0 || pdfCount > 0 || fileCount > 0) {
        var parts = [];
        if (imageCount > 0) parts.push(imageCount + ' image(s)');
        if (pdfCount > 0) parts.push(pdfCount + ' PDF(s)');
        if (fileCount > 0) parts.push(fileCount + ' file(s)');
        attachLabel = '[User attached ' + parts.join(' and ') + ']';
    }
    var userMessageContent = message || attachLabel;

    // Inject placeholder results for any interrupted tool calls before adding user message
    if (injectInterruptedToolResults(chat)) {
        // Tool calls were interrupted - clean up UI state
        activeStreamingChatId = null;
        isRunning = false;
        paused = false;
        hideSpinner();
        hidePauseButton();
        saveChatsToStorage();
        renderMessages();
    }

    chat.messages.push({ role: 'user', content: userMessageContent });

    // Add pending attachments as screenshot/pdf/file messages
    if (pendingImageAttachments.length > 0) {
        pendingImageAttachments.forEach(function(img) {
            if (img.fileType === 'pdf') {
                chat.messages.push({
                    role: 'pdf',
                    base64: img.base64,
                    name: img.name,
                    description: 'User attached PDF',
                    timestamp: Date.now()
                });
            } else if (img.fileType === 'file') {
                chat.messages.push({
                    role: 'file',
                    content: img.content,
                    name: img.name,
                    mimeType: img.mimeType,
                    size: img.size,
                    description: 'User attached file',
                    timestamp: Date.now()
                });
            } else {
                chat.messages.push({
                    role: 'screenshot',
                    base64: img.base64,
                    name: img.name,
                    description: 'User attached image',
                    timestamp: Date.now(),
                    width: img.width,
                    height: img.height
                });
            }
        });
        // Clear pending attachments after adding to messages
        clearPendingImages();
    }

    // Append browser context message if browser is open (at the end, for cache stability)
    var panel = document.getElementById('iframe-panel');
    if (panel && panel.classList.contains('visible') && currentIframeUrl) {
        chat.messages.push({ role: 'browser_context', url: currentIframeUrl });
    }

    updateChatTitle(chat);

    delete chat.isTemporary;
    saveChatsToStorage();

    renderMessages();
    renderChatList();
    input.value = '';
    input.style.height = 'auto';
    paused = false;
    document.getElementById('pause-btn').innerHTML = '<span class="btn-icon">' + UI_ICONS.pause + '</span>Pause';

    await runAgent();
}

// Send message in widget editing mode - uses main agent chat
async function sendWidgetMessage(message) {
    var input = document.getElementById('message-input');
    var widget = dashboardWidgets[currentEditingWidget];
    if (!widget) return;

    // Update title if it's still default
    if (widget.title === 'New Widget' || !widget.title) {
        widget.title = message.substring(0, 50) + (message.length > 50 ? '...' : '');
        var headerTitle = document.getElementById('header-chat-title');
        if (headerTitle) {
            headerTitle.innerHTML = '<span class="widget-mode-badge">Widget</span> ' + escapeHtml(widget.title);
        }
    }

    // Set prompt if not set
    if (!widget.prompt) {
        widget.prompt = message;
    }

    // Store widget conversation for context
    widget.conversation = widget.conversation || [];
    widget.conversation.push({ role: 'user', content: message });

    // Build widget context message for main agent
    var widgetContext = '[WIDGET MODE] You are editing widget "' + widget.title + '" (ID: ' + widget.id + '). ' +
        'Use the html_widget tool with widget_id="' + widget.id + '" to update this widget. ' +
        'Create a complete, self-contained HTML widget with styles and scripts. ' +
        'For ServiceNow API calls, use: await executeTool("servicenow_api", {method:"GET", table:"...", ...})\n\n' +
        'User request: ' + message;

    var chat = chats[currentChatId];
    chat.messages.push({ role: 'user', content: widgetContext, isWidgetRequest: true, widgetId: widget.id });

    input.value = '';
    input.style.height = 'auto';

    // Show widget as loading
    widget.isLoading = true;
    widget.isStreaming = true;
    activeWidgetStreamingId = widget.id;
    await saveDashboardWidget(widget);

    // Render loading state
    renderWidgetInChat(widget);

    updateChatTitle(chat);
    delete chat.isTemporary;
    saveChatsToStorage();
    renderMessages();
    renderChatList();

    paused = false;
    document.getElementById('pause-btn').innerHTML = '<span class="btn-icon">' + UI_ICONS.pause + '</span>Pause';

    // Run main agent
    await runAgent();

    // After agent completes, update widget state
    widget.isLoading = false;
    widget.isStreaming = false;
    activeWidgetStreamingId = null;
    await saveDashboardWidget(widget);

    input.focus();
    renderWidgetInChat(widget);
}

function handleKeyDown(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
    }
}

// =============================================
// IMAGE ATTACHMENT HANDLING
// =============================================

// Handle file input selection
function handleImageFileSelect(event) {
    var files = event.target.files;
    if (!files || files.length === 0) return;

    for (var i = 0; i < files.length; i++) {
        processImageFile(files[i]);
    }

    // Clear the input so the same file can be selected again
    event.target.value = '';
}

// Process an image, PDF, or spreadsheet file and add it to pending attachments
function processImageFile(file) {
    // Handle PDF files
    if (file.type === 'application/pdf') {
        if (file.size > 25 * 1024 * 1024) {
            showSnackbar('PDF too large (max 25MB)', 'error');
            return;
        }

        var reader = new FileReader();
        reader.onload = function(e) {
            var name = file.name || 'document.pdf';

            pendingImageAttachments.push({
                base64: e.target.result,
                name: name,
                fileType: 'pdf'
            });

            renderPendingImages();
        };
        reader.readAsDataURL(file);
        return;
    }

    // Handle text files (CSV, plain text, etc.)
    var isTextFile = file.type.startsWith('text/') ||
                     file.name.toLowerCase().endsWith('.csv') ||
                     file.name.toLowerCase().endsWith('.txt') ||
                     file.name.toLowerCase().endsWith('.json') ||
                     file.name.toLowerCase().endsWith('.xml') ||
                     file.name.toLowerCase().endsWith('.md');

    if (isTextFile) {
        if (file.size > 10 * 1024 * 1024) {
            showSnackbar('File too large (max 10MB)', 'error');
            return;
        }

        var reader = new FileReader();
        reader.onload = function(e) {
            var name = file.name || 'file';
            var content = e.target.result;

            pendingImageAttachments.push({
                content: content,
                name: name,
                fileType: 'file',
                mimeType: file.type || 'text/plain',
                size: file.size
            });

            renderPendingImages();
        };
        reader.readAsText(file);
        return;
    }

    // Handle image files
    if (!file.type.startsWith('image/')) {
        showSnackbar('Unsupported file type. Use image, PDF, or text files.', 'error');
        return;
    }

    // Limit file size to 10MB
    if (file.size > 10 * 1024 * 1024) {
        showSnackbar('Image too large (max 10MB)', 'error');
        return;
    }

    var reader = new FileReader();
    reader.onload = function(e) {
        var img = new Image();
        img.onload = function() {
            // Resize if too large (max 1200px on longest side for reasonable token usage)
            var maxDim = 1200;
            var width = img.width;
            var height = img.height;

            if (width > maxDim || height > maxDim) {
                if (width > height) {
                    height = Math.round(height * maxDim / width);
                    width = maxDim;
                } else {
                    width = Math.round(width * maxDim / height);
                    height = maxDim;
                }
            }

            // Create resized canvas
            var canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            var ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, width, height);

            var base64 = canvas.toDataURL('image/png');
            var name = file.name.replace(/\.[^.]+$/, '') || 'image';

            pendingImageAttachments.push({
                base64: base64,
                name: name,
                width: width,
                height: height
            });

            renderPendingImages();
        };
        img.src = e.target.result;
    };
    reader.readAsDataURL(file);
}

// Handle paste events for images and PDFs
function handlePasteForImages(e) {
    var items = e.clipboardData && e.clipboardData.items;
    if (!items) return;

    var hasFile = false;
    for (var i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1 || items[i].type === 'application/pdf') {
            hasFile = true;
            var file = items[i].getAsFile();
            if (file) {
                processImageFile(file);
            }
        }
    }

    // If we processed a file, don't prevent default (allow text paste too)
    // But if ONLY file was pasted, prevent default
    if (hasFile && (!e.clipboardData.getData('text/plain'))) {
        e.preventDefault();
    }
}

// Track drag enter/leave depth for nested elements
var dragDepth = 0;

// Handle drag enter/over for the full page
function handleDragOver(e) {
    e.preventDefault();
    e.stopPropagation();
}

function handleDragEnter(e) {
    e.preventDefault();
    e.stopPropagation();
    dragDepth++;
    if (dragDepth === 1) {
        var overlay = document.getElementById('drop-overlay');
        if (overlay) overlay.classList.add('visible');
    }
}

// Handle drag leave for the full page
function handleDragLeave(e) {
    e.preventDefault();
    e.stopPropagation();
    dragDepth--;
    if (dragDepth <= 0) {
        dragDepth = 0;
        var overlay = document.getElementById('drop-overlay');
        if (overlay) overlay.classList.remove('visible');
    }
}

// Handle drop for the full page
function handleDrop(e) {
    e.preventDefault();
    e.stopPropagation();

    dragDepth = 0;
    var overlay = document.getElementById('drop-overlay');
    if (overlay) overlay.classList.remove('visible');

    var files = e.dataTransfer && e.dataTransfer.files;
    if (!files || files.length === 0) return;

    for (var i = 0; i < files.length; i++) {
        if (files[i].type.startsWith('image/') || files[i].type === 'application/pdf') {
            processImageFile(files[i]);
        }
    }
}

// Render pending images/PDFs preview - updates both chat and home containers
function renderPendingImages() {
    var chatContainer = document.getElementById('pending-images-container');
    var homeContainer = document.getElementById('home-pending-images-container');

    // Build the HTML once
    var html = '';
    if (pendingImageAttachments.length > 0) {
        pendingImageAttachments.forEach(function(img, idx) {
            if (img.fileType === 'pdf') {
                html += '<div class="pending-image-item pending-pdf-item" onclick="viewPendingImage(' + idx + ')">';
                html += '<div class="pending-pdf-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg><span class="pending-pdf-label">PDF</span></div>';
                html += '<div class="pending-pdf-name">' + escapeHtml(img.name) + '</div>';
                html += '<button class="pending-image-remove" onclick="event.stopPropagation();removePendingImage(' + idx + ')" title="Remove">×</button>';
                html += '</div>';
            } else if (img.fileType === 'file') {
                var fileExt = (img.name || '').split('.').pop().toUpperCase();
                html += '<div class="pending-image-item pending-file-item" onclick="viewPendingImage(' + idx + ')">';
                html += '<div class="pending-file-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg><span class="pending-file-label">' + escapeHtml(fileExt) + '</span></div>';
                html += '<div class="pending-file-name">' + escapeHtml(img.name) + '</div>';
                html += '<button class="pending-image-remove" onclick="event.stopPropagation();removePendingImage(' + idx + ')" title="Remove">×</button>';
                html += '</div>';
            } else {
                html += '<div class="pending-image-item" onclick="viewPendingImage(' + idx + ')">';
                html += '<img src="' + img.base64 + '" alt="' + escapeHtml(img.name) + '" />';
                html += '<button class="pending-image-remove" onclick="event.stopPropagation();removePendingImage(' + idx + ')" title="Remove">×</button>';
                html += '</div>';
            }
        });
        var imageCount = pendingImageAttachments.filter(function(a) { return !a.fileType || a.fileType === 'image'; }).length;
        var pdfCount = pendingImageAttachments.filter(function(a) { return a.fileType === 'pdf'; }).length;
        var fileCount = pendingImageAttachments.filter(function(a) { return a.fileType === 'file'; }).length;
        var parts = [];
        if (imageCount > 0) parts.push(imageCount + ' image' + (imageCount > 1 ? 's' : ''));
        if (pdfCount > 0) parts.push(pdfCount + ' PDF' + (pdfCount > 1 ? 's' : ''));
        if (fileCount > 0) parts.push(fileCount + ' file' + (fileCount > 1 ? 's' : ''));
        html += '<div class="pending-images-hint">' + parts.join(', ') + ' attached. Click to preview, or × to remove.</div>';
    }

    // Update both containers
    [chatContainer, homeContainer].forEach(function(container) {
        if (!container) return;
        if (pendingImageAttachments.length === 0) {
            container.style.display = 'none';
            container.innerHTML = '';
        } else {
            container.style.display = 'flex';
            container.innerHTML = html;
        }
    });

    // Persist pending images to sessionStorage for reload survival
    persistPendingImagesToSession();

    // Update pending-draft indicators in sidebar
    updateHomePendingIndicator();
    renderChatList();
}

// Remove a pending image by index
function removePendingImage(index) {
    pendingImageAttachments.splice(index, 1);
    renderPendingImages();
}

// View a pending image, PDF, or file in fullscreen modal
function viewPendingImage(index) {
    var img = pendingImageAttachments[index];
    if (!img) return;

    if (img.fileType === 'pdf') {
        openPdfModal(img.base64, img.name);
    } else if (img.fileType === 'file') {
        openFileModal(img.content, img.name, img.mimeType);
    } else {
        openScreenshotModal(img.base64, img.name + ' (' + img.width + '×' + img.height + ')');
    }
}

// Open PDF in modal for full-screen preview
function openPdfModal(base64, title, msgIndex) {
    var overlay = document.getElementById('modal-overlay');
    var header = document.getElementById('modal-header');
    var body = document.getElementById('modal-body');
    var actions = document.getElementById('modal-actions');

    overlay.classList.add('pdf-modal');
    var headerHtml = '<span class="modal-title-text">' + escapeHtml(title || 'PDF') + '</span><div class="modal-header-actions">';
    // Show annotations button if we have a message index with annotations
    if (typeof msgIndex === 'number') {
        var chat = chats[currentChatId];
        if (chat && chat.messages) {
            var annotations = findPdfAnnotations(chat.messages, msgIndex);
            if (annotations) {
                headerHtml += '<button class="modal-close-icon" onclick="viewPdfAnnotations(' + msgIndex + ')" title="View parsed content">' + UI_ICONS.file + '</button>';
            }
        }
    }
    headerHtml += '<button class="modal-close-icon" onclick="downloadPdfFromModal()" title="Download">' + UI_ICONS.download + '</button>';
    headerHtml += '<button class="modal-close-icon" onclick="closeModal()" title="Close">' + UI_ICONS.close + '</button></div>';
    header.innerHTML = headerHtml;
    body.innerHTML = '<iframe src="' + base64 + '" style="width:100%;height:100%;border:none;" title="PDF Preview"></iframe>';
    actions.innerHTML = '';

    // Store base64 for download
    body.dataset.pdfSrc = base64;
    body.dataset.pdfName = title || 'document';

    overlay.classList.add('show');
}

// Find PDF annotations for a given pdf message index by looking at subsequent assistant messages
function findPdfAnnotations(messages, pdfMsgIndex) {
    var pdfMsg = messages[pdfMsgIndex];
    if (!pdfMsg || pdfMsg.role !== 'pdf') return null;
    // Look for annotations stored on the pdf message itself
    if (pdfMsg.annotations) return pdfMsg.annotations;
    // Look at subsequent assistant messages for annotations referencing this PDF
    for (var i = pdfMsgIndex + 1; i < messages.length; i++) {
        var msg = messages[i];
        if (msg.role === 'assistant' && msg.annotations) {
            for (var j = 0; j < msg.annotations.length; j++) {
                var ann = msg.annotations[j];
                if (ann.type === 'file' && ann.file) {
                    return [ann];
                }
            }
        }
        // Stop searching if we hit another user message
        if (msg.role === 'user') break;
    }
    return null;
}

// View parsed PDF annotations in a modal
function viewPdfAnnotations(msgIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages) return;
    var annotations = findPdfAnnotations(chat.messages, msgIndex);
    if (!annotations) {
        showSnackbar('No parsed content available for this PDF', 'info');
        return;
    }

    var overlay = document.getElementById('modal-overlay');
    var header = document.getElementById('modal-header');
    var body = document.getElementById('modal-body');
    var actions = document.getElementById('modal-actions');
    var pdfMsg = chat.messages[msgIndex];
    var pdfTitle = pdfMsg.name || pdfMsg.description || 'Document';

    overlay.classList.remove('pdf-modal');
    overlay.classList.add('screenshot-modal');
    header.innerHTML = '<span class="modal-title-text">Parsed: ' + escapeHtml(pdfTitle) + '</span><div class="modal-header-actions"><button class="modal-close-icon" onclick="openPdfFromMessage(' + msgIndex + ')" title="Back to PDF">' + UI_ICONS.eye + '</button><button class="modal-close-icon" onclick="closeModal()" title="Close">' + UI_ICONS.close + '</button></div>';

    var contentHtml = '<div class="pdf-annotations-content">';
    annotations.forEach(function(ann) {
        if (ann.type === 'file' && ann.file) {
            if (ann.file.name) {
                contentHtml += '<div class="pdf-ann-filename">' + escapeHtml(ann.file.name) + '</div>';
            }
            if (ann.file.hash) {
                contentHtml += '<div class="pdf-ann-hash">Hash: <code>' + escapeHtml(ann.file.hash) + '</code></div>';
            }
            if (ann.file.content && ann.file.content.length > 0) {
                ann.file.content.forEach(function(part) {
                    if (part.type === 'text') {
                        contentHtml += '<div class="pdf-ann-text">' + escapeHtml(part.text).replace(/\n/g, '<br>') + '</div>';
                    } else if (part.type === 'image_url' && part.image_url) {
                        contentHtml += '<div class="pdf-ann-image"><img src="' + part.image_url.url + '" alt="Parsed image" /></div>';
                    }
                });
            }
        }
    });
    contentHtml += '</div>';

    body.innerHTML = contentHtml;
    actions.innerHTML = '';
    overlay.classList.add('show');
}

function downloadPdfFromModal() {
    var body = document.getElementById('modal-body');
    if (!body || !body.dataset.pdfSrc) return;

    var link = document.createElement('a');
    link.href = body.dataset.pdfSrc;
    link.download = (body.dataset.pdfName || 'document') + '.pdf';
    link.click();
}

// Open text file in modal for full-screen preview
function openFileModal(content, title, mimeType) {
    var overlay = document.getElementById('modal-overlay');
    var header = document.getElementById('modal-header');
    var body = document.getElementById('modal-body');
    var actions = document.getElementById('modal-actions');

    overlay.classList.add('file-modal');
    header.innerHTML = '<span class="modal-title-text">' + escapeHtml(title || 'File') + '</span><div class="modal-header-actions"><button class="modal-close-icon" onclick="downloadTextFile()" title="Download">' + UI_ICONS.download + '</button><button class="modal-close-icon" onclick="closeModal()" title="Close">' + UI_ICONS.close + '</button></div>';
    body.innerHTML = '<pre style="white-space:pre-wrap;word-wrap:break-word;margin:0;padding:16px;font-family:monospace;font-size:12px;line-height:1.5;overflow:auto;height:100%;background:var(--secondary-lighter);">' + escapeHtml(content) + '</pre>';
    actions.innerHTML = '';

    // Store content for download
    body.dataset.fileContent = content;
    body.dataset.fileName = title || 'file';
    body.dataset.fileMimeType = mimeType || 'text/plain';

    overlay.classList.add('show');
}

function downloadTextFile() {
    var body = document.getElementById('modal-body');
    if (!body || !body.dataset.fileContent) return;

    var blob = new Blob([body.dataset.fileContent], { type: body.dataset.fileMimeType || 'text/plain' });
    var url = URL.createObjectURL(blob);
    var link = document.createElement('a');
    link.href = url;
    link.download = body.dataset.fileName || 'file.txt';
    link.click();
    URL.revokeObjectURL(url);
}

// Open file preview from a chat message by index
function openFileFromMessage(msgIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages[msgIndex]) return;
    var msg = chat.messages[msgIndex];
    if (msg.role !== 'file' || !msg.content) return;
    openFileModal(msg.content, msg.name || 'File', msg.mimeType);
}

// Open PDF preview from a chat message by index
function openPdfFromMessage(msgIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages[msgIndex]) return;
    var msg = chat.messages[msgIndex];
    if (msg.role !== 'pdf' || !msg.base64) return;
    openPdfModal(msg.base64, msg.name || msg.description || 'Document', msgIndex);
}

// Clear all pending images
function clearPendingImages() {
    pendingImageAttachments = [];
    // Also clear from per-chat map
    delete chatPendingImages[getCurrentPendingContext()];
    renderPendingImages();
}

// Save current pending images for a chat/view key, then restore for a new key
function savePendingImagesForContext(contextKey) {
    if (pendingImageAttachments.length > 0) {
        chatPendingImages[contextKey] = pendingImageAttachments.slice();
    }
    // Don't delete when empty — persistPendingImagesToSession handles cleanup
}

function restorePendingImagesForContext(contextKey) {
    pendingImageAttachments = (chatPendingImages[contextKey] || []).slice();
    renderPendingImages();
}

function getCurrentPendingContext() {
    if (currentView === 'home') return 'home';
    return currentChatId || 'none';
}

function savePendingTextForContext(contextKey) {
    var inputId = contextKey === 'home' ? 'home-message-input' : 'message-input';
    var input = document.getElementById(inputId);
    var text = input ? input.value : '';
    if (text) {
        chatPendingTexts[contextKey] = text;
    } else {
        delete chatPendingTexts[contextKey];
    }
}

function restorePendingTextForContext(contextKey) {
    var inputId = contextKey === 'home' ? 'home-message-input' : 'message-input';
    var input = document.getElementById(inputId);
    if (input) {
        input.value = chatPendingTexts[contextKey] || '';
        autoResizeTextarea(input);
    }
}

function persistPendingTextsToStorage() {
    setSetting('chatPendingTexts', Object.keys(chatPendingTexts).length > 0 ? chatPendingTexts : null);
    updateHomePendingIndicator();
}

async function restorePendingTextsFromStorage() {
    var saved = await getSetting('chatPendingTexts', null);
    if (saved) {
        chatPendingTexts = saved;
    }
}

function persistPendingImagesToSession() {
    // Keep in-memory map in sync with active images
    var ctx = getCurrentPendingContext();
    if (pendingImageAttachments.length > 0) {
        chatPendingImages[ctx] = pendingImageAttachments.slice();
    } else {
        delete chatPendingImages[ctx];
    }
    if (Object.keys(chatPendingImages).length > 0) {
        setSetting('chatPendingImages', chatPendingImages);
    } else {
        setSetting('chatPendingImages', null);
    }
}

async function restorePendingImagesFromSession() {
    var saved = await getSetting('chatPendingImages', null);
    if (saved) {
        chatPendingImages = saved;
    }
}

// Initialize image attachment event listeners
function initImageAttachmentListeners() {
    // Paste listener on the document (works even when input not focused)
    document.addEventListener('paste', handlePasteForImages);

    // Drag and drop listeners on the full page
    document.addEventListener('dragover', handleDragOver);
    document.addEventListener('dragenter', handleDragEnter);
    document.addEventListener('dragleave', handleDragLeave);
    document.addEventListener('drop', handleDrop);
}

// Resend a user message in a new chat
function resendMessage(msgIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages[msgIndex]) return;
    var userMsg = chat.messages[msgIndex];
    if (userMsg.role !== 'user') return;

    // Create new chat and send the message
    newChat();
    var input = document.getElementById('message-input');
    input.value = userMsg.content;
    sendMessage();
}

// Edit a user message - creates a new chat branch with history up to that point
function editMessage(msgIndex) {
    var chat = chats[currentChatId];
    if (!chat || !chat.messages[msgIndex]) return;
    var userMsg = chat.messages[msgIndex];
    if (userMsg.role !== 'user') return;

    // Copy all messages up to (but not including) this message
    // Include everything to preserve artifacts and cache prefix
    var historyMessages = chat.messages.slice(0, msgIndex);

    // Create a new chat with the history
    var newChatId = 'chat_' + Date.now();
    chats[newChatId] = {
        id: newChatId,
        title: chat.title + ' (edited)',
        messages: historyMessages,
        createdAt: Date.now()
    };

    // Copy cached tool results so cached_content_* tools still work in the branched chat
    if (chat.cachedToolResults) {
        chats[newChatId].cachedToolResults = Object.assign({}, chat.cachedToolResults);
    }

    // Copy version history (artifacts) for messages being kept, updating chatId
    if (chat.versionHistory && chat.versionHistory.length > 0) {
        chats[newChatId].versionHistory = chat.versionHistory
            .filter(function(v) { return v.messageIndex < msgIndex; })
            .map(function(v) {
                var copy = Object.assign({}, v);
                copy.chatId = newChatId;
                return copy;
            });
    }

    // Note: Widgets are NOT copied to avoid ID conflicts with dashboard
    // The branched chat can create new widgets as needed

    // Switch to new chat without full navigation - keep UI seamless
    currentChatId = newChatId;
    appStorage.setItem('lastChatId', newChatId);
    saveChatsToStorage();

    // Load version history for the new chat so artifacts are displayed
    loadVersionHistory();

    // Re-render messages to show truncated history (messages after edited one disappear)
    renderMessages();
    renderChatList();
    updateChatTitleHeader();

    // Put the original message content in the input for editing
    var input = document.getElementById('message-input');
    input.value = userMsg.content;
    input.focus();
    autoResizeTextarea(input);

    showSnackbar('Editing message - modify and send to branch', 'success');
}

window.onload = init;
